revoke all privileges on function pac_dsd.assert_safe_page_link(text) from public;
revoke all privileges on function pac_dsd.assert_valid_page_block_copy(text, jsonb) from public;
revoke all privileges on function pac_dsd.read_page_block_publication(text, text) from public;
revoke all privileges on function pac_dsd.read_page_block_editing_state(text, text) from public;
