revoke all privileges on function pac_dsd.record_page_block_review(text, text, uuid, text, text, uuid, text) from public;
revoke all privileges on function pac_dsd.publish_page_block_draft(text, text, uuid, bigint, text) from public;
revoke all privileges on function pac_dsd.withdraw_page_block_publication(text, text, uuid, bigint, text) from public;
revoke all privileges on function pac_dsd.rollback_page_block_publication(text, text, uuid, uuid, bigint, text) from public;

grant execute on function pac_dsd.read_page_block_publication(text, text) to pac_dsd_app_runtime;
grant execute on function pac_dsd.read_page_block_editing_state(text, text) to pac_dsd_app_runtime;
grant execute on function pac_dsd.create_page_block_draft(text, text, uuid, jsonb, text) to pac_dsd_app_runtime;
grant execute on function pac_dsd.record_page_block_review(text, text, uuid, text, text, uuid, text) to pac_dsd_app_runtime;
grant execute on function pac_dsd.publish_page_block_draft(text, text, uuid, bigint, text) to pac_dsd_app_runtime;
grant execute on function pac_dsd.withdraw_page_block_publication(text, text, uuid, bigint, text) to pac_dsd_app_runtime;
grant execute on function pac_dsd.rollback_page_block_publication(text, text, uuid, uuid, bigint, text) to pac_dsd_app_runtime;

revoke all privileges on pac_dsd.source_carriers from pac_dsd_app_runtime;
