revoke all privileges on pac_dsd.content_items from pac_dsd_app_runtime;
revoke all privileges on pac_dsd.content_revisions from pac_dsd_app_runtime;
revoke all privileges on pac_dsd.revision_sources from pac_dsd_app_runtime;
revoke all privileges on pac_dsd.revision_assets from pac_dsd_app_runtime;
revoke all privileges on pac_dsd.review_records from pac_dsd_app_runtime;
revoke all privileges on pac_dsd.publication_decisions from pac_dsd_app_runtime;
revoke all privileges on pac_dsd.change_events from pac_dsd_app_runtime;
revoke all privileges on pac_dsd.source_items from pac_dsd_app_runtime;
revoke all privileges on pac_dsd.source_carriers from pac_dsd_app_runtime;

comment on function pac_dsd.read_resource_editing_state(text, text) is
  'Returns an exact-scope resource draft or a read-only inherited publication as the base for a new local draft.';
comment on function pac_dsd.create_resource_draft(text, text, uuid, jsonb, text) is
  'Creates an unpublished resource draft only in the requested program scope.';
comment on function pac_dsd.read_resource_release_state(text, text) is
  'Shows local release state and inherited staff visibility while keeping inherited publications read-only.';
comment on function pac_dsd.record_resource_review(text, text, uuid, text, uuid, text, text) is
  'Appends a review only when both the draft and prior review versions still match.';
comment on function pac_dsd.publish_resource_draft(text, text, uuid, bigint, text) is
  'Publishes a reviewed resource only in the requested scope and checks the latest scope decision under lock.';
comment on function pac_dsd.withdraw_resource_publication(text, text, uuid, bigint, text) is
  'Withdraws only the requested scope publication after checking its exact decision version.';
comment on function pac_dsd.republish_resource_revision(text, text, uuid, bigint, text) is
  'Restores only a previously published exact-scope resource after checking the current decision version.';


-- 0009_pac_data_trust_foundation.sql

-- RG-2 trust vocabulary. Unknown material remains protected (S2) until a
-- review and publication decision assigns a lower class explicitly.
create table if not exists pac_dsd.participation_classes (
  participation_class text primary key check (
    participation_class in ('voluntary_private', 'voluntary_shared', 'supports_required', 'required_record')
  ),
  description text not null,
  may_create_official_record boolean not null,
  created_at timestamptz not null default now()
);

insert into pac_dsd.participation_classes (
  participation_class, description, may_create_official_record
)
values
  ('voluntary_private', 'Self-directed activity that is private by default and does not become compliance evidence.', false),
  ('voluntary_shared', 'A person explicitly chooses to share a draft, feedback item, or support request with named recipients.', false),
  ('supports_required', 'The program supports a required process but is not the official system of record.', false),
  ('required_record', 'A separately authorized formal workflow with explicit identity, viewers, retention, and correction controls.', true)
on conflict (participation_class) do update
set description = excluded.description,
    may_create_official_record = excluded.may_create_official_record;

create table if not exists pac_dsd.retention_policies (
  retention_policy_id text primary key,
  record_class text not null,
  policy_version text not null,
  status text not null check (status in ('draft', 'approved', 'withdrawn', 'superseded')),
  retention_days integer check (retention_days is null or retention_days between 1 and 3650),
  correction_process text,
  deletion_process text,
  recovery_process text,
  incident_process text,
  approved_by text,
  approved_at timestamptz,
  created_at timestamptz not null default now(),
  check (
    status <> 'approved'
    or (
      retention_days is not null
      and correction_process is not null
      and deletion_process is not null
      and recovery_process is not null
      and incident_process is not null
      and approved_by is not null
      and approved_at is not null
    )
  )
);

