-- A database backstop rejects exact fields that would create ideology scoring,
-- inferred protected traits, supervisor surveillance, or hidden staff profiles.
create or replace function pac_dsd.assert_no_prohibited_profile_fields(payload jsonb)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
declare
  item record;
  normalized_key text;
begin
  if payload is null then
    return;
  end if;

  if jsonb_typeof(payload) = 'object' then
    for item in select key, value from jsonb_each(payload)
    loop
      -- Removing separators makes this check independent of snake case,
      -- camel case, spaces, punctuation, and capitalized acronyms.
      normalized_key := lower(regexp_replace(item.key, '[^A-Za-z0-9]+', '', 'g'));
      if normalized_key = any(array[
        'beliefprofile',
        'beliefsbyworker',
        'completionbystaff',
        'compliancescore',
        'culturalcompetencescore',
        'deiscore',
        'employeeequityscore',
        'employeeequityreadiness',
        'employeeideology',
        'employeeprofile',
        'ideologybyemployee',
        'equitymaturityscore',
        'equityscore',
        'ideologyscore',
        'inferreddisability',
        'inferredethnicity',
        'inferredgenderidentity',
        'inferredprotectedclass',
        'inferredrace',
        'learningcompliancescore',
        'learningprogressbyemployee',
        'participationleaderboard',
        'supervisorparticipationdashboard',
        'supervisorparticipationscore',
        'workerinclusionmaturityscore'
      ])
      or normalized_key ~ '^(racialbias|equityreadiness|deireadiness|culturalcompetence|equitymaturity|inclusionmaturity)(score|rating|ranking|rank|profile)$'
      or normalized_key ~ '^(political|religious|ideological)(belief|beliefs|affiliation|affiliations|profile)$'
      or normalized_key ~ '^(belief|beliefs|ideology|ideologies|learningprogress|trainingprogress|learningcompletion|trainingcompletion|coursecompletion|completion|activity)(by|per)(employee|staff|worker|person|individual|member|user|supervisor)$'
      or normalized_key ~ '^(participation|engagement)(by|per)(employee|staff|worker|person|individual|member|user|supervisor)$'
      or normalized_key ~ '^(employee|staff|worker|personnel|supervisor)(equity|dei|ideology|inclusion|bias|participation|engagement|culturalcompetence)(score|rating|ranking|rank|profile|dashboard|leaderboard)$'
      or normalized_key ~ '^(employee|staff|worker|personnel|supervisor)(equityreadiness|inclusionmaturity|learningprogress|completion|activity)(score|rating|ranking|rank|profile|dashboard|leaderboard)?$'
      or normalized_key ~ '^(inferred|predicted|estimated|guessed)(race|ethnicity|genderidentity|disability|protectedclass|politicalbelief|politicalbeliefs|religion)$'
      then
        raise exception using
          errcode = '22023',
          message = 'Prohibited employee-profile field';
      end if;
      perform pac_dsd.assert_no_prohibited_profile_fields(item.value);
    end loop;
  elsif jsonb_typeof(payload) = 'array' then
    for item in select value from jsonb_array_elements(payload)
    loop
      perform pac_dsd.assert_no_prohibited_profile_fields(item.value);
    end loop;
  end if;
end;
$$;

create or replace function pac_dsd.reject_prohibited_profile_row()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
as $$
begin
  perform pac_dsd.assert_no_prohibited_profile_fields(to_jsonb(new));
  return new;
end;
$$;

do $$
declare
  table_name text;
begin
  for table_name in
    select columns.table_name
    from information_schema.columns columns
    join information_schema.tables tables
      on tables.table_schema = columns.table_schema
      and tables.table_name = columns.table_name
    where columns.table_schema = 'pac_dsd'
      and columns.udt_name = 'jsonb'
      and tables.table_type = 'BASE TABLE'
    group by columns.table_name
  loop
    execute format('drop trigger if exists no_prohibited_profile_fields on pac_dsd.%I', table_name);
    execute format(
      'create trigger no_prohibited_profile_fields before insert or update on pac_dsd.%I for each row execute function pac_dsd.reject_prohibited_profile_row()',
      table_name
    );
  end loop;
end;
$$;

-- A staff publication is safe for an unauthenticated request only when the
-- publication decision explicitly permits exposure and every projected layer
-- is S0 or S1. Scope inheritance can narrow, but never broaden, this decision.
create or replace function pac_dsd.enforce_data_trust_publication_gate()
returns trigger
language plpgsql
set search_path = pg_catalog, pac_dsd
as $$
declare
  revision_class text;
  revision_indexing boolean;
  item_class text;
  protected_sources integer;
  protected_assets integer;
begin
  if new.decision <> 'publish' then
    return new;
  end if;

  select r.sensitivity_class, r.ordinary_indexing_allowed, i.sensitivity_class
  into revision_class, revision_indexing, item_class
  from pac_dsd.content_revisions r
  join pac_dsd.content_items i on i.content_item_id = r.content_item_id
  where r.revision_id = new.revision_id
    and i.content_item_id = new.content_item_id;

  if revision_class is null then
    raise exception 'Publication revision and content item do not match';
  end if;
  if revision_class not in ('S0', 'S1') or item_class not in ('S0', 'S1') then
    raise exception 'Protected or unreviewed content cannot be published to a staff projection';
  end if;
  if new.sensitivity_class is distinct from revision_class then
    raise exception 'Publication sensitivity must match the reviewed revision';
  end if;
  if new.unauthenticated_exposure_permitted and not revision_indexing then
    raise exception 'Unauthenticated exposure requires an explicitly indexable staff revision';
  end if;
  if new.unauthenticated_exposure_permitted and nullif(trim(new.exposure_reason), '') is null then
    raise exception 'Unauthenticated exposure requires a recorded reason';
  end if;

  select count(*) into protected_sources
  from pac_dsd.revision_sources rs
  join pac_dsd.source_items source on source.source_item_id = rs.source_item_id
  where rs.revision_id = new.revision_id
    and (
      source.sensitivity_class not in ('S0', 'S1')
      or source.ordinary_indexing_allowed is distinct from true
      or source.deidentification_status not in ('not_needed', 'verified')
    );
  if protected_sources > 0 then
    raise exception 'A protected or unreviewed source cannot enter a staff publication';
  end if;

  select count(*) into protected_assets
  from pac_dsd.revision_assets ra
  join pac_dsd.assets asset on asset.asset_id = ra.asset_id
  where ra.revision_id = new.revision_id
    and asset.sensitivity_class not in ('S0', 'S1');
  if protected_assets > 0 then
    raise exception 'A protected or unreviewed asset cannot enter a staff publication';
  end if;

  return new;
end;
$$;

drop trigger if exists data_trust_publication_gate on pac_dsd.publication_decisions;
create trigger data_trust_publication_gate
before insert on pac_dsd.publication_decisions
for each row execute function pac_dsd.enforce_data_trust_publication_gate();

create or replace view pac_dsd.current_publications
with (security_invoker = true) as
select content_item_id, revision_id, scope_id, decision, gate_snapshot, decided_at, decided_by, reason,
  sensitivity_class, unauthenticated_exposure_permitted, exposure_reason
from (
  select d.*,
    row_number() over (partition by content_item_id, scope_id order by publication_decision_id desc) as row_rank
  from pac_dsd.publication_decisions d
) ranked
where row_rank = 1 and decision = 'publish';

create or replace view pac_dsd.current_staff_publications
with (security_invoker = true) as
select p.content_item_id, p.revision_id, p.scope_id, p.gate_snapshot, p.decided_at,
  i.content_kind, i.staff_label, r.canonical_payload, r.payload_sha256,
  p.sensitivity_class, p.unauthenticated_exposure_permitted, p.exposure_reason,
  r.model_context_allowed
from pac_dsd.current_publications p
join pac_dsd.content_items i on i.content_item_id = p.content_item_id
join pac_dsd.content_revisions r on r.revision_id = p.revision_id
where i.restricted = false
  and i.retired_at is null
  and i.sensitivity_class in ('S0', 'S1')
  and r.sensitivity_class in ('S0', 'S1')
  and p.sensitivity_class in ('S0', 'S1')
  and not exists (
    select 1
    from pac_dsd.revision_sources source_link
    join pac_dsd.source_items source on source.source_item_id = source_link.source_item_id
    where source_link.revision_id = r.revision_id
      and (
        source.sensitivity_class not in ('S0', 'S1')
        or source.ordinary_indexing_allowed is distinct from true
        or source.deidentification_status not in ('not_needed', 'verified')
      )
  )
  and not exists (
    select 1
    from pac_dsd.revision_assets asset_link
    join pac_dsd.assets asset on asset.asset_id = asset_link.asset_id
    where asset_link.revision_id = r.revision_id
      and asset.sensitivity_class not in ('S0', 'S1')
  );

create or replace function pac_dsd.read_staff_publications(
  requested_scope_id text,
  requested_content_item_id text default null
)
returns table (
  content_item_id text,
  revision_id uuid,
  scope_id text,
  canonical_payload jsonb,
  payload_sha256 text,
  decided_at timestamptz
)
language plpgsql
stable
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
begin
  if not exists (
    select 1 from pac_dsd.program_scopes s
    where s.scope_id = requested_scope_id
      and s.active = true
      and s.scope_id <> 'one-dhs-pac'
  ) then
    raise exception 'Unknown or inactive staff scope: %', requested_scope_id using errcode = '22023';
  end if;

  return query
  with recursive visible_scopes as (
    select s.scope_id, s.parent_scope_id, 0 as distance
    from pac_dsd.program_scopes s
    where s.scope_id = requested_scope_id and s.active = true

    union all

    select parent.scope_id, parent.parent_scope_id, child.distance + 1
    from pac_dsd.program_scopes parent
    join visible_scopes child on parent.scope_id = child.parent_scope_id
    where parent.active = true and parent.scope_id <> 'one-dhs-pac'
  ),
  ranked as (
    select publication.content_item_id,
      publication.revision_id,
      publication.scope_id,
      publication.canonical_payload,
      publication.payload_sha256,
      publication.decided_at,
      row_number() over (
        partition by publication.content_item_id
        order by visible.distance asc, publication.decided_at desc, publication.revision_id desc
      ) as publication_rank
    from pac_dsd.current_staff_publications publication
    join visible_scopes visible on visible.scope_id = publication.scope_id
    where (requested_content_item_id is null or publication.content_item_id = requested_content_item_id)
      and publication.canonical_payload ->> 'status' = 'approved'
      and publication.sensitivity_class in ('S0', 'S1')
      and publication.unauthenticated_exposure_permitted = true
  )
  select ranked.content_item_id,
    ranked.revision_id,
    ranked.scope_id,
    ranked.canonical_payload,
    ranked.payload_sha256,
    ranked.decided_at
  from ranked
  where ranked.publication_rank = 1
  order by ranked.content_item_id;
end;
$$;

-- Distributed, privacy-minimized fixed-window rate limiter. The application
-- supplies only an HMAC subject hash; raw network identifiers are never stored.
create table if not exists pac_dsd.runtime_rate_limits (
  scope text not null check (
    scope in ('staff-ask', 'owner-login', 'consultation-intake', 'consultation-tracking')
  ),
  subject_hash text not null check (subject_hash ~ '^[a-f0-9]{64}$'),
  request_count integer not null check (request_count > 0),
  reset_at timestamptz not null,
  updated_at timestamptz not null default now(),
  primary key (scope, subject_hash)
);

alter table pac_dsd.runtime_rate_limits enable row level security;
revoke all privileges on pac_dsd.runtime_rate_limits from public;
revoke all privileges on pac_dsd.runtime_rate_limits from pac_dsd_app_runtime;

create or replace function pac_dsd.consume_runtime_rate_limit(
  requested_scope text,
  requested_subject_hash text,
  requested_limit integer,
  requested_window_seconds integer
)
returns table (allowed boolean, remaining integer, reset_at timestamptz)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  current_count integer;
  current_reset timestamptz;
begin
  if requested_subject_hash !~ '^[a-f0-9]{64}$'
    or not (
      (requested_scope = 'staff-ask' and requested_limit = 30 and requested_window_seconds = 600)
      or (requested_scope = 'owner-login' and requested_limit = 10 and requested_window_seconds = 900)
      or (requested_scope = 'consultation-intake' and requested_limit = 20 and requested_window_seconds = 3600)
      or (requested_scope = 'consultation-tracking' and requested_limit = 20 and requested_window_seconds = 600)
    )
  then
    raise exception 'Invalid rate-limit request' using errcode = '22023';
  end if;

  insert into pac_dsd.runtime_rate_limits (scope, subject_hash, request_count, reset_at)
  values (
    requested_scope,
    requested_subject_hash,
    1,
    clock_timestamp() + make_interval(secs => requested_window_seconds)
  )
  on conflict (scope, subject_hash) do update
  set request_count = case
        when pac_dsd.runtime_rate_limits.reset_at <= clock_timestamp() then 1
        else pac_dsd.runtime_rate_limits.request_count + 1
      end,
      reset_at = case
        when pac_dsd.runtime_rate_limits.reset_at <= clock_timestamp()
          then clock_timestamp() + make_interval(secs => requested_window_seconds)
        else pac_dsd.runtime_rate_limits.reset_at
      end,
      updated_at = clock_timestamp()
  returning request_count, pac_dsd.runtime_rate_limits.reset_at
  into current_count, current_reset;

  allowed := current_count <= requested_limit;
  remaining := greatest(0, requested_limit - current_count);
  reset_at := current_reset;
  return next;
end;
$$;

revoke all privileges on function pac_dsd.consume_runtime_rate_limit(text, text, integer, integer) from public;
grant execute on function pac_dsd.consume_runtime_rate_limit(text, text, integer, integer) to pac_dsd_app_runtime;

do $$
declare
  role_name text;
begin
  foreach role_name in array array['anon', 'authenticated']
  loop
    if exists (select 1 from pg_catalog.pg_roles where rolname = role_name) then
      execute format('revoke all privileges on pac_dsd.participation_classes from %I', role_name);
      execute format('revoke all privileges on pac_dsd.retention_policies from %I', role_name);
      execute format('revoke all privileges on pac_dsd.runtime_rate_limits from %I', role_name);
    end if;
  end loop;
end;
$$;

revoke all privileges on pac_dsd.participation_classes from public, pac_dsd_app_runtime;
revoke all privileges on pac_dsd.retention_policies from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.assert_no_prohibited_profile_fields(jsonb) from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.reject_prohibited_profile_row() from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.enforce_data_trust_publication_gate() from public, pac_dsd_app_runtime;

comment on table pac_dsd.participation_classes is 'Canonical DEC-007 participation classes. Active experience notices are versioned in application contracts.';
comment on table pac_dsd.retention_policies is 'Protected-record lifecycles. A policy cannot become approved without retention, correction, deletion, recovery, incident, and approval evidence.';
comment on table pac_dsd.runtime_rate_limits is 'Short-lived abuse counters keyed by an application-generated HMAC; raw network identifiers are prohibited.';


-- 0010_pac_trusted_resource_release.sql

-- A staff-facing release is an explicit data-trust decision. The release API may
-- never rely on the S2/false defaults added by migration 0009.
create or replace function pac_dsd.assert_explicit_resource_staff_exposure(
  requested_sensitivity_class text,
  requested_unauthenticated_exposure_permitted boolean,
  requested_exposure_reason text
)
returns void
language plpgsql
set search_path = pg_catalog, pac_dsd
as $$
begin
  if requested_sensitivity_class is null
    or requested_sensitivity_class not in ('S0', 'S1') then
    raise exception 'A reviewed S0 or S1 classification is required' using errcode = '22023';
  end if;
  if requested_unauthenticated_exposure_permitted is distinct from true then
    raise exception 'Staff-facing exposure without sign-in must be approved explicitly' using errcode = '22023';
  end if;
  if requested_exposure_reason is null
    or length(btrim(requested_exposure_reason)) not between 1 and 500 then
    raise exception 'A short staff exposure reason is required' using errcode = '22023';
  end if;
  perform pac_dsd.assert_plain_resource_text(requested_exposure_reason);
end;
$$;

create or replace function pac_dsd.publish_resource_draft(
  requested_scope_id text,
  requested_content_item_id text,
  expected_draft_revision_id uuid,
  expected_scope_decision_id bigint,
  requested_reason text,
  requested_sensitivity_class text,
  requested_unauthenticated_exposure_permitted boolean,
  requested_exposure_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  draft_revision pac_dsd.content_revisions%rowtype;
  current_scope_decision_id bigint;
  release_revision_id uuid;
  release_payload jsonb;
  release_revision_number integer;
  gate_reviews jsonb;
  new_publication_decision_id bigint;
begin
  if not pac_dsd.resource_management_allowed(
    requested_scope_id, requested_content_item_id
  ) then
    raise exception 'This resource is not available for publication' using errcode = 'P0002';
  end if;
  if requested_reason is null or length(btrim(requested_reason)) not between 1 and 500 then
    raise exception 'A short publication note is required' using errcode = '22023';
  end if;
  perform pac_dsd.assert_plain_resource_text(requested_reason);
  perform pac_dsd.assert_explicit_resource_staff_exposure(
    requested_sensitivity_class,
    requested_unauthenticated_exposure_permitted,
    requested_exposure_reason
  );

  perform 1
  from pac_dsd.content_items item
  where item.content_item_id = requested_content_item_id
    and item.content_kind = 'resource'
    and item.retired_at is null
  for update;
  if not found then
    raise exception 'This resource is not available for publication' using errcode = 'P0002';
  end if;

  select decision.publication_decision_id into current_scope_decision_id
  from pac_dsd.publication_decisions decision
  where decision.content_item_id = requested_content_item_id
    and decision.scope_id = requested_scope_id
  order by decision.publication_decision_id desc
  limit 1;
  if current_scope_decision_id is distinct from expected_scope_decision_id then
    raise exception 'The publication changed after this page was opened' using errcode = '40001';
  end if;

  select revision.* into draft_revision
  from pac_dsd.content_revisions revision
  where revision.content_item_id = requested_content_item_id
    and revision.canonical_payload ->> 'status' = 'under_review'
    and pac_dsd.resource_scope_id(revision.canonical_payload) = requested_scope_id
    and not exists (
      select 1 from pac_dsd.content_revisions release
      where release.based_on_revision_id = revision.revision_id
        and release.canonical_payload ->> 'status' = 'approved'
    )
  order by revision.revision_number desc, revision.revision_id desc
  limit 1;
  if draft_revision.revision_id is distinct from expected_draft_revision_id then
    raise exception 'The resource changed after the publication review was opened' using errcode = '40001';
  end if;
  perform pac_dsd.assert_exact_resource_scope(
    requested_scope_id, draft_revision.canonical_payload
  );

  if exists (
    select 1
    from unnest(draft_revision.required_review_dimensions) required(dimension)
    left join lateral (
      select review.status
      from pac_dsd.review_records review
      where review.revision_id = draft_revision.revision_id
        and review.dimension = required.dimension
      order by review.recorded_at desc, review.review_id desc
      limit 1
    ) current_review on true
    where current_review.status is null
      or current_review.status not in ('pass', 'not_applicable')
  ) then
    raise exception 'Complete every required review before publication' using errcode = '55000';
  end if;

  perform pac_dsd.assert_resource_staff_release(draft_revision.revision_id);
  release_payload := draft_revision.canonical_payload
    || jsonb_build_object('status', 'approved', 'accessibility', 'reviewed');
  perform pac_dsd.assert_exact_resource_scope(requested_scope_id, release_payload);
  select coalesce(max(revision.revision_number), 0) + 1
  into release_revision_number
  from pac_dsd.content_revisions revision
  where revision.content_item_id = requested_content_item_id;

  update pac_dsd.content_items
  set sensitivity_class = requested_sensitivity_class
  where content_item_id = requested_content_item_id;

  insert into pac_dsd.content_revisions (
    content_item_id, revision_number, canonical_payload, change_summary,
    required_review_dimensions, created_by, based_on_revision_id,
    sensitivity_class, ordinary_indexing_allowed, model_context_allowed,
    limitations
  ) values (
    requested_content_item_id, release_revision_number, release_payload,
    'Reviewed and approved for staff use.',
    draft_revision.required_review_dimensions,
    'practice-workspace-owner', draft_revision.revision_id,
    requested_sensitivity_class, true, false,
    array['Approved only for ordinary retrieval at the staff-facing web address; model context requires a separate decision.']::text[]
  ) returning revision_id into release_revision_id;

  insert into pac_dsd.revision_sources (
    revision_id, source_item_id, relationship, note
  )
  select release_revision_id, source.source_item_id, source.relationship, source.note
  from pac_dsd.revision_sources source
  where source.revision_id = draft_revision.revision_id;

  insert into pac_dsd.revision_assets (
    revision_id, asset_id, purpose, staff_label, sort_order
  )
  select release_revision_id, asset.asset_id, asset.purpose,
    asset.staff_label, asset.sort_order
  from pac_dsd.revision_assets asset
  where asset.revision_id = draft_revision.revision_id;

  insert into pac_dsd.review_records (
    revision_id, dimension, status, reviewer_role, reviewer_id, findings
  )
  select release_revision_id,
    required.dimension,
    current_review.status,
    'publishing_approver',
    'practice-workspace-owner',
    jsonb_build_object(
      'carried_forward_from_review_id', current_review.review_id,
      'release_validation', true
    )
  from unnest(draft_revision.required_review_dimensions) required(dimension)
  cross join lateral (
    select review.review_id, review.status
    from pac_dsd.review_records review
    where review.revision_id = draft_revision.revision_id
      and review.dimension = required.dimension
    order by review.recorded_at desc, review.review_id desc
    limit 1
  ) current_review;

  perform pac_dsd.assert_resource_staff_release(release_revision_id);
  select jsonb_agg(
    jsonb_build_object('dimension', review.dimension, 'status', review.status)
    order by array_position(
      draft_revision.required_review_dimensions, review.dimension
    )
  ) into gate_reviews
  from (
    select distinct on (record.dimension) record.dimension, record.status
    from pac_dsd.review_records record
    where record.revision_id = release_revision_id
    order by record.dimension, record.recorded_at desc, record.review_id desc
  ) review;

  insert into pac_dsd.publication_decisions (
    content_item_id, revision_id, scope_id, decision,
    gate_snapshot, decided_by, reason, sensitivity_class,
    unauthenticated_exposure_permitted, exposure_reason
  ) values (
    requested_content_item_id,
    release_revision_id,
    requested_scope_id,
    'publish',
    jsonb_build_object(
      'reviewed_draft_revision_id', draft_revision.revision_id,
      'replaced_scope_decision_id', current_scope_decision_id,
      'required_reviews', coalesce(gate_reviews, '[]'::jsonb),
      'staff_voice_checked', true,
      'plain_text_checked', true,
      'icons_checked', true,
      'sensitivity_class', requested_sensitivity_class,
      'ordinary_indexing_allowed', true,
      'model_context_allowed', false,
      'unauthenticated_exposure_permitted', true,
      'exposure_reason_recorded', true
    ),
    'practice-workspace-owner',
    btrim(requested_reason),
    requested_sensitivity_class,
    requested_unauthenticated_exposure_permitted,
    btrim(requested_exposure_reason)
  ) returning publication_decision_id into new_publication_decision_id;

  insert into pac_dsd.change_events (
    actor_id, actor_role, scope_id, object_type, object_id, action, detail
  ) values (
    'practice-workspace-owner', 'owner', requested_scope_id, 'content_item',
    requested_content_item_id, 'resource_published',
    jsonb_build_object(
      'draft_revision_id', draft_revision.revision_id,
      'published_revision_id', release_revision_id,
      'publication_decision_id', new_publication_decision_id,
      'revision_number', release_revision_number,
      'staff_release_explicit', true,
      'sensitivity_class', requested_sensitivity_class,
      'unauthenticated_exposure_permitted', true,
      'model_context_allowed', false
    )
  );

  return pac_dsd.read_resource_release_state(
    requested_scope_id, requested_content_item_id
  );
end;
$$;

create or replace function pac_dsd.republish_resource_revision(
  requested_scope_id text,
  requested_content_item_id text,
  requested_revision_id uuid,
  expected_scope_decision_id bigint,
  requested_reason text,
  requested_sensitivity_class text,
  requested_unauthenticated_exposure_permitted boolean,
  requested_exposure_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  requested_revision pac_dsd.content_revisions%rowtype;
  current_decision pac_dsd.publication_decisions%rowtype;
  gate_reviews jsonb;
  new_publication_decision_id bigint;
begin
  if not pac_dsd.resource_management_allowed(
    requested_scope_id, requested_content_item_id
  ) then
    raise exception 'This resource is not available for restoration' using errcode = 'P0002';
  end if;
  if requested_reason is null or length(btrim(requested_reason)) not between 1 and 500 then
    raise exception 'A short restoration note is required' using errcode = '22023';
  end if;
  perform pac_dsd.assert_plain_resource_text(requested_reason);
  perform pac_dsd.assert_explicit_resource_staff_exposure(
    requested_sensitivity_class,
    requested_unauthenticated_exposure_permitted,
    requested_exposure_reason
  );

  perform 1
  from pac_dsd.content_items item
  where item.content_item_id = requested_content_item_id
    and item.content_kind = 'resource'
    and item.retired_at is null
  for update;
  if not found then
    raise exception 'This resource is not available for restoration' using errcode = 'P0002';
  end if;

  select decision.* into current_decision
  from pac_dsd.publication_decisions decision
  where decision.content_item_id = requested_content_item_id
    and decision.scope_id = requested_scope_id
  order by decision.publication_decision_id desc
  limit 1;
  if current_decision.publication_decision_id
    is distinct from expected_scope_decision_id then
    raise exception 'The publication changed after this page was opened' using errcode = '40001';
  end if;

  select revision.* into requested_revision
  from pac_dsd.content_revisions revision
  where revision.content_item_id = requested_content_item_id
    and revision.revision_id = requested_revision_id;
  if requested_revision.revision_id is null
    or requested_revision.canonical_payload ->> 'status' <> 'approved' then
    raise exception 'Only a previously approved version can be restored' using errcode = '22023';
  end if;
  if requested_revision.sensitivity_class is distinct from requested_sensitivity_class
    or requested_revision.sensitivity_class not in ('S0', 'S1')
    or requested_revision.ordinary_indexing_allowed is distinct from true then
    raise exception 'Only a previously classified S0 or S1 staff version can be restored' using errcode = '22023';
  end if;
  perform pac_dsd.assert_exact_resource_scope(
    requested_scope_id, requested_revision.canonical_payload
  );

  if not exists (
    select 1
    from pac_dsd.publication_decisions decision
    where decision.content_item_id = requested_content_item_id
      and decision.revision_id = requested_revision_id
      and decision.scope_id = requested_scope_id
      and decision.decision = 'publish'
  ) then
    raise exception 'Only a version previously published in this scope can be restored' using errcode = '22023';
  end if;

  if exists (
    select 1
    from unnest(requested_revision.required_review_dimensions) required(dimension)
    left join lateral (
      select review.status
      from pac_dsd.review_records review
      where review.revision_id = requested_revision_id
        and review.dimension = required.dimension
      order by review.recorded_at desc, review.review_id desc
      limit 1
    ) current_review on true
    where current_review.status is null
      or current_review.status not in ('pass', 'not_applicable')
  ) then
    raise exception 'Only a fully reviewed version can be restored' using errcode = '55000';
  end if;
  perform pac_dsd.assert_resource_staff_release(requested_revision_id);

  if current_decision.decision = 'publish'
    and current_decision.revision_id = requested_revision_id then
    raise exception 'That version is already published' using errcode = '55000';
  end if;

  select jsonb_agg(
    jsonb_build_object('dimension', review.dimension, 'status', review.status)
    order by array_position(
      requested_revision.required_review_dimensions, review.dimension
    )
  ) into gate_reviews
  from (
    select distinct on (record.dimension) record.dimension, record.status
    from pac_dsd.review_records record
    where record.revision_id = requested_revision_id
    order by record.dimension, record.recorded_at desc, record.review_id desc
  ) review;

  update pac_dsd.content_items
  set sensitivity_class = requested_sensitivity_class
  where content_item_id = requested_content_item_id;

  insert into pac_dsd.publication_decisions (
    content_item_id, revision_id, scope_id, decision,
    gate_snapshot, decided_by, reason, sensitivity_class,
    unauthenticated_exposure_permitted, exposure_reason
  ) values (
    requested_content_item_id,
    requested_revision_id,
    requested_scope_id,
    'publish',
    jsonb_build_object(
      'restored_previous_revision', true,
      'replaced_scope_decision_id', current_decision.publication_decision_id,
      'required_reviews', coalesce(gate_reviews, '[]'::jsonb),
      'staff_voice_checked', true,
      'plain_text_checked', true,
      'icons_checked', true,
      'sensitivity_class', requested_sensitivity_class,
      'ordinary_indexing_allowed', true,
      'unauthenticated_exposure_permitted', true,
      'exposure_reason_recorded', true
    ),
    'practice-workspace-owner',
    btrim(requested_reason),
    requested_sensitivity_class,
    requested_unauthenticated_exposure_permitted,
    btrim(requested_exposure_reason)
  ) returning publication_decision_id into new_publication_decision_id;

  insert into pac_dsd.change_events (
    actor_id, actor_role, scope_id, object_type, object_id, action, detail
  ) values (
    'practice-workspace-owner', 'owner', requested_scope_id, 'content_item',
    requested_content_item_id, 'resource_restored',
    jsonb_build_object(
      'restored_revision_id', requested_revision_id,
      'publication_decision_id', new_publication_decision_id,
      'staff_release_explicit', true,
      'sensitivity_class', requested_sensitivity_class,
      'unauthenticated_exposure_permitted', true
    )
  );

  return pac_dsd.read_resource_release_state(
    requested_scope_id, requested_content_item_id
  );
end;
$$;

-- Existing deployments may already contain the one frozen 25-resource seed
-- release. This narrow, named migration decision restores only that reviewed
-- release after migration 0009 deliberately classified legacy rows as S2.
do $$
declare
  release_id constant text := 'permanent-seed-staff-release-2026-09-05';
  seed_source_id constant text := 'owner:current-seed-collection-2026-09-04:v1';
  seed_collection_id constant text := 'current-seed-2026-09-04';
  expected_item_ids constant text[] := array[
    'ext-ada',
    'ext-clas',
    'ext-dhs-equity-toolkit',
    'ext-mn-accessibility',
    'ext-title-vi-lep',
    'ja-access-checks',
    'ja-climate-action-plan',
    'ja-equity-impact-questions',
    'ja-facilitation-session-plan',
    'ja-form-notice-change',
    'ja-language-access-checklist',
    'ja-launch-embed-checklist',
    'ja-plain-language',
    'ja-process-burden',
    'ja-stakeholder-map',
    'lm-facilitation-application',
    'lm-how-this-program-works',
    'lm-interpreter',
    'lm-workplace-climate',
    'pn-embed-early',
    'pn-equity-in-practice',
    'pn-intercultural-method',
    'pn-partnership-spine',
    'pn-self-check',
    'pn-when-to-escalate'
  ]::text[];
  seed_exposure_reason constant text := 'The consultant-approved permanent seed release contains reviewed internal-purpose resources and is intentionally available at the staff-facing web address without sign-in.';
  release_rows integer;
  release_items integer;
  release_item_ids text[];
begin
  select count(*), count(distinct decision.content_item_id),
    array_agg(distinct decision.content_item_id order by decision.content_item_id)
  into release_rows, release_items, release_item_ids
  from pac_dsd.publication_decisions decision
  where decision.gate_snapshot ->> 'release_id' = release_id;

  if release_rows = 0 then
    return;
  end if;
  if release_rows <> 25
    or release_items <> 25
    or release_item_ids is distinct from expected_item_ids
    or exists (
    select 1
    from pac_dsd.publication_decisions decision
    where decision.gate_snapshot ->> 'release_id' = release_id
      and (
        decision.decision <> 'publish'
        or decision.scope_id not in ('one-dhs', 'dsd')
        or decision.gate_snapshot ->> 'collection_id' <> seed_collection_id
        or decision.gate_snapshot ->> 'linked_source_item_id' <> seed_source_id
        or decision.gate_snapshot ->> 'staff_retrieval_eligible' <> 'true'
      )
  ) then
    raise exception 'The historical permanent seed release does not match its governed 25-resource boundary';
  end if;
  if not exists (
    select 1 from pac_dsd.source_items source where source.source_item_id = seed_source_id
  ) then
    raise exception 'The governed permanent seed source is missing';
  end if;

  perform pg_catalog.set_config('pac_dsd.allow_immutable_change', 'on', true);

  update pac_dsd.source_carriers carrier
  set sensitivity_class = 'S1'
  from pac_dsd.source_items source
  where source.source_item_id = seed_source_id
    and carrier.carrier_id = source.carrier_id;

  update pac_dsd.source_items
  set sensitivity_class = 'S1',
      deidentification_status = 'not_needed',
      ordinary_indexing_allowed = true,
      model_context_allowed = false
  where source_item_id = seed_source_id;

  update pac_dsd.content_items item
  set sensitivity_class = 'S1'
  where exists (
    select 1
    from pac_dsd.publication_decisions decision
    where decision.gate_snapshot ->> 'release_id' = release_id
      and decision.content_item_id = item.content_item_id
  );

  update pac_dsd.content_revisions revision
  set sensitivity_class = 'S1',
      ordinary_indexing_allowed = true,
      model_context_allowed = false,
      limitations = array['Internal-purpose staff resource; exposure approved by the governed permanent seed release.']::text[]
  where exists (
    select 1
    from pac_dsd.publication_decisions decision
    where decision.gate_snapshot ->> 'release_id' = release_id
      and decision.revision_id = revision.revision_id
  );

  if exists (
    select 1
    from pac_dsd.publication_decisions decision
    join pac_dsd.revision_sources link on link.revision_id = decision.revision_id
    join pac_dsd.source_items source on source.source_item_id = link.source_item_id
    where decision.gate_snapshot ->> 'release_id' = release_id
      and (
        source.sensitivity_class not in ('S0', 'S1')
        or source.ordinary_indexing_allowed is distinct from true
        or source.deidentification_status not in ('not_needed', 'verified')
      )
  ) or exists (
    select 1
    from pac_dsd.publication_decisions decision
    join pac_dsd.revision_assets link on link.revision_id = decision.revision_id
    join pac_dsd.assets asset on asset.asset_id = link.asset_id
    where decision.gate_snapshot ->> 'release_id' = release_id
      and asset.sensitivity_class not in ('S0', 'S1')
  ) then
    raise exception 'The governed permanent seed release contains an unclassified linked source or asset';
  end if;

  update pac_dsd.publication_decisions decision
  set sensitivity_class = 'S1',
      unauthenticated_exposure_permitted = true,
      exposure_reason = seed_exposure_reason,
      gate_snapshot = decision.gate_snapshot || jsonb_build_object(
        'sensitivity_class', 'S1',
        'ordinary_indexing_allowed', true,
        'model_context_allowed', false,
        'unauthenticated_exposure_permitted', true,
        'exposure_reason_recorded', true,
        'trust_decision_source', 'governed_seed_release'
      )
  where decision.gate_snapshot ->> 'release_id' = release_id;

  perform pg_catalog.set_config('pac_dsd.allow_immutable_change', 'off', true);

  insert into pac_dsd.change_events (
    actor_id, actor_role, scope_id, object_type, object_id, action, detail
  ) values (
    'Equity and Inclusion Operations Consultant', 'owner', 'one-dhs',
    'seed_release', release_id, 'data_trust_classified',
    jsonb_build_object(
      'resource_count', 25,
      'sensitivity_class', 'S1',
      'ordinary_indexing_allowed', true,
      'model_context_allowed', false,
      'unauthenticated_exposure_permitted', true,
      'exposure_reason', seed_exposure_reason
    )
  );
end;
$$;

revoke all privileges on function pac_dsd.assert_explicit_resource_staff_exposure(text, boolean, text) from public;
revoke execute on function pac_dsd.publish_resource_draft(text, text, uuid, bigint, text) from pac_dsd_app_runtime;
revoke execute on function pac_dsd.republish_resource_revision(text, text, uuid, bigint, text) from pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.publish_resource_draft(text, text, uuid, bigint, text, text, boolean, text) from public;
revoke all privileges on function pac_dsd.republish_resource_revision(text, text, uuid, bigint, text, text, boolean, text) from public;

grant execute on function pac_dsd.publish_resource_draft(text, text, uuid, bigint, text, text, boolean, text) to pac_dsd_app_runtime;
grant execute on function pac_dsd.republish_resource_revision(text, text, uuid, bigint, text, text, boolean, text) to pac_dsd_app_runtime;

comment on function pac_dsd.assert_explicit_resource_staff_exposure(text, boolean, text) is
  'Rejects implicit/default data classification or exposure during a staff-facing resource release.';
comment on function pac_dsd.publish_resource_draft(text, text, uuid, bigint, text, text, boolean, text) is
  'Publishes a reviewed resource only with an explicit S0/S1 classification and recorded approval for staff-facing access without sign-in.';
comment on function pac_dsd.republish_resource_revision(text, text, uuid, bigint, text, text, boolean, text) is
  'Restores only a previously classified S0/S1 revision with a new explicit staff-facing exposure decision.';


-- 0011_pac_consultation_atomic_cas.sql

-- The invalid-expiry recovery path must distinguish canonical operational
-- instants from permissive PostgreSQL timestamp inputs such as `9999`.
create or replace function pac_dsd.is_canonical_utc_instant(candidate text)
returns boolean
language plpgsql
stable
strict
set search_path = pg_catalog, pg_temp
as $$
declare
  parsed timestamptz;
begin
  if candidate !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' then
    return false;
  end if;
  begin
    parsed := candidate::timestamptz;
  exception when others then
    return false;
  end;
  return to_char(parsed at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') = candidate;
end;
$$;

-- Consultation records contain S3 material. Once a record is redacted, no
-- ordinary table update may restore the full request over its tombstone.
create or replace function pac_dsd.enforce_consultation_cas_update()
returns trigger
language plpgsql
set search_path = pg_catalog, pac_dsd
as $$
begin
  if old.work_kind = 'consult_request'
    and current_user = 'pac_dsd_app_runtime' then
    raise exception using
      errcode = '42501',
      message = 'Consultation records require the atomic lifecycle mutation function';
  end if;
  if new.work_kind is distinct from old.work_kind
    or new.object_id is distinct from old.object_id then
    raise exception using errcode = '22023', message = 'Runtime work-object identity is immutable';
  end if;
  return new;
end;
$$;

drop trigger if exists consultation_cas_update on pac_dsd.runtime_work_objects;
create trigger consultation_cas_update
before update on pac_dsd.runtime_work_objects
for each row execute function pac_dsd.enforce_consultation_cas_update();

create or replace function pac_dsd.jsonb_array_is_exact_prefix(
  current_value jsonb,
  replacement_value jsonb
)
returns boolean
language sql
immutable
set search_path = pg_catalog, pac_dsd
as $$
  with arrays as (
    select case when jsonb_typeof(current_value) = 'array' then current_value else '[]'::jsonb end as current_array,
      case when jsonb_typeof(replacement_value) = 'array' then replacement_value else '[]'::jsonb end as replacement_array
  )
  select jsonb_array_length(replacement_array) >= jsonb_array_length(current_array)
    and not exists (
      select 1
      from generate_series(0, jsonb_array_length(current_array) - 1) index_value
      where current_array -> index_value is distinct from replacement_array -> index_value
    )
  from arrays
$$;

create or replace function pac_dsd.jsonb_only_approved_keys_changed(
  current_value jsonb,
  replacement_value jsonb,
  approved_keys text[]
)
returns boolean
language sql
immutable
set search_path = pg_catalog, pac_dsd
as $$
  select jsonb_typeof(current_value) = 'object'
    and jsonb_typeof(replacement_value) = 'object'
    and not exists (
      select 1
      from (
        select key from jsonb_object_keys(current_value) current_keys(key)
        union
        select key from jsonb_object_keys(replacement_value) replacement_keys(key)
      ) keys
      where not (keys.key = any(approved_keys))
        and current_value -> keys.key is distinct from replacement_value -> keys.key
    )
$$;

create or replace function pac_dsd.consultation_packet_status_change_only(
  current_value jsonb,
  replacement_value jsonb
)
returns boolean
language sql
immutable
set search_path = pg_catalog, pac_dsd
as $$
  select current_value is not distinct from replacement_value
    or (
      jsonb_typeof(current_value) = 'object'
      and jsonb_typeof(replacement_value) = 'object'
      and jsonb_typeof(current_value -> 'snapshot') = 'object'
      and jsonb_typeof(replacement_value -> 'snapshot') = 'object'
      and current_value is not distinct from jsonb_set(
        replacement_value,
        '{snapshot,Status}',
        current_value #> '{snapshot,Status}',
        true
      )
    )
$$;

create or replace function pac_dsd.consultation_transition_is_valid(
  from_eligibility text,
  from_status text,
  to_eligibility text,
  to_status text
)
returns boolean
language sql
immutable
set search_path = pg_catalog, pac_dsd
as $$
  select row(from_eligibility, from_status) is not distinct from row(to_eligibility, to_status)
    or (
      from_eligibility = 'pending'
      and from_status = 'pending_eligibility_review'
      and (
        (to_eligibility = 'pending' and to_status = 'withdrawn')
        or (to_eligibility = 'not_dsd' and to_status = 'declined')
        or (to_eligibility = 'confirmed_dsd' and to_status in ('received', 'under_review', 'declined', 'withdrawn'))
      )
    )
    or (
      from_eligibility = 'confirmed_dsd'
      and to_eligibility = 'confirmed_dsd'
      and (
        (from_status = 'received' and to_status in ('under_review', 'declined', 'withdrawn'))
        or (from_status = 'under_review' and to_status in ('scheduled', 'declined', 'withdrawn', 'in_progress'))
        or (from_status = 'scheduled' and to_status in ('in_progress', 'completed', 'declined'))
        or (from_status = 'in_progress' and to_status in ('completed', 'declined'))
      )
    )
$$;

create or replace function pac_dsd.consultation_active_mutation_authorized(
  current_value jsonb,
  replacement_value jsonb,
  mutation_kind text,
  guard_text text
)
returns boolean
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
declare
  correction_current jsonb := case when jsonb_typeof(current_value -> 'correction_history') = 'array'
    then current_value -> 'correction_history' else '[]'::jsonb end;
  correction_next jsonb := case when jsonb_typeof(replacement_value -> 'correction_history') = 'array'
    then replacement_value -> 'correction_history' else '[]'::jsonb end;
  history_current jsonb := case when jsonb_typeof(current_value -> 'history') = 'array'
    then current_value -> 'history' else '[]'::jsonb end;
  history_next jsonb := case when jsonb_typeof(replacement_value -> 'history') = 'array'
    then replacement_value -> 'history' else '[]'::jsonb end;
  appended jsonb;
  appended_count integer;
  state_changed boolean;
  field_name text;
  entry_keys text[];
  correctable_fields constant text[] := array[
    'requester_role', 'work_name', 'stage', 'goals', 'equity_questions_considered',
    'desired_support_type', 'support_other_note', 'timing_urgency', 'deadline_date',
    'affected_populations', 'populations_note', 'access_language_needs', 'access_note',
    'preferred_meeting_mode', 'links', 'attachment_notes', 'situation'
  ];
begin
  if replacement_value ->> 'updated_at' is distinct from guard_text then
    return false;
  end if;

  if mutation_kind = 'requester_correction' then
    if not pac_dsd.jsonb_only_approved_keys_changed(current_value, replacement_value, array[
      'requester_role', 'work_name', 'stage', 'goals', 'equity_questions_considered',
      'desired_support_type', 'support_other_note', 'timing_urgency', 'deadline_date',
      'affected_populations', 'populations_note', 'access_language_needs', 'access_note',
      'preferred_meeting_mode', 'links', 'attachment_notes', 'situation',
      'priority_signals', 'packet', 'correction_history', 'updated_at', 'version'
    ])
      or current_value -> 'history' is distinct from replacement_value -> 'history'
      or not pac_dsd.jsonb_array_is_exact_prefix(correction_current, correction_next)
      or jsonb_array_length(correction_next) <> jsonb_array_length(correction_current) + 1 then
      return false;
    end if;
    appended := correction_next -> jsonb_array_length(correction_current);
    if appended ->> 'at' is distinct from guard_text
      or appended ->> 'by' <> 'requester' then
      return false;
    end if;
    foreach field_name in array correctable_fields
    loop
      if current_value -> field_name is distinct from replacement_value -> field_name
        and not (appended -> 'fields' ? field_name) then
        return false;
      end if;
    end loop;
    return true;
  end if;

  if mutation_kind = 'requester_withdrawal' then
    if not pac_dsd.jsonb_only_approved_keys_changed(current_value, replacement_value, array[
      'status', 'packet', 'history', 'updated_at', 'version'
    ])
      or current_value -> 'correction_history' is distinct from replacement_value -> 'correction_history'
      or not pac_dsd.jsonb_array_is_exact_prefix(history_current, history_next)
      or jsonb_array_length(history_next) <> jsonb_array_length(history_current) + 1
      or replacement_value ->> 'eligibility_status' is distinct from current_value ->> 'eligibility_status'
      or not pac_dsd.consultation_transition_is_valid(
        current_value ->> 'eligibility_status', current_value ->> 'status',
        replacement_value ->> 'eligibility_status', replacement_value ->> 'status'
      )
      or not pac_dsd.consultation_packet_status_change_only(current_value -> 'packet', replacement_value -> 'packet') then
      return false;
    end if;
    appended := history_next -> jsonb_array_length(history_current);
    select array_agg(key order by key) into entry_keys from jsonb_object_keys(appended) keys(key);
    return entry_keys is not distinct from array['at', 'by', 'status']::text[]
      and appended ->> 'at' is not distinct from guard_text
      and appended ->> 'by' = 'requester'
      and appended ->> 'status' = 'withdrawn';
  end if;

  if mutation_kind = 'owner_update' then
    if not pac_dsd.jsonb_only_approved_keys_changed(current_value, replacement_value, array[
      'eligibility_status', 'status', 'status_reason', 'scheduled_for', 'owner_notes',
      'pinned_order', 'packet', 'history', 'updated_at', 'version'
    ])
      or current_value -> 'correction_history' is distinct from replacement_value -> 'correction_history'
      or not pac_dsd.jsonb_array_is_exact_prefix(history_current, history_next)
      or not pac_dsd.consultation_transition_is_valid(
        current_value ->> 'eligibility_status', current_value ->> 'status',
        replacement_value ->> 'eligibility_status', replacement_value ->> 'status'
      )
      or not pac_dsd.consultation_packet_status_change_only(current_value -> 'packet', replacement_value -> 'packet') then
      return false;
    end if;
    appended_count := jsonb_array_length(history_next) - jsonb_array_length(history_current);
    state_changed := row(current_value ->> 'eligibility_status', current_value ->> 'status')
      is distinct from row(replacement_value ->> 'eligibility_status', replacement_value ->> 'status');
    if appended_count < 0 or appended_count > 2
      or (state_changed and appended_count < 1)
      or (not state_changed and appended_count <> 0) then
      return false;
    end if;
    for appended in
      select value from jsonb_array_elements(history_next) with ordinality entries(value, ordinal)
      where ordinal > jsonb_array_length(history_current)
    loop
      if appended ->> 'at' is distinct from guard_text or appended ->> 'by' <> 'owner' then
        return false;
      end if;
    end loop;
    return true;
  end if;

  if mutation_kind = 'system_packet_refresh' then
    return pac_dsd.jsonb_only_approved_keys_changed(current_value, replacement_value, array[
      'packet', 'updated_at', 'version'
    ])
      and current_value -> 'history' is not distinct from replacement_value -> 'history'
      and current_value -> 'correction_history' is not distinct from replacement_value -> 'correction_history';
  end if;

  if mutation_kind = 'system_triage' then
    if not pac_dsd.jsonb_only_approved_keys_changed(current_value, replacement_value, array[
      'status', 'pinned_order', 'packet', 'history', 'updated_at', 'version'
    ])
      or current_value -> 'correction_history' is distinct from replacement_value -> 'correction_history'
      or not pac_dsd.jsonb_array_is_exact_prefix(history_current, history_next)
      or jsonb_array_length(history_next) <> jsonb_array_length(history_current) + 1
      or current_value ->> 'eligibility_status' <> 'confirmed_dsd'
      or replacement_value ->> 'eligibility_status' <> 'confirmed_dsd'
      or not pac_dsd.consultation_packet_status_change_only(current_value -> 'packet', replacement_value -> 'packet') then
      return false;
    end if;
    appended := history_next -> jsonb_array_length(history_current);
    if appended ->> 'at' is distinct from guard_text then
      return false;
    end if;
    return current_value ->> 'status' = 'received'
      and replacement_value ->> 'status' = 'under_review'
      and appended ->> 'by' = 'system'
      and appended ->> 'status' = 'under_review';
  end if;

  return false;
end;
$$;

create or replace function pac_dsd.compare_and_swap_consultation(
  requested_object_id text,
  expected_version integer,
  expected_record_type text,
  expected_retention_expires_at text,
  mutation_kind text,
  guard_at timestamptz,
  replacement jsonb
)
returns table (applied boolean, reason text, current_value jsonb)
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  stored jsonb;
  stored_type text;
  stored_version integer;
  stored_expiry timestamptz;
  effective_guard timestamptz;
  server_now timestamptz;
  replacement_keys text[];
begin
  if requested_object_id is null or btrim(requested_object_id) = ''
    or expected_version is null or expected_version < 1
    or expected_record_type is null or expected_record_type <> 'consultation_request'
    or expected_retention_expires_at is null
    or mutation_kind is null or mutation_kind not in (
      'requester_correction', 'requester_withdrawal', 'owner_update',
      'system_packet_refresh', 'system_triage',
      'credential_rotation', 'expiry_tombstone', 'invalid_expiry_tombstone'
    )
    or guard_at is null
    or replacement is null or jsonb_typeof(replacement) <> 'object' then
    raise exception 'Invalid consultation CAS command' using errcode = '22023';
  end if;

  select work.value into stored
  from pac_dsd.runtime_work_objects work
  where work.work_kind = 'consult_request'
    and work.object_id = requested_object_id
  for update;
  if not found then
    return query select false, 'not_found'::text, null::jsonb;
    return;
  end if;

  stored_type := coalesce(stored ->> 'record_type', 'consultation_request');
  if stored_type = 'consultation_tombstone' then
    return query select false, 'tombstone'::text, stored;
    return;
  end if;

  begin
    stored_version := (stored ->> 'version')::integer;
  exception when others then
    return query select false, 'conflict'::text, stored;
    return;
  end;
  if mutation_kind = 'invalid_expiry_tombstone' then
    if pac_dsd.is_canonical_utc_instant(stored ->> 'retention_expires_at') then
      stored_expiry := (stored ->> 'retention_expires_at')::timestamptz;
      return query select false, 'conflict'::text, stored;
      return;
    else
      stored_expiry := null;
    end if;
  else
    if pac_dsd.is_canonical_utc_instant(stored ->> 'retention_expires_at') then
      stored_expiry := (stored ->> 'retention_expires_at')::timestamptz;
    else
      return query select false, 'conflict'::text, stored;
      return;
    end if;
  end if;
  server_now := clock_timestamp();
  if abs(extract(epoch from (guard_at - server_now))) > 300 then
    raise exception 'Consultation mutation timestamp is outside the server-authorized window' using errcode = '22023';
  end if;
  -- Expiry authority comes from the database clock, never the caller-provided
  -- display/audit instant. This prevents future-dated premature redaction and
  -- backdated tombstones that would immediately qualify for terminal cleanup.
  effective_guard := server_now;

  if stored_type <> expected_record_type
    or stored ->> 'request_id' is distinct from requested_object_id
    or stored_version is distinct from expected_version
    or stored ->> 'retention_expires_at' is distinct from expected_retention_expires_at
    or replacement ->> 'request_id' is distinct from requested_object_id
    or (replacement ->> 'version')::integer is distinct from expected_version + 1
    or (
      mutation_kind = 'invalid_expiry_tombstone'
      and (replacement ->> 'retention_expires_at')::timestamptz is distinct from guard_at
    )
    or (
      mutation_kind <> 'invalid_expiry_tombstone'
      and replacement ->> 'retention_expires_at' is distinct from expected_retention_expires_at
    )
    or (
      mutation_kind <> 'credential_rotation'
      and replacement ->> 'access_key_hash' is distinct from stored ->> 'access_key_hash'
    )
    or replacement ->> 'access_key_version' is distinct from stored ->> 'access_key_version'
    or replacement ->> 'retention_policy_id' is distinct from stored ->> 'retention_policy_id' then
    return query select false, 'conflict'::text, stored;
    return;
  end if;

  if mutation_kind in (
    'requester_correction', 'requester_withdrawal', 'owner_update',
    'system_packet_refresh', 'system_triage',
    'credential_rotation'
  ) then
    if stored_expiry <= effective_guard then
      return query select false, 'expired'::text, stored;
      return;
    end if;
    if coalesce(replacement ->> 'record_type', 'consultation_request') <> 'consultation_request'
      or replacement ->> 'status' = 'expired'
      or replacement ->> 'sensitivity_class' <> 'S3'
      or replacement ? 'redacted_at' then
      raise exception 'Invalid active consultation replacement' using errcode = '22023';
    end if;
    if mutation_kind = 'credential_rotation' then
      if replacement ->> 'access_key_hash' = stored ->> 'access_key_hash'
        or replacement ->> 'access_key_hash' !~ '^[a-f0-9]{64}$'
        or not pac_dsd.is_canonical_utc_instant(replacement ->> 'updated_at')
        or replacement ->> 'updated_at' is distinct from
          to_char(guard_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
        or (replacement - 'access_key_hash' - 'updated_at' - 'version')
          is distinct from (stored - 'access_key_hash' - 'updated_at' - 'version') then
        raise exception 'Invalid consultation credential rotation' using errcode = '22023';
      end if;
    elsif not pac_dsd.consultation_active_mutation_authorized(
      stored,
      replacement,
      mutation_kind,
      to_char(guard_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
    ) then
      raise exception 'Consultation mutation exceeds its authority' using errcode = '22023';
    end if;
  else
    if mutation_kind = 'expiry_tombstone' and stored_expiry > effective_guard then
      return query select false, 'conflict'::text, stored;
      return;
    end if;
    select array_agg(key order by key) into replacement_keys
    from jsonb_object_keys(replacement) keys(key);
    if replacement ->> 'record_type' <> 'consultation_tombstone'
      or replacement ->> 'status' <> 'expired'
      or (replacement ->> 'redacted_at')::timestamptz is distinct from guard_at
      or (replacement ->> 'updated_at')::timestamptz is distinct from guard_at
      or (
        mutation_kind = 'invalid_expiry_tombstone'
        and (replacement ->> 'retention_expires_at')::timestamptz is distinct from guard_at
      )
      or replacement_keys is distinct from array[
        'access_key_hash', 'access_key_version', 'record_type', 'redacted_at',
        'request_id', 'retention_expires_at', 'retention_policy_id', 'status',
        'updated_at', 'version'
      ]::text[] then
      raise exception 'Invalid consultation tombstone replacement' using errcode = '22023';
    end if;
  end if;

  perform pac_dsd.assert_no_prohibited_profile_fields(replacement);
  update pac_dsd.runtime_work_objects work
  set value = replacement,
      updated_at = clock_timestamp()
  where work.work_kind = 'consult_request'
    and work.object_id = requested_object_id
    and coalesce(work.value ->> 'record_type', 'consultation_request') = expected_record_type
    and (work.value ->> 'version')::integer = expected_version
    and work.value ->> 'retention_expires_at' = expected_retention_expires_at
  returning work.value into stored;

  if not found then
    return query select false, 'conflict'::text, null::jsonb;
    return;
  end if;
  return query select true, 'applied'::text, stored;
end;
$$;

revoke all privileges on function pac_dsd.enforce_consultation_cas_update() from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.is_canonical_utc_instant(text) from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.jsonb_array_is_exact_prefix(jsonb, jsonb) from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.jsonb_only_approved_keys_changed(jsonb, jsonb, text[]) from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.consultation_packet_status_change_only(jsonb, jsonb) from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.consultation_transition_is_valid(text, text, text, text) from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.consultation_active_mutation_authorized(jsonb, jsonb, text, text) from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.compare_and_swap_consultation(text, integer, text, text, text, timestamptz, jsonb) from public;
grant execute on function pac_dsd.compare_and_swap_consultation(text, integer, text, text, text, timestamptz, jsonb) to pac_dsd_app_runtime;

comment on function pac_dsd.compare_and_swap_consultation(text, integer, text, text, text, timestamptz, jsonb) is
  'Atomic consultation lifecycle mutation with version, record-type, retention-expiry, immutable identity, and tombstone-shape guards.';


-- 0012_pac_no_surveillance_contracts.sql

-- Expand the semantic field-name backstop without treating ordinary content
-- quality or evaluation scores as employee measures. Keys are compacted first,
-- so snake case, camel case, punctuation, spaces, and acronym casing behave the
-- same way at the database boundary.
create or replace function pac_dsd.assert_no_prohibited_profile_fields(payload jsonb)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
declare
  item record;
  normalized_key text;
begin
  if payload is null then
    return;
  end if;

  if jsonb_typeof(payload) = 'object' then
    for item in select key, value from jsonb_each(payload)
    loop
      normalized_key := lower(regexp_replace(item.key, '[^A-Za-z0-9]+', '', 'g'));
      if normalized_key = any(array[
        'beliefprofile',
        'beliefsbyworker',
        'completionbystaff',
        'compliancescore',
        'culturalcompetencescore',
        'deiscore',
        'employeeequityscore',
        'employeeequityreadiness',
        'employeeideology',
        'employeeprofile',
        'ideologybyemployee',
        'equitymaturityscore',
        'equityreadinessrating',
        'equityscore',
        'ideologyscore',
        'inferreddisability',
        'inferredethnicity',
        'inferredgenderidentity',
        'inferredprotectedclass',
        'inferredrace',
        'learningcompliancescore',
        'learningprogressbyemployee',
        'participationbyemployee',
        'participationleaderboard',
        'politicalbeliefs',
        'racialbiasscore',
        'staffinclusionranking',
        'supervisorparticipationdashboard',
        'supervisorparticipationscore',
        'workerinclusionmaturityscore'
      ])
      or normalized_key ~ '^(racialbias|equityreadiness|deireadiness|culturalcompetence|equitymaturity|inclusionmaturity)(score|rating|ranking|rank|profile)$'
      or normalized_key ~ '^(political|religious|ideological)(belief|beliefs|affiliation|affiliations|profile)$'
      or normalized_key ~ '^(belief|beliefs|ideology|ideologies|learningprogress|trainingprogress|learningcompletion|trainingcompletion|coursecompletion|completion|activity)(by|per)(employee|staff|worker|person|individual|member|user|supervisor)$'
      or normalized_key ~ '^(participation|engagement)(by|per)(employee|staff|worker|person|individual|member|user|supervisor)$'
      or normalized_key ~ '^(employee|staff|worker|personnel|supervisor)(equity|dei|ideology|inclusion|bias|participation|engagement|culturalcompetence)(score|rating|ranking|rank|profile|dashboard|leaderboard)$'
      or normalized_key ~ '^(employee|staff|worker|personnel|supervisor)(equityreadiness|inclusionmaturity|learningprogress|completion|activity)(score|rating|ranking|rank|profile|dashboard|leaderboard)?$'
      or normalized_key ~ '^(inferred|predicted|estimated|guessed)(race|ethnicity|genderidentity|disability|protectedclass|politicalbelief|politicalbeliefs|religion)$'
      then
        raise exception using
          errcode = '22023',
          message = 'Prohibited employee-profile field';
      end if;
      perform pac_dsd.assert_no_prohibited_profile_fields(item.value);
    end loop;
  elsif jsonb_typeof(payload) = 'array' then
    for item in select value from jsonb_array_elements(payload)
    loop
      perform pac_dsd.assert_no_prohibited_profile_fields(item.value);
    end loop;
  end if;
end;
$$;

-- Upgrade every JSON-bearing persistence carrier to the same DEC-014
-- backstop. Validate existing rows before installing the trigger so an older
-- unguarded metadata column cannot carry a hidden staff profile forward.
do $$
declare
  table_name text;
begin
  for table_name in
    select columns.table_name
    from information_schema.columns columns
    join information_schema.tables tables
      on tables.table_schema = columns.table_schema
      and tables.table_name = columns.table_name
    where columns.table_schema = 'pac_dsd'
      and columns.udt_name = 'jsonb'
      and tables.table_type = 'BASE TABLE'
    group by columns.table_name
  loop
    execute format(
      'select pac_dsd.assert_no_prohibited_profile_fields(to_jsonb(row_value)) from pac_dsd.%I row_value',
      table_name
    );
    execute format('drop trigger if exists no_prohibited_profile_fields on pac_dsd.%I', table_name);
    execute format(
      'create trigger no_prohibited_profile_fields before insert or update on pac_dsd.%I for each row execute function pac_dsd.reject_prohibited_profile_row()',
      table_name
    );
  end loop;
end;
$$;

create or replace function pac_dsd.assert_allowed_jsonb_keys(
  payload jsonb,
  allowed_keys text[]
)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
begin
  if payload is null or jsonb_typeof(payload) <> 'object'
    or exists (
      select 1
      from jsonb_object_keys(payload) keys(key)
      where not (key = any(allowed_keys))
    ) then
    raise exception using
      errcode = '22023',
      message = 'Work object does not match an approved persistence contract';
  end if;
end;
$$;

-- Collaboration is open-ended human text, so key allowlists alone cannot stop
-- the workspace from becoming a staff-ranking request channel. Reject text
-- only when it combines a surveillance action, people, and a sensitive
-- learning/equity measure; ordinary invitations to participate remain valid.
create or replace function pac_dsd.assert_no_collaboration_surveillance_text(payload jsonb)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
declare
  item record;
  text_value text;
begin
  if payload is null then
    return;
  end if;
  if jsonb_typeof(payload) = 'string' then
    text_value := payload #>> '{}';
    if text_value ~* '\m(staff|employee|employees|worker|workers|personnel|supervisor|supervisors|person|people|individual|individuals|member|members|coworker|coworkers|colleague|colleagues|manager|managers)\M'
      and text_value ~* '\m(equity|dei|inclusive|inclusion|maturity|readiness|bias|belief|beliefs|ideology|participation|engagement|learning|training|course[- ]completion|completion|activity|behavior|cultural|culturally|competence|competency|competent|capability|capable)\M'
      and (
        text_value ~* '\m(rank|ranking|score|scoring|scorecard|leaderboard|grade|rate|rating|profile|profiling|compare|classify|categorize|order|sort|arrange|assign|stratify|cluster|quartile|quartiles|tier|tiers|bucket|buckets|segment|segments|label|labels)\M'
        or text_value ~* '\m(most|least|more|less|highest|lowest|furthest|farthest|best|worst|top|bottom)\M'
        or text_value ~* '\m(based on|on the basis of|according to)\M'
        or (
          text_value ~* '\m(chart|evaluate|assess|monitor|track|report|sequence|band|group|place|map|determine|identify|create|summarize|show|showing|display|list|listing|measure|analyze)\M'
          and (
            text_value ~* '\m(each|every|individual|per|which)\M.{0,30}\m(staff|staff members|employee|employees|worker|workers|personnel|person|persons|member|members|supervisor|supervisors)\M'
            or text_value ~* '\m(staff|employees|workers|members|supervisors)\M([''’]s|s[''’])'
            or text_value ~* '\m(employee-by-employee|staff-level|employee-level|worker-level|person-level)\M'
            or text_value ~* '\m(by|per)\M[ ]+(each[ ]+|individual[ ]+)?\m(staff|employee|worker|person|member|supervisor)\M'
            or text_value ~* '\mfor\M[ ]+(each[ ]+|every[ ]+|their[ ]+|the[ ]+)?\m(staff|employee|worker|person|member|supervisor)\M'
          )
        )
        or (
          text_value ~* '\m(matrix|dashboard|dashboards|index|quartile|quartiles|heatmap|heat map|roster|rosters|report|reports)\M'
          and (
            text_value ~* '\m(each|every|individual|per|which)\M.{0,30}\m(staff|staff members|employee|employees|worker|workers|personnel|person|persons|member|members|supervisor|supervisors)\M'
            or text_value ~* '\m(staff|employees|workers|members|supervisors)\M([''’]s|s[''’])'
            or text_value ~* '\m(employee-by-employee|staff-level|employee-level|worker-level|person-level)\M'
            or text_value ~* '\m(by|per)\M[ ]+(each[ ]+|individual[ ]+)?\m(staff|employee|worker|person|member|supervisor)\M'
            or text_value ~* '\mfor\M[ ]+(each[ ]+|every[ ]+|their[ ]+|the[ ]+)?\m(staff|employee|worker|person|member|supervisor)\M'
            or text_value ~* '\m(for|to|with)\M[ ]+(the[ ]+)?\m(supervisor|supervisors|manager|managers|management)\M'
          )
        )
        or (
          text_value ~* '\m(develop|produce|build|provide|make|give|generate|create)\M'
          and text_value ~* '\m(matrix|dashboard|dashboards|index|quartile|quartiles|heatmap|heat map|roster|rosters|report|reports)\M'
        )
      ) then
      raise exception 'Collaboration text requests prohibited staff surveillance' using errcode = '22023';
    end if;
  elsif jsonb_typeof(payload) = 'object' then
    for item in select value from jsonb_each(payload)
    loop
      perform pac_dsd.assert_no_collaboration_surveillance_text(item.value);
    end loop;
  elsif jsonb_typeof(payload) = 'array' then
    for item in select value from jsonb_array_elements(payload)
    loop
      perform pac_dsd.assert_no_collaboration_surveillance_text(item.value);
    end loop;
  end if;
end;
$$;

create or replace function pac_dsd.assert_jsonb_string_array(
  payload jsonb,
  allowed_values text[] default null
)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
declare
  item jsonb;
begin
  if payload is null or jsonb_typeof(payload) <> 'array' then
    raise exception 'Expected a JSON string array' using errcode = '22023';
  end if;
  for item in select value from jsonb_array_elements(payload)
  loop
    if jsonb_typeof(item) <> 'string'
      or (allowed_values is not null and not ((item #>> '{}') = any(allowed_values))) then
      raise exception 'Expected a JSON string array' using errcode = '22023';
    end if;
  end loop;
end;
$$;

-- JSON text extraction deliberately stringifies objects and arrays. Every
-- allowlisted scalar therefore receives an explicit JSON type check before it
-- can cross the generic persistence boundary.
create or replace function pac_dsd.assert_jsonb_scalar_types(
  payload jsonb,
  string_keys text[],
  boolean_keys text[],
  number_keys text[]
)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
declare
  field_name text;
begin
  if payload is null or jsonb_typeof(payload) <> 'object' then
    raise exception 'Expected a JSON object' using errcode = '22023';
  end if;
  foreach field_name in array string_keys
  loop
    if payload ? field_name and jsonb_typeof(payload -> field_name) <> 'string' then
      raise exception 'Expected a JSON string scalar' using errcode = '22023';
    end if;
  end loop;
  foreach field_name in array boolean_keys
  loop
    if payload ? field_name and jsonb_typeof(payload -> field_name) <> 'boolean' then
      raise exception 'Expected a JSON boolean scalar' using errcode = '22023';
    end if;
  end loop;
  foreach field_name in array number_keys
  loop
    if payload ? field_name and jsonb_typeof(payload -> field_name) <> 'number' then
      raise exception 'Expected a JSON number scalar' using errcode = '22023';
    end if;
  end loop;
end;
$$;

create or replace function pac_dsd.jsonb_is_safe_integer(payload jsonb, minimum_value numeric default null)
returns boolean
language sql
immutable
set search_path = pg_catalog, pac_dsd
as $$
  select jsonb_typeof(payload) = 'number'
    and (payload #>> '{}') ~ '^-?(0|[1-9][0-9]*)$'
    and abs((payload #>> '{}')::numeric) <= 9007199254740991
    and (minimum_value is null or (payload #>> '{}')::numeric >= minimum_value)
$$;

create or replace function pac_dsd.jsonb_is_instant(payload jsonb)
returns boolean
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
begin
  if jsonb_typeof(payload) <> 'string' or coalesce(payload #>> '{}', '') = '' then
    return false;
  end if;
  perform (payload #>> '{}')::timestamptz;
  return true;
exception when others then
  return false;
end;
$$;

create or replace function pac_dsd.jsonb_is_canonical_utc_instant(payload jsonb)
returns boolean
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
declare
  candidate text;
  parsed timestamptz;
begin
  if jsonb_typeof(payload) <> 'string' then
    return false;
  end if;
  candidate := payload #>> '{}';
  if candidate !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' then
    return false;
  end if;
  parsed := candidate::timestamptz;
  return to_char(parsed at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') = candidate;
exception when others then
  return false;
end;
$$;

create or replace function pac_dsd.assert_agent_override_contract(payload jsonb)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
declare
  entry record;
begin
  if payload is null or jsonb_typeof(payload) <> 'object' then
    raise exception 'Invalid agent policy overrides' using errcode = '22023';
  end if;
  for entry in select key, value from jsonb_each(payload)
  loop
    if entry.key <> all(array[
      'program_orchestrator', 'ask_concierge', 'ci_guide', 'librarian',
      'a11y_reviewer', 'consult_intake', 'graduation_coach', 'embed_advisor',
      'content_sentinel', 'eval_steward'
    ]) or jsonb_typeof(entry.value) <> 'object' then
      raise exception 'Unknown or invalid agent policy override' using errcode = '22023';
    end if;
    perform pac_dsd.assert_allowed_jsonb_keys(entry.value, array['enabled', 'ceiling']);
    perform pac_dsd.assert_jsonb_scalar_types(entry.value, array['ceiling'], array['enabled'], array[]::text[]);
    if entry.value ? 'ceiling'
      and entry.value ->> 'ceiling' not in ('A0', 'A1', 'A2', 'A3', 'A4', 'A5') then
      raise exception 'Unknown or invalid agent policy override' using errcode = '22023';
    end if;
  end loop;
end;
$$;

create or replace function pac_dsd.assert_flag_override_contract(payload jsonb)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
declare
  entry record;
begin
  if payload is null or jsonb_typeof(payload) <> 'object' then
    raise exception 'Invalid feature flag overrides' using errcode = '22023';
  end if;
  for entry in select key, value from jsonb_each(payload)
  loop
    if entry.key <> all(array[
      'agent.content_sentinel', 'agent.eval_steward_write',
      'model.generative_pilot', 'autonomy.a3_calendar_schedule',
      'autonomy.a3_stale_flag', 'tool.browser_fetch_public',
      'tool.office_drafts', 'tool.publish_chain',
      'surface.ecosystem_intelligence'
    ]) or jsonb_typeof(entry.value) <> 'boolean' then
      raise exception 'Unknown or invalid feature flag override' using errcode = '22023';
    end if;
  end loop;
end;
$$;

create or replace function pac_dsd.assert_policy_patch_contract(payload jsonb)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
begin
  perform pac_dsd.assert_allowed_jsonb_keys(payload, array['max_autonomy', 'flags', 'agents']);
  perform pac_dsd.assert_jsonb_scalar_types(payload, array['max_autonomy'], array[]::text[], array[]::text[]);
  if payload ? 'max_autonomy'
    and payload ->> 'max_autonomy' not in ('A0', 'A1', 'A2', 'A3', 'A4', 'A5') then
    raise exception 'Invalid policy patch' using errcode = '22023';
  end if;
  if payload ? 'flags' then
    perform pac_dsd.assert_flag_override_contract(payload -> 'flags');
  end if;
  if payload ? 'agents' then
    perform pac_dsd.assert_agent_override_contract(payload -> 'agents');
  end if;
end;
$$;

create or replace function pac_dsd.assert_proposal_contract(payload jsonb)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
begin
  perform pac_dsd.assert_allowed_jsonb_keys(payload, array[
    'id', 'cycle_id', 'kind', 'title', 'rationale', 'apply', 'status',
    'created_at', 'decided_at', 'decision_note'
  ]);
  if not (payload ?& array['id', 'cycle_id', 'kind', 'title', 'rationale', 'status', 'created_at']) then
    raise exception 'Invalid proposal decision contract' using errcode = '22023';
  end if;
  perform pac_dsd.assert_jsonb_scalar_types(payload, array[
    'id', 'cycle_id', 'kind', 'title', 'rationale', 'status', 'created_at',
    'decided_at', 'decision_note'
  ], array[]::text[], array[]::text[]);
  if payload ->> 'id' !~ '^cycle-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}-[pg][1-9][0-9]*$'
    or payload ->> 'cycle_id' !~ '^cycle-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or payload ->> 'id' !~ ('^' || (payload ->> 'cycle_id') || '-[pg][1-9][0-9]*$')
    or payload ->> 'kind' not in (
      'enable_model', 'review_brief', 'retire_content', 'raise_autonomy',
      'lower_autonomy', 'content_gap', 'capacity', 'other'
    )
    or coalesce(payload ->> 'title', '') = ''
    or coalesce(payload ->> 'rationale', '') = ''
    or payload ->> 'status' not in ('proposed', 'accepted', 'rejected')
    or coalesce(payload ->> 'created_at', '') = '' then
    raise exception 'Invalid proposal decision contract' using errcode = '22023';
  end if;
  if payload ? 'apply' then
    perform pac_dsd.assert_policy_patch_contract(payload -> 'apply');
  end if;
end;
$$;

create or replace function pac_dsd.assert_consultation_owner_text_safe(candidate jsonb)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
declare
  value_text text;
  name_scan text;
begin
  if jsonb_typeof(candidate) <> 'string' then
    raise exception 'Invalid consultation owner text' using errcode = '22023';
  end if;
  perform pac_dsd.assert_no_collaboration_surveillance_text(candidate);
  value_text := candidate #>> '{}';
  name_scan := regexp_replace(
    value_text,
    '\m(Minnesota Department of Human Services|Aging and Disability Services Administration|Disability Services Division|Office of Indian Policy|Human Resources|Employee Culture|Civil Rights|Equity Director|Equity Specialist|Program Steward|Practice Owner|One DHS|One DSD)\M',
    ' ',
    'gi'
  );
  if value_text ~* '[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}'
    or value_text ~ '\m[0-9]{3}-[0-9]{2}-[0-9]{4}\M'
    or value_text ~ '\m[0-9]{3}[-. ][0-9]{3}[-. ][0-9]{4}\M'
    or value_text ~* '\m(employee|staff|worker|personnel)[[:space:]]*(id|number|no\.?|#)[[:space:]#:]*[A-Z0-9-]{3,}\M'
    or value_text ~* '\m(case|claim|client|PMI|MA|MAXIS|MMIS|MnCHOICES|recipient|member)[[:space:]]*(id|number|no\.?|#)[[:space:]#:]*[A-Z]?[0-9]{4,}\M'
    or value_text ~* '\m(date of birth|DOB)[[:space:]:]*[0-9]{1,2}[/\-][0-9]{1,2}[/\-][0-9]{2,4}\M'
    or name_scan ~ '\m[A-Z][[:alpha:]''’-]{1,40}[[:space:]]+[A-Z][[:alpha:]''’-]{1,40}\M'
    or name_scan ~* '\m(by|with|from|contact|email|call|ask)[[:space:]]+[[:alpha:]''’-]{2,40}[[:space:]]+[[:alpha:]''’-]{2,40}\M'
    or name_scan ~* '\m(assigned[[:space:]]+to|reviewed[[:space:]]+by|prepared[[:space:]]+by|submitted[[:space:]]+by|approved[[:space:]]+by|written[[:space:]]+by|met[[:space:]]+with|sent[[:space:]]+to|forwarded[[:space:]]+to)[[:space:]]+[[:alpha:]''’-]{2,40}[[:space:]]+[[:alpha:]''’-]{2,40}\M'
    or name_scan ~* '\m[[:alpha:]][.][[:space:]]+[[:alpha:]''’-]{2,40}\M'
    or name_scan ~* '\m[[:alpha:]''’-]{2,40},[[:space:]]+[[:alpha:]''’-]{2,40}\M'
    or name_scan ~* '\m[[:alpha:]''’-]{1,40}[[:space:]]+[[:alpha:]''’-]{2,40}[[:space:]]+(will|can|should|must|is|was|has|had)[[:space:]]+(review|contact|call|email|prepare|submit|approve|write|meet|send|forward)\M'
    or name_scan ~* '\m(waiting[[:space:]]+for|coordinate[[:space:]]+through|escalate([[:space:]]+this|[[:space:]]+the)?([[:space:]]+matter|[[:space:]]+request)?[[:space:]]+to|reviewer[[:space:]]+is|reviewer:)[[:space:]]+[[:alpha:]''’-]{1,40}[[:space:]]+[[:alpha:]''’-]{2,40}\M'
    or name_scan ~* '(^|[.!?][[:space:]]+)[[:alpha:]''’-]{1,40}[[:space:]]+[[:alpha:]''’-]{2,40}[[:space:]]+(is|was|has|had|will|can|should|must|owns|holds|keeps|attended|reviewed|prepared|submitted|approved|wrote|met|sent|forwarded)[[:space:]]'
    or (
      value_text ~* '\m(my|our|this|the|a|an)[[:space:]]+(client|patient|participant|recipient|resident|member|employee|coworker|co-worker|colleague|supervisor|manager|staff member|worker|caseworker)\M'
      and value_text ~* '\m(diagnosis|diagnosed|medical|medication|hospitalized|disability|accommodation|eligibility|benefits|waiver|case|claim|assessment|complaint|grievance|investigation|discipline|termination|harassment|performance review|PIP)\M'
    )
    or value_text ~* '\m(complaint|grievance)[[:space:]]+(about|against)\M'
    or value_text ~* '\m(investigate|investigation|discipline|disciplinary action|write-up|terminate|demote|suspend)[[:space:]]+(my|a|the|this|our)?[[:space:]]*(coworker|co-worker|colleague|employee|supervisor|manager|staff|person)\M' then
    raise exception 'Consultation owner text contains private person details' using errcode = '22023';
  end if;
end;
$$;

create or replace function pac_dsd.assert_runtime_work_object_contract(
  requested_kind text,
  requested_object_id text,
  payload jsonb
)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
declare
  entry record;
  nested_entry record;
  collection_name text;
  collection_keys text[];
begin
  perform pac_dsd.assert_no_prohibited_profile_fields(payload);
  if requested_object_id is null or btrim(requested_object_id) = ''
    or length(requested_object_id) > 180
    or payload is null or jsonb_typeof(payload) <> 'object' then
    raise exception 'Work object does not match an approved persistence contract' using errcode = '22023';
  end if;

  if requested_kind = 'consult_request' then
    if payload ->> 'record_type' = 'consultation_tombstone' then
      perform pac_dsd.assert_allowed_jsonb_keys(payload, array[
        'record_type', 'request_id', 'status', 'access_key_hash',
        'access_key_version', 'retention_policy_id', 'retention_expires_at',
        'redacted_at', 'updated_at', 'version'
      ]);
      perform pac_dsd.assert_jsonb_scalar_types(
        payload,
        array[
          'record_type', 'request_id', 'status', 'access_key_hash',
          'access_key_version', 'retention_policy_id', 'retention_expires_at',
          'redacted_at', 'updated_at'
        ],
        array[]::text[],
        array['version']
      );
      if not (payload ?& array[
        'record_type', 'request_id', 'status', 'access_key_hash',
        'access_key_version', 'retention_policy_id', 'retention_expires_at',
        'redacted_at', 'updated_at', 'version'
      ])
        or payload ->> 'request_id' is distinct from requested_object_id
        or payload ->> 'status' <> 'expired'
        or payload ->> 'access_key_hash' !~ '^[a-f0-9]{64}$'
        or payload ->> 'access_key_version' <> 'sha256-v1'
        or coalesce(payload ->> 'retention_policy_id', '') = ''
        or not pac_dsd.jsonb_is_canonical_utc_instant(payload -> 'retention_expires_at')
        or not pac_dsd.jsonb_is_canonical_utc_instant(payload -> 'redacted_at')
        or not pac_dsd.jsonb_is_canonical_utc_instant(payload -> 'updated_at')
        or not pac_dsd.jsonb_is_safe_integer(payload -> 'version', 2) then
        raise exception 'Invalid consultation tombstone persistence contract' using errcode = '22023';
      end if;
      return;
    end if;

    perform pac_dsd.assert_no_collaboration_surveillance_text(payload);
    perform pac_dsd.assert_allowed_jsonb_keys(payload, array[
      'record_type', 'request_id', 'access_key_hash', 'access_key_version',
      'sensitivity_class', 'participation_class', 'official_record',
      'eligibility_status', 'participation_acknowledged_at',
      'retention_policy_id', 'retention_expires_at', 'submission_fingerprint',
      'created_at', 'updated_at', 'version', 'status', 'status_reason',
      'scheduled_for', 'owner_notes', 'pinned_order', 'priority_signals',
      'packet', 'correction_history', 'history', 'program_context',
      'dsd_eligibility_attestation', 'requester_role', 'work_name', 'stage',
      'goals', 'equity_questions_considered', 'desired_support_type',
      'support_other_note', 'timing_urgency', 'deadline_date',
      'affected_populations', 'populations_note', 'access_language_needs',
      'access_note', 'preferred_meeting_mode', 'links', 'attachment_notes',
      'situation', 'ask_context', 'path_id', 'participation_notice_id',
      'participation_notice_version', 'share_confirmation'
    ]);
    perform pac_dsd.assert_jsonb_scalar_types(
      payload,
      array[
        'record_type', 'request_id', 'access_key_hash', 'access_key_version',
        'sensitivity_class', 'participation_class', 'eligibility_status',
        'participation_acknowledged_at', 'retention_policy_id',
        'retention_expires_at', 'submission_fingerprint', 'created_at',
        'updated_at', 'status', 'status_reason', 'scheduled_for', 'owner_notes',
        'program_context', 'requester_role', 'work_name', 'stage', 'goals',
        'equity_questions_considered', 'support_other_note', 'timing_urgency',
        'deadline_date', 'populations_note', 'access_note',
        'preferred_meeting_mode', 'attachment_notes', 'situation', 'path_id',
        'participation_notice_id', 'participation_notice_version'
      ],
      array['official_record', 'dsd_eligibility_attestation', 'share_confirmation'],
      array['version', 'pinned_order']
    );
    if not (payload ?& array[
      'record_type', 'request_id', 'access_key_hash', 'access_key_version',
      'sensitivity_class', 'participation_class', 'official_record',
      'eligibility_status', 'participation_acknowledged_at',
      'retention_policy_id', 'retention_expires_at', 'submission_fingerprint',
      'created_at', 'updated_at', 'version', 'status', 'priority_signals',
      'packet', 'history', 'program_context', 'dsd_eligibility_attestation',
      'work_name', 'stage', 'goals', 'equity_questions_considered',
      'desired_support_type', 'support_other_note', 'timing_urgency',
      'deadline_date', 'affected_populations', 'populations_note',
      'access_language_needs', 'access_note', 'links', 'attachment_notes',
      'situation', 'participation_notice_id', 'participation_notice_version',
      'share_confirmation'
    ])
      or payload ->> 'record_type' <> 'consultation_request'
      or payload ->> 'request_id' is distinct from requested_object_id
      or requested_object_id !~ '^CR-[0-9]{8}-[0-9]{4,10}$'
      or payload ->> 'access_key_hash' !~ '^[a-f0-9]{64}$'
      or payload ->> 'access_key_version' <> 'sha256-v1'
      or payload ->> 'sensitivity_class' <> 'S3'
      or payload ->> 'participation_class' <> 'voluntary_shared'
      or payload -> 'official_record' <> 'false'::jsonb
      or payload ->> 'eligibility_status' not in ('pending', 'confirmed_dsd', 'not_dsd')
      or payload ->> 'status' not in (
        'pending_eligibility_review', 'received', 'under_review', 'scheduled',
        'in_progress', 'completed', 'declined', 'withdrawn'
      )
      or not (
        (payload ->> 'eligibility_status' = 'pending' and payload ->> 'status' in ('pending_eligibility_review', 'withdrawn'))
        or (payload ->> 'eligibility_status' = 'confirmed_dsd' and payload ->> 'status' in ('received', 'under_review', 'scheduled', 'in_progress', 'completed', 'declined', 'withdrawn'))
        or (payload ->> 'eligibility_status' = 'not_dsd' and payload ->> 'status' = 'declined')
      )
      or (payload ->> 'status' = 'scheduled' and not (
        payload ? 'scheduled_for' and pac_dsd.jsonb_is_instant(payload -> 'scheduled_for')
      ))
      or (payload ->> 'status' = 'declined' and btrim(coalesce(payload ->> 'status_reason', '')) = '')
      or not pac_dsd.jsonb_is_canonical_utc_instant(payload -> 'participation_acknowledged_at')
      or coalesce(payload ->> 'retention_policy_id', '') = ''
      or not pac_dsd.jsonb_is_canonical_utc_instant(payload -> 'retention_expires_at')
      or payload ->> 'submission_fingerprint' !~ '^[a-f0-9]{64}$'
      or not pac_dsd.jsonb_is_canonical_utc_instant(payload -> 'created_at')
      or not pac_dsd.jsonb_is_canonical_utc_instant(payload -> 'updated_at')
      or not pac_dsd.jsonb_is_safe_integer(payload -> 'version', 1)
      or payload ->> 'program_context' <> 'one_dsd'
      or payload -> 'dsd_eligibility_attestation' <> 'true'::jsonb
      or payload ->> 'stage' not in ('conceptual', 'designing', 'launching', 'live_change')
      or coalesce(payload ->> 'work_name', '') = ''
      or coalesce(payload ->> 'goals', '') = ''
      or jsonb_typeof(payload -> 'equity_questions_considered') <> 'string'
      or jsonb_typeof(payload -> 'support_other_note') <> 'string'
      or payload ->> 'timing_urgency' not in ('exploratory', 'within_2_weeks', 'hard_deadline', 'live_urgent')
      or jsonb_typeof(payload -> 'deadline_date') <> 'string'
      or jsonb_typeof(payload -> 'populations_note') <> 'string'
      or jsonb_typeof(payload -> 'access_note') <> 'string'
      or jsonb_typeof(payload -> 'attachment_notes') <> 'string'
      or coalesce(payload ->> 'situation', '') = ''
      or payload ->> 'participation_notice_id' <> 'dsd_consultation_request'
      or payload ->> 'participation_notice_version' <> '1.0.0'
      or payload -> 'share_confirmation' <> 'true'::jsonb
      or (payload ? 'requester_role' and payload ->> 'requester_role' not in ('program_ops', 'supervisor', 'equity_director_specialist', 'analyst_tech', 'communications', 'procurement_contracts', 'other'))
      or (payload ? 'preferred_meeting_mode' and payload ->> 'preferred_meeting_mode' not in ('in_person', 'virtual', 'either', 'not_sure'))
      or (payload ? 'scheduled_for' and not pac_dsd.jsonb_is_instant(payload -> 'scheduled_for'))
      or (payload ? 'pinned_order' and not pac_dsd.jsonb_is_safe_integer(payload -> 'pinned_order')) then
      raise exception 'Invalid consultation request persistence contract' using errcode = '22023';
    end if;

    perform pac_dsd.assert_jsonb_string_array(payload -> 'desired_support_type', array[
      'scoping_goals', 'equity_embed_review', 'access_language_check',
      'stakeholder_partner_map', 'facilitation_prep', 'other'
    ]);
    perform pac_dsd.assert_jsonb_string_array(payload -> 'affected_populations', array[
      'language_access_needs', 'disability_access', 'rural_greater_minnesota',
      'older_adults', 'children_families', 'immigrant_refugee_general',
      'specific_minnesota_community', 'tribal_nation'
    ]);
    perform pac_dsd.assert_jsonb_string_array(payload -> 'access_language_needs', array[
      'interpreter_for_consult', 'captioning', 'plain_language_materials',
      'timing_constraints', 'other'
    ]);
    perform pac_dsd.assert_jsonb_string_array(payload -> 'links');
    if payload ? 'status_reason' then
      perform pac_dsd.assert_consultation_owner_text_safe(payload -> 'status_reason');
    end if;
    if payload ? 'owner_notes' then
      perform pac_dsd.assert_consultation_owner_text_safe(payload -> 'owner_notes');
    end if;

    if payload ? 'ask_context' then
      perform pac_dsd.assert_allowed_jsonb_keys(payload -> 'ask_context', array['session_id', 'intents_tried', 'excerpt']);
      if not (payload -> 'ask_context' ?& array['session_id', 'intents_tried', 'excerpt'])
        or jsonb_typeof(payload -> 'ask_context' -> 'session_id') <> 'string'
        or coalesce(payload -> 'ask_context' ->> 'session_id', '') = ''
        or jsonb_typeof(payload -> 'ask_context' -> 'excerpt') <> 'string'
        or coalesce(payload -> 'ask_context' ->> 'excerpt', '') = '' then
        raise exception 'Invalid consultation Ask context contract' using errcode = '22023';
      end if;
      perform pac_dsd.assert_jsonb_string_array(payload -> 'ask_context' -> 'intents_tried');
    end if;

    perform pac_dsd.assert_allowed_jsonb_keys(payload -> 'priority_signals', array[
      'urgency_weight', 'support_weight', 'stage_weight', 'total', 'tribal_gate', 'high_stakes'
    ]);
    if not (payload -> 'priority_signals' ?& array[
      'urgency_weight', 'support_weight', 'stage_weight', 'total', 'tribal_gate', 'high_stakes'
    ])
      or exists (
        select 1 from jsonb_each(payload -> 'priority_signals') signal
        where signal.key in ('urgency_weight', 'support_weight', 'stage_weight', 'total')
          and jsonb_typeof(signal.value) <> 'number'
      )
      or jsonb_typeof(payload -> 'priority_signals' -> 'tribal_gate') <> 'boolean'
      or jsonb_typeof(payload -> 'priority_signals' -> 'high_stakes') <> 'boolean' then
      raise exception 'Invalid consultation priority-signal contract' using errcode = '22023';
    end if;

    perform pac_dsd.assert_allowed_jsonb_keys(payload -> 'packet', array[
      'snapshot', 'summary', 'equity_questions_considered', 'suggested_questions',
      'related_resources', 'risks_unknowns', 'agenda', 'calendar_handoff', 'ask_context'
    ]);
    perform pac_dsd.assert_jsonb_scalar_types(
      payload -> 'packet', array['calendar_handoff'], array[]::text[], array[]::text[]
    );
    if not (payload -> 'packet' ?& array[
      'snapshot', 'summary', 'equity_questions_considered', 'suggested_questions',
      'related_resources', 'risks_unknowns', 'agenda', 'calendar_handoff'
    ])
      or jsonb_typeof(payload -> 'packet' -> 'snapshot') <> 'object'
      or coalesce(payload -> 'packet' ->> 'calendar_handoff', '') = '' then
      raise exception 'Invalid consultation packet contract' using errcode = '22023';
    end if;
    perform pac_dsd.assert_allowed_jsonb_keys(payload -> 'packet' -> 'snapshot', array[
      'Reference ID', 'Status', 'Submitted', 'Stage', 'Work name', 'Desired support',
      'Timing', 'Preferred meeting mode', 'Requester role'
    ]);
    if exists (
      select 1 from jsonb_each(payload -> 'packet' -> 'snapshot') snapshot_entry
      where jsonb_typeof(snapshot_entry.value) <> 'string'
    ) then
      raise exception 'Invalid consultation packet snapshot contract' using errcode = '22023';
    end if;
    perform pac_dsd.assert_jsonb_string_array(payload -> 'packet' -> 'summary');
    perform pac_dsd.assert_jsonb_string_array(payload -> 'packet' -> 'equity_questions_considered');
    perform pac_dsd.assert_jsonb_string_array(payload -> 'packet' -> 'risks_unknowns');

    if jsonb_typeof(payload -> 'packet' -> 'suggested_questions') <> 'array'
      or jsonb_typeof(payload -> 'packet' -> 'related_resources') <> 'array'
      or jsonb_typeof(payload -> 'packet' -> 'agenda') <> 'array' then
      raise exception 'Invalid consultation packet collection contract' using errcode = '22023';
    end if;
    for entry in select value from jsonb_array_elements(payload -> 'packet' -> 'suggested_questions')
    loop
      perform pac_dsd.assert_allowed_jsonb_keys(entry.value, array['id', 'category', 'text']);
      if not (entry.value ?& array['id', 'category', 'text'])
        or jsonb_typeof(entry.value -> 'id') <> 'string'
        or jsonb_typeof(entry.value -> 'category') <> 'string'
        or jsonb_typeof(entry.value -> 'text') <> 'string'
        or coalesce(entry.value ->> 'id', '') = ''
        or coalesce(entry.value ->> 'category', '') = ''
        or coalesce(entry.value ->> 'text', '') = '' then
        raise exception 'Invalid consultation suggested-question contract' using errcode = '22023';
      end if;
    end loop;
    for entry in select value from jsonb_array_elements(payload -> 'packet' -> 'related_resources')
    loop
      perform pac_dsd.assert_allowed_jsonb_keys(entry.value, array[
        'id', 'title', 'href', 'authority', 'authorityLabel', 'reviewDate', 'excerpt', 'citeable'
      ]);
      if not (entry.value ?& array['id', 'title', 'href', 'authority', 'authorityLabel', 'reviewDate', 'excerpt', 'citeable'])
        or exists (
          select 1 from jsonb_each(entry.value) resource_field
          where resource_field.key in ('id', 'title', 'href', 'authority', 'authorityLabel', 'reviewDate', 'excerpt')
            and jsonb_typeof(resource_field.value) <> 'string'
        )
        or exists (
          select 1 from jsonb_each(entry.value) resource_field
          where resource_field.key in ('id', 'title', 'href', 'authority', 'authorityLabel', 'reviewDate', 'excerpt')
            and coalesce(resource_field.value #>> '{}', '') = ''
        )
        or jsonb_typeof(entry.value -> 'citeable') <> 'boolean' then
        raise exception 'Invalid consultation related-resource contract' using errcode = '22023';
      end if;
    end loop;
    for entry in select value from jsonb_array_elements(payload -> 'packet' -> 'agenda')
    loop
      perform pac_dsd.assert_allowed_jsonb_keys(entry.value, array['minutes', 'item', 'owner']);
      if not (entry.value ?& array['minutes', 'item', 'owner'])
        or jsonb_typeof(entry.value -> 'minutes') <> 'number'
        or jsonb_typeof(entry.value -> 'item') <> 'string'
        or jsonb_typeof(entry.value -> 'owner') <> 'string'
        or coalesce(entry.value ->> 'item', '') = ''
        or coalesce(entry.value ->> 'owner', '') = '' then
        raise exception 'Invalid consultation agenda contract' using errcode = '22023';
      end if;
    end loop;
    if payload -> 'packet' ? 'ask_context' then
      perform pac_dsd.assert_allowed_jsonb_keys(payload -> 'packet' -> 'ask_context', array['intents_tried', 'excerpt']);
      if not (payload -> 'packet' -> 'ask_context' ?& array['intents_tried', 'excerpt'])
        or jsonb_typeof(payload -> 'packet' -> 'ask_context' -> 'excerpt') <> 'string'
        or coalesce(payload -> 'packet' -> 'ask_context' ->> 'excerpt', '') = '' then
        raise exception 'Invalid consultation packet Ask context contract' using errcode = '22023';
      end if;
      perform pac_dsd.assert_jsonb_string_array(payload -> 'packet' -> 'ask_context' -> 'intents_tried');
    end if;

    if jsonb_typeof(payload -> 'history') <> 'array' or jsonb_array_length(payload -> 'history') = 0 then
      raise exception 'Invalid consultation history contract' using errcode = '22023';
    end if;
    for entry in select value from jsonb_array_elements(payload -> 'history')
    loop
      perform pac_dsd.assert_allowed_jsonb_keys(entry.value, array['at', 'status', 'by', 'note']);
      if not (entry.value ?& array['at', 'status', 'by'])
        or jsonb_typeof(entry.value -> 'at') <> 'string'
        or not pac_dsd.jsonb_is_canonical_utc_instant(entry.value -> 'at')
        or jsonb_typeof(entry.value -> 'status') <> 'string'
        or jsonb_typeof(entry.value -> 'by') <> 'string'
        or entry.value ->> 'status' not in (
          'pending_eligibility_review', 'received', 'under_review', 'scheduled',
          'in_progress', 'completed', 'declined', 'withdrawn'
        )
        or entry.value ->> 'by' not in ('system', 'requester', 'owner')
        or (entry.value ? 'note' and jsonb_typeof(entry.value -> 'note') <> 'string') then
        raise exception 'Invalid consultation history entry contract' using errcode = '22023';
      end if;
    end loop;
    if payload -> 'history' -> -1 ->> 'status' is distinct from payload ->> 'status' then
      raise exception 'Consultation history does not match current status' using errcode = '22023';
    end if;

    if payload ? 'correction_history' then
      if jsonb_typeof(payload -> 'correction_history') <> 'array' then
        raise exception 'Invalid consultation correction history contract' using errcode = '22023';
      end if;
      for entry in select value from jsonb_array_elements(payload -> 'correction_history')
      loop
        perform pac_dsd.assert_allowed_jsonb_keys(entry.value, array['at', 'fields', 'by']);
        if not (entry.value ?& array['at', 'fields', 'by'])
          or jsonb_typeof(entry.value -> 'at') <> 'string'
          or not pac_dsd.jsonb_is_canonical_utc_instant(entry.value -> 'at')
          or jsonb_typeof(entry.value -> 'by') <> 'string'
          or entry.value ->> 'by' <> 'requester' then
          raise exception 'Invalid consultation correction history entry' using errcode = '22023';
        end if;
        perform pac_dsd.assert_jsonb_string_array(entry.value -> 'fields', array[
          'requester_role', 'work_name', 'stage', 'goals',
          'equity_questions_considered', 'desired_support_type', 'support_other_note',
          'timing_urgency', 'deadline_date', 'affected_populations',
          'populations_note', 'access_language_needs', 'access_note',
          'preferred_meeting_mode', 'links', 'attachment_notes', 'situation'
        ]);
      end loop;
    end if;
    return;
  end if;

  if requested_kind = 'decision' then
    if requested_object_id = 'autonomy_policy' then
      perform pac_dsd.assert_allowed_jsonb_keys(payload, array[
        'killed', 'max_autonomy', 'agents', 'flags', 'updated_at', 'by', 'note'
      ]);
      if not (payload ?& array['killed', 'max_autonomy', 'agents', 'flags', 'updated_at', 'by']) then
        raise exception 'Invalid autonomy policy persistence contract' using errcode = '22023';
      end if;
      perform pac_dsd.assert_jsonb_scalar_types(
        payload,
        array['max_autonomy', 'updated_at', 'by', 'note'],
        array['killed'],
        array[]::text[]
      );
      if jsonb_typeof(payload -> 'agents') <> 'object'
        or jsonb_typeof(payload -> 'flags') <> 'object'
        or payload ->> 'max_autonomy' not in ('A0', 'A1', 'A2', 'A3', 'A4', 'A5')
        or coalesce(payload ->> 'updated_at', '') = ''
        or payload ->> 'by' not in ('env_default', 'owner', 'system') then
        raise exception 'Invalid autonomy policy persistence contract' using errcode = '22023';
      end if;
      perform pac_dsd.assert_agent_override_contract(payload -> 'agents');
      perform pac_dsd.assert_flag_override_contract(payload -> 'flags');
    elsif requested_object_id = 'research_policy' then
      perform pac_dsd.assert_allowed_jsonb_keys(payload, array[
        'enabled', 'mode', 'provider_order', 'daily_request_cap',
        'monthly_usd_cap', 'allowed_domains', 'recency', 'deep_research_enabled'
      ]);
      if payload = '{}'::jsonb then
        raise exception 'Invalid research policy persistence contract' using errcode = '22023';
      end if;
      perform pac_dsd.assert_jsonb_scalar_types(
        payload,
        array['mode', 'recency'],
        array['enabled', 'deep_research_enabled'],
        array['daily_request_cap', 'monthly_usd_cap']
      );
      if (payload ? 'mode' and payload ->> 'mode' not in ('auto', 'on_request', 'off'))
        or (payload ? 'recency' and payload ->> 'recency' not in ('any', 'year', 'month', 'week'))
        or (payload ? 'daily_request_cap' and (
          not pac_dsd.jsonb_is_safe_integer(payload -> 'daily_request_cap', 0)
          or (payload ->> 'daily_request_cap')::numeric > 100000
        ))
        or (payload ? 'monthly_usd_cap' and (
          (payload ->> 'monthly_usd_cap')::numeric < 0
          or (payload ->> 'monthly_usd_cap')::numeric > 100000
        )) then
        raise exception 'Invalid research policy persistence contract' using errcode = '22023';
      end if;
      if payload ? 'provider_order' then
        perform pac_dsd.assert_jsonb_string_array(payload -> 'provider_order', array[
          'perplexity_agent', 'fixture', 'perplexity_direct', 'vercel_gateway'
        ]);
      end if;
      if payload ? 'allowed_domains' then
        perform pac_dsd.assert_jsonb_string_array(payload -> 'allowed_domains');
        if jsonb_array_length(payload -> 'allowed_domains') > 20
          or (select count(*) from jsonb_array_elements_text(payload -> 'allowed_domains'))
            <> (select count(distinct domain) from jsonb_array_elements_text(payload -> 'allowed_domains') domain)
          or exists (
            select 1 from jsonb_array_elements_text(payload -> 'allowed_domains') domain
            where domain !~ '^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]([a-z0-9-]{0,61}[a-z0-9])?$'
          ) then
          raise exception 'Invalid research policy domain contract' using errcode = '22023';
        end if;
      end if;
    elsif requested_object_id like 'research_usage:%' then
      perform pac_dsd.assert_allowed_jsonb_keys(payload, array[
        'id', 'at', 'provider', 'model', 'depth', 'query_hash', 'domains',
        'estimated_usd', 'reported_usd', 'input_tokens', 'output_tokens',
        'search_queries', 'web_search_calls', 'fetch_url_calls', 'tool_calls',
        'ok', 'error_code', 'latency_ms', 'trace_id', 'provider_trace_id'
      ]);
      if not (payload ?& array[
        'id', 'at', 'provider', 'model', 'depth', 'query_hash', 'domains',
        'estimated_usd', 'ok', 'latency_ms', 'trace_id'
      ]) then
        raise exception 'Invalid research usage persistence contract' using errcode = '22023';
      end if;
      perform pac_dsd.assert_jsonb_scalar_types(
        payload,
        array[
          'id', 'at', 'provider', 'model', 'depth', 'query_hash', 'error_code',
          'trace_id', 'provider_trace_id'
        ],
        array['ok'],
        array[
          'estimated_usd', 'reported_usd', 'input_tokens', 'output_tokens',
          'search_queries', 'web_search_calls', 'fetch_url_calls', 'tool_calls',
          'latency_ms'
        ]
      );
      if requested_object_id is distinct from 'research_usage:' || (payload ->> 'id')
        or payload ->> 'id' !~ '^ru_[0-9]{14}_[a-f0-9]{6}_[a-f0-9]{4}$'
        or not pac_dsd.jsonb_is_canonical_utc_instant(payload -> 'at')
        or payload ->> 'provider' not in ('perplexity_agent', 'fixture')
        or payload ->> 'depth' not in ('current_web', 'deep_research')
        or not (
          payload ->> 'model' in (
            'fixture/research-1', 'perplexity-search', 'fast', 'low', 'medium', 'high'
          )
          or payload ->> 'model' ~ '^msh_[a-f0-9]{64}$'
        )
        or payload ->> 'query_hash' !~ '^[a-f0-9]{16}$'
        or payload ->> 'trace_id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        or (payload ? 'provider_trace_id'
          and payload ->> 'provider_trace_id' !~ '^pth_[a-f0-9]{64}$')
        or (payload ? 'error_code'
          and payload ->> 'error_code' <> 'research_execution_failed')
        or (payload -> 'ok' = 'true'::jsonb and payload ? 'error_code')
        or (payload -> 'ok' = 'false'::jsonb
          and payload ->> 'error_code' is distinct from 'research_execution_failed')
        or (payload ->> 'estimated_usd')::numeric < 0
        or (payload ? 'reported_usd' and (payload ->> 'reported_usd')::numeric < 0)
        or not pac_dsd.jsonb_is_safe_integer(payload -> 'latency_ms', 0)
        or exists (
          select 1
          from unnest(array[
            'input_tokens', 'output_tokens', 'search_queries', 'web_search_calls',
            'fetch_url_calls', 'tool_calls'
          ]) counter_name
          where payload ? counter_name
            and not pac_dsd.jsonb_is_safe_integer(payload -> counter_name, 0)
        ) then
        raise exception 'Invalid research usage persistence contract' using errcode = '22023';
      end if;
      perform pac_dsd.assert_jsonb_string_array(payload -> 'domains');
      if jsonb_array_length(payload -> 'domains') > 20
        or (select count(*) from jsonb_array_elements_text(payload -> 'domains'))
          <> (select count(distinct domain) from jsonb_array_elements_text(payload -> 'domains') domain)
        or exists (
          select 1 from jsonb_array_elements_text(payload -> 'domains') domain
          where domain !~ '^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]([a-z0-9-]{0,61}[a-z0-9])?$'
        ) then
        raise exception 'Invalid research usage domain contract' using errcode = '22023';
      end if;
    elsif requested_object_id ~ '^owner-session-revoked-[a-f0-9]{64}$' then
      perform pac_dsd.assert_allowed_jsonb_keys(payload, array['kind', 'session_hash', 'revoked_at', 'expires_at']);
      if payload ->> 'kind' <> 'owner_session_revocation'
        or payload ->> 'session_hash' !~ '^[a-f0-9]{64}$'
        or coalesce(payload ->> 'revoked_at', '') = ''
        or coalesce(payload ->> 'expires_at', '') = '' then
        raise exception 'Invalid owner-session revocation contract' using errcode = '22023';
      end if;
    elsif requested_object_id like 'cycle:%' then
      perform pac_dsd.assert_allowed_jsonb_keys(payload, array[
        'id', 'at', 'by', 'policy', 'effective_ceiling', 'generative', 'steps',
        'triaged', 'expired_consultations', 'refreshed_packets', 'stale_flags',
        'quality_problems', 'a11y', 'proposals', 'summary', 'exceptions', 'undone'
      ]);
      if not (payload ?& array[
        'id', 'at', 'by', 'policy', 'effective_ceiling', 'generative', 'steps',
        'triaged', 'expired_consultations', 'refreshed_packets', 'stale_flags',
        'quality_problems', 'a11y', 'proposals', 'summary', 'exceptions'
      ]) then
        raise exception 'Invalid cycle report persistence contract' using errcode = '22023';
      end if;
      perform pac_dsd.assert_jsonb_scalar_types(
        payload,
        array['id', 'at', 'by', 'effective_ceiling', 'summary'],
        array['generative'],
        array[]::text[]
      );
      if requested_object_id is distinct from 'cycle:' || (payload ->> 'id')
        or payload ->> 'id' !~ '^cycle-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        or coalesce(payload ->> 'at', '') = ''
        or payload ->> 'by' not in ('owner', 'cron')
        or payload ->> 'effective_ceiling' not in ('A0', 'A1', 'A2', 'A3', 'A4', 'A5')
        or coalesce(payload ->> 'summary', '') = ''
        or jsonb_typeof(payload -> 'policy') <> 'object' then
        raise exception 'Invalid cycle report persistence contract' using errcode = '22023';
      end if;
      perform pac_dsd.assert_allowed_jsonb_keys(payload -> 'policy', array['max_autonomy', 'killed']);
      if not (payload -> 'policy' ?& array['max_autonomy', 'killed']) then
        raise exception 'Invalid cycle policy contract' using errcode = '22023';
      end if;
      perform pac_dsd.assert_jsonb_scalar_types(
        payload -> 'policy', array['max_autonomy'], array['killed'], array[]::text[]
      );
      if payload -> 'policy' ->> 'max_autonomy' not in ('A0', 'A1', 'A2', 'A3', 'A4', 'A5') then
        raise exception 'Invalid cycle policy contract' using errcode = '22023';
      end if;

      perform pac_dsd.assert_jsonb_string_array(payload -> 'expired_consultations');
      perform pac_dsd.assert_jsonb_string_array(payload -> 'refreshed_packets');
      perform pac_dsd.assert_jsonb_string_array(payload -> 'exceptions');
      if exists (
        select 1
        from jsonb_array_elements_text(
          (payload -> 'expired_consultations') || (payload -> 'refreshed_packets')
        ) request_id
        where request_id !~ '^CR-[0-9]{8}-[0-9]{4,10}$'
      ) then
        raise exception 'Invalid cycle consultation reference' using errcode = '22023';
      end if;

      if jsonb_typeof(payload -> 'steps') <> 'array'
        or jsonb_typeof(payload -> 'triaged') <> 'array'
        or jsonb_typeof(payload -> 'stale_flags') <> 'array'
        or jsonb_typeof(payload -> 'quality_problems') <> 'array'
        or jsonb_typeof(payload -> 'a11y') <> 'array'
        or jsonb_typeof(payload -> 'proposals') <> 'array' then
        raise exception 'Invalid cycle collection contract' using errcode = '22023';
      end if;

      for entry in select value from jsonb_array_elements(payload -> 'steps')
      loop
        perform pac_dsd.assert_allowed_jsonb_keys(entry.value, array['name', 'autonomy', 'outcome', 'detail']);
        if not (entry.value ?& array['name', 'autonomy', 'outcome', 'detail']) then
          raise exception 'Invalid cycle step contract' using errcode = '22023';
        end if;
        perform pac_dsd.assert_jsonb_scalar_types(
          entry.value, array['name', 'autonomy', 'outcome', 'detail'], array[]::text[], array[]::text[]
        );
        if coalesce(entry.value ->> 'name', '') = ''
          or entry.value ->> 'autonomy' not in ('A0', 'A1', 'A2', 'A3', 'A4', 'A5')
          or entry.value ->> 'outcome' not in ('done', 'skipped', 'denied') then
          raise exception 'Invalid cycle step contract' using errcode = '22023';
        end if;
      end loop;
      for entry in select value from jsonb_array_elements(payload -> 'triaged')
      loop
        perform pac_dsd.assert_allowed_jsonb_keys(entry.value, array['request_id', 'from', 'to']);
        if not (entry.value ?& array['request_id', 'from', 'to']) then
          raise exception 'Invalid cycle triage contract' using errcode = '22023';
        end if;
        perform pac_dsd.assert_jsonb_scalar_types(
          entry.value, array['request_id', 'from', 'to'], array[]::text[], array[]::text[]
        );
        if coalesce(entry.value ->> 'request_id', '') = ''
          or entry.value ->> 'request_id' !~ '^CR-[0-9]{8}-[0-9]{4,10}$'
          or coalesce(entry.value ->> 'from', '') = ''
          or coalesce(entry.value ->> 'to', '') = '' then
          raise exception 'Invalid cycle triage contract' using errcode = '22023';
        end if;
      end loop;
      for entry in select value from jsonb_array_elements(payload -> 'stale_flags')
      loop
        perform pac_dsd.assert_allowed_jsonb_keys(entry.value, array['id', 'title', 'owner', 'reviewDate', 'problem']);
        if not (entry.value ?& array['id', 'title', 'owner', 'reviewDate', 'problem']) then
          raise exception 'Invalid cycle stale flag contract' using errcode = '22023';
        end if;
        perform pac_dsd.assert_jsonb_scalar_types(
          entry.value, array['id', 'title', 'owner', 'reviewDate', 'problem'], array[]::text[], array[]::text[]
        );
        if entry.value ->> 'id' !~ '^((pn|ja|lm|ext|asset)-[a-z0-9][a-z0-9-]{0,119}|somali|hmong|karen|oromo|african-american|latino|vietnamese|khmer|lao|russian-speaking|arabic-speaking|deaf-deafblind-hard-of-hearing|rural|tribal-nations)$'
          or coalesce(entry.value ->> 'title', '') = ''
          or coalesce(entry.value ->> 'reviewDate', '') = ''
          or entry.value ->> 'problem' not in ('past_review_date', 'review_due_soon', 'missing_owner', 'accessibility_pending') then
          raise exception 'Invalid cycle stale flag contract' using errcode = '22023';
        end if;
      end loop;
      for entry in select value from jsonb_array_elements(payload -> 'quality_problems')
      loop
        perform pac_dsd.assert_allowed_jsonb_keys(entry.value, array['id', 'problems']);
        if not (entry.value ?& array['id', 'problems'])
          or jsonb_typeof(entry.value -> 'id') <> 'string'
          or entry.value ->> 'id' !~ '^((pn|ja|lm|ext|asset)-[a-z0-9][a-z0-9-]{0,119}|somali|hmong|karen|oromo|african-american|latino|vietnamese|khmer|lao|russian-speaking|arabic-speaking|deaf-deafblind-hard-of-hearing|rural|tribal-nations)$' then
          raise exception 'Invalid cycle quality problem contract' using errcode = '22023';
        end if;
        perform pac_dsd.assert_jsonb_string_array(entry.value -> 'problems');
      end loop;
      for entry in select value from jsonb_array_elements(payload -> 'a11y')
      loop
        perform pac_dsd.assert_allowed_jsonb_keys(entry.value, array['id', 'blockers', 'should_fix']);
        if not (entry.value ?& array['id', 'blockers', 'should_fix']) then
          raise exception 'Invalid cycle accessibility result contract' using errcode = '22023';
        end if;
        perform pac_dsd.assert_jsonb_scalar_types(
          entry.value, array['id'], array[]::text[], array['blockers', 'should_fix']
        );
        if entry.value ->> 'id' !~ '^((pn|ja|lm|ext|asset)-[a-z0-9][a-z0-9-]{0,119}|somali|hmong|karen|oromo|african-american|latino|vietnamese|khmer|lao|russian-speaking|arabic-speaking|deaf-deafblind-hard-of-hearing|rural|tribal-nations)$' then
          raise exception 'Invalid cycle accessibility result contract' using errcode = '22023';
        end if;
      end loop;
      for entry in select value from jsonb_array_elements(payload -> 'proposals')
      loop
        perform pac_dsd.assert_proposal_contract(entry.value);
        if entry.value ->> 'cycle_id' is distinct from payload ->> 'id' then
          raise exception 'Invalid cycle proposal reference' using errcode = '22023';
        end if;
      end loop;
      if payload ? 'undone' then
        perform pac_dsd.assert_allowed_jsonb_keys(payload -> 'undone', array['at', 'by']);
        if not (payload -> 'undone' ?& array['at', 'by']) then
          raise exception 'Invalid cycle undo contract' using errcode = '22023';
        end if;
        perform pac_dsd.assert_jsonb_scalar_types(
          payload -> 'undone', array['at', 'by'], array[]::text[], array[]::text[]
        );
        if coalesce(payload -> 'undone' ->> 'at', '') = ''
          or coalesce(payload -> 'undone' ->> 'by', '') = '' then
          raise exception 'Invalid cycle undo contract' using errcode = '22023';
        end if;
      end if;
    elsif requested_object_id like 'stale_flag:%' then
      perform pac_dsd.assert_allowed_jsonb_keys(payload, array[
        'id', 'title', 'owner', 'reviewDate', 'problem', 'cycle_id',
        'flagged_at', 'disposition', 'undone_at'
      ]);
      if not (payload ?& array[
        'id', 'title', 'owner', 'reviewDate', 'problem', 'cycle_id',
        'flagged_at', 'disposition'
      ]) then
        raise exception 'Invalid stale-content decision contract' using errcode = '22023';
      end if;
      perform pac_dsd.assert_jsonb_scalar_types(
        payload,
        array[
          'id', 'title', 'owner', 'reviewDate', 'problem', 'cycle_id',
          'flagged_at', 'disposition', 'undone_at'
        ],
        array[]::text[],
        array[]::text[]
      );
      if payload ->> 'id' !~ '^((pn|ja|lm|ext|asset)-[a-z0-9][a-z0-9-]{0,119}|somali|hmong|karen|oromo|african-american|latino|vietnamese|khmer|lao|russian-speaking|arabic-speaking|deaf-deafblind-hard-of-hearing|rural|tribal-nations)$'
        or coalesce(payload ->> 'title', '') = ''
        or coalesce(payload ->> 'reviewDate', '') = ''
        or payload ->> 'problem' not in ('past_review_date', 'review_due_soon', 'missing_owner', 'accessibility_pending')
        or requested_object_id is distinct from 'stale_flag:' || (payload ->> 'id') || ':' || (payload ->> 'problem')
        or payload ->> 'cycle_id' !~ '^cycle-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        or coalesce(payload ->> 'flagged_at', '') = ''
        or coalesce(payload ->> 'disposition', '') = '' then
        raise exception 'Invalid stale-content decision contract' using errcode = '22023';
      end if;
    elsif requested_object_id like 'proposal:%' then
      perform pac_dsd.assert_proposal_contract(payload);
      if requested_object_id is distinct from 'proposal:' || (payload ->> 'id')
        or requested_object_id !~ '^proposal:cycle-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}-[pg][1-9][0-9]*$' then
        raise exception 'Invalid proposal decision contract' using errcode = '22023';
      end if;
    elsif requested_object_id like 'rejected_rec:%' then
      perform pac_dsd.assert_allowed_jsonb_keys(payload, array['id', 'at', 'title', 'note']);
      if not (payload ?& array['id', 'at', 'title']) then
        raise exception 'Invalid rejected recommendation contract' using errcode = '22023';
      end if;
      perform pac_dsd.assert_jsonb_scalar_types(
        payload, array['id', 'at', 'title', 'note'], array[]::text[], array[]::text[]
      );
      if requested_object_id is distinct from 'rejected_rec:' || (payload ->> 'id')
        or payload ->> 'id' !~ '^cycle-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}-[pg][1-9][0-9]*$'
        or coalesce(payload ->> 'at', '') = ''
        or coalesce(payload ->> 'title', '') = '' then
        raise exception 'Invalid rejected recommendation contract' using errcode = '22023';
      end if;
    else
      raise exception 'Unregistered decision persistence family' using errcode = '22023';
    end if;
    return;
  end if;

  if requested_kind = 'eval_result' then
    perform pac_dsd.assert_allowed_jsonb_keys(payload, array[
      'id', 'at', 'suites', 'results', 'pass', 'fail', 'manual', 'releaseBlocked'
    ]);
    if not (payload ?& array[
      'id', 'at', 'suites', 'results', 'pass', 'fail', 'manual', 'releaseBlocked'
    ]) then
      raise exception 'Invalid evaluation result persistence contract' using errcode = '22023';
    end if;
    perform pac_dsd.assert_jsonb_scalar_types(
      payload,
      array['id', 'at'],
      array['releaseBlocked'],
      array['pass', 'fail', 'manual']
    );
    if payload ->> 'id' is distinct from requested_object_id
      or requested_object_id !~ '^eval-[0-9]{10,16}$'
      or jsonb_typeof(payload -> 'results') <> 'array'
      or coalesce(payload ->> 'at', '') = '' then
      raise exception 'Invalid evaluation result persistence contract' using errcode = '22023';
    end if;
    perform pac_dsd.assert_jsonb_string_array(payload -> 'suites', array[
      'ask_mvp', 'ci_mvp', 'ciq_mvp', 'gp_mvp', 'mindset_abc'
    ]);
    for entry in select value from jsonb_array_elements(payload -> 'results')
    loop
      perform pac_dsd.assert_allowed_jsonb_keys(entry.value, array['id', 'suite', 'scenario', 'status', 'detail', 'ms']);
      if not (entry.value ?& array['id', 'suite', 'scenario', 'status', 'detail', 'ms']) then
        raise exception 'Invalid evaluation result entry contract' using errcode = '22023';
      end if;
      perform pac_dsd.assert_jsonb_scalar_types(
        entry.value,
        array['id', 'suite', 'scenario', 'status', 'detail'],
        array[]::text[],
        array['ms']
      );
      if entry.value ->> 'id' !~ '^(ASK-E[1-9][0-9]*|CI-E[1-9][0-9]*|CIQ-E[1-9][0-9]*|GP-E[1-9][0-9]*|MIND-[ABC][1-9][0-9]*|CP-[1-9][0-9]*)$'
        or entry.value ->> 'suite' not in ('ask_mvp', 'ci_mvp', 'ciq_mvp', 'gp_mvp', 'mindset_abc')
        or coalesce(entry.value ->> 'scenario', '') = ''
        or entry.value ->> 'status' not in ('pass', 'fail', 'manual') then
        raise exception 'Invalid evaluation result entry contract' using errcode = '22023';
      end if;
    end loop;
    return;
  end if;

  if requested_kind = 'collaboration_workspace' then
    perform pac_dsd.assert_no_collaboration_surveillance_text(payload);
    perform pac_dsd.assert_allowed_jsonb_keys(payload, array[
      'workspace', 'memberships', 'channels', 'channelMemberships', 'threads',
      'posts', 'reactions', 'attachments', 'meetingSeries', 'meetingOccurrences',
      'agendaItems', 'decisions', 'polls', 'pollResponses', 'feedback',
      'feedbackResponses', 'learningActivities', 'notificationPreferences',
      'notificationDeliveries', 'actionItems', 'contentProposals',
      'automationPolicies', 'automationRuns', 'processedKeys', 'revision'
    ]);
    if not (payload ?& array[
      'workspace', 'memberships', 'channels', 'channelMemberships', 'threads',
      'posts', 'reactions', 'attachments', 'meetingSeries', 'meetingOccurrences',
      'agendaItems', 'decisions', 'polls', 'pollResponses', 'feedback',
      'feedbackResponses', 'learningActivities', 'notificationPreferences',
      'notificationDeliveries', 'actionItems', 'contentProposals',
      'automationPolicies', 'automationRuns', 'processedKeys', 'revision'
    ])
      or requested_object_id <> 'one_dsd_team'
      or jsonb_typeof(payload -> 'workspace') <> 'object'
      or not pac_dsd.jsonb_is_safe_integer(payload -> 'revision', 1) then
      raise exception 'Invalid collaboration workspace persistence contract' using errcode = '22023';
    end if;
    perform pac_dsd.assert_allowed_jsonb_keys(payload -> 'workspace', array[
      'id', 'name', 'programName', 'scopeLabel', 'summary', 'status', 'sample',
      'createdAt', 'updatedAt'
    ]);
    if not (payload -> 'workspace' ?& array[
      'id', 'name', 'programName', 'scopeLabel', 'summary', 'status', 'sample',
      'createdAt', 'updatedAt'
    ]) then
      raise exception 'Invalid collaboration workspace persistence contract' using errcode = '22023';
    end if;
    perform pac_dsd.assert_jsonb_scalar_types(
      payload -> 'workspace',
      array['id', 'name', 'programName', 'scopeLabel', 'summary', 'status', 'createdAt', 'updatedAt'],
      array['sample'],
      array[]::text[]
    );
    if payload -> 'workspace' ->> 'id' <> requested_object_id
      or payload -> 'workspace' ->> 'status' not in ('preview', 'pilot', 'active', 'archived')
      or not pac_dsd.jsonb_is_instant(payload -> 'workspace' -> 'createdAt')
      or not pac_dsd.jsonb_is_instant(payload -> 'workspace' -> 'updatedAt') then
      raise exception 'Invalid collaboration workspace persistence contract' using errcode = '22023';
    end if;
    perform pac_dsd.assert_jsonb_string_array(payload -> 'processedKeys');
    if exists (
      select 1
      from jsonb_array_elements_text(payload -> 'processedKeys') key_value
      where key_value = ''
    )
      or (select count(*) from jsonb_array_elements_text(payload -> 'processedKeys'))
        <> (select count(distinct key_value) from jsonb_array_elements_text(payload -> 'processedKeys') key_value) then
      raise exception 'Invalid collaboration idempotency-key contract' using errcode = '22023';
    end if;

    for collection_name, collection_keys in
      select * from (values
        ('memberships', array['id','workspaceId','displayLabel','role','status','sample']),
        ('channels', array['id','workspaceId','name','purpose','access','position','sample','updatedAt']),
        ('channelMemberships', array['id','channelId','workspaceMembershipId','sample']),
        ('threads', array['id','channelId','title','createdByLabel','createdAt','updatedAt','pinned','sample']),
        ('posts', array['id','threadId','parentPostId','body','authorLabel','createdAt','updatedAt','moderationStatus','sample']),
        ('reactions', array['id','postId','memberId','label','sample']),
        ('attachments', array['id','postId','fileName','mediaType','byteSize','checksum','status','accessibilityStatus','sample']),
        ('meetingSeries', array['id','workspaceId','name','purpose','cadence','scheduleNote','sample']),
        ('meetingOccurrences', array['id','seriesId','title','scheduleNote','accessNote','status','sample','updatedAt']),
        ('agendaItems', array['id','meetingOccurrenceId','title','ownerLabel','minutes','position','sample']),
        ('decisions', array['id','workspaceId','title','summary','status','confirmedByLabel','confirmedAt','sourceThreadId','sample']),
        ('polls', array['id','channelId','question','options','status','sample']),
        ('pollResponses', array['id','pollId','memberId','optionId','sample']),
        ('feedback', array['id','channelId','prompt','status','sample']),
        ('feedbackResponses', array['id','feedbackId','authorLabel','response','createdAt','sample']),
        ('learningActivities', array['id','channelId','title','description','reflectionPrompt','status','sample']),
        ('notificationPreferences', array['id','memberId','channelId','mode','quietHoursNote','sample']),
        ('notificationDeliveries', array['id','preferenceId','destinationClass','status','attemptCount','sample']),
        ('actionItems', array['id','workspaceId','title','ownerLabel','dueNote','status','sourceThreadId','sample','updatedAt']),
        ('contentProposals', array['id','workspaceId','title','sourceThreadId','status','sample']),
        ('automationPolicies', array['id','workspaceId','name','status','exactDestination','allowedAction','expiresAt','sample']),
        ('automationRuns', array['id','policyId','status','resultNote','createdAt','sample'])
      ) as contract(collection_name, collection_keys)
    loop
      if jsonb_typeof(payload -> collection_name) <> 'array' then
        raise exception 'Invalid collaboration collection contract' using errcode = '22023';
      end if;
      for entry in select value from jsonb_array_elements(payload -> collection_name)
      loop
        perform pac_dsd.assert_allowed_jsonb_keys(entry.value, collection_keys);

        case collection_name
          when 'memberships' then
            if not (entry.value ?& array['id', 'workspaceId', 'displayLabel', 'role', 'status', 'sample']) then
              raise exception 'Invalid collaboration membership contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'workspaceId', 'displayLabel', 'role', 'status'], array['sample'], array[]::text[]
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or entry.value ->> 'workspaceId' <> requested_object_id
              or entry.value ->> 'role' not in (
                'owner', 'steward', 'member', 'contributor', 'reviewer', 'moderator',
                'automation_operator', 'technical_operator'
              )
              or entry.value ->> 'status' not in ('invited', 'active', 'suspended', 'expired', 'revoked') then
              raise exception 'Invalid collaboration membership contract' using errcode = '22023';
            end if;

          when 'channels' then
            if not (entry.value ?& array['id', 'workspaceId', 'name', 'purpose', 'access', 'position', 'sample', 'updatedAt']) then
              raise exception 'Invalid collaboration channel contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'workspaceId', 'name', 'purpose', 'access', 'updatedAt'], array['sample'], array['position']
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or entry.value ->> 'workspaceId' <> requested_object_id
              or entry.value ->> 'access' not in ('workspace', 'private')
              or not pac_dsd.jsonb_is_safe_integer(entry.value -> 'position', 0)
              or not pac_dsd.jsonb_is_instant(entry.value -> 'updatedAt') then
              raise exception 'Invalid collaboration channel contract' using errcode = '22023';
            end if;

          when 'channelMemberships' then
            if not (entry.value ?& array['id', 'channelId', 'workspaceMembershipId', 'sample']) then
              raise exception 'Invalid collaboration channel membership contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'channelId', 'workspaceMembershipId'], array['sample'], array[]::text[]
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or not exists (
                select 1 from jsonb_array_elements(payload -> 'channels') target
                where target ->> 'id' = entry.value ->> 'channelId'
              )
              or not exists (
                select 1 from jsonb_array_elements(payload -> 'memberships') target
                where target ->> 'id' = entry.value ->> 'workspaceMembershipId'
              ) then
              raise exception 'Invalid collaboration channel membership contract' using errcode = '22023';
            end if;

          when 'threads' then
            if not (entry.value ?& array['id', 'channelId', 'title', 'createdByLabel', 'createdAt', 'updatedAt', 'pinned', 'sample']) then
              raise exception 'Invalid collaboration thread contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'channelId', 'title', 'createdByLabel', 'createdAt', 'updatedAt'],
              array['pinned', 'sample'], array[]::text[]
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or not exists (
                select 1 from jsonb_array_elements(payload -> 'channels') target
                where target ->> 'id' = entry.value ->> 'channelId'
              )
              or not pac_dsd.jsonb_is_instant(entry.value -> 'createdAt')
              or not pac_dsd.jsonb_is_instant(entry.value -> 'updatedAt') then
              raise exception 'Invalid collaboration thread contract' using errcode = '22023';
            end if;

          when 'posts' then
            if not (entry.value ?& array[
              'id', 'threadId', 'parentPostId', 'body', 'authorLabel', 'createdAt',
              'updatedAt', 'moderationStatus', 'sample'
            ]) then
              raise exception 'Invalid collaboration post contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'threadId', 'body', 'authorLabel', 'createdAt', 'updatedAt', 'moderationStatus'],
              array['sample'], array[]::text[]
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or not exists (
                select 1 from jsonb_array_elements(payload -> 'threads') target
                where target ->> 'id' = entry.value ->> 'threadId'
              )
              or jsonb_typeof(entry.value -> 'parentPostId') not in ('null', 'string')
              or not pac_dsd.jsonb_is_instant(entry.value -> 'createdAt')
              or not pac_dsd.jsonb_is_instant(entry.value -> 'updatedAt')
              or entry.value ->> 'moderationStatus' not in ('visible', 'held', 'removed') then
              raise exception 'Invalid collaboration post contract' using errcode = '22023';
            end if;
            if jsonb_typeof(entry.value -> 'parentPostId') = 'string'
              and not exists (
                select 1 from jsonb_array_elements(payload -> 'posts') target
                where target ->> 'id' = entry.value ->> 'parentPostId'
                  and target ->> 'id' <> entry.value ->> 'id'
                  and target ->> 'threadId' = entry.value ->> 'threadId'
              ) then
              raise exception 'Invalid collaboration post parent contract' using errcode = '22023';
            end if;

          when 'reactions' then
            if not (entry.value ?& array['id', 'postId', 'memberId', 'label', 'sample']) then
              raise exception 'Invalid collaboration reaction contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'postId', 'memberId', 'label'], array['sample'], array[]::text[]
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or entry.value ->> 'label' not in ('Helpful', 'Support', 'Question')
              or not exists (
                select 1 from jsonb_array_elements(payload -> 'posts') target
                where target ->> 'id' = entry.value ->> 'postId'
              )
              or not exists (
                select 1 from jsonb_array_elements(payload -> 'memberships') target
                where target ->> 'id' = entry.value ->> 'memberId'
              ) then
              raise exception 'Invalid collaboration reaction contract' using errcode = '22023';
            end if;

          when 'attachments' then
            if not (entry.value ?& array[
              'id', 'postId', 'fileName', 'mediaType', 'byteSize', 'checksum',
              'status', 'accessibilityStatus', 'sample'
            ]) then
              raise exception 'Invalid collaboration attachment contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'postId', 'fileName', 'mediaType', 'checksum', 'status', 'accessibilityStatus'],
              array['sample'], array['byteSize']
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or not exists (
                select 1 from jsonb_array_elements(payload -> 'posts') target
                where target ->> 'id' = entry.value ->> 'postId'
              )
              or not pac_dsd.jsonb_is_safe_integer(entry.value -> 'byteSize', 0)
              or entry.value ->> 'status' not in ('quarantined', 'approved', 'rejected')
              or entry.value ->> 'accessibilityStatus' not in ('pending', 'reviewed', 'needs_work') then
              raise exception 'Invalid collaboration attachment contract' using errcode = '22023';
            end if;

          when 'meetingSeries' then
            if not (entry.value ?& array['id', 'workspaceId', 'name', 'purpose', 'cadence', 'scheduleNote', 'sample']) then
              raise exception 'Invalid collaboration meeting series contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'workspaceId', 'name', 'purpose', 'cadence', 'scheduleNote'],
              array['sample'], array[]::text[]
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or entry.value ->> 'workspaceId' <> requested_object_id
              or entry.value ->> 'cadence' <> 'monthly' then
              raise exception 'Invalid collaboration meeting series contract' using errcode = '22023';
            end if;

          when 'meetingOccurrences' then
            if not (entry.value ?& array[
              'id', 'seriesId', 'title', 'scheduleNote', 'accessNote', 'status', 'sample', 'updatedAt'
            ]) then
              raise exception 'Invalid collaboration meeting occurrence contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'seriesId', 'title', 'scheduleNote', 'accessNote', 'status', 'updatedAt'],
              array['sample'], array[]::text[]
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or not exists (
                select 1 from jsonb_array_elements(payload -> 'meetingSeries') target
                where target ->> 'id' = entry.value ->> 'seriesId'
              )
              or entry.value ->> 'status' not in ('planning', 'scheduled', 'completed', 'cancelled')
              or not pac_dsd.jsonb_is_instant(entry.value -> 'updatedAt') then
              raise exception 'Invalid collaboration meeting occurrence contract' using errcode = '22023';
            end if;

          when 'agendaItems' then
            if not (entry.value ?& array[
              'id', 'meetingOccurrenceId', 'title', 'ownerLabel', 'minutes', 'position', 'sample'
            ]) then
              raise exception 'Invalid collaboration agenda item contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'meetingOccurrenceId', 'title', 'ownerLabel'],
              array['sample'], array['minutes', 'position']
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or not exists (
                select 1 from jsonb_array_elements(payload -> 'meetingOccurrences') target
                where target ->> 'id' = entry.value ->> 'meetingOccurrenceId'
              )
              or not pac_dsd.jsonb_is_safe_integer(entry.value -> 'minutes', 0)
              or not pac_dsd.jsonb_is_safe_integer(entry.value -> 'position', 0) then
              raise exception 'Invalid collaboration agenda item contract' using errcode = '22023';
            end if;

          when 'decisions' then
            if not (entry.value ?& array['id', 'workspaceId', 'title', 'summary', 'status', 'sample']) then
              raise exception 'Invalid collaboration decision contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value,
              array['id', 'workspaceId', 'title', 'summary', 'status', 'confirmedByLabel', 'confirmedAt', 'sourceThreadId'],
              array['sample'], array[]::text[]
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or entry.value ->> 'workspaceId' <> requested_object_id
              or entry.value ->> 'status' not in ('proposed', 'confirmed', 'superseded')
              or (entry.value ? 'confirmedAt' and not pac_dsd.jsonb_is_instant(entry.value -> 'confirmedAt'))
              or (entry.value ? 'sourceThreadId' and not exists (
                select 1 from jsonb_array_elements(payload -> 'threads') target
                where target ->> 'id' = entry.value ->> 'sourceThreadId'
              )) then
              raise exception 'Invalid collaboration decision contract' using errcode = '22023';
            end if;

          when 'polls' then
            if not (entry.value ?& array['id', 'channelId', 'question', 'options', 'status', 'sample']) then
              raise exception 'Invalid collaboration poll contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'channelId', 'question', 'status'], array['sample'], array[]::text[]
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or not exists (
                select 1 from jsonb_array_elements(payload -> 'channels') target
                where target ->> 'id' = entry.value ->> 'channelId'
              )
              or entry.value ->> 'status' not in ('draft', 'open', 'closed')
              or jsonb_typeof(entry.value -> 'options') <> 'array' then
              raise exception 'Invalid collaboration poll contract' using errcode = '22023';
            end if;
            for nested_entry in select value from jsonb_array_elements(entry.value -> 'options')
            loop
              perform pac_dsd.assert_allowed_jsonb_keys(nested_entry.value, array['id', 'label']);
              if not (nested_entry.value ?& array['id', 'label']) then
                raise exception 'Invalid collaboration poll option contract' using errcode = '22023';
              end if;
              perform pac_dsd.assert_jsonb_scalar_types(
                nested_entry.value, array['id', 'label'], array[]::text[], array[]::text[]
              );
              if coalesce(nested_entry.value ->> 'id', '') = '' then
                raise exception 'Invalid collaboration poll option contract' using errcode = '22023';
              end if;
            end loop;
            if (select count(*) from jsonb_array_elements(entry.value -> 'options'))
              <> (select count(distinct option_value ->> 'id') from jsonb_array_elements(entry.value -> 'options') option_value) then
              raise exception 'Duplicate collaboration poll option id' using errcode = '22023';
            end if;

          when 'pollResponses' then
            if not (entry.value ?& array['id', 'pollId', 'memberId', 'optionId', 'sample']) then
              raise exception 'Invalid collaboration poll response contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'pollId', 'memberId', 'optionId'], array['sample'], array[]::text[]
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or not exists (
                select 1 from jsonb_array_elements(payload -> 'polls') target
                where target ->> 'id' = entry.value ->> 'pollId'
                  and exists (
                    select 1 from jsonb_array_elements(target -> 'options') option_value
                    where option_value ->> 'id' = entry.value ->> 'optionId'
                  )
              )
              or not exists (
                select 1 from jsonb_array_elements(payload -> 'memberships') target
                where target ->> 'id' = entry.value ->> 'memberId'
              ) then
              raise exception 'Invalid collaboration poll response contract' using errcode = '22023';
            end if;

          when 'feedback' then
            if not (entry.value ?& array['id', 'channelId', 'prompt', 'status', 'sample']) then
              raise exception 'Invalid collaboration feedback contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'channelId', 'prompt', 'status'], array['sample'], array[]::text[]
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or not exists (
                select 1 from jsonb_array_elements(payload -> 'channels') target
                where target ->> 'id' = entry.value ->> 'channelId'
              )
              or entry.value ->> 'status' not in ('draft', 'open', 'closed') then
              raise exception 'Invalid collaboration feedback contract' using errcode = '22023';
            end if;

          when 'feedbackResponses' then
            if not (entry.value ?& array['id', 'feedbackId', 'authorLabel', 'response', 'createdAt', 'sample']) then
              raise exception 'Invalid collaboration feedback response contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'feedbackId', 'authorLabel', 'response', 'createdAt'], array['sample'], array[]::text[]
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or not exists (
                select 1 from jsonb_array_elements(payload -> 'feedback') target
                where target ->> 'id' = entry.value ->> 'feedbackId'
              )
              or not pac_dsd.jsonb_is_instant(entry.value -> 'createdAt') then
              raise exception 'Invalid collaboration feedback response contract' using errcode = '22023';
            end if;

          when 'learningActivities' then
            if not (entry.value ?& array['id', 'channelId', 'title', 'description', 'reflectionPrompt', 'status', 'sample']) then
              raise exception 'Invalid collaboration learning activity contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'channelId', 'title', 'description', 'reflectionPrompt', 'status'],
              array['sample'], array[]::text[]
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or not exists (
                select 1 from jsonb_array_elements(payload -> 'channels') target
                where target ->> 'id' = entry.value ->> 'channelId'
              )
              or entry.value ->> 'status' not in ('planned', 'open', 'complete') then
              raise exception 'Invalid collaboration learning activity contract' using errcode = '22023';
            end if;

          when 'notificationPreferences' then
            if not (entry.value ?& array['id', 'memberId', 'mode', 'sample']) then
              raise exception 'Invalid collaboration notification preference contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'memberId', 'channelId', 'mode', 'quietHoursNote'], array['sample'], array[]::text[]
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or not exists (
                select 1 from jsonb_array_elements(payload -> 'memberships') target
                where target ->> 'id' = entry.value ->> 'memberId'
              )
              or (entry.value ? 'channelId' and not exists (
                select 1 from jsonb_array_elements(payload -> 'channels') target
                where target ->> 'id' = entry.value ->> 'channelId'
              ))
              or entry.value ->> 'mode' not in ('off', 'immediate', 'digest') then
              raise exception 'Invalid collaboration notification preference contract' using errcode = '22023';
            end if;

          when 'notificationDeliveries' then
            if not (entry.value ?& array['id', 'preferenceId', 'destinationClass', 'status', 'attemptCount', 'sample']) then
              raise exception 'Invalid collaboration notification delivery contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'preferenceId', 'destinationClass', 'status'], array['sample'], array['attemptCount']
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or not exists (
                select 1 from jsonb_array_elements(payload -> 'notificationPreferences') target
                where target ->> 'id' = entry.value ->> 'preferenceId'
              )
              or entry.value ->> 'destinationClass' not in ('native', 'email', 'microsoft')
              or entry.value ->> 'status' not in ('pending', 'delivered', 'failed', 'cancelled')
              or not pac_dsd.jsonb_is_safe_integer(entry.value -> 'attemptCount', 0) then
              raise exception 'Invalid collaboration notification delivery contract' using errcode = '22023';
            end if;

          when 'actionItems' then
            if not (entry.value ?& array['id', 'workspaceId', 'title', 'ownerLabel', 'dueNote', 'status', 'sample', 'updatedAt']) then
              raise exception 'Invalid collaboration action item contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value,
              array['id', 'workspaceId', 'title', 'ownerLabel', 'dueNote', 'status', 'sourceThreadId', 'updatedAt'],
              array['sample'], array[]::text[]
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or entry.value ->> 'workspaceId' <> requested_object_id
              or entry.value ->> 'status' not in ('planned', 'in_progress', 'blocked', 'complete')
              or (entry.value ? 'sourceThreadId' and not exists (
                select 1 from jsonb_array_elements(payload -> 'threads') target
                where target ->> 'id' = entry.value ->> 'sourceThreadId'
              ))
              or not pac_dsd.jsonb_is_instant(entry.value -> 'updatedAt') then
              raise exception 'Invalid collaboration action item contract' using errcode = '22023';
            end if;

          when 'contentProposals' then
            if not (entry.value ?& array['id', 'workspaceId', 'title', 'status', 'sample']) then
              raise exception 'Invalid collaboration content proposal contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'workspaceId', 'title', 'sourceThreadId', 'status'], array['sample'], array[]::text[]
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or entry.value ->> 'workspaceId' <> requested_object_id
              or (entry.value ? 'sourceThreadId' and not exists (
                select 1 from jsonb_array_elements(payload -> 'threads') target
                where target ->> 'id' = entry.value ->> 'sourceThreadId'
              ))
              or entry.value ->> 'status' not in ('draft', 'submitted', 'accepted', 'rejected') then
              raise exception 'Invalid collaboration content proposal contract' using errcode = '22023';
            end if;

          when 'automationPolicies' then
            if not (entry.value ?& array['id', 'workspaceId', 'name', 'status', 'allowedAction', 'sample']) then
              raise exception 'Invalid collaboration automation policy contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'workspaceId', 'name', 'status', 'exactDestination', 'allowedAction', 'expiresAt'],
              array['sample'], array[]::text[]
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or entry.value ->> 'workspaceId' <> requested_object_id
              or entry.value ->> 'status' not in ('draft', 'approved', 'stopped', 'expired')
              or (entry.value ? 'expiresAt' and not pac_dsd.jsonb_is_instant(entry.value -> 'expiresAt')) then
              raise exception 'Invalid collaboration automation policy contract' using errcode = '22023';
            end if;

          when 'automationRuns' then
            if not (entry.value ?& array['id', 'policyId', 'status', 'resultNote', 'createdAt', 'sample']) then
              raise exception 'Invalid collaboration automation run contract' using errcode = '22023';
            end if;
            perform pac_dsd.assert_jsonb_scalar_types(
              entry.value, array['id', 'policyId', 'status', 'resultNote', 'createdAt'], array['sample'], array[]::text[]
            );
            if coalesce(entry.value ->> 'id', '') = ''
              or not exists (
                select 1 from jsonb_array_elements(payload -> 'automationPolicies') target
                where target ->> 'id' = entry.value ->> 'policyId'
              )
              or entry.value ->> 'status' not in ('proposed', 'approved', 'running', 'completed', 'stopped', 'failed')
              or not pac_dsd.jsonb_is_instant(entry.value -> 'createdAt') then
              raise exception 'Invalid collaboration automation run contract' using errcode = '22023';
            end if;
        end case;
      end loop;

      if (select count(*) from jsonb_array_elements(payload -> collection_name))
        <> (select count(distinct collection_entry ->> 'id') from jsonb_array_elements(payload -> collection_name) collection_entry) then
        raise exception 'Duplicate collaboration collection id' using errcode = '22023';
      end if;
    end loop;
    return;
  end if;

  raise exception 'Unregistered work-object kind' using errcode = '22023';
end;
$$;

create or replace function pac_dsd.enforce_runtime_work_object_contract()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
as $$
begin
  perform pac_dsd.assert_runtime_work_object_contract(new.work_kind, new.object_id, new.value);
  return new;
end;
$$;

-- A new trigger protects future writes only. Refuse the upgrade when an older
-- deployment already contains a work object that the strict contract would not
-- permit, so an invalid legacy row cannot remain trusted after this migration.
do $$
declare
  stored record;
begin
  for stored in
    select work_kind, object_id, value
    from pac_dsd.runtime_work_objects
  loop
    perform pac_dsd.assert_runtime_work_object_contract(
      stored.work_kind,
      stored.object_id,
      stored.value
    );
  end loop;
end;
$$;

drop trigger if exists runtime_work_object_contract on pac_dsd.runtime_work_objects;
create trigger runtime_work_object_contract
before insert or update on pac_dsd.runtime_work_objects
for each row execute function pac_dsd.enforce_runtime_work_object_contract();

create or replace function pac_dsd.assert_runtime_idempotency_receipt_contract(
  requested_idempotency_key text,
  requested_kind text,
  requested_object_id text,
  payload jsonb
)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
begin
  perform pac_dsd.assert_allowed_jsonb_keys(payload, array['work_kind', 'object_id']);
  if not (payload ?& array['work_kind', 'object_id']) then
    raise exception 'Invalid idempotency receipt contract' using errcode = '22023';
  end if;
  perform pac_dsd.assert_jsonb_scalar_types(
    payload,
    array['work_kind', 'object_id'],
    array[]::text[],
    array[]::text[]
  );
  if requested_idempotency_key !~ '^((consult-submit-v2-[a-f0-9]{64})|(idem-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}))$'
    or requested_kind not in ('consult_request', 'decision', 'eval_result', 'collaboration_workspace')
    or payload ->> 'work_kind' is distinct from requested_kind
    or payload ->> 'object_id' is distinct from requested_object_id
    or requested_object_id ~* '((employee|worker|personnel)[-_]?[0-9]{1,12}.*(belief|ideolog|equity|readiness|bias|inclusion|participation|engagement))|((belief|ideolog|equity|readiness|bias|inclusion|participation|engagement).*(employee|worker|personnel)[-_]?[0-9]{1,12})'
    or not (
      (requested_kind = 'consult_request'
        and requested_object_id ~ '^CR-[0-9]{8}-[0-9]{4,10}$')
      or (requested_kind = 'decision' and (
        requested_object_id in ('autonomy_policy', 'research_policy')
        or requested_object_id ~ '^research_usage:ru_[0-9]{14}_[a-f0-9]{6}_[a-f0-9]{4}$'
        or requested_object_id ~ '^owner-session-revoked-[a-f0-9]{64}$'
        or requested_object_id ~ '^cycle:cycle-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        or requested_object_id ~ '^stale_flag:[A-Za-z0-9][A-Za-z0-9_-]{0,127}:(past_review_date|review_due_soon|missing_owner|accessibility_pending)$'
        or requested_object_id ~ '^(proposal|rejected_rec):cycle-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}-[pg][1-9][0-9]*$'
      ))
      or (requested_kind = 'eval_result'
        and requested_object_id ~ '^eval-[0-9]{10,16}$')
      or (requested_kind = 'collaboration_workspace'
        and requested_object_id = 'one_dsd_team')
    ) then
    raise exception 'Invalid idempotency receipt contract' using errcode = '22023';
  end if;
end;
$$;

create or replace function pac_dsd.enforce_runtime_idempotency_receipt_contract()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
as $$
begin
  perform pac_dsd.assert_runtime_idempotency_receipt_contract(
    new.idempotency_key,
    new.work_kind,
    new.object_id,
    new.value
  );
  return new;
end;
$$;

create or replace function pac_dsd.enforce_runtime_idempotency_reference_contract()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
begin
  if not exists (
    select 1
    from pac_dsd.runtime_work_objects work
    where work.work_kind = new.work_kind
      and work.object_id = new.object_id
  ) then
    raise exception 'Idempotency receipt references a missing work object' using errcode = '22023';
  end if;
  return null;
end;
$$;

-- Do not bless legacy replay receipts merely because the stricter triggers did
-- not exist when they were written. Every existing receipt must be opaque,
-- canonical, and point at a purpose-limited work object before this upgrade can
-- complete.
do $$
declare
  stored record;
begin
  for stored in
    select idempotency_key, work_kind, object_id, value
    from pac_dsd.runtime_idempotency
  loop
    perform pac_dsd.assert_runtime_idempotency_receipt_contract(
      stored.idempotency_key,
      stored.work_kind,
      stored.object_id,
      stored.value
    );
    if not exists (
      select 1
      from pac_dsd.runtime_work_objects work
      where work.work_kind = stored.work_kind
        and work.object_id = stored.object_id
    ) then
      raise exception 'Legacy idempotency receipt references a missing work object' using errcode = '22023';
    end if;
  end loop;
end;
$$;

drop trigger if exists runtime_idempotency_receipt_contract on pac_dsd.runtime_idempotency;
create trigger runtime_idempotency_receipt_contract
before insert on pac_dsd.runtime_idempotency
for each row execute function pac_dsd.enforce_runtime_idempotency_receipt_contract();

drop trigger if exists runtime_idempotency_reference_contract on pac_dsd.runtime_idempotency;
create constraint trigger runtime_idempotency_reference_contract
after insert on pac_dsd.runtime_idempotency
deferrable initially deferred
for each row execute function pac_dsd.enforce_runtime_idempotency_reference_contract();

-- Durable counters are reserved for opaque consultation reference-number
-- allocation. A semantic free-text scope would otherwise create an unbounded,
-- non-JSON profile carrier outside the DEC-014 scanner.
alter table pac_dsd.runtime_counters
  drop constraint if exists runtime_counters_registered_scope;
alter table pac_dsd.runtime_counters
  add constraint runtime_counters_registered_scope
  check (scope ~ '^cr:[0-9]{8}$') not valid;
alter table pac_dsd.runtime_counters
  validate constraint runtime_counters_registered_scope;

-- Rate-limit rows retain only one of four registered purposes and an opaque
-- HMAC. Revalidate legacy rows before trusting the upgraded database.
alter table pac_dsd.runtime_rate_limits
  drop constraint if exists runtime_rate_limits_registered_identity;
alter table pac_dsd.runtime_rate_limits
  add constraint runtime_rate_limits_registered_identity
  check (
    scope in ('staff-ask', 'owner-login', 'consultation-intake', 'consultation-tracking')
    and subject_hash ~ '^[a-f0-9]{64}$'
  ) not valid;
alter table pac_dsd.runtime_rate_limits
  validate constraint runtime_rate_limits_registered_identity;

create or replace function pac_dsd.assert_runtime_rate_limit_request(
  requested_scope text,
  requested_subject_hash text,
  requested_limit integer,
  requested_window_seconds integer
)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
begin
  if requested_subject_hash !~ '^[a-f0-9]{64}$'
    or not (
      (requested_scope = 'staff-ask' and requested_limit = 30 and requested_window_seconds = 600)
      or (requested_scope = 'owner-login' and requested_limit = 10 and requested_window_seconds = 900)
      or (requested_scope = 'consultation-intake' and requested_limit = 20 and requested_window_seconds = 3600)
      or (requested_scope = 'consultation-tracking' and requested_limit = 20 and requested_window_seconds = 600)
    ) then
    raise exception 'Invalid rate-limit request' using errcode = '22023';
  end if;
end;
$$;

-- Replace the security-definer entry point as part of the upgrade too; an
-- already-deployed 0009 may still contain the former generic scope grammar.
create or replace function pac_dsd.consume_runtime_rate_limit(
  requested_scope text,
  requested_subject_hash text,
  requested_limit integer,
  requested_window_seconds integer
)
returns table (allowed boolean, remaining integer, reset_at timestamptz)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  current_count integer;
  current_reset timestamptz;
begin
  perform pac_dsd.assert_runtime_rate_limit_request(
    requested_scope,
    requested_subject_hash,
    requested_limit,
    requested_window_seconds
  );

  insert into pac_dsd.runtime_rate_limits (scope, subject_hash, request_count, reset_at)
  values (
    requested_scope,
    requested_subject_hash,
    1,
    clock_timestamp() + make_interval(secs => requested_window_seconds)
  )
  on conflict (scope, subject_hash) do update
  set request_count = case
        when pac_dsd.runtime_rate_limits.reset_at <= clock_timestamp() then 1
        else pac_dsd.runtime_rate_limits.request_count + 1
      end,
      reset_at = case
        when pac_dsd.runtime_rate_limits.reset_at <= clock_timestamp()
          then clock_timestamp() + make_interval(secs => requested_window_seconds)
        else pac_dsd.runtime_rate_limits.reset_at
      end,
      updated_at = clock_timestamp()
  returning request_count, pac_dsd.runtime_rate_limits.reset_at
  into current_count, current_reset;

  allowed := current_count <= requested_limit;
  remaining := greatest(0, requested_limit - current_count);
  reset_at := current_reset;
  return next;
end;
$$;

revoke all privileges on function pac_dsd.assert_runtime_rate_limit_request(text, text, integer, integer) from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.consume_runtime_rate_limit(text, text, integer, integer) from public;
grant execute on function pac_dsd.consume_runtime_rate_limit(text, text, integer, integer) to pac_dsd_app_runtime;

create or replace function pac_dsd.assert_runtime_audit_event_contract(payload jsonb)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
begin
  perform pac_dsd.assert_no_prohibited_profile_fields(payload);
  perform pac_dsd.assert_allowed_jsonb_keys(payload, array[
    'trace_id', 'span_id', 'at', 'agent_id', 'agent_version', 'tool_name',
    'autonomy_level_used', 'permission_mode', 'dry_run', 'content_ids_touched',
    'allowlist_hit', 'allowlist_miss_reason', 'safety_refusal_code',
    'human_disposition', 'model_id', 'latency_ms', 'ok', 'error_code'
  ]);
  if not (payload ?& array[
    'trace_id', 'span_id', 'at', 'agent_id', 'agent_version', 'tool_name',
    'autonomy_level_used', 'permission_mode', 'dry_run', 'content_ids_touched',
    'allowlist_hit', 'ok'
  ]) then
    raise exception 'Invalid runtime audit-event persistence contract' using errcode = '22023';
  end if;
  perform pac_dsd.assert_jsonb_scalar_types(
    payload,
    array[
      'trace_id', 'span_id', 'at', 'agent_id', 'agent_version', 'tool_name',
      'autonomy_level_used', 'permission_mode', 'allowlist_miss_reason',
      'safety_refusal_code', 'model_id', 'error_code'
    ],
    array['dry_run', 'allowlist_hit', 'ok'],
    array['latency_ms']
  );
  if payload ->> 'trace_id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or payload ->> 'span_id' !~ '^[0-9a-f]{8}$'
    or not pac_dsd.jsonb_is_canonical_utc_instant(payload -> 'at')
    or payload ->> 'agent_id' not in (
      'program_orchestrator', 'ask_concierge', 'ci_guide', 'librarian',
      'a11y_reviewer', 'consult_intake', 'graduation_coach', 'embed_advisor',
      'content_sentinel', 'eval_steward', 'system'
    )
    or payload ->> 'agent_version' not in ('0.1.0', 'collaboration-owner-v1')
    or not (payload ->> 'tool_name' = any(array[
      'corpus.search', 'corpus.semantic_retrieve', 'authority.label_resolve',
      'community.brief_get', 'community.brief_list', 'citation.attach',
      'gap.report_draft', 'research.web_search', 'research.current_answer',
      'research.deep_search', 'answer.structured_draft', 'checklist.draft',
      'agenda.consult_prep_draft', 'intake.summary_pack', 'work_object.draft',
      'conflict.surface', 'resource.classify_draft', 'resource.tag_L1_L4',
      'resource.stale_detect', 'resource.stale_flag_state', 'resource.page_draft',
      'resource.retire_recommend', 'a11y.scan_draft', 'a11y.alt_text_suggest',
      'plain.reading_level_check', 'a11y.keyboard_checklist', 'a11y.no_icons_lint',
      'intake.form_assist', 'intake.requester_track', 'intake.requester_correct',
      'intake.requester_withdraw', 'intake.requester_rotate_key',
      'queue.rank_suggest', 'queue.status_get',
      'queue.status_set', 'queue.auto_triage', 'calendar.handoff_prep',
      'calendar.schedule_reversible', 'escalate.route', 'learn.path_recommend',
      'progress.local_get', 'progress.local_write', 'graduation.next_practice',
      'completion.aggregate_safe', 'embed.question_bank',
      'embed.journey_burden_prompts', 'embed.equity_impact_qs',
      'embed.stakeholder_map_draft', 'memory.decision_read',
      'memory.decision_write', 'memory.version_read', 'memory.eval_results_read',
      'memory.eval_results_write', 'memory.rejected_rec_log',
      'orchestrator.run_cycle', 'proposal.write', 'proposal.decide',
      'eval.run_cases', 'eval.compare_models', 'registry.model_list',
      'registry.agent_toggle', 'flags.set', 'policy.stop_all',
      'safety.pii_detect', 'safety.surveillance_refuse', 'safety.persona_refuse',
      'safety.publish_refuse', 'safety.tribal_gate', 'safety.privacy_notice',
      'runtime.unknown_tool_refusal',
      'collaboration.update_workspace_summary', 'collaboration.update_channel',
      'collaboration.create_thread', 'collaboration.reply',
      'collaboration.edit_post', 'collaboration.update_meeting',
      'collaboration.update_action', 'collaboration.submit_feedback'
    ]))
    or payload ->> 'autonomy_level_used' not in ('A0', 'A1', 'A2', 'A3', 'A4', 'A5')
    or payload ->> 'permission_mode' not in ('always', 'with_preview', 'human_approve', 'owner_only')
    or jsonb_typeof(payload -> 'content_ids_touched') <> 'array'
    or (payload ? 'allowlist_miss_reason' and not (
      payload ->> 'allowlist_miss_reason' = any(array[
        'tool not registered', 'tool disabled by flag or phase',
        'tool not in agent allowlist',
        'paused by the Equity and Inclusion Operations Consultant',
        'agent disabled by owner policy', 'agent disabled in its definition',
        'owner-only tool'
      ])
      or payload ->> 'allowlist_miss_reason' ~ '^tool requires A[0-5]; effective ceiling A[0-5]$'
    ))
    or (payload -> 'allowlist_hit' = 'true'::jsonb and payload ? 'allowlist_miss_reason')
    or (payload ? 'safety_refusal_code' and payload ->> 'safety_refusal_code' not in (
      'pii_detected', 'hr_complaint_redirect', 'surveillance_refused',
      'persona_refused', 'publish_refused', 'tribal_gate', 'legal_invention_refused'
    ))
    or (payload ? 'human_disposition' and jsonb_typeof(payload -> 'human_disposition') not in ('null', 'string'))
    or (payload ? 'human_disposition' and jsonb_typeof(payload -> 'human_disposition') = 'string'
      and payload ->> 'human_disposition' not in ('approve', 'edit', 'reject', 'regenerate'))
    or (payload ? 'model_id' and (
      length(payload ->> 'model_id') > 80
      or payload ->> 'model_id' !~ '^[A-Za-z0-9][A-Za-z0-9._-]*(/[A-Za-z0-9][A-Za-z0-9._-]*)*$'
    ))
    or (payload ? 'latency_ms' and (payload ->> 'latency_ms')::numeric < 0)
    or (payload ? 'error_code' and payload ->> 'error_code' not in (
      'tool_unknown', 'tool_disabled', 'allowlist_miss', 'kill_switch',
      'agent_disabled', 'autonomy_ceiling', 'owner_only', 'tool_execution_failed'
    )) then
    raise exception 'Invalid runtime audit-event persistence contract' using errcode = '22023';
  end if;
  perform pac_dsd.assert_jsonb_string_array(payload -> 'content_ids_touched');
  if jsonb_array_length(payload -> 'content_ids_touched') > 100
    or (select count(*) from jsonb_array_elements_text(payload -> 'content_ids_touched'))
      <> (select count(distinct content_id) from jsonb_array_elements_text(payload -> 'content_ids_touched') content_id)
    or exists (
      select 1 from jsonb_array_elements_text(payload -> 'content_ids_touched') content_id
      where content_id !~ '^(CR-[0-9]{8}-[0-9]{4,10}|one_dsd_team|(pn|ja|lm|ext|asset)-[a-z0-9][a-z0-9-]{0,119}|somali|hmong|karen|oromo|african-american|latino|vietnamese|khmer|lao|russian-speaking|arabic-speaking|deaf-deafblind-hard-of-hearing|rural|tribal-nations|cycle-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}(-[pg][1-9][0-9]*)?)$'
        or content_id ~* '(employee|worker|personnel)[-_]?[0-9]{1,12}.*(belief|ideolog|equity|readiness|bias|inclusion|participation|engagement)|(belief|ideolog|equity|readiness|bias|inclusion|participation|engagement).*(employee|worker|personnel)[-_]?[0-9]{1,12}'
    ) then
    raise exception 'Invalid runtime audit content identifier' using errcode = '22023';
  end if;
end;
$$;

create or replace function pac_dsd.enforce_runtime_audit_event_contract()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
as $$
begin
  perform pac_dsd.assert_runtime_audit_event_contract(new.event);
  if new.occurred_at is distinct from (new.event ->> 'at')::timestamptz then
    raise exception 'Audit timestamp does not match the canonical event instant' using errcode = '22023';
  end if;
  return new;
end;
$$;

-- Apply the same fail-closed upgrade rule to audit rows written before this
-- contract existed. Operators must explicitly remove or quarantine rejected
-- legacy data before retrying the migration.
do $$
declare
  stored record;
begin
  for stored in
    select event, occurred_at
    from pac_dsd.runtime_audit_events
  loop
    perform pac_dsd.assert_runtime_audit_event_contract(stored.event);
    if stored.occurred_at is distinct from (stored.event ->> 'at')::timestamptz then
      raise exception 'Legacy audit timestamp does not match the canonical event instant' using errcode = '22023';
    end if;
  end loop;
end;
$$;

drop trigger if exists runtime_audit_event_contract on pac_dsd.runtime_audit_events;
create trigger runtime_audit_event_contract
before insert on pac_dsd.runtime_audit_events
for each row execute function pac_dsd.enforce_runtime_audit_event_contract();

