  'Purpose-limits generic runtime storage to registered consultation, decision, evaluation, and collaboration object families.';


-- 0013_pac_security_housekeeping.sql

-- Owner-session revocations are retained only through the lifetime of the signed
-- session they invalidate. Canonical UTC instants make expiry comparisons
-- unambiguous and let malformed records remain fail-closed instead of being
-- accidentally removed by housekeeping.
create or replace function pac_dsd.is_canonical_utc_instant(candidate text)
returns boolean
language plpgsql
stable
strict
set search_path = pg_catalog, pg_temp
as $$
declare
  parsed timestamptz;
begin
  if candidate !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' then
    return false;
  end if;
  begin
    parsed := candidate::timestamptz;
  exception when others then
    return false;
  end;
  return to_char(parsed at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') = candidate;
end;
$$;

-- Housekeeping must never infer that an arbitrary decision is a research
-- usage record. This mirrors the application's narrow persisted shape closely
-- enough to make deletion authority explicit and fail closed on malformed data.
create or replace function pac_dsd.is_valid_research_usage_record(
  candidate_id text,
  candidate jsonb
)
returns boolean
language sql
immutable
strict
set search_path = pg_catalog, pg_temp
as $$
  select
    jsonb_typeof(candidate) = 'object'
    and candidate_id ~ '^research_usage:ru_[0-9]{14}_[a-f0-9]{6}_[a-f0-9]{4}$'
    and candidate_id = 'research_usage:' || (candidate ->> 'id')
    and (candidate - array[
      'id', 'at', 'provider', 'model', 'depth', 'query_hash', 'domains',
      'estimated_usd', 'reported_usd', 'input_tokens', 'output_tokens',
      'search_queries', 'web_search_calls', 'fetch_url_calls', 'tool_calls',
      'ok', 'error_code', 'latency_ms', 'trace_id', 'provider_trace_id'
    ]::text[]) = '{}'::jsonb
    and candidate ?& array[
      'id', 'at', 'provider', 'model', 'depth', 'query_hash', 'domains',
      'estimated_usd', 'ok', 'latency_ms', 'trace_id'
    ]::text[]
    and candidate ->> 'id' ~ '^ru_[0-9]{14}_[a-f0-9]{6}_[a-f0-9]{4}$'
    and pac_dsd.is_canonical_utc_instant(candidate ->> 'at')
    and candidate ->> 'provider' in ('perplexity_agent', 'fixture')
    and (
      candidate ->> 'model' in (
        'fixture/research-1', 'perplexity-search', 'fast', 'low', 'medium', 'high'
      )
      or candidate ->> 'model' ~ '^msh_[a-f0-9]{64}$'
    )
    and candidate ->> 'depth' in ('current_web', 'deep_research')
    and candidate ->> 'query_hash' ~ '^[a-f0-9]{16}$'
    and case
      when jsonb_typeof(candidate -> 'domains') = 'array' then
        jsonb_array_length(candidate -> 'domains') <= 20
        and (select count(*) from jsonb_array_elements_text(candidate -> 'domains'))
          = (select count(distinct domain) from jsonb_array_elements_text(candidate -> 'domains') domain)
        and not exists (
          select 1
          from jsonb_array_elements(candidate -> 'domains') as domain(value)
          where jsonb_typeof(domain.value) <> 'string'
            or domain.value #>> '{}' !~ '^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]([a-z0-9-]{0,61}[a-z0-9])?$'
        )
      else false
    end
    and jsonb_typeof(candidate -> 'estimated_usd') = 'number'
    and (candidate ->> 'estimated_usd')::numeric >= 0
    and (not (candidate ? 'reported_usd') or (
      jsonb_typeof(candidate -> 'reported_usd') = 'number'
      and (candidate ->> 'reported_usd')::numeric >= 0
    ))
    and (not (candidate ? 'input_tokens') or pac_dsd.jsonb_is_safe_integer(candidate -> 'input_tokens', 0))
    and (not (candidate ? 'output_tokens') or pac_dsd.jsonb_is_safe_integer(candidate -> 'output_tokens', 0))
    and (not (candidate ? 'search_queries') or pac_dsd.jsonb_is_safe_integer(candidate -> 'search_queries', 0))
    and (not (candidate ? 'web_search_calls') or pac_dsd.jsonb_is_safe_integer(candidate -> 'web_search_calls', 0))
    and (not (candidate ? 'fetch_url_calls') or pac_dsd.jsonb_is_safe_integer(candidate -> 'fetch_url_calls', 0))
    and (not (candidate ? 'tool_calls') or pac_dsd.jsonb_is_safe_integer(candidate -> 'tool_calls', 0))
    and jsonb_typeof(candidate -> 'ok') = 'boolean'
    and ((candidate -> 'ok' = 'true'::jsonb and not (candidate ? 'error_code')) or (
      candidate -> 'ok' = 'false'::jsonb
      and candidate ->> 'error_code' = 'research_execution_failed'
    ))
    and pac_dsd.jsonb_is_safe_integer(candidate -> 'latency_ms', 0)
    and jsonb_typeof(candidate -> 'trace_id') = 'string'
    and candidate ->> 'trace_id' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and (not (candidate ? 'provider_trace_id') or (
      jsonb_typeof(candidate -> 'provider_trace_id') = 'string'
      and candidate ->> 'provider_trace_id' ~ '^pth_[a-f0-9]{64}$'
    ));
$$;

create or replace function pac_dsd.enforce_owner_session_revocation_contract()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $$
begin
  if new.work_kind = 'decision'
    and new.object_id ~ '^owner-session-revoked-[a-f0-9]{64}$'
    and (
      new.value ->> 'kind' is distinct from 'owner_session_revocation'
      or new.value ->> 'session_hash' !~ '^[a-f0-9]{64}$'
      or new.object_id is distinct from 'owner-session-revoked-' || (new.value ->> 'session_hash')
      or not pac_dsd.is_canonical_utc_instant(new.value ->> 'revoked_at')
      or not pac_dsd.is_canonical_utc_instant(new.value ->> 'expires_at')
      or new.value ->> 'revoked_at' > new.value ->> 'expires_at'
    ) then
    raise exception 'Invalid owner-session revocation lifecycle' using errcode = '22023';
  end if;
  return new;
end;
$$;

drop trigger if exists owner_session_revocation_contract on pac_dsd.runtime_work_objects;
create trigger owner_session_revocation_contract
before insert or update on pac_dsd.runtime_work_objects
for each row execute function pac_dsd.enforce_owner_session_revocation_contract();

create index if not exists runtime_rate_limits_expiry_idx
  on pac_dsd.runtime_rate_limits(reset_at);

create index if not exists runtime_audit_events_expiry_idx
  on pac_dsd.runtime_audit_events(occurred_at, audit_id);

create index if not exists runtime_research_usage_expiry_idx
  on pac_dsd.runtime_work_objects(((value ->> 'at')::text), object_id)
  where work_kind = 'decision' and object_id like 'research_usage:%';

-- The application role cannot delete either backing table directly. This
-- bounded definer operation may delete only already-expired, well-formed
-- revocation records and already-expired abuse-control buckets.
create or replace function pac_dsd.purge_expired_security_records()
returns table (
  owner_session_revocations_deleted integer,
  rate_limit_buckets_deleted integer,
  audit_events_deleted integer,
  research_usage_records_deleted integer
)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pg_temp
set row_security = off
as $$
declare
  revocation_cutoff text;
  removed_revocations integer;
  removed_buckets integer;
  operational_cutoff timestamptz;
  removed_audit_events integer;
  removed_research_usage integer;
begin
  revocation_cutoff := to_char(
    (clock_timestamp() - interval '10 minutes') at time zone 'UTC',
    'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
  );
  operational_cutoff := clock_timestamp() - interval '90 days';

  with candidates as materialized (
    select work_kind, object_id
    from pac_dsd.runtime_work_objects
    where work_kind = 'decision'
      and object_id ~ '^owner-session-revoked-[a-f0-9]{64}$'
      and value ->> 'kind' = 'owner_session_revocation'
      and value ->> 'session_hash' ~ '^[a-f0-9]{64}$'
      and object_id = 'owner-session-revoked-' || (value ->> 'session_hash')
      and pac_dsd.is_canonical_utc_instant(value ->> 'revoked_at')
      and pac_dsd.is_canonical_utc_instant(value ->> 'expires_at')
      and value ->> 'revoked_at' <= value ->> 'expires_at'
      and value ->> 'expires_at' <= revocation_cutoff
    order by updated_at, object_id
    for update skip locked
    limit 10000
  ), removed as (
    delete from pac_dsd.runtime_work_objects stored
    using candidates
    where stored.work_kind = candidates.work_kind
      and stored.object_id = candidates.object_id
    returning 1
  )
  select count(*)::integer into removed_revocations from removed;

  with candidates as materialized (
    select scope, subject_hash
    from pac_dsd.runtime_rate_limits
    where reset_at <= clock_timestamp()
    order by reset_at, scope, subject_hash
    for update skip locked
    limit 10000
  ), removed as (
    delete from pac_dsd.runtime_rate_limits stored
    using candidates
    where stored.scope = candidates.scope
      and stored.subject_hash = candidates.subject_hash
    returning 1
  )
  select count(*)::integer into removed_buckets from removed;

  -- The append-only trigger accepts deletion only inside this narrowly scoped
  -- definer operation. A malformed or mismatched event is never deletion
  -- authority, even when its typed occurred_at column is old.
  perform pg_catalog.set_config('pac_dsd.allow_immutable_change', 'on', true);
  with candidates as materialized (
    select audit_id
    from pac_dsd.runtime_audit_events
    where occurred_at <= operational_cutoff
      and pac_dsd.is_canonical_utc_instant(event ->> 'at')
      and (event ->> 'at')::timestamptz = occurred_at
    order by occurred_at, audit_id
    for update skip locked
    limit 10000
  ), removed as (
    delete from pac_dsd.runtime_audit_events stored
    using candidates
    where stored.audit_id = candidates.audit_id
    returning 1
  )
  select count(*)::integer into removed_audit_events from removed;
  perform pg_catalog.set_config('pac_dsd.allow_immutable_change', 'off', true);

  with candidates as materialized (
    select work_kind, object_id
    from pac_dsd.runtime_work_objects
    where work_kind = 'decision'
      and object_id like 'research_usage:%'
      and pac_dsd.is_valid_research_usage_record(object_id, value)
      and (value ->> 'at')::timestamptz <= operational_cutoff
    order by value ->> 'at', object_id
    for update skip locked
    limit 10000
  ), removed as (
    delete from pac_dsd.runtime_work_objects stored
    using candidates
    where stored.work_kind = candidates.work_kind
      and stored.object_id = candidates.object_id
    returning 1
  )
  select count(*)::integer into removed_research_usage from removed;

  return query select
    removed_revocations,
    removed_buckets,
    removed_audit_events,
    removed_research_usage;
end;
$$;

revoke all privileges on function pac_dsd.is_canonical_utc_instant(text) from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.is_valid_research_usage_record(text, jsonb) from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.enforce_owner_session_revocation_contract() from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.purge_expired_security_records() from public;
grant execute on function pac_dsd.purge_expired_security_records() to pac_dsd_app_runtime;

do $$
declare
  role_name text;
begin
  foreach role_name in array array['anon', 'authenticated']
  loop
    if exists (select 1 from pg_catalog.pg_roles where rolname = role_name) then
      execute format(
        'revoke all privileges on function pac_dsd.purge_expired_security_records() from %I',
        role_name
      );
    end if;
  end loop;
end;
$$;

comment on function pac_dsd.purge_expired_security_records() is
  'Bounded privacy housekeeping for expired owner-session revocations, HMAC rate-limit buckets, content-free audit events, and research-usage records; malformed records remain fail-closed.';


-- 0014_pac_consultation_persistence_contract.sql

create or replace function pac_dsd.is_consultation_request_id(candidate text)
returns boolean
language plpgsql
stable
strict
set search_path = pg_catalog, pg_temp
as $$
declare
  compact_date text;
  parsed_date date;
begin
  if candidate !~ '^CR-[0-9]{8}-[0-9]{4,16}$'
    or split_part(candidate, '-', 3) ~ '^0+$' then
    return false;
  end if;
  compact_date := split_part(candidate, '-', 2);
  begin
    parsed_date := to_date(compact_date, 'YYYYMMDD');
  exception when others then
    return false;
  end;
  return to_char(parsed_date, 'YYYYMMDD') = compact_date;
end;
$$;

create or replace function pac_dsd.is_iso_calendar_date(candidate text)
returns boolean
language plpgsql
stable
strict
set search_path = pg_catalog, pg_temp
as $$
declare
  parsed_date date;
begin
  if candidate !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
    return false;
  end if;
  begin
    parsed_date := candidate::date;
  exception when others then
    return false;
  end;
  return to_char(parsed_date, 'YYYY-MM-DD') = candidate;
end;
$$;

create or replace function pac_dsd.is_zoned_instant(candidate text)
returns boolean
language plpgsql
stable
strict
set search_path = pg_catalog, pg_temp
as $$
declare
  parsed timestamptz;
begin
  if candidate !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2}(\.[0-9]{1,3})?)?(Z|[+-][0-9]{2}:[0-9]{2})$' then
    return false;
  end if;
  begin
    parsed := candidate::timestamptz;
  exception when others then
    return false;
  end;
  return parsed is not null;
end;
$$;

create or replace function pac_dsd.is_bounded_json_string(
  candidate jsonb,
  minimum_length integer,
  maximum_length integer,
  require_trimmed boolean default false
)
returns boolean
language sql
immutable
strict
set search_path = pg_catalog, pg_temp
as $$
  select jsonb_typeof(candidate) = 'string'
    and length(candidate #>> '{}') between minimum_length and maximum_length
    and (not require_trimmed or candidate #>> '{}' = btrim(candidate #>> '{}'))
$$;

create or replace function pac_dsd.is_json_safe_integer(
  candidate jsonb,
  minimum_value numeric,
  maximum_value numeric
)
returns boolean
language sql
immutable
strict
set search_path = pg_catalog, pg_temp
as $$
  select jsonb_typeof(candidate) = 'number'
    and candidate::text ~ '^(0|[1-9][0-9]*)$'
    and (candidate #>> '{}')::numeric between minimum_value and maximum_value
$$;

create or replace function pac_dsd.assert_bounded_json_string_array(
  candidate jsonb,
  minimum_items integer,
  maximum_items integer,
  maximum_item_length integer,
  allowed_values text[] default null,
  require_unique boolean default false
)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
begin
  if candidate is null or jsonb_typeof(candidate) <> 'array'
    or jsonb_array_length(candidate) not between minimum_items and maximum_items
    or exists (
      select 1
      from jsonb_array_elements(candidate) item(value)
      where jsonb_typeof(value) <> 'string'
        or length(value #>> '{}') > maximum_item_length
        or (allowed_values is not null and not ((value #>> '{}') = any(allowed_values)))
    )
    or (require_unique and (
      select count(*) from jsonb_array_elements_text(candidate)
    ) <> (
      select count(distinct value) from jsonb_array_elements_text(candidate) item(value)
    )) then
    raise exception 'Invalid bounded JSON string array' using errcode = '22023';
  end if;
end;
$$;

create or replace function pac_dsd.assert_consultation_persistence_contract(
  requested_object_id text,
  payload jsonb
)
returns void
language plpgsql
stable
set search_path = pg_catalog, pac_dsd
as $$
declare
  entry record;
  previous_at text := null;
  previous_status text := null;
  root_ask boolean;
  packet_ask boolean;
  expected_support numeric;
  expected_stage numeric;
  expected_urgency numeric;
  expected_tribal boolean;
  expected_high_stakes boolean;
begin
  perform pac_dsd.assert_runtime_work_object_contract('consult_request', requested_object_id, payload);
  if not pac_dsd.is_consultation_request_id(requested_object_id) then
    raise exception 'Invalid consultation request identifier' using errcode = '22023';
  end if;

  if payload ->> 'record_type' = 'consultation_tombstone' then
    if not pac_dsd.is_canonical_utc_instant(payload ->> 'retention_expires_at')
      or not pac_dsd.is_canonical_utc_instant(payload ->> 'redacted_at')
      or payload ->> 'updated_at' is distinct from payload ->> 'redacted_at'
      or not pac_dsd.is_json_safe_integer(payload -> 'version', 2, 9007199254740991)
      or payload ->> 'retention_policy_id' !~ '^[A-Za-z0-9][A-Za-z0-9._-]{2,79}$' then
      raise exception 'Invalid strict consultation tombstone contract' using errcode = '22023';
    end if;
    return;
  end if;

  if payload ->> 'record_type' <> 'consultation_request'
    or substring(requested_object_id from 4 for 8)
       is distinct from replace(substring(payload ->> 'created_at' from 1 for 10), '-', '')
    or not pac_dsd.is_canonical_utc_instant(payload ->> 'created_at')
    or not pac_dsd.is_canonical_utc_instant(payload ->> 'participation_acknowledged_at')
    or payload ->> 'participation_acknowledged_at' is distinct from payload ->> 'created_at'
    or not pac_dsd.is_canonical_utc_instant(payload ->> 'updated_at')
    or not pac_dsd.is_canonical_utc_instant(payload ->> 'retention_expires_at')
    or payload ->> 'updated_at' < payload ->> 'created_at'
    or payload ->> 'retention_expires_at' <= payload ->> 'created_at'
    or payload ->> 'retention_policy_id' !~ '^[A-Za-z0-9][A-Za-z0-9._-]{2,79}$'
    or not pac_dsd.is_json_safe_integer(payload -> 'version', 1, 9007199254740991)
    or not pac_dsd.is_bounded_json_string(payload -> 'work_name', 3, 120, true)
    or not pac_dsd.is_bounded_json_string(payload -> 'goals', 20, 2000, true)
    or not pac_dsd.is_bounded_json_string(payload -> 'equity_questions_considered', 0, 2000, true)
    or not pac_dsd.is_bounded_json_string(payload -> 'support_other_note', 0, 200, true)
    or not pac_dsd.is_bounded_json_string(payload -> 'populations_note', 0, 300, true)
    or not pac_dsd.is_bounded_json_string(payload -> 'access_note', 0, 300, true)
    or not pac_dsd.is_bounded_json_string(payload -> 'attachment_notes', 0, 500, true)
    or not pac_dsd.is_bounded_json_string(payload -> 'situation', 40, 4000, true)
    or (payload ? 'status_reason' and not pac_dsd.is_bounded_json_string(payload -> 'status_reason', 0, 1000, true))
    or (payload ->> 'status' = 'declined' and not coalesce(pac_dsd.is_bounded_json_string(payload -> 'status_reason', 1, 1000, true), false))
    or (payload ? 'owner_notes' and not pac_dsd.is_bounded_json_string(payload -> 'owner_notes', 0, 5000, true))
    or (payload ? 'path_id' and not pac_dsd.is_bounded_json_string(payload -> 'path_id', 0, 10, false))
    or (payload ? 'pinned_order' and not pac_dsd.is_json_safe_integer(payload -> 'pinned_order', 0, 999))
    or (payload ? 'scheduled_for' and not pac_dsd.is_zoned_instant(payload ->> 'scheduled_for'))
    or (payload ->> 'status' = 'scheduled' and not coalesce(pac_dsd.is_zoned_instant(payload ->> 'scheduled_for'), false))
    or not (
      payload ->> 'deadline_date' = ''
      or pac_dsd.is_iso_calendar_date(payload ->> 'deadline_date')
    )
    or (payload ->> 'timing_urgency' = 'hard_deadline' and not pac_dsd.is_iso_calendar_date(payload ->> 'deadline_date'))
    or (payload ? 'requester_role' and payload ->> 'requester_role' not in ('program_ops', 'supervisor', 'equity_director_specialist', 'analyst_tech', 'communications', 'procurement_contracts', 'other'))
    or (payload ? 'preferred_meeting_mode' and payload ->> 'preferred_meeting_mode' not in ('in_person', 'virtual', 'either', 'not_sure')) then
    raise exception 'Invalid strict consultation root contract' using errcode = '22023';
  end if;

  perform pac_dsd.assert_bounded_json_string_array(payload -> 'desired_support_type', 1, 6, 30, array[
    'scoping_goals', 'equity_embed_review', 'access_language_check',
    'stakeholder_partner_map', 'facilitation_prep', 'other'
  ], true);
  perform pac_dsd.assert_bounded_json_string_array(payload -> 'affected_populations', 0, 8, 40, array[
    'language_access_needs', 'disability_access', 'rural_greater_minnesota',
    'older_adults', 'children_families', 'immigrant_refugee_general',
    'specific_minnesota_community', 'tribal_nation'
  ], true);
  perform pac_dsd.assert_bounded_json_string_array(payload -> 'access_language_needs', 0, 5, 40, array[
    'interpreter_for_consult', 'captioning', 'plain_language_materials',
    'timing_constraints', 'other'
  ], true);
  perform pac_dsd.assert_bounded_json_string_array(payload -> 'links', 0, 5, 2048, null, true);
  if (payload -> 'desired_support_type') ? 'other'
    and not pac_dsd.is_bounded_json_string(payload -> 'support_other_note', 1, 200, true) then
    raise exception 'Other consultation support requires a note' using errcode = '22023';
  end if;
  for entry in select value from jsonb_array_elements(payload -> 'links')
  loop
    if entry.value #>> '{}' !~* '^https?://[^/@[:space:]]+([.:][^/@[:space:]]+)(/|$)'
      or entry.value #>> '{}' ~* '^https?://([^/]*@|localhost([:/]|$)|[^/]+\.(local|internal|intranet|corp)([:/]|$))' then
      raise exception 'Invalid public consultation link' using errcode = '22023';
    end if;
  end loop;

  if payload ? 'ask_context' then
    if not pac_dsd.is_bounded_json_string(payload -> 'ask_context' -> 'session_id', 0, 64, false)
      or not pac_dsd.is_bounded_json_string(payload -> 'ask_context' -> 'excerpt', 0, 600, false) then
      raise exception 'Invalid strict consultation Ask context' using errcode = '22023';
    end if;
    perform pac_dsd.assert_bounded_json_string_array(payload -> 'ask_context' -> 'intents_tried', 0, 10, 40, null, false);
  end if;

  expected_support := case
    when (payload -> 'desired_support_type') ?| array['scoping_goals', 'equity_embed_review'] then 6
    when (payload -> 'desired_support_type') ? 'facilitation_prep' then 3
    else 4
  end;
  expected_stage := case payload ->> 'stage'
    when 'conceptual' then 5 when 'designing' then 5 when 'launching' then 4 else 2
  end;
  expected_urgency := case payload ->> 'timing_urgency'
    when 'exploratory' then 10 when 'within_2_weeks' then 20 when 'live_urgent' then 40 else null
  end;
  expected_tribal := (payload -> 'affected_populations') ? 'tribal_nation';
  expected_high_stakes := ((payload ->> 'goals') || ' ' || (payload ->> 'situation'))
    ~* '\m(procurement|contract|vendor|RFP|budget|statute|rule change|technology|system replacement|data sharing|algorithm)\M';
  if not pac_dsd.is_json_safe_integer(payload -> 'priority_signals' -> 'support_weight', expected_support, expected_support)
    or not pac_dsd.is_json_safe_integer(payload -> 'priority_signals' -> 'stage_weight', expected_stage, expected_stage)
    or jsonb_typeof(payload -> 'priority_signals' -> 'total') <> 'number'
    or (payload -> 'priority_signals' ->> 'total')::numeric not between 0 and 100
    or jsonb_typeof(payload -> 'priority_signals' -> 'urgency_weight') <> 'number'
    or (payload ->> 'timing_urgency' = 'hard_deadline' and (payload -> 'priority_signals' ->> 'urgency_weight')::numeric not between 30 and 40)
    or (payload ->> 'timing_urgency' <> 'hard_deadline' and (payload -> 'priority_signals' ->> 'urgency_weight')::numeric <> expected_urgency)
    or (payload -> 'priority_signals' ->> 'total')::numeric <>
       (payload -> 'priority_signals' ->> 'urgency_weight')::numeric + expected_support + expected_stage
    or (payload -> 'priority_signals' ->> 'tribal_gate')::boolean is distinct from expected_tribal
    or (payload -> 'priority_signals' ->> 'high_stakes')::boolean is distinct from expected_high_stakes then
    raise exception 'Invalid strict consultation priority signals' using errcode = '22023';
  end if;

  perform pac_dsd.assert_allowed_jsonb_keys(payload -> 'packet' -> 'snapshot', array[
    'Reference ID', 'Status', 'Submitted', 'Stage', 'Work name', 'Desired support',
    'Timing', 'Preferred meeting mode', 'Requester role'
  ]);
  if not (payload -> 'packet' -> 'snapshot' ?& array[
      'Reference ID', 'Status', 'Submitted', 'Stage', 'Work name', 'Desired support',
      'Timing', 'Preferred meeting mode', 'Requester role'
    ])
    or exists (
      select 1 from jsonb_each(payload -> 'packet' -> 'snapshot') item
      where not pac_dsd.is_bounded_json_string(item.value, 1, 4096, false)
    )
    or payload -> 'packet' -> 'snapshot' ->> 'Reference ID' is distinct from requested_object_id
    or payload -> 'packet' -> 'snapshot' ->> 'Work name' is distinct from payload ->> 'work_name'
    or payload -> 'packet' -> 'snapshot' ->> 'Status' is distinct from (case payload ->> 'status'
      when 'pending_eligibility_review' then 'Eligibility review' when 'received' then 'Received'
      when 'under_review' then 'Under review' when 'scheduled' then 'Scheduled'
      when 'in_progress' then 'In progress' when 'completed' then 'Completed'
      when 'declined' then 'Declined' else 'Withdrawn' end)
    or payload -> 'packet' -> 'snapshot' ->> 'Stage' is distinct from (case payload ->> 'stage'
      when 'conceptual' then 'Early idea' when 'designing' then 'Planning or design'
      when 'launching' then 'Preparing to begin' else 'Already in use and changing' end)
    or not pac_dsd.is_bounded_json_string(payload -> 'packet' -> 'calendar_handoff', 1, 12000, false) then
    raise exception 'Invalid strict consultation packet snapshot' using errcode = '22023';
  end if;
  perform pac_dsd.assert_bounded_json_string_array(payload -> 'packet' -> 'summary', 1, 12, 4096, null, false);
  perform pac_dsd.assert_bounded_json_string_array(payload -> 'packet' -> 'equity_questions_considered', 1, 1000, 2000, null, false);
  perform pac_dsd.assert_bounded_json_string_array(payload -> 'packet' -> 'risks_unknowns', 1, 10, 4096, null, false);

  if jsonb_array_length(payload -> 'packet' -> 'suggested_questions') > 10 then
    raise exception 'Too many consultation suggested questions' using errcode = '22023';
  end if;
  for entry in select value from jsonb_array_elements(payload -> 'packet' -> 'suggested_questions')
  loop
    if not pac_dsd.is_bounded_json_string(entry.value -> 'id', 1, 120, false)
      or not pac_dsd.is_bounded_json_string(entry.value -> 'category', 1, 120, false)
      or not pac_dsd.is_bounded_json_string(entry.value -> 'text', 1, 2000, false) then
      raise exception 'Invalid strict consultation suggested question' using errcode = '22023';
    end if;
  end loop;
  if jsonb_array_length(payload -> 'packet' -> 'related_resources') > 6 then
    raise exception 'Too many consultation related resources' using errcode = '22023';
  end if;
  for entry in select value from jsonb_array_elements(payload -> 'packet' -> 'related_resources')
  loop
    if not pac_dsd.is_bounded_json_string(entry.value -> 'id', 1, 180, false)
      or not pac_dsd.is_bounded_json_string(entry.value -> 'title', 1, 500, false)
      or not pac_dsd.is_bounded_json_string(entry.value -> 'href', 1, 2048, false)
      or entry.value ->> 'authority' not in ('official', 'guidance', 'practice_note', 'learning', 'community_brief', 'partner_informed', 'local', 'under_review', 'external_verify')
      or not pac_dsd.is_bounded_json_string(entry.value -> 'authorityLabel', 1, 120, false)
      or not pac_dsd.is_iso_calendar_date(entry.value ->> 'reviewDate')
      or not pac_dsd.is_bounded_json_string(entry.value -> 'excerpt', 1, 2000, false)
      or jsonb_typeof(entry.value -> 'citeable') <> 'boolean' then
      raise exception 'Invalid strict consultation related resource' using errcode = '22023';
    end if;
  end loop;
  if jsonb_array_length(payload -> 'packet' -> 'agenda') not between 1 and 10 then
    raise exception 'Invalid consultation agenda size' using errcode = '22023';
  end if;
  for entry in select value from jsonb_array_elements(payload -> 'packet' -> 'agenda')
  loop
    if not pac_dsd.is_json_safe_integer(entry.value -> 'minutes', 1, 240)
      or not pac_dsd.is_bounded_json_string(entry.value -> 'item', 1, 2000, false)
      or not pac_dsd.is_bounded_json_string(entry.value -> 'owner', 1, 200, false) then
      raise exception 'Invalid strict consultation agenda item' using errcode = '22023';
    end if;
  end loop;

  root_ask := payload ? 'ask_context';
  packet_ask := payload -> 'packet' ? 'ask_context';
  if root_ask is distinct from packet_ask then
    raise exception 'Consultation packet Ask context mismatch' using errcode = '22023';
  end if;
  if root_ask then
    if payload -> 'packet' -> 'ask_context' -> 'intents_tried' is distinct from payload -> 'ask_context' -> 'intents_tried'
      or payload -> 'packet' -> 'ask_context' -> 'excerpt' is distinct from payload -> 'ask_context' -> 'excerpt'
      or not pac_dsd.is_bounded_json_string(payload -> 'packet' -> 'ask_context' -> 'excerpt', 0, 600, false) then
      raise exception 'Invalid consultation packet Ask context values' using errcode = '22023';
    end if;
    perform pac_dsd.assert_bounded_json_string_array(payload -> 'packet' -> 'ask_context' -> 'intents_tried', 0, 10, 40, null, false);
  end if;

  if jsonb_array_length(payload -> 'history') not between 1 and 100 then
    raise exception 'Invalid consultation history size' using errcode = '22023';
  end if;
  for entry in select value, ordinal from jsonb_array_elements(payload -> 'history') with ordinality history(value, ordinal)
  loop
    if not pac_dsd.is_canonical_utc_instant(entry.value ->> 'at')
      or entry.value ->> 'at' < payload ->> 'created_at'
      or entry.value ->> 'at' > payload ->> 'updated_at'
      or (previous_at is not null and entry.value ->> 'at' < previous_at)
      or (entry.value ? 'note' and not pac_dsd.is_bounded_json_string(entry.value -> 'note', 0, 1000, true)) then
      raise exception 'Invalid strict consultation history entry' using errcode = '22023';
    end if;
    if entry.ordinal = 1 and (
      entry.value ->> 'at' is distinct from payload ->> 'created_at'
      or entry.value ->> 'status' <> 'pending_eligibility_review'
      or entry.value ->> 'by' <> 'system'
    ) then
      raise exception 'Invalid initial consultation history entry' using errcode = '22023';
    end if;
    if entry.ordinal > 1 and not (
      (previous_status = 'pending_eligibility_review'
        and entry.value ->> 'status' in ('received', 'declined', 'withdrawn'))
      or (previous_status = 'received'
        and entry.value ->> 'status' in ('under_review', 'declined', 'withdrawn'))
      or (previous_status = 'under_review'
        and entry.value ->> 'status' in ('scheduled', 'declined', 'withdrawn', 'in_progress'))
      or (previous_status = 'scheduled'
        and entry.value ->> 'status' in ('in_progress', 'completed', 'declined'))
      or (previous_status = 'in_progress'
        and entry.value ->> 'status' in ('completed', 'declined'))
      or (previous_status = 'under_review'
        and entry.value ->> 'status' = 'received'
        and entry.value ->> 'by' = 'owner'
        and entry.value ->> 'note' ~ '^Undo of orchestrator cycle cycle-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12} by owner\.$')
    ) then
      raise exception 'Invalid consultation history transition' using errcode = '22023';
    end if;
    if entry.ordinal > 1 and (
      (entry.value ->> 'by' = 'requester'
        and entry.value ->> 'status' <> 'withdrawn')
      or (entry.value ->> 'by' = 'system'
        and not (
          previous_status = 'received'
          and entry.value ->> 'status' = 'under_review'
        ))
    ) then
      raise exception 'Invalid consultation history actor' using errcode = '22023';
    end if;
    previous_at := entry.value ->> 'at';
    previous_status := entry.value ->> 'status';
  end loop;

  if payload ? 'correction_history' then
    if jsonb_array_length(payload -> 'correction_history') > 100 then
      raise exception 'Invalid consultation correction history size' using errcode = '22023';
    end if;
    for entry in select value from jsonb_array_elements(payload -> 'correction_history')
    loop
      if not pac_dsd.is_canonical_utc_instant(entry.value ->> 'at')
        or entry.value ->> 'at' < payload ->> 'created_at'
        or entry.value ->> 'at' > payload ->> 'updated_at' then
        raise exception 'Invalid strict consultation correction history entry' using errcode = '22023';
      end if;
      perform pac_dsd.assert_bounded_json_string_array(entry.value -> 'fields', 1, 17, 40, array[
        'requester_role', 'work_name', 'stage', 'goals', 'equity_questions_considered',
        'desired_support_type', 'support_other_note', 'timing_urgency', 'deadline_date',
        'affected_populations', 'populations_note', 'access_language_needs', 'access_note',
        'preferred_meeting_mode', 'links', 'attachment_notes', 'situation'
      ], true);
    end loop;
  end if;
end;
$$;

create or replace function pac_dsd.enforce_consultation_persistence_contract()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
as $$
begin
  if new.work_kind = 'consult_request' then
    perform pac_dsd.assert_consultation_persistence_contract(new.object_id, new.value);
    -- Runtime creation always begins at the acknowledged eligibility-review
    -- state. Historical terminal records are restored only through a separate
    -- administrative recovery procedure, never by a generic application put.
    if tg_op = 'INSERT'
      and new.value ->> 'record_type' = 'consultation_request'
      and (
        new.value ->> 'eligibility_status' <> 'pending'
        or new.value ->> 'status' <> 'pending_eligibility_review'
        or new.value ->> 'version' <> '1'
        or jsonb_array_length(new.value -> 'history') <> 1
        or coalesce(jsonb_array_length(new.value -> 'correction_history'), 0) <> 0
        or new.value ?| array['status_reason', 'scheduled_for', 'owner_notes', 'pinned_order']
      ) then
      raise exception 'New consultation must begin at the acknowledged eligibility-review state' using errcode = '22023';
    end if;
  end if;
  return new;
end;
$$;

-- Do not mark an upgraded database strict while a consultation row written
-- under the earlier, broader contract is still present. Remediation is an
-- explicit operator action; the migration never silently rewrites S3 records.
do $$
declare
  stored record;
begin
  for stored in
    select object_id, value
    from pac_dsd.runtime_work_objects
    where work_kind = 'consult_request'
  loop
    perform pac_dsd.assert_consultation_persistence_contract(
      stored.object_id,
      stored.value
    );
  end loop;
end;
$$;

drop trigger if exists consultation_persistence_contract on pac_dsd.runtime_work_objects;
create trigger consultation_persistence_contract
before insert or update on pac_dsd.runtime_work_objects
for each row execute function pac_dsd.enforce_consultation_persistence_contract();

revoke all privileges on function pac_dsd.is_consultation_request_id(text) from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.is_iso_calendar_date(text) from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.is_zoned_instant(text) from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.is_bounded_json_string(jsonb, integer, integer, boolean) from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.is_json_safe_integer(jsonb, numeric, numeric) from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.assert_bounded_json_string_array(jsonb, integer, integer, integer, text[], boolean) from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.assert_consultation_persistence_contract(text, jsonb) from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.enforce_consultation_persistence_contract() from public, pac_dsd_app_runtime;

comment on function pac_dsd.assert_consultation_persistence_contract(text, jsonb) is
  'Strict full-request and exact ten-field tombstone contract for S3 consultation persistence.';


-- 0015_pac_terminal_consultation_cleanup.sql

-- A consultation tombstone is a short-lived replay and requester-status guard,
-- not permanent program memory. Only a record that passes the complete strict
-- consultation contract can authorize terminal deletion.
create or replace function pac_dsd.consultation_tombstone_terminal_delete_due(
  candidate_id text,
  candidate jsonb,
  cutoff timestamptz
)
returns boolean
language plpgsql
stable
strict
set search_path = pg_catalog, pac_dsd
as $$
begin
  begin
    perform pac_dsd.assert_consultation_persistence_contract(candidate_id, candidate);
  exception when others then
    return false;
  end;
  return candidate ->> 'record_type' = 'consultation_tombstone'
    and pac_dsd.is_canonical_utc_instant(candidate ->> 'redacted_at')
    and (candidate ->> 'redacted_at')::timestamptz <= cutoff;
end;
$$;

-- The previous function has four output columns. PostgreSQL requires a drop
-- before replacing it with the expanded, versioned lifecycle result.
drop function if exists pac_dsd.purge_expired_security_records();

create function pac_dsd.purge_expired_security_records()
returns table (
  owner_session_revocations_deleted integer,
  rate_limit_buckets_deleted integer,
  audit_events_deleted integer,
  research_usage_records_deleted integer,
  consultation_tombstones_deleted integer,
  idempotency_receipts_deleted integer
)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pg_temp
set row_security = off
as $$
declare
  revocation_cutoff text;
  operational_cutoff timestamptz;
  tombstone_cutoff timestamptz;
  removed_revocations integer;
  removed_buckets integer;
  removed_audit_events integer;
  removed_research_usage integer;
  removed_tombstones integer;
  removed_receipts integer;
begin
  revocation_cutoff := to_char(
    (clock_timestamp() - interval '10 minutes') at time zone 'UTC',
    'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
  );
  operational_cutoff := clock_timestamp() - interval '90 days';
  tombstone_cutoff := clock_timestamp() - interval '30 days';

  with candidates as materialized (
    select work_kind, object_id
    from pac_dsd.runtime_work_objects
    where work_kind = 'decision'
      and object_id ~ '^owner-session-revoked-[a-f0-9]{64}$'
      and value ->> 'kind' = 'owner_session_revocation'
      and value ->> 'session_hash' ~ '^[a-f0-9]{64}$'
      and object_id = 'owner-session-revoked-' || (value ->> 'session_hash')
      and pac_dsd.is_canonical_utc_instant(value ->> 'revoked_at')
      and pac_dsd.is_canonical_utc_instant(value ->> 'expires_at')
      and value ->> 'revoked_at' <= value ->> 'expires_at'
      and value ->> 'expires_at' <= revocation_cutoff
    order by updated_at, object_id
    for update skip locked
    limit 10000
  ), removed as (
    delete from pac_dsd.runtime_work_objects stored
    using candidates
    where stored.work_kind = candidates.work_kind
      and stored.object_id = candidates.object_id
    returning 1
  )
  select count(*)::integer into removed_revocations from removed;

  with candidates as materialized (
    select scope, subject_hash
    from pac_dsd.runtime_rate_limits
    where reset_at <= clock_timestamp()
    order by reset_at, scope, subject_hash
    for update skip locked
    limit 10000
  ), removed as (
    delete from pac_dsd.runtime_rate_limits stored
    using candidates
    where stored.scope = candidates.scope
      and stored.subject_hash = candidates.subject_hash
    returning 1
  )
  select count(*)::integer into removed_buckets from removed;

  perform pg_catalog.set_config('pac_dsd.allow_immutable_change', 'on', true);
  with candidates as materialized (
    select audit_id
    from pac_dsd.runtime_audit_events
    where occurred_at <= operational_cutoff
      and pac_dsd.is_canonical_utc_instant(event ->> 'at')
      and (event ->> 'at')::timestamptz = occurred_at
    order by occurred_at, audit_id
    for update skip locked
    limit 10000
  ), removed as (
    delete from pac_dsd.runtime_audit_events stored
    using candidates
    where stored.audit_id = candidates.audit_id
    returning 1
  )
  select count(*)::integer into removed_audit_events from removed;
  perform pg_catalog.set_config('pac_dsd.allow_immutable_change', 'off', true);

  with candidates as materialized (
    select work_kind, object_id
    from pac_dsd.runtime_work_objects
    where work_kind = 'decision'
      and object_id like 'research_usage:%'
      and pac_dsd.is_valid_research_usage_record(object_id, value)
      and (value ->> 'at')::timestamptz <= operational_cutoff
    order by value ->> 'at', object_id
    for update skip locked
    limit 10000
  ), removed as (
    delete from pac_dsd.runtime_work_objects stored
    using candidates
    where stored.work_kind = candidates.work_kind
      and stored.object_id = candidates.object_id
    returning 1
  )
  select count(*)::integer into removed_research_usage from removed;

  -- Remove the immutable replay receipt before its terminal tombstone. If a
  -- batch leaves any receipt behind, the related tombstone remains until a
  -- later run so replay behavior never points at a missing object.
  perform pg_catalog.set_config('pac_dsd.allow_immutable_change', 'on', true);
  with candidates as materialized (
    select receipt.idempotency_key
    from pac_dsd.runtime_idempotency receipt
    join pac_dsd.runtime_work_objects work
      on work.work_kind = receipt.work_kind and work.object_id = receipt.object_id
    where receipt.work_kind = 'consult_request'
      and pac_dsd.consultation_tombstone_terminal_delete_due(
        work.object_id,
        work.value,
        tombstone_cutoff
      )
    order by receipt.created_at, receipt.idempotency_key
    for update of receipt skip locked
    limit 10000
  ), removed as (
    delete from pac_dsd.runtime_idempotency stored
    using candidates
    where stored.idempotency_key = candidates.idempotency_key
    returning 1
  )
  select count(*)::integer into removed_receipts from removed;
  perform pg_catalog.set_config('pac_dsd.allow_immutable_change', 'off', true);

  with candidates as materialized (
    select work.work_kind, work.object_id
    from pac_dsd.runtime_work_objects work
    where work.work_kind = 'consult_request'
      and pac_dsd.consultation_tombstone_terminal_delete_due(
        work.object_id,
        work.value,
        tombstone_cutoff
      )
      and not exists (
        select 1
        from pac_dsd.runtime_idempotency receipt
        where receipt.work_kind = work.work_kind
          and receipt.object_id = work.object_id
      )
    order by work.updated_at, work.object_id
    for update of work skip locked
    limit 10000
  ), removed as (
    delete from pac_dsd.runtime_work_objects stored
    using candidates
    where stored.work_kind = candidates.work_kind
      and stored.object_id = candidates.object_id
    returning 1
  )
  select count(*)::integer into removed_tombstones from removed;

  return query select
    removed_revocations,
    removed_buckets,
    removed_audit_events,
    removed_research_usage,
    removed_tombstones,
    removed_receipts;
end;
$$;

revoke all privileges on function pac_dsd.consultation_tombstone_terminal_delete_due(text, jsonb, timestamptz)
  from public, pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.purge_expired_security_records() from public;
grant execute on function pac_dsd.purge_expired_security_records() to pac_dsd_app_runtime;

do $$
declare
  role_name text;
begin
  foreach role_name in array array['anon', 'authenticated']
  loop
    if exists (select 1 from pg_catalog.pg_roles where rolname = role_name) then
      execute format(
        'revoke all privileges on function pac_dsd.purge_expired_security_records() from %I',
        role_name
      );
    end if;
  end loop;
end;
$$;

comment on function pac_dsd.consultation_tombstone_terminal_delete_due(text, jsonb, timestamptz) is
  'Fail-closed terminal lifecycle predicate for strict consultation tombstones.';
comment on function pac_dsd.purge_expired_security_records() is
  'Bounded privacy housekeeping for expired security records, 90-day operational records, and 30-day consultation tombstones with their replay receipts.';


-- 0016_pac_trusted_home_footer_release.sql

-- RG-3 forward publication for the reconciled Home page and footer. Migration
-- 0007 remains immutable historical evidence. This migration appends a new,
-- explicitly reviewed S1 release and repairs the page-copy lifecycle so an S2
-- default, unsafe source, or later withdrawal can never leak to staff.

create or replace function pac_dsd.page_block_revision_is_staff_exposable(
  requested_content_item_id text,
  requested_revision_id uuid
)
returns boolean
language sql
stable
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
  select exists (
    select 1
    from pac_dsd.content_items item
    join pac_dsd.content_revisions revision
      on revision.content_item_id = item.content_item_id
    where item.content_item_id = requested_content_item_id
      and revision.revision_id = requested_revision_id
      and requested_content_item_id = any(array['page-home', 'site-footer']::text[])
      and item.content_kind = 'internal'
      and item.default_scope_id = 'one-dhs'
      and item.restricted = true
      and item.retired_at is null
      and item.sensitivity_class = 'S1'
      and revision.sensitivity_class = 'S1'
      and revision.ordinary_indexing_allowed = true
      and revision.model_context_allowed = false
      and cardinality(revision.limitations) > 0
      and not exists (
        select 1 from unnest(revision.limitations) limitation(value)
        where nullif(btrim(limitation.value), '') is null
      )
      and revision.canonical_payload ->> 'id' = requested_content_item_id
      and revision.canonical_payload ->> 'status' = 'approved'
      and revision.canonical_payload ->> 'accessibility' = 'reviewed'
      and cardinality(revision.required_review_dimensions) > 0
      and not exists (
        select 1
        from unnest(revision.required_review_dimensions) required(dimension)
        left join lateral (
          select review.status
          from pac_dsd.review_records review
          where review.revision_id = revision.revision_id
            and review.dimension = required.dimension
          order by review.recorded_at desc, review.review_id desc
          limit 1
        ) current_review on true
        where current_review.status is null
          or current_review.status not in ('pass', 'not_applicable')
      )
      and exists (
        select 1 from pac_dsd.revision_sources source_link
        where source_link.revision_id = revision.revision_id
      )
      and not exists (
        select 1
        from pac_dsd.revision_sources source_link
        left join pac_dsd.source_items source
          on source.source_item_id = source_link.source_item_id
        left join pac_dsd.source_carriers carrier
          on carrier.carrier_id = source.carrier_id
        where source_link.revision_id = revision.revision_id
          and (
            source.source_item_id is null
            or source.carrier_id is null
            or carrier.carrier_id is null
            or carrier.sensitivity_class <> 'S1'
            or source.sensitivity_class <> 'S1'
            or source.deidentification_status not in ('not_needed', 'verified')
            or source.ordinary_indexing_allowed is distinct from true
            or source.model_context_allowed is distinct from false
            or source.owner_approval_status <> 'owner_approved_for_ingestion'
            or source.accounting_status <> 'accounted'
            or source.access_scope <> 'staff_candidate'
          )
      )
      and not exists (
        select 1
        from pac_dsd.revision_assets asset_link
        left join pac_dsd.assets asset on asset.asset_id = asset_link.asset_id
        where asset_link.revision_id = revision.revision_id
          and (
            asset.asset_id is null
            or asset.sensitivity_class not in ('S0', 'S1')
          )
      )
  );
$$;

create or replace function pac_dsd.read_page_block_publication(
  requested_scope_id text,
  requested_content_item_id text
)
returns table (
  content_item_id text,
  revision_id uuid,
  canonical_payload jsonb
)
language plpgsql
stable
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
begin
  perform pac_dsd.assert_page_block_request(requested_scope_id, requested_content_item_id);
  return query
  with recursive visible_scopes as (
    select scope_record.scope_id, scope_record.parent_scope_id, 0 as distance
    from pac_dsd.program_scopes scope_record
    where scope_record.scope_id = requested_scope_id
      and scope_record.active = true
    union all
    select parent.scope_id, parent.parent_scope_id, child.distance + 1
    from pac_dsd.program_scopes parent
    join visible_scopes child on parent.scope_id = child.parent_scope_id
    where parent.active = true
      and parent.scope_id <> 'one-dhs-pac'
  ),
  latest_per_scope as (
    select decision.*,
      row_number() over (
        partition by decision.content_item_id, decision.scope_id
        order by decision.publication_decision_id desc
      ) as decision_rank
    from pac_dsd.publication_decisions decision
    join visible_scopes visible on visible.scope_id = decision.scope_id
    where decision.content_item_id = requested_content_item_id
  ),
  effective as (
    select decision.*,
      row_number() over (
        order by visible.distance asc, decision.publication_decision_id desc
      ) as scope_rank
    from latest_per_scope decision
    join visible_scopes visible on visible.scope_id = decision.scope_id
    where decision.decision_rank = 1
  )
  select item.content_item_id, revision.revision_id, revision.canonical_payload
  from effective decision
  join pac_dsd.content_items item
    on item.content_item_id = decision.content_item_id
  join pac_dsd.content_revisions revision
    on revision.revision_id = decision.revision_id
    and revision.content_item_id = decision.content_item_id
  where decision.scope_rank = 1
    and decision.decision = 'publish'
    and decision.sensitivity_class = 'S1'
    and decision.unauthenticated_exposure_permitted = true
    and nullif(btrim(decision.exposure_reason), '') is not null
    and pac_dsd.page_block_revision_is_staff_exposable(
      decision.content_item_id, decision.revision_id
    );
end;
$$;

create or replace function pac_dsd.read_page_block_editing_state(
  requested_scope_id text,
  requested_content_item_id text
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  requested_payload_scope text;
  requested_surface text;
  latest_revision_id uuid;
  latest_payload jsonb;
  latest_required_reviews text[];
  latest_sensitivity_class text;
  latest_ordinary_indexing_allowed boolean;
  latest_model_context_allowed boolean;
  published_revision_id uuid;
  publication_decision_id bigint;
  review_summary jsonb;
  history_summary jsonb;
  ready_to_publish boolean;
begin
  perform pac_dsd.assert_page_block_request(requested_scope_id, requested_content_item_id);
  requested_payload_scope := case when requested_scope_id = 'dsd' then 'dsd' else 'agencywide' end;
  requested_surface := case when requested_content_item_id = 'page-home' then 'home' else 'footer' end;

  if not exists (
    select 1
    from pac_dsd.content_items item
    where item.content_item_id = requested_content_item_id
      and item.default_scope_id = requested_scope_id
      and item.content_kind = 'internal'
      and item.restricted = true
      and item.retired_at is null
  ) then
    return null;
  end if;

  select revision.revision_id,
    revision.canonical_payload,
    revision.required_review_dimensions,
    revision.sensitivity_class,
    revision.ordinary_indexing_allowed,
    revision.model_context_allowed
  into latest_revision_id,
    latest_payload,
    latest_required_reviews,
    latest_sensitivity_class,
    latest_ordinary_indexing_allowed,
    latest_model_context_allowed
  from pac_dsd.content_revisions revision
  where revision.content_item_id = requested_content_item_id
    and (
      revision.canonical_payload ->> 'scope' = requested_payload_scope
      or (
        requested_scope_id = 'dsd'
        and revision.canonical_payload ->> 'scope' = 'agencywide'
      )
    )
  order by
    case when revision.canonical_payload ->> 'scope' = requested_payload_scope then 0 else 1 end,
    revision.revision_number desc,
    revision.revision_id desc
  limit 1;
  if latest_revision_id is null then
    return null;
  end if;

  select publication.revision_id into published_revision_id
  from pac_dsd.read_page_block_publication(
    requested_scope_id, requested_content_item_id
  ) publication;

  select decision.publication_decision_id into publication_decision_id
  from pac_dsd.publication_decisions decision
  where decision.content_item_id = requested_content_item_id
    and decision.scope_id = requested_scope_id
  order by decision.publication_decision_id desc
  limit 1;

  select coalesce(jsonb_agg(jsonb_build_object(
      'reviewId', review.review_id,
      'dimension', required.dimension,
      'status', coalesce(review.status, 'pending'),
      'note', review.findings ->> 'note'
    ) order by array_position(latest_required_reviews, required.dimension)), '[]'::jsonb)
  into review_summary
  from unnest(latest_required_reviews) required(dimension)
  left join lateral (
    select record.review_id, record.status, record.findings
    from pac_dsd.review_records record
    where record.revision_id = latest_revision_id
      and record.dimension = required.dimension
    order by record.recorded_at desc, record.review_id desc
    limit 1
  ) review on true;

  ready_to_publish := latest_payload ->> 'status' = 'under_review'
    and latest_sensitivity_class = 'S2'
    and latest_ordinary_indexing_allowed = false
    and latest_model_context_allowed = false
    and not exists (
      select 1
      from unnest(latest_required_reviews) required(dimension)
      left join lateral (
        select record.status
        from pac_dsd.review_records record
        where record.revision_id = latest_revision_id
          and record.dimension = required.dimension
        order by record.recorded_at desc, record.review_id desc
        limit 1
      ) review on true
      where review.status is null
        or review.status not in ('pass', 'not_applicable')
    );

  with recursive visible_scopes as (
    select scope_record.scope_id, scope_record.parent_scope_id
    from pac_dsd.program_scopes scope_record
    where scope_record.scope_id = requested_scope_id
      and scope_record.active = true
    union all
    select parent.scope_id, parent.parent_scope_id
    from pac_dsd.program_scopes parent
    join visible_scopes child on parent.scope_id = child.parent_scope_id
    where parent.active = true
      and parent.scope_id <> 'one-dhs-pac'
  ),
  published_revisions as (
    select decision.revision_id, max(decision.decided_at) as published_at
    from pac_dsd.publication_decisions decision
    join visible_scopes visible on visible.scope_id = decision.scope_id
    where decision.content_item_id = requested_content_item_id
      and decision.decision = 'publish'
      and decision.sensitivity_class = 'S1'
      and decision.unauthenticated_exposure_permitted = true
      and nullif(btrim(decision.exposure_reason), '') is not null
      and pac_dsd.page_block_revision_is_staff_exposable(
        decision.content_item_id, decision.revision_id
      )
    group by decision.revision_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'revisionId', revision.revision_id,
      'label', case
        when requested_surface = 'home' then
          'Version ' || revision.revision_number || ': '
          || (revision.canonical_payload #>> '{copy,headlineLine1}') || ' '
          || (revision.canonical_payload #>> '{copy,headlineLine2}') || ' '
          || (revision.canonical_payload #>> '{copy,headlineLine3}')
        else
          'Version ' || revision.revision_number || ': '
          || (revision.canonical_payload #>> '{copy,identityKicker}')
      end,
      'publishedAt', published.published_at,
      'isCurrent', revision.revision_id = published_revision_id
    ) order by published.published_at desc), '[]'::jsonb)
  into history_summary
  from published_revisions published
  join pac_dsd.content_revisions revision
    on revision.revision_id = published.revision_id;

  return jsonb_build_object(
    'surface', requested_surface,
    'contentItemId', requested_content_item_id,
    'expectedRevisionId', latest_revision_id,
    'publishedRevisionId', published_revision_id,
    'publicationDecisionId', publication_decision_id::text,
    'isPublished', published_revision_id is not null,
    'hasUnpublishedChanges', published_revision_id is null
      or latest_revision_id <> published_revision_id,
    'copy', latest_payload -> 'copy',
    'reviews', review_summary,
    'canPublish', ready_to_publish,
    'history', history_summary
  );
end;
$$;

create or replace function pac_dsd.create_page_block_draft(
  requested_scope_id text,
  requested_content_item_id text,
  expected_base_revision_id uuid,
  requested_copy jsonb,
  requested_change_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  current_state jsonb;
  latest_revision_id uuid;
  latest_payload jsonb;
  next_revision_id uuid;
  next_revision_number integer;
  next_payload jsonb;
  requested_surface text;
  requested_payload_scope text;
begin
  perform pac_dsd.assert_page_block_mutation_allowed(
    requested_scope_id, requested_content_item_id
  );
  perform pac_dsd.assert_valid_page_block_copy(
    requested_content_item_id, requested_copy
  );
  if requested_change_note is not null
    and length(btrim(requested_change_note)) > 1000 then
    raise exception 'The change note is too long' using errcode = '22023';
  end if;
  if requested_change_note is not null
    and length(btrim(requested_change_note)) > 0 then
    perform pac_dsd.assert_plain_page_text(requested_change_note);
  end if;

  perform 1
  from pac_dsd.content_items item
  where item.content_item_id = requested_content_item_id
    and item.sensitivity_class = 'S1'
  for update;
  if not found then
    raise exception 'This page area is not available' using errcode = 'P0002';
  end if;

  current_state := pac_dsd.read_page_block_editing_state(
    requested_scope_id, requested_content_item_id
  );
  if current_state is null then
    raise exception 'This page area is not available' using errcode = 'P0002';
  end if;
  latest_revision_id := (current_state ->> 'expectedRevisionId')::uuid;
  if latest_revision_id is distinct from expected_base_revision_id then
    raise exception 'Page wording changed after it was opened' using errcode = '40001';
  end if;

  select revision.canonical_payload into latest_payload
  from pac_dsd.content_revisions revision
  where revision.revision_id = latest_revision_id;
  if latest_payload -> 'copy' = requested_copy then
    raise exception 'No page wording changes were provided' using errcode = '22000';
  end if;

  select coalesce(max(revision.revision_number), 0) + 1
  into next_revision_number
  from pac_dsd.content_revisions revision
  where revision.content_item_id = requested_content_item_id;
  requested_surface := case
    when requested_content_item_id = 'page-home' then 'home'
    else 'footer'
  end;
  requested_payload_scope := case
    when requested_scope_id = 'dsd' then 'dsd'
    else 'agencywide'
  end;
  next_payload := jsonb_build_object(
    'id', requested_content_item_id,
    'blockType', requested_surface,
    'status', 'under_review',
    'accessibility', 'pending',
    'scope', requested_payload_scope,
    'version', next_revision_number::text,
    'copy', requested_copy
  );

  insert into pac_dsd.content_revisions (
    content_item_id, revision_number, canonical_payload, change_summary,
    required_review_dimensions, created_by, based_on_revision_id,
    sensitivity_class, ordinary_indexing_allowed, model_context_allowed,
    limitations
  ) values (
    requested_content_item_id,
    next_revision_number,
    next_payload,
    coalesce(
      nullif(btrim(requested_change_note), ''),
      'Page wording updated in the consultant workspace.'
    ),
    array[
      'language_alignment', 'factual_currentness', 'accessibility',
      'scope', 'placement'
    ]::text[],
    'pac-consultant-workspace-owner',
    latest_revision_id,
    'S2',
    false,
    false,
    array[
      'Draft wording is protected review material and is not available to staff until a separate S1 publication decision.'
    ]::text[]
  ) returning revision_id into next_revision_id;

  insert into pac_dsd.revision_sources (
    revision_id, source_item_id, relationship, note
  )
  select next_revision_id, source.source_item_id, source.relationship, source.note
  from pac_dsd.revision_sources source
  where source.revision_id = latest_revision_id;

  insert into pac_dsd.revision_assets (
    revision_id, asset_id, purpose, staff_label, sort_order
  )
  select next_revision_id, asset.asset_id, asset.purpose,
    asset.staff_label, asset.sort_order
  from pac_dsd.revision_assets asset
  where asset.revision_id = latest_revision_id;

  insert into pac_dsd.review_records (
    revision_id, dimension, status, reviewer_role, findings
  )
  select next_revision_id,
    dimension,
    'pending',
    'program_steward',
    jsonb_build_object(
      'note', 'Review is required before this wording can be published.'
    )
  from unnest(array[
    'language_alignment', 'factual_currentness', 'accessibility',
    'scope', 'placement'
  ]::text[]) dimension;

  insert into pac_dsd.change_events (
    actor_id, actor_role, scope_id, object_type, object_id, action, detail
  ) values (
    'pac-consultant-workspace-owner',
    'owner',
    requested_scope_id,
    'page_block',
    requested_content_item_id,
    'draft_created',
    jsonb_build_object(
      'based_on_revision_id', latest_revision_id,
      'draft_revision_id', next_revision_id,
      'sensitivity_class', 'S2',
      'ordinary_indexing_allowed', false,
      'model_context_allowed', false,
      'staff_publication_unchanged', true
    )
  );
  return pac_dsd.read_page_block_editing_state(
    requested_scope_id, requested_content_item_id
  );
end;
$$;

create or replace function pac_dsd.record_page_block_review(
  requested_scope_id text,
  requested_content_item_id text,
  requested_revision_id uuid,
  requested_dimension text,
  requested_status text,
  expected_previous_review_id uuid,
  requested_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  current_state jsonb;
  previous_review_id uuid;
  required_dimensions text[];
begin
  perform pac_dsd.assert_page_block_mutation_allowed(
    requested_scope_id, requested_content_item_id
  );
  if requested_status not in ('pass', 'revise', 'blocked', 'not_applicable') then
    raise exception 'Review result is not allowed' using errcode = '22023';
  end if;
  if requested_note is not null
    and length(btrim(requested_note)) > 1000 then
    raise exception 'The review note is too long' using errcode = '22023';
  end if;
  if requested_note is not null
    and length(btrim(requested_note)) > 0 then
    perform pac_dsd.assert_plain_page_text(requested_note);
  end if;

  perform 1
  from pac_dsd.content_items item
  where item.content_item_id = requested_content_item_id
    and item.sensitivity_class = 'S1'
  for update;
  if not found then
    raise exception 'This page area is not available' using errcode = 'P0002';
  end if;

  current_state := pac_dsd.read_page_block_editing_state(
    requested_scope_id, requested_content_item_id
  );
  if current_state is null
    or (current_state ->> 'expectedRevisionId')::uuid is distinct from requested_revision_id then
    raise exception 'Page wording changed after it was opened' using errcode = '40001';
  end if;

  select revision.required_review_dimensions into required_dimensions
  from pac_dsd.content_revisions revision
  where revision.revision_id = requested_revision_id
    and revision.content_item_id = requested_content_item_id
    and revision.canonical_payload ->> 'status' = 'under_review'
    and revision.sensitivity_class = 'S2'
    and revision.ordinary_indexing_allowed = false
    and revision.model_context_allowed = false;
  if not found then
    raise exception 'Only the current draft can be reviewed' using errcode = '55000';
  end if;
  if requested_dimension <> all(required_dimensions) then
    raise exception 'This review area is not required' using errcode = '22023';
  end if;

  select review.review_id into previous_review_id
  from pac_dsd.review_records review
  where review.revision_id = requested_revision_id
    and review.dimension = requested_dimension
  order by review.recorded_at desc, review.review_id desc
  limit 1;
  if previous_review_id is distinct from expected_previous_review_id then
    raise exception 'This review changed after it was opened' using errcode = '40001';
  end if;

  insert into pac_dsd.review_records (
    revision_id, dimension, status, reviewer_role, reviewer_id,
    findings, supersedes_review_id
  ) values (
    requested_revision_id,
    requested_dimension,
    requested_status,
    'program_steward',
    'pac-consultant-workspace-owner',
    jsonb_build_object('note', nullif(btrim(requested_note), '')),
    previous_review_id
  );

  insert into pac_dsd.change_events (
    actor_id, actor_role, scope_id, object_type, object_id, action, detail
  ) values (
    'pac-consultant-workspace-owner',
    'owner',
    requested_scope_id,
    'page_block',
    requested_content_item_id,
    'review_recorded',
    jsonb_build_object(
      'revision_id', requested_revision_id,
      'dimension', requested_dimension,
      'status', requested_status
    )
  );
  return pac_dsd.read_page_block_editing_state(
    requested_scope_id, requested_content_item_id
  );
end;
$$;

create or replace function pac_dsd.publish_page_block_draft(
  requested_scope_id text,
  requested_content_item_id text,
  requested_revision_id uuid,
  expected_publication_decision_id bigint,
  requested_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  current_state jsonb;
  draft_revision pac_dsd.content_revisions%rowtype;
  release_revision_id uuid := gen_random_uuid();
  release_revision_number integer;
  release_payload jsonb;
  current_publication_decision_id bigint;
  release_carrier_id uuid;
  release_source_id text;
  release_source_payload jsonb;
  gate_reviews jsonb;
  new_publication_decision_id bigint;
begin
  perform pac_dsd.assert_page_block_mutation_allowed(
    requested_scope_id, requested_content_item_id
  );
  if requested_reason is null
    or length(btrim(requested_reason)) not between 1 and 500 then
    raise exception 'A brief publishing reason is required' using errcode = '22023';
  end if;
  perform pac_dsd.assert_plain_page_text(requested_reason);

  perform 1
  from pac_dsd.content_items item
  where item.content_item_id = requested_content_item_id
    and item.sensitivity_class = 'S1'
  for update;
  if not found then
    raise exception 'This page area is not available' using errcode = 'P0002';
  end if;

  select decision.publication_decision_id
  into current_publication_decision_id
  from pac_dsd.publication_decisions decision
  where decision.content_item_id = requested_content_item_id
    and decision.scope_id = requested_scope_id
  order by decision.publication_decision_id desc
  limit 1;
  if current_publication_decision_id is distinct from expected_publication_decision_id then
    raise exception 'The publication decision changed after it was opened' using errcode = '40001';
  end if;

  current_state := pac_dsd.read_page_block_editing_state(
    requested_scope_id, requested_content_item_id
  );
  if current_state is null
    or (current_state ->> 'expectedRevisionId')::uuid is distinct from requested_revision_id then
    raise exception 'Page wording changed after it was opened' using errcode = '40001';
  end if;

  select revision.* into draft_revision
  from pac_dsd.content_revisions revision
  where revision.revision_id = requested_revision_id
    and revision.content_item_id = requested_content_item_id
    and revision.canonical_payload ->> 'status' = 'under_review'
    and revision.sensitivity_class = 'S2'
    and revision.ordinary_indexing_allowed = false
    and revision.model_context_allowed = false;
  if not found then
    raise exception 'Only a reviewed draft can be published' using errcode = '55000';
  end if;

  if exists (
    select 1
    from unnest(draft_revision.required_review_dimensions) required(dimension)
    left join lateral (
      select review.status
      from pac_dsd.review_records review
      where review.revision_id = requested_revision_id
        and review.dimension = required.dimension
      order by review.recorded_at desc, review.review_id desc
      limit 1
    ) current_review on true
    where current_review.status is null
      or current_review.status not in ('pass', 'not_applicable')
  ) then
    raise exception 'Every required review must be complete before publishing' using errcode = '55000';
  end if;

  select coalesce(max(revision.revision_number), 0) + 1
  into release_revision_number
  from pac_dsd.content_revisions revision
  where revision.content_item_id = requested_content_item_id;
  release_payload := draft_revision.canonical_payload || jsonb_build_object(
    'status', 'approved',
    'accessibility', 'reviewed',
    'version', release_revision_number::text
  );
  release_source_id := 'page-copy-release-' || release_revision_id::text;
  release_source_payload := jsonb_build_object(
    'kind', 'reviewed_page_copy_release',
    'contentItemId', requested_content_item_id,
    'scopeId', requested_scope_id,
    'releaseRevisionId', release_revision_id,
    'copy', release_payload -> 'copy'
  );

  insert into pac_dsd.source_carriers (
    logical_key, media_type, original_name, byte_count, raw_blob_sha256,
    external_locator, captured_by, sensitivity_class
  ) values (
    'page-copy-release:' || release_revision_id::text,
    'application/json',
    requested_content_item_id || '-release.json',
    octet_length(convert_to(release_source_payload::text, 'UTF8')),
    encode(pac_dsd.digest(convert_to(release_source_payload::text, 'UTF8'), 'sha256'), 'hex'),
    jsonb_build_object(
      'kind', 'governed_page_copy_release',
      'revisionId', release_revision_id
    ),
    'pac-consultant-workspace-owner',
    'S1'
  ) returning carrier_id into release_carrier_id;

  insert into pac_dsd.source_items (
    source_item_id, source_business_id, carrier_id, source_version,
    source_pointer, title, normalized_payload, normalized_item_sha256,
    hash_algorithm, hash_algorithm_version, owner_approval_status,
    accounting_status, access_scope, sensitivity_class,
    deidentification_status, ordinary_indexing_allowed,
    model_context_allowed
  ) values (
    release_source_id,
    release_source_id,
    release_carrier_id,
    '1',
    'release/' || release_revision_id::text,
    case
      when requested_content_item_id = 'page-home' then 'Reviewed Home page wording release'
      else 'Reviewed footer wording release'
    end,
    release_source_payload,
    encode(pac_dsd.digest(convert_to(release_source_payload::text, 'UTF8'), 'sha256'), 'hex'),
    'sha256',
    '1',
    'owner_approved_for_ingestion',
    'accounted',
    'staff_candidate',
    'S1',
    'not_needed',
    true,
    false
  );

  insert into pac_dsd.content_revisions (
    revision_id, content_item_id, revision_number, canonical_payload,
    change_summary, required_review_dimensions, created_by,
    based_on_revision_id, sensitivity_class, ordinary_indexing_allowed,
    model_context_allowed, limitations
  ) values (
    release_revision_id,
    requested_content_item_id,
    release_revision_number,
    release_payload,
    'Reviewed page wording approved for staff.',
    draft_revision.required_review_dimensions,
    'pac-consultant-workspace-owner',
    requested_revision_id,
    'S1',
    true,
    false,
    array[
      'Approved for ordinary staff retrieval only; use as model context requires a separate item-level decision.'
    ]::text[]
  );

  insert into pac_dsd.revision_sources (
    revision_id, source_item_id, relationship, note
  ) values (
    release_revision_id,
    release_source_id,
    'primary',
    'Exact reviewed wording captured for this immutable staff release.'
  );

  insert into pac_dsd.revision_assets (
    revision_id, asset_id, purpose, staff_label, sort_order
  )
  select release_revision_id, asset.asset_id, asset.purpose,
    asset.staff_label, asset.sort_order
  from pac_dsd.revision_assets asset
  where asset.revision_id = requested_revision_id;

  insert into pac_dsd.review_records (
    revision_id, dimension, status, reviewer_role, reviewer_id, findings
  )
  select release_revision_id,
    required.dimension,
    current_review.status,
    'publishing_approver',
    'pac-consultant-workspace-owner',
    jsonb_build_object(
      'carried_forward_from_review_id', current_review.review_id,
      'reviewed_draft_revision_id', requested_revision_id,
      'release_validation', true
    )
  from unnest(draft_revision.required_review_dimensions) required(dimension)
  cross join lateral (
    select review.review_id, review.status
    from pac_dsd.review_records review
    where review.revision_id = requested_revision_id
      and review.dimension = required.dimension
    order by review.recorded_at desc, review.review_id desc
    limit 1
  ) current_review;

  if not pac_dsd.page_block_revision_is_staff_exposable(
    requested_content_item_id, release_revision_id
  ) then
    raise exception 'The reviewed wording did not pass the staff publication trust gate' using errcode = '55000';
  end if;

  select jsonb_agg(
    jsonb_build_object(
      'dimension', review.dimension,
      'status', review.status
    ) order by array_position(
      draft_revision.required_review_dimensions, review.dimension
    )
  ) into gate_reviews
  from (
    select distinct on (record.dimension)
      record.dimension, record.status
    from pac_dsd.review_records record
    where record.revision_id = release_revision_id
    order by record.dimension, record.recorded_at desc, record.review_id desc
  ) review;

  insert into pac_dsd.publication_decisions (
    content_item_id, revision_id, scope_id, decision, gate_snapshot,
    decided_by, reason, sensitivity_class,
    unauthenticated_exposure_permitted, exposure_reason
  ) values (
    requested_content_item_id,
    release_revision_id,
    requested_scope_id,
    'publish',
    jsonb_build_object(
      'reviewed_draft_revision_id', requested_revision_id,
      'replaced_scope_decision_id', current_publication_decision_id,
      'required_reviews', coalesce(gate_reviews, '[]'::jsonb),
      'required_reviews_complete', true,
      'linked_source_item_id', release_source_id,
      'exact_release_copy_captured', true,
      'explicit_owner_decision', true,
      'staff_voice_checked', true,
      'plain_text_checked', true,
      'icons_checked', true,
      'accessibility_reviewed', true,
      'sensitivity_class', 'S1',
      'ordinary_indexing_allowed', true,
      'model_context_allowed', false,
      'unauthenticated_exposure_permitted', true,
      'exposure_reason_recorded', true,
      'trust_decision_source', 'governed_page_copy_release'
    ),
    'pac-consultant-workspace-owner',
    btrim(requested_reason),
    'S1',
    true,
    btrim(requested_reason)
  ) returning publication_decision_id into new_publication_decision_id;

  insert into pac_dsd.change_events (
    actor_id, actor_role, scope_id, object_type, object_id, action, detail
  ) values (
    'pac-consultant-workspace-owner',
    'owner',
    requested_scope_id,
    'page_block',
    requested_content_item_id,
    'published',
    jsonb_build_object(
      'reviewed_draft_revision_id', requested_revision_id,
      'release_revision_id', release_revision_id,
      'publication_decision_id', new_publication_decision_id,
      'sensitivity_class', 'S1',
      'ordinary_indexing_allowed', true,
      'model_context_allowed', false,
      'unauthenticated_exposure_permitted', true
    )
  );
  return pac_dsd.read_page_block_editing_state(
    requested_scope_id, requested_content_item_id
  );
end;
$$;

create or replace function pac_dsd.withdraw_page_block_publication(
  requested_scope_id text,
  requested_content_item_id text,
  expected_published_revision_id uuid,
  expected_publication_decision_id bigint,
  requested_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  current_revision_id uuid;
  current_publication_decision_id bigint;
begin
  perform pac_dsd.assert_page_block_mutation_allowed(
    requested_scope_id, requested_content_item_id
  );
  if requested_reason is null
    or length(btrim(requested_reason)) not between 1 and 500 then
    raise exception 'A brief withdrawal reason is required' using errcode = '22023';
  end if;
  perform pac_dsd.assert_plain_page_text(requested_reason);

  perform 1
  from pac_dsd.content_items item
  where item.content_item_id = requested_content_item_id
  for update;
  if not found then
    raise exception 'This page area is not available' using errcode = 'P0002';
  end if;

  select decision.publication_decision_id
  into current_publication_decision_id
  from pac_dsd.publication_decisions decision
  where decision.content_item_id = requested_content_item_id
    and decision.scope_id = requested_scope_id
  order by decision.publication_decision_id desc
  limit 1;
  if current_publication_decision_id is distinct from expected_publication_decision_id then
    raise exception 'The publication decision changed after it was opened' using errcode = '40001';
  end if;

  select publication.revision_id into current_revision_id
  from pac_dsd.read_page_block_publication(
    requested_scope_id, requested_content_item_id
  ) publication;
  if current_revision_id is null
    or current_revision_id is distinct from expected_published_revision_id then
    raise exception 'Published page wording changed after it was opened' using errcode = '40001';
  end if;

  insert into pac_dsd.publication_decisions (
    content_item_id, revision_id, scope_id, decision, gate_snapshot,
    decided_by, reason, sensitivity_class,
    unauthenticated_exposure_permitted, exposure_reason
  ) values (
    requested_content_item_id,
    current_revision_id,
    requested_scope_id,
    'withdraw',
    jsonb_build_object(
      'explicit_owner_decision', true,
      'replaced_scope_decision_id', current_publication_decision_id,
      'sensitivity_class', 'S1',
      'ordinary_indexing_allowed', false,
      'model_context_allowed', false,
      'unauthenticated_exposure_permitted', false,
      'exposure_reason_recorded', false
    ),
    'pac-consultant-workspace-owner',
    btrim(requested_reason),
    'S1',
    false,
    null
  );

  insert into pac_dsd.change_events (
    actor_id, actor_role, scope_id, object_type, object_id, action, detail
  ) values (
    'pac-consultant-workspace-owner',
    'owner',
    requested_scope_id,
    'page_block',
    requested_content_item_id,
    'withdrawn',
    jsonb_build_object(
      'revision_id', current_revision_id,
      'unauthenticated_exposure_permitted', false
    )
  );
  return pac_dsd.read_page_block_editing_state(
    requested_scope_id, requested_content_item_id
  );
end;
$$;

create or replace function pac_dsd.rollback_page_block_publication(
  requested_scope_id text,
  requested_content_item_id text,
  expected_published_revision_id uuid,
  target_revision_id uuid,
  expected_publication_decision_id bigint,
  requested_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  current_revision_id uuid;
  current_publication_decision_id bigint;
  previous_safe_publication_decision_id bigint;
begin
  perform pac_dsd.assert_page_block_mutation_allowed(
    requested_scope_id, requested_content_item_id
  );
  if requested_reason is null
    or length(btrim(requested_reason)) not between 1 and 500 then
    raise exception 'A brief restoration reason is required' using errcode = '22023';
  end if;
  perform pac_dsd.assert_plain_page_text(requested_reason);

  perform 1
  from pac_dsd.content_items item
  where item.content_item_id = requested_content_item_id
  for update;
  if not found then
    raise exception 'This page area is not available' using errcode = 'P0002';
  end if;

  select decision.publication_decision_id
  into current_publication_decision_id
  from pac_dsd.publication_decisions decision
  where decision.content_item_id = requested_content_item_id
    and decision.scope_id = requested_scope_id
  order by decision.publication_decision_id desc
  limit 1;
  if current_publication_decision_id is distinct from expected_publication_decision_id then
    raise exception 'The publication decision changed after it was opened' using errcode = '40001';
  end if;

  select publication.revision_id into current_revision_id
  from pac_dsd.read_page_block_publication(
    requested_scope_id, requested_content_item_id
  ) publication;
  if current_revision_id is distinct from expected_published_revision_id then
    raise exception 'Published page wording changed after it was opened' using errcode = '40001';
  end if;
  if target_revision_id is not distinct from current_revision_id then
    raise exception 'The selected wording is already available to staff' using errcode = '22000';
  end if;

  select decision.publication_decision_id
  into previous_safe_publication_decision_id
  from pac_dsd.publication_decisions decision
  where decision.content_item_id = requested_content_item_id
    and decision.revision_id = target_revision_id
    and decision.scope_id = requested_scope_id
    and decision.decision = 'publish'
    and decision.sensitivity_class = 'S1'
    and decision.unauthenticated_exposure_permitted = true
    and nullif(btrim(decision.exposure_reason), '') is not null
  order by decision.publication_decision_id desc
  limit 1;
  if previous_safe_publication_decision_id is null
    or not pac_dsd.page_block_revision_is_staff_exposable(
      requested_content_item_id, target_revision_id
    ) then
    raise exception 'The selected reviewed wording cannot be restored' using errcode = '55000';
  end if;

  insert into pac_dsd.publication_decisions (
    content_item_id, revision_id, scope_id, decision, gate_snapshot,
    decided_by, reason, sensitivity_class,
    unauthenticated_exposure_permitted, exposure_reason
  ) values (
    requested_content_item_id,
    target_revision_id,
    requested_scope_id,
    'publish',
    jsonb_build_object(
      'explicit_owner_decision', true,
      'restored_approved_revision', true,
      'previous_safe_publication_decision_id', previous_safe_publication_decision_id,
      'replaced_scope_decision_id', current_publication_decision_id,
      'sensitivity_class', 'S1',
      'ordinary_indexing_allowed', true,
      'model_context_allowed', false,
      'unauthenticated_exposure_permitted', true,
      'exposure_reason_recorded', true,
      'trust_decision_source', 'governed_page_copy_rollback'
    ),
    'pac-consultant-workspace-owner',
    btrim(requested_reason),
    'S1',
    true,
    btrim(requested_reason)
  );

  insert into pac_dsd.change_events (
    actor_id, actor_role, scope_id, object_type, object_id, action, detail
  ) values (
    'pac-consultant-workspace-owner',
    'owner',
    requested_scope_id,
    'page_block',
    requested_content_item_id,
    'approved_revision_restored',
    jsonb_build_object(
      'previous_revision_id', current_revision_id,
      'restored_revision_id', target_revision_id,
      'previous_safe_publication_decision_id', previous_safe_publication_decision_id
    )
  );
  return pac_dsd.read_page_block_editing_state(
    requested_scope_id, requested_content_item_id
  );
end;
$$;

do $$
declare
  release_id constant text := 'page-copy-reconciled-s1-2026-09-05';
  release_actor constant text := 'pac-home-footer-s1-migration';
  release_exposure_reason constant text := 'The reconciled Home page and footer are reviewed internal-purpose wording intentionally available to DHS staff at the staff-facing web address without sign-in.';
  home_copy jsonb := $home$
  {
    "heroKicker":"One DHS People, Access and Culture Program",
    "headlineLine1":"One DHS People,",
    "headlineLine2":"Access and Culture",
    "headlineLine3":"Program",
    "heroLede":"Practical support for workplace culture and equitable workforce, policy, program, and service decisions.",
    "heroNote":"Bring the work in front of you. Ask a question, find guidance, practice with a useful work product, or identify the right person to involve. Ordinary learning and practice are voluntary. Notes you choose to save stay in the web browser you are using.",
    "heroImageAlt":"Colleagues in conversation around a table with papers and a laptop.",
    "primaryActionLabel":"Start with your work",
    "primaryActionHref":"/start",
    "secondaryActionLabel":"Ask a question",
    "secondaryActionHref":"/ask",
    "aboutLabel":"What this program is.",
    "aboutText":"This is an independently managed, internal-purpose resource for DHS staff. It is not connected to DHS information technology, case, or personnel systems. Its guidance supports knowledge work and does not replace policy, legal advice, formal processes, or decisions made by responsible DHS offices. Authority labels show what each item can and cannot establish.",
    "guidedKicker":"Areas of work",
    "guidedTitle":"What are you responsible for today?",
    "guidedIntro":"Choose the area closest to your work. Each area connects learning, practical questions, useful material, a useful work product, and the people who hold the relevant responsibility.",
    "guidedFallbackLabel":"Not sure where your work fits?",
    "guidedFallbackNote":"Answer three short questions about your role, task, and timing. Start will suggest a useful route and explain why.",
    "helpKicker":"Choose a way to work",
    "helpTitle":"Ask, Minnesota Communities, Library, or Support",
    "askLabel":"Ask",
    "askHref":"/ask",
    "askDescription":"Ask a work question and get a clear answer with its sources, scope, and limits. No meeting is needed.",
    "communitiesLabel":"Minnesota Communities",
    "communitiesHref":"/minnesota-communities",
    "communitiesDescription":"Prepare for Minnesota work with questions about access, engagement, who to involve, and what not to assume. Community information is never a label for a person.",
    "resourcesLabel":"Library",
    "resourcesHref":"/library",
    "resourcesDescription":"Search reviewed checklists, job aids, question banks, learning materials, and source notes. Each item shows where it came from, who reviewed it, and its limits.",
    "supportLabel":"Support",
    "supportHref":"/support",
    "supportAvailableDescription":"Find the responsible DHS person or office. Eligible DSD work can also request direct consultation.",
    "supportPreviewDescription":"Find the responsible DHS person or office, and review how direct consultation works for eligible DSD work.",
    "goalsKicker":"Keep moving",
    "goalsTitle":"Explore, learn, practice, and see One DSD",
    "foundationLabel":"Areas of work: enter through a decision or responsibility",
    "foundationHref":"/areas",
    "learnLabel":"Learn: move through six stages at your own pace",
    "learnHref":"/learn",
    "applyLabel":"Practice: build a useful work product",
    "applyHref":"/practice",
    "leadLabel":"One DSD: explore the divisional reference program",
    "leadHref":"/one-dsd",
    "commitmentsKicker":"Core commitments",
    "commitmentsTitle":"Six commitments behind every decision",
    "commitmentsLinkLabel":"Learn how the program works",
    "commitmentsLinkHref":"/about",
    "privacyLabel":"Protect your privacy.",
    "privacyText":"Please do not enter case, medical, personnel, complaint, or identifying details anywhere in this program. Guidance shows its sources, scope, and limits. It does not replace official policy, legal advice, Human Resources, civil-rights processes, Tribal consultation, or another responsible office."
  }
  $home$::jsonb;
  footer_copy jsonb := $footer$
  {
    "identityKicker":"One DHS People, Access and Culture Program",
    "identityText":"This independently managed, internal-purpose resource is built for DHS staff. It is not connected to DHS information technology, case, or personnel systems. Its guidance supports knowledge work and does not replace policy, legal advice, formal processes, or decisions made by responsible DHS offices. Authority labels show what each item can and cannot establish.",
    "helpHeading":"Find your next step",
    "askLabel":"Ask a question",
    "askHref":"/ask",
    "resourcesLabel":"Library",
    "resourcesHref":"/library",
    "communitiesLabel":"Minnesota Communities",
    "communitiesHref":"/minnesota-communities",
    "requestAvailableLabel":"Support and DSD consultation",
    "requestPreviewLabel":"Support and DSD consultation guidance",
    "requestHref":"/support",
    "trackLabel":"Check a DSD consultation request",
    "trackHref":"/support/track",
    "escalationLabel":"Find the right person or office",
    "escalationHref":"/support/right-person",
    "privacyHeading":"Privacy and access",
    "privacyText":"Please do not enter case, medical, personnel, complaint, or identifying details anywhere in this program. Working notes stay in the web browser you are using, where another person using the same browser may be able to see them. If any part of the program is difficult to use with assistive technology, Support explains how to report the barrier."
  }
  $footer$::jsonb;
  release_rows integer;
  release_items integer;
  release_item_ids text[];
  partial_rows integer;
  block_record record;
  release_carrier_id uuid;
  release_source_payload jsonb;
  release_revision_id uuid;
  historical_revision_id uuid;
  release_revision_number integer;
  release_payload jsonb;
  required_dimension text;
begin
  perform pg_advisory_xact_lock(hashtextextended(release_id, 0));
  perform pac_dsd.assert_valid_page_block_copy('page-home', home_copy);
  perform pac_dsd.assert_valid_page_block_copy('site-footer', footer_copy);

  -- Serialize migration replay with the owner lifecycle, which locks the same
  -- rows. The stable ordering avoids cross-surface lock inversion.
  perform item.content_item_id
  from pac_dsd.content_items item
  where item.content_item_id in ('page-home', 'site-footer')
  order by item.content_item_id
  for update;
  if (
    select count(*)
    from pac_dsd.content_items item
    where item.content_item_id in ('page-home', 'site-footer')
  ) <> 2 then
    raise exception 'The governed Home and footer content items are missing';
  end if;

  select count(*),
    count(distinct decision.content_item_id),
    array_agg(distinct decision.content_item_id order by decision.content_item_id)
  into release_rows, release_items, release_item_ids
  from pac_dsd.publication_decisions decision
  where decision.gate_snapshot ->> 'release_id' = release_id;

  if release_rows <> 0 then
    if release_rows <> 2
      or release_items <> 2
      or release_item_ids is distinct from array['page-home', 'site-footer']::text[]
      or exists (
        select 1
        from (values
          (
            'page-home'::text,
            'home'::text,
            'Home page wording'::text,
            'app/page.tsx'::text,
            'built-in:app/page.tsx@reconciled-2026-09-05'::text,
            'built-in-home-copy-reconciled-2026-09-05'::text,
            'built-in-home-copy'::text,
            home_copy
          ),
          (
            'site-footer'::text,
            'footer'::text,
            'Page footer wording'::text,
            'components/site-footer.tsx'::text,
            'built-in:components/site-footer.tsx@reconciled-2026-09-05'::text,
            'built-in-footer-copy-reconciled-2026-09-05'::text,
            'built-in-footer-copy'::text,
            footer_copy
          )
        ) expected(
          content_item_id, surface, staff_label, source_path,
          carrier_logical_key, source_item_id, source_business_id, copy
        )
        where not exists (
          select 1
          from pac_dsd.publication_decisions decision
          join pac_dsd.content_revisions revision
            on revision.revision_id = decision.revision_id
            and revision.content_item_id = decision.content_item_id
          join pac_dsd.revision_sources source_link
            on source_link.revision_id = revision.revision_id
          join pac_dsd.source_items source
            on source.source_item_id = source_link.source_item_id
          join pac_dsd.source_carriers carrier
            on carrier.carrier_id = source.carrier_id
          where decision.gate_snapshot ->> 'release_id' = release_id
            and decision.content_item_id = expected.content_item_id
            and decision.scope_id = 'one-dhs'
            and decision.decision = 'publish'
            and decision.decided_by = release_actor
            and decision.reason = 'Publish the reconciled Home and footer wording for the RG-3 staff experience.'
            and decision.sensitivity_class = 'S1'
            and decision.unauthenticated_exposure_permitted = true
            and decision.exposure_reason = release_exposure_reason
            and decision.gate_snapshot = jsonb_build_object(
              'release_id', release_id,
              'surface', expected.surface,
              'required_reviews_complete', true,
              'required_reviews', jsonb_build_array(
                jsonb_build_object('dimension', 'language_alignment', 'status', 'pass'),
                jsonb_build_object('dimension', 'factual_currentness', 'status', 'pass'),
                jsonb_build_object('dimension', 'accessibility', 'status', 'pass'),
                jsonb_build_object('dimension', 'scope', 'status', 'pass'),
                jsonb_build_object('dimension', 'placement', 'status', 'pass')
              ),
              'linked_source_item_id', expected.source_item_id,
              'exact_release_copy_captured', true,
              'explicit_owner_decision', true,
              'staff_voice_checked', true,
              'plain_text_checked', true,
              'icons_checked', true,
              'accessibility_reviewed', true,
              'sensitivity_class', 'S1',
              'ordinary_indexing_allowed', true,
              'model_context_allowed', false,
              'unauthenticated_exposure_permitted', true,
              'exposure_reason_recorded', true,
              'trust_decision_source', 'governed_page_copy_release'
            )
            and revision.revision_number = 2
            and revision.canonical_payload = jsonb_build_object(
              'id', expected.content_item_id,
              'blockType', expected.surface,
              'status', 'approved',
              'accessibility', 'reviewed',
              'scope', 'agencywide',
              'version', '2',
              'copy', expected.copy
            )
            and revision.created_by = release_actor
            and revision.sensitivity_class = 'S1'
            and revision.ordinary_indexing_allowed = true
            and revision.model_context_allowed = false
            and revision.limitations = array[
              'Approved for ordinary staff retrieval only; use as model context requires a separate item-level decision.'
            ]::text[]
            and revision.required_review_dimensions = array[
              'language_alignment', 'factual_currentness', 'accessibility',
              'scope', 'placement'
            ]::text[]
            and revision.based_on_revision_id = (
              select historical.revision_id
              from pac_dsd.publication_decisions historical
              where historical.content_item_id = expected.content_item_id
                and historical.gate_snapshot ->> 'seeded_current_approved_wording' = 'true'
              order by historical.publication_decision_id asc
              limit 1
            )
            and source_link.relationship = 'primary'
            and source_link.note = 'Exact reconciled built-in wording captured for this immutable release.'
            and source.source_item_id = expected.source_item_id
            and source.source_business_id = expected.source_business_id
            and source.source_version = '2026-09-05-reconciled'
            and source.source_pointer = expected.source_path
            and source.title = expected.staff_label || ' reconciled release source'
            and source.normalized_payload = jsonb_build_object(
              'kind', 'built_in_program_copy',
              'path', expected.source_path,
              'surface', expected.surface,
              'releaseId', release_id,
              'purpose', 'Reconciled wording approved for ordinary staff retrieval; not approved for model context.',
              'copy', expected.copy
            )
            and source.normalized_item_sha256 = encode(pac_dsd.digest(convert_to(
              jsonb_build_object(
                'kind', 'built_in_program_copy',
                'path', expected.source_path,
                'surface', expected.surface,
                'releaseId', release_id,
                'purpose', 'Reconciled wording approved for ordinary staff retrieval; not approved for model context.',
                'copy', expected.copy
              )::text,
              'UTF8'
            ), 'sha256'), 'hex')
            and source.hash_algorithm = 'sha256'
            and source.hash_algorithm_version = '1'
            and source.owner_approval_status = 'owner_approved_for_ingestion'
            and source.accounting_status = 'accounted'
            and source.access_scope = 'staff_candidate'
            and source.sensitivity_class = 'S1'
            and source.deidentification_status = 'not_needed'
            and source.ordinary_indexing_allowed = true
            and source.model_context_allowed = false
            and carrier.logical_key = expected.carrier_logical_key
            and carrier.media_type = 'application/json'
            and carrier.original_name = expected.source_path
            and carrier.byte_count = octet_length(convert_to(
              source.normalized_payload::text, 'UTF8'
            ))
            and carrier.raw_blob_sha256 = source.normalized_item_sha256
            and carrier.external_locator = jsonb_build_object(
              'kind', 'built_in_program_copy',
              'path', expected.source_path,
              'releaseId', release_id
            )
            and carrier.captured_by = release_actor
            and carrier.sensitivity_class = 'S1'
            and (
              select count(*)
              from pac_dsd.revision_sources exact_links
              where exact_links.revision_id = revision.revision_id
            ) = 1
            and (
              select count(*)
              from pac_dsd.review_records exact_reviews
              where exact_reviews.revision_id = revision.revision_id
            ) = 5
            and (
              select count(*)
              from pac_dsd.review_records exact_reviews
              where exact_reviews.revision_id = revision.revision_id
                and exact_reviews.status = 'pass'
                and exact_reviews.dimension = any(array[
                  'language_alignment', 'factual_currentness', 'accessibility',
                  'scope', 'placement'
                ]::text[])
                and exact_reviews.reviewer_role = 'publishing_approver'
                and exact_reviews.reviewer_id = release_actor
                and exact_reviews.findings ->> 'release_id' = release_id
            ) = 5
            and (
              select count(distinct exact_reviews.dimension)
              from pac_dsd.review_records exact_reviews
              where exact_reviews.revision_id = revision.revision_id
                and exact_reviews.dimension = any(array[
                  'language_alignment', 'factual_currentness', 'accessibility',
                  'scope', 'placement'
                ]::text[])
            ) = 5
            and pac_dsd.page_block_revision_is_staff_exposable(
              decision.content_item_id, decision.revision_id
            )
        )
      )
    then
      raise exception 'The reconciled Home and footer release does not match its governed two-block boundary';
    end if;
    return;
  end if;

  -- A first application may advance only the exact 0007 baseline. Any draft,
  -- prior owner decision, or other unexpected history requires deliberate
  -- reconciliation instead of being silently buried by this migration.
  if exists (
    select 1
    from (values
      (
        'page-home'::text,
        'Home page wording'::text,
        'home'::text,
        'app/page.tsx'::text,
        'built-in:app/page.tsx'::text,
        'built-in-home-copy-2026-09-05'::text,
        'built-in-home-copy'::text,
        '891abcf3e52160bd6661d8649acd61514c5745fe0296760ddbd81f82c5fb31b2'::text,
        '8a57dbcb88c2e6a20596398c82bc2f5ffc1604cd6011e9e59ab209d2d9f60c34'::text
      ),
      (
        'site-footer'::text,
        'Page footer wording'::text,
        'footer'::text,
        'components/site-footer.tsx'::text,
        'built-in:components/site-footer.tsx'::text,
        'built-in-footer-copy-2026-09-05'::text,
        'built-in-footer-copy'::text,
        '9c1d5155684f88457df27cd352ff95a19e1a96fde6b3793f9a633611551aaf8b'::text,
        'ca2d20e695ff5e2cca7a0ba5ee22379999552efc700c9ecca1ec14b29334549c'::text
      )
    ) expected(
      content_item_id, staff_label, surface, source_path,
      carrier_logical_key, historical_source_item_id, source_business_id,
      revision_payload_sha256, source_payload_sha256
    )
    where (
      select count(*)
      from pac_dsd.content_revisions revision
      where revision.content_item_id = expected.content_item_id
    ) <> 1
      or (
        select count(*)
        from pac_dsd.publication_decisions decision
        where decision.content_item_id = expected.content_item_id
      ) <> 1
      or not exists (
        select 1
        from pac_dsd.content_items item
        join pac_dsd.publication_decisions decision
          on decision.content_item_id = item.content_item_id
        join pac_dsd.content_revisions revision
          on revision.revision_id = decision.revision_id
          and revision.content_item_id = decision.content_item_id
        join pac_dsd.revision_sources source_link
          on source_link.revision_id = revision.revision_id
        join pac_dsd.source_items source
          on source.source_item_id = source_link.source_item_id
        join pac_dsd.source_carriers carrier
          on carrier.carrier_id = source.carrier_id
        where item.content_item_id = expected.content_item_id
          and item.content_kind = 'internal'
          and item.default_scope_id = 'one-dhs'
          and item.staff_label = expected.staff_label
          and item.restricted = true
          and item.retired_at is null
          and item.sensitivity_class = 'S2'
          and item.created_by = 'pac-home-footer-content-migration'
          and decision.scope_id = 'one-dhs'
          and decision.decision = 'publish'
          and decision.gate_snapshot = jsonb_build_object(
            'seeded_current_approved_wording', true,
            'required_reviews_complete', true
          )
          and decision.decided_by = 'pac-home-footer-content-migration'
          and decision.reason = 'Current approved wording retained for staff.'
          and decision.sensitivity_class = 'S2'
          and decision.unauthenticated_exposure_permitted = false
          and decision.exposure_reason is null
          and revision.revision_number = 1
          and revision.payload_sha256 = expected.revision_payload_sha256
          and revision.canonical_payload ->> 'status' = 'approved'
          and revision.canonical_payload ->> 'accessibility' = 'reviewed'
          and revision.canonical_payload ->> 'id' = expected.content_item_id
          and revision.canonical_payload ->> 'blockType' = expected.surface
          and revision.canonical_payload ->> 'scope' = 'agencywide'
          and revision.canonical_payload ->> 'version' = '1'
          and revision.change_summary = 'Current approved wording captured for governed inline editing.'
          and revision.required_review_dimensions = array[
            'language_alignment', 'factual_currentness', 'accessibility',
            'scope', 'placement'
          ]::text[]
          and revision.created_by = 'pac-home-footer-content-migration'
          and revision.based_on_revision_id is null
          and revision.sensitivity_class = 'S2'
          and revision.ordinary_indexing_allowed = false
          and revision.model_context_allowed = false
          and revision.limitations = '{}'::text[]
          and source_link.relationship = 'primary'
          and source_link.note = 'Accounted built-in wording captured from the application.'
          and source.source_item_id = expected.historical_source_item_id
          and source.source_business_id = expected.source_business_id
          and source.source_version = '1'
          and source.source_pointer = expected.source_path
          and source.title = expected.staff_label
          and source.normalized_payload = jsonb_build_object(
            'kind', 'built_in_program_copy',
            'path', expected.source_path,
            'surface', expected.surface,
            'purpose', 'Approved wording captured before program-wide inline editing.'
          )
          and source.normalized_item_sha256 = expected.source_payload_sha256
          and source.hash_algorithm = 'sha256'
          and source.hash_algorithm_version = '1'
          and source.owner_approval_status = 'owner_approved_for_ingestion'
          and source.accounting_status = 'accounted'
          and source.access_scope = 'internal_source'
          and source.sensitivity_class = 'S2'
          and source.deidentification_status = 'not_reviewed'
          and source.ordinary_indexing_allowed = false
          and source.model_context_allowed = false
          and carrier.logical_key = expected.carrier_logical_key
          and carrier.media_type = 'application/json'
          and carrier.original_name = expected.source_path
          and carrier.byte_count = octet_length(convert_to(
            source.normalized_payload::text, 'UTF8'
          ))
          and carrier.raw_blob_sha256 = expected.source_payload_sha256
          and carrier.external_locator = jsonb_build_object(
            'kind', 'built_in_program_copy',
            'path', expected.source_path
          )
          and carrier.captured_by = 'pac-home-footer-content-migration'
          and carrier.sensitivity_class = 'S2'
          and (
            select count(*)
            from pac_dsd.revision_sources historical_links
            where historical_links.revision_id = revision.revision_id
          ) = 1
          and (
            select count(*)
            from pac_dsd.review_records historical_reviews
            where historical_reviews.revision_id = revision.revision_id
          ) = 5
          and (
            select count(*)
            from pac_dsd.review_records historical_reviews
            where historical_reviews.revision_id = revision.revision_id
              and historical_reviews.status = 'pass'
              and historical_reviews.dimension = any(array[
                'language_alignment', 'factual_currentness', 'accessibility',
                'scope', 'placement'
              ]::text[])
              and historical_reviews.reviewer_role = 'program_steward'
              and historical_reviews.reviewer_id = 'pac-home-footer-content-migration'
              and historical_reviews.findings = jsonb_build_object(
                'note', 'Current approved wording retained without alteration.'
              )
          ) = 5
          and (
            select count(distinct historical_reviews.dimension)
            from pac_dsd.review_records historical_reviews
            where historical_reviews.revision_id = revision.revision_id
              and historical_reviews.dimension = any(array[
                'language_alignment', 'factual_currentness', 'accessibility',
                'scope', 'placement'
              ]::text[])
          ) = 5
          and not exists (
            select 1
            from pac_dsd.revision_assets historical_assets
            where historical_assets.revision_id = revision.revision_id
          )
      )
  ) then
    raise exception 'Unexpected Home or footer history must be reconciled before the trusted release can be applied';
  end if;

  select count(*) into partial_rows
  from (
    select source.source_item_id
    from pac_dsd.source_items source
    where source.source_item_id in (
      'built-in-home-copy-reconciled-2026-09-05',
      'built-in-footer-copy-reconciled-2026-09-05'
    )
    union all
    select carrier.logical_key
    from pac_dsd.source_carriers carrier
    where carrier.logical_key in (
      'built-in:app/page.tsx@reconciled-2026-09-05',
      'built-in:components/site-footer.tsx@reconciled-2026-09-05'
    )
  ) partial;
  if partial_rows <> 0 then
    raise exception 'A partial reconciled Home and footer release already exists';
  end if;

  for block_record in
    select * from (values
      (
        'page-home'::text,
        'home'::text,
        'Home page wording'::text,
        'app/page.tsx'::text,
        'built-in:app/page.tsx@reconciled-2026-09-05'::text,
        'built-in-home-copy-reconciled-2026-09-05'::text,
        'built-in-home-copy'::text,
        home_copy
      ),
      (
        'site-footer'::text,
        'footer'::text,
        'Page footer wording'::text,
        'components/site-footer.tsx'::text,
        'built-in:components/site-footer.tsx@reconciled-2026-09-05'::text,
        'built-in-footer-copy-reconciled-2026-09-05'::text,
        'built-in-footer-copy'::text,
        footer_copy
      )
    ) block_values(
      content_item_id, surface, staff_label, source_path,
      carrier_logical_key, source_item_id, source_business_id, copy
    )
  loop
    if not exists (
      select 1
      from pac_dsd.content_items item
      where item.content_item_id = block_record.content_item_id
        and item.content_kind = 'internal'
        and item.default_scope_id = 'one-dhs'
        and item.staff_label = block_record.staff_label
        and item.restricted = true
        and item.retired_at is null
        and item.sensitivity_class in ('S1', 'S2')
    ) then
      raise exception 'Existing page block has incompatible content settings';
    end if;

    select revision.revision_id into historical_revision_id
    from pac_dsd.content_revisions revision
    where revision.content_item_id = block_record.content_item_id
    order by revision.revision_number desc, revision.revision_id desc
    limit 1;
    if historical_revision_id is null then
      raise exception 'The historical page block revision is missing';
    end if;

    update pac_dsd.content_items item
    set sensitivity_class = 'S1'
    where item.content_item_id = block_record.content_item_id
      and item.sensitivity_class = 'S2';

    release_revision_id := gen_random_uuid();
    release_source_payload := jsonb_build_object(
      'kind', 'built_in_program_copy',
      'path', block_record.source_path,
      'surface', block_record.surface,
      'releaseId', release_id,
      'purpose', 'Reconciled wording approved for ordinary staff retrieval; not approved for model context.',
      'copy', block_record.copy
    );

    insert into pac_dsd.source_carriers (
      logical_key, media_type, original_name, byte_count, raw_blob_sha256,
      external_locator, captured_by, sensitivity_class
    ) values (
      block_record.carrier_logical_key,
      'application/json',
      block_record.source_path,
      octet_length(convert_to(release_source_payload::text, 'UTF8')),
      encode(pac_dsd.digest(convert_to(release_source_payload::text, 'UTF8'), 'sha256'), 'hex'),
      jsonb_build_object(
        'kind', 'built_in_program_copy',
        'path', block_record.source_path,
        'releaseId', release_id
      ),
      release_actor,
      'S1'
    ) returning carrier_id into release_carrier_id;

    insert into pac_dsd.source_items (
      source_item_id, source_business_id, carrier_id, source_version,
      source_pointer, title, normalized_payload, normalized_item_sha256,
      hash_algorithm, hash_algorithm_version, owner_approval_status,
      accounting_status, access_scope, sensitivity_class,
      deidentification_status, ordinary_indexing_allowed,
      model_context_allowed
    ) values (
      block_record.source_item_id,
      block_record.source_business_id,
      release_carrier_id,
      '2026-09-05-reconciled',
      block_record.source_path,
      block_record.staff_label || ' reconciled release source',
      release_source_payload,
      encode(pac_dsd.digest(convert_to(release_source_payload::text, 'UTF8'), 'sha256'), 'hex'),
      'sha256',
      '1',
      'owner_approved_for_ingestion',
      'accounted',
      'staff_candidate',
      'S1',
      'not_needed',
      true,
      false
    );

    select coalesce(max(revision.revision_number), 0) + 1
    into release_revision_number
    from pac_dsd.content_revisions revision
    where revision.content_item_id = block_record.content_item_id;
    release_payload := jsonb_build_object(
      'id', block_record.content_item_id,
      'blockType', block_record.surface,
      'status', 'approved',
      'accessibility', 'reviewed',
      'scope', 'agencywide',
      'version', release_revision_number::text,
      'copy', block_record.copy
    );

    insert into pac_dsd.content_revisions (
      revision_id, content_item_id, revision_number, canonical_payload,
      change_summary, required_review_dimensions, created_by,
      based_on_revision_id, sensitivity_class, ordinary_indexing_allowed,
      model_context_allowed, limitations
    ) values (
      release_revision_id,
      block_record.content_item_id,
      release_revision_number,
      release_payload,
      'Reconciled RG-3 staff wording published through a forward S1 release.',
      array[
        'language_alignment', 'factual_currentness', 'accessibility',
        'scope', 'placement'
      ]::text[],
      release_actor,
      historical_revision_id,
      'S1',
      true,
      false,
      array[
        'Approved for ordinary staff retrieval only; use as model context requires a separate item-level decision.'
      ]::text[]
    );

    insert into pac_dsd.revision_sources (
      revision_id, source_item_id, relationship, note
    ) values (
      release_revision_id,
      block_record.source_item_id,
      'primary',
      'Exact reconciled built-in wording captured for this immutable release.'
    );

    foreach required_dimension in array array[
      'language_alignment', 'factual_currentness', 'accessibility',
      'scope', 'placement'
    ]::text[] loop
      insert into pac_dsd.review_records (
        revision_id, dimension, status, reviewer_role, reviewer_id, findings
      ) values (
        release_revision_id,
        required_dimension,
        'pass',
        'publishing_approver',
        release_actor,
        jsonb_build_object(
          'note', 'Reconciled owner-approved wording verified for the RG-3 staff release.',
          'release_id', release_id
        )
      );
    end loop;

    if not pac_dsd.page_block_revision_is_staff_exposable(
      block_record.content_item_id, release_revision_id
    ) then
      raise exception 'The reconciled page block did not pass the staff publication trust gate';
    end if;

    insert into pac_dsd.publication_decisions (
      content_item_id, revision_id, scope_id, decision, gate_snapshot,
      decided_by, reason, sensitivity_class,
      unauthenticated_exposure_permitted, exposure_reason
    ) values (
      block_record.content_item_id,
      release_revision_id,
      'one-dhs',
      'publish',
      jsonb_build_object(
        'release_id', release_id,
        'surface', block_record.surface,
        'required_reviews_complete', true,
        'required_reviews', jsonb_build_array(
          jsonb_build_object('dimension', 'language_alignment', 'status', 'pass'),
          jsonb_build_object('dimension', 'factual_currentness', 'status', 'pass'),
          jsonb_build_object('dimension', 'accessibility', 'status', 'pass'),
          jsonb_build_object('dimension', 'scope', 'status', 'pass'),
          jsonb_build_object('dimension', 'placement', 'status', 'pass')
        ),
        'linked_source_item_id', block_record.source_item_id,
        'exact_release_copy_captured', true,
        'explicit_owner_decision', true,
        'staff_voice_checked', true,
        'plain_text_checked', true,
        'icons_checked', true,
        'accessibility_reviewed', true,
        'sensitivity_class', 'S1',
        'ordinary_indexing_allowed', true,
        'model_context_allowed', false,
        'unauthenticated_exposure_permitted', true,
        'exposure_reason_recorded', true,
        'trust_decision_source', 'governed_page_copy_release'
      ),
      release_actor,
      'Publish the reconciled Home and footer wording for the RG-3 staff experience.',
      'S1',
      true,
      release_exposure_reason
    );
  end loop;

  select count(*) into release_rows
  from pac_dsd.publication_decisions decision
  where decision.gate_snapshot ->> 'release_id' = release_id;
  if release_rows <> 2 then
    raise exception 'The reconciled Home and footer release did not complete atomically';
  end if;

  insert into pac_dsd.change_events (
    actor_id, actor_role, scope_id, object_type, object_id, action, detail
  ) values (
    release_actor,
    'owner',
    'one-dhs',
    'page_copy_release',
    release_id,
    'trusted_staff_release_published',
    jsonb_build_object(
      'content_item_ids', array['page-home', 'site-footer']::text[],
      'sensitivity_class', 'S1',
      'ordinary_indexing_allowed', true,
      'model_context_allowed', false,
      'unauthenticated_exposure_permitted', true,
      'historical_release_preserved', true
    )
  );
end;
$$;

