-- 0019_pac_corpus_inventory_and_relationships.sql

create index if not exists knowledge_nodes_revision_reference_idx
  on pac_dsd.knowledge_nodes ((properties->>'revisionId')) where node_type = 'revision';

create or replace function pac_dsd.read_owner_corpus_inventory(
  requested_scope text, requested_search text default '', requested_limit integer default 40, requested_offset integer default 0
)
returns jsonb language plpgsql stable security definer
set search_path = pg_catalog, pac_dsd set row_security = off
as $$
declare result jsonb;
begin
  if requested_scope not in ('one-dhs','dsd') or requested_scope is null
    or length(coalesce(requested_search,'')) > 200
    or requested_limit is null or requested_limit not between 1 and 100
    or requested_offset is null or requested_offset < 0 or requested_offset > 1000000 then
    raise exception 'Invalid collection request' using errcode='22023';
  end if;
  with eligible as (
    select i.* from pac_dsd.content_items i
    where (i.default_scope_id='one-dhs' or i.default_scope_id=requested_scope)
      and (coalesce(requested_search,'')='' or strpos(lower(i.staff_label),lower(requested_search))>0)
  ), entries as (
    select i.content_item_id, i.staff_label, i.content_kind, i.default_scope_id,
      r.revision_id, r.revision_number,
      exists(select 1 from pac_dsd.read_staff_publications(requested_scope,i.content_item_id)) as published
    from eligible i
    left join lateral (
      select cr.revision_id,cr.revision_number from pac_dsd.content_revisions cr
      where cr.content_item_id=i.content_item_id
      order by cr.revision_number desc limit 1
    ) r on true
    order by i.staff_label,i.content_item_id limit requested_limit offset requested_offset
  )
  select jsonb_build_object(
    'total', (select count(*) from eligible),
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'id',content_item_id,'title',staff_label,'kind',content_kind,'scope',default_scope_id,
      'revisionId',revision_id,'revisionNumber',revision_number,'published',published
    ) order by staff_label,content_item_id) from entries),'[]'::jsonb),
    'counts',jsonb_build_object(
      'sources',(select count(*) from pac_dsd.source_items),
      'unavailableSources',(select count(*) from pac_dsd.source_items where accounting_status='accounted_awaiting_source'),
      'receipts',(select count(*) from pac_dsd.source_receipts),
      'content',(select count(*) from pac_dsd.content_items),
      'revisions',(select count(*) from pac_dsd.content_revisions),
      'storedFiles',(select count(*) from pac_dsd.source_carrier_locations),
      'nodes',(select count(*) from pac_dsd.knowledge_nodes),
      'relationships',(select count(*) from pac_dsd.knowledge_edges)
    )
  ) into result;
  return result;
end;
$$;

-- Relationship hints only connect exact currently visible revisions. An older
-- graph snapshot cannot keep a corrected or withdrawn resource visible.
create or replace function pac_dsd.read_staff_graph_neighbors(requested_scope text, requested_item text, requested_limit integer default 4)
returns table(content_item_id text,title text,shared_topics bigint)
language plpgsql stable security definer
set search_path=pg_catalog,pac_dsd set row_security=off
as $$
begin
  if requested_scope not in ('one-dhs','dsd') or requested_scope is null
    or requested_limit is null or requested_limit not between 1 and 12 then
    raise exception 'Invalid related reading request' using errcode='22023';
  end if;
  return query
  with visible as materialized (select * from pac_dsd.read_staff_publications(requested_scope,null)),
  starting as (
    select edge.to_node_id
    from visible item
    join pac_dsd.knowledge_nodes node on node.properties->>'revisionId'=item.revision_id::text and node.node_type='revision'
    join pac_dsd.knowledge_edges edge on edge.from_node_id=node.node_id and edge.edge_type='applies_to'
    where item.content_item_id=requested_item
  )
  select candidate.content_item_id,candidate.canonical_payload->>'title',count(distinct edge.to_node_id)
  from visible candidate
  join pac_dsd.knowledge_nodes node on node.properties->>'revisionId'=candidate.revision_id::text and node.node_type='revision'
  join pac_dsd.knowledge_edges edge on edge.from_node_id=node.node_id and edge.edge_type='applies_to'
  join starting on starting.to_node_id=edge.to_node_id
  where candidate.content_item_id<>requested_item
  group by candidate.content_item_id,candidate.canonical_payload->>'title'
  order by count(distinct edge.to_node_id) desc,candidate.content_item_id
  limit requested_limit;
end;
$$;

revoke all on function pac_dsd.read_owner_corpus_inventory(text,text,integer,integer) from public;
revoke all on function pac_dsd.read_staff_graph_neighbors(text,text,integer) from public;
grant execute on function pac_dsd.read_owner_corpus_inventory(text,text,integer,integer) to pac_dsd_app_runtime;
grant execute on function pac_dsd.read_staff_graph_neighbors(text,text,integer) to pac_dsd_app_runtime;
comment on function pac_dsd.read_owner_corpus_inventory(text,text,integer,integer) is
  'Owner application boundary only: counts and paginated content labels; source bodies, private submissions, and secrets are excluded.';


-- 0020_pac_unpublished_resource_authoring.sql

create or replace function pac_dsd.resource_management_allowed(requested_scope_id text,requested_content_item_id text)
returns boolean language sql stable set search_path=pg_catalog,pac_dsd
as $$
  with recursive visible_scopes as (
    select scope_id,parent_scope_id from pac_dsd.program_scopes
    where scope_id=requested_scope_id and active and scope_id in ('one-dhs','dsd')
    union all
    select parent.scope_id,parent.parent_scope_id from pac_dsd.program_scopes parent
    join visible_scopes child on child.parent_scope_id=parent.scope_id
    where parent.active and parent.scope_id<>'one-dhs-pac'
  )
  select exists(select 1 from pac_dsd.content_items item
    where item.content_item_id=requested_content_item_id and item.content_kind='resource'
      and not item.restricted and item.retired_at is null
      and item.default_scope_id in (select scope_id from visible_scopes)
      and exists(select 1 from pac_dsd.content_revisions revision
        where revision.content_item_id=item.content_item_id
          and revision.canonical_payload->>'status' in ('under_review','approved')
          and revision.canonical_payload->>'id'=item.content_item_id));
$$;

create or replace function pac_dsd.read_resource_editing_state(requested_scope_id text,requested_content_item_id text)
returns table(content_item_id text,published_revision_id uuid,base_revision_id uuid,editable_fields jsonb,has_unpublished_changes boolean)
language plpgsql stable security definer set search_path=pg_catalog,pac_dsd set row_security=off
as $$
begin
  if not pac_dsd.resource_management_allowed(requested_scope_id,requested_content_item_id) then
    raise exception 'Resource is not available for editing' using errcode='P0002';
  end if;
  return query
  with visible as (select p.* from pac_dsd.read_staff_publications(requested_scope_id,requested_content_item_id) p),
  local_draft as (
    select r.* from pac_dsd.content_revisions r
    where r.content_item_id=requested_content_item_id and r.canonical_payload->>'status'='under_review'
      and pac_dsd.resource_scope_id(r.canonical_payload)=requested_scope_id
      and not exists(select 1 from pac_dsd.content_revisions released
        where released.based_on_revision_id=r.revision_id and released.canonical_payload->>'status'='approved')
    order by r.revision_number desc limit 1
  ), base as (
    select r.* from pac_dsd.content_revisions r
    join pac_dsd.content_items i on i.content_item_id=r.content_item_id
    where r.content_item_id=requested_content_item_id
      and r.canonical_payload->>'status' in ('under_review','approved')
      and pac_dsd.resource_scope_id(r.canonical_payload) in (requested_scope_id,i.default_scope_id)
    order by (r.revision_id=(select d.revision_id from local_draft d)) desc nulls last,
      (r.revision_id=(select v.revision_id from visible v)) desc nulls last,r.revision_number desc
    limit 1
  )
  select requested_content_item_id,(select v.revision_id from visible v),b.revision_id,
    jsonb_build_object(
      'title',b.canonical_payload->'title','type',b.canonical_payload->'type',
      'authority',b.canonical_payload->'authority','layer',b.canonical_payload->'layer',
      'summary',b.canonical_payload->'summary','whyItMatters',coalesce(b.canonical_payload->'whyItMatters','null'::jsonb),
      'body',b.canonical_payload->'body','nextActions',b.canonical_payload->'nextActions',
      'tags',b.canonical_payload->'tags','intents',b.canonical_payload->'intents',
      'pathIds',coalesce(b.canonical_payload->'pathIds','[]'::jsonb),
      'owner',b.canonical_payload->'owner','reviewDate',b.canonical_payload->'reviewDate',
      'scope',to_jsonb(case when requested_scope_id='one-dhs' then 'agencywide' else 'dsd' end),
      'href',coalesce(b.canonical_payload->'href','null'::jsonb),
      'sourceName',coalesce(b.canonical_payload->'sourceName','null'::jsonb)
    ),b.canonical_payload->>'status'='under_review'
  from base b;
end;
$$;
revoke all on function pac_dsd.resource_management_allowed(text,text) from public;
revoke all on function pac_dsd.read_resource_editing_state(text,text) from public;
grant execute on function pac_dsd.read_resource_editing_state(text,text) to pac_dsd_app_runtime;
comment on function pac_dsd.read_resource_editing_state(text,text) is
  'Owner authoring includes recovered unpublished resource candidates. The actual staff reader remains the only source of published_revision_id.';


-- 0021_pac_optional_home_note.sql

-- The Home page may omit its optional supporting note. Every other page-copy
-- field remains required, and a nonblank note still receives the same length,
-- plain-text, staff-language, icon, and safe-link validation as before.
create or replace function pac_dsd.assert_valid_page_block_copy(
  requested_content_item_id text,
  requested_copy jsonb
)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
declare
  expected_keys text[];
  link_keys text[];
  candidate_key text;
  maximum_length integer;
  candidate_value text;
begin
  if jsonb_typeof(requested_copy) <> 'object' then
    raise exception 'Page wording must be a complete set of labeled fields' using errcode = '22023';
  end if;

  if requested_content_item_id = 'page-home' then
    expected_keys := array[
      'heroKicker', 'headlineLine1', 'headlineLine2', 'headlineLine3',
      'heroLede', 'heroNote', 'heroImageAlt', 'primaryActionLabel',
      'primaryActionHref', 'secondaryActionLabel', 'secondaryActionHref',
      'aboutLabel', 'aboutText', 'guidedKicker', 'guidedTitle', 'guidedIntro',
      'guidedFallbackLabel', 'guidedFallbackNote', 'helpKicker', 'helpTitle',
      'askLabel', 'askHref', 'askDescription', 'communitiesLabel',
      'communitiesHref', 'communitiesDescription', 'resourcesLabel',
      'resourcesHref', 'resourcesDescription', 'supportLabel', 'supportHref',
      'supportAvailableDescription', 'supportPreviewDescription', 'goalsKicker',
      'goalsTitle', 'foundationLabel', 'foundationHref', 'learnLabel', 'learnHref',
      'applyLabel', 'applyHref', 'leadLabel', 'leadHref', 'commitmentsKicker',
      'commitmentsTitle', 'commitmentsLinkLabel', 'commitmentsLinkHref',
      'privacyLabel', 'privacyText'
    ]::text[];
    link_keys := array[
      'primaryActionHref', 'secondaryActionHref', 'askHref', 'communitiesHref',
      'resourcesHref', 'supportHref', 'foundationHref', 'learnHref', 'applyHref',
      'leadHref', 'commitmentsLinkHref'
    ]::text[];
  elsif requested_content_item_id = 'site-footer' then
    expected_keys := array[
      'identityKicker', 'identityText', 'helpHeading', 'askLabel', 'askHref',
      'resourcesLabel', 'resourcesHref', 'communitiesLabel', 'communitiesHref',
      'requestAvailableLabel', 'requestPreviewLabel', 'requestHref', 'trackLabel',
      'trackHref', 'escalationLabel', 'escalationHref', 'privacyHeading', 'privacyText'
    ]::text[];
    link_keys := array[
      'askHref', 'resourcesHref', 'communitiesHref', 'requestHref', 'trackHref',
      'escalationHref'
    ]::text[];
  else
    raise exception 'This page area is not available' using errcode = 'P0002';
  end if;

  if exists (
    select 1 from unnest(expected_keys) expected(name)
    where not requested_copy ? expected.name
  ) or exists (
    select 1 from jsonb_object_keys(requested_copy) actual(name)
    where actual.name <> all(expected_keys)
  ) then
    raise exception 'Page wording fields do not match this page area' using errcode = '22023';
  end if;

  foreach candidate_key in array expected_keys loop
    if jsonb_typeof(requested_copy -> candidate_key) <> 'string' then
      raise exception 'Every page wording field must be text' using errcode = '22023';
    end if;
    candidate_value := requested_copy ->> candidate_key;
    maximum_length := case
      when candidate_key = any(link_keys) then 2000
      when candidate_key in ('identityText', 'privacyText') and requested_content_item_id = 'site-footer' then 4000
      when candidate_key in ('aboutText', 'guidedIntro', 'privacyText') then 3000
      when candidate_key in (
        'heroNote', 'askDescription', 'communitiesDescription', 'resourcesDescription',
        'supportAvailableDescription', 'supportPreviewDescription'
      ) then 2000
      when candidate_key in ('heroLede', 'guidedFallbackNote') then 1000
      when candidate_key in (
        'helpTitle', 'goalsTitle', 'foundationLabel', 'learnLabel', 'applyLabel',
        'leadLabel', 'commitmentsTitle', 'escalationLabel', 'heroImageAlt'
      ) then 500
      when candidate_key in ('guidedTitle', 'guidedFallbackLabel', 'commitmentsLinkLabel',
        'requestAvailableLabel', 'requestPreviewLabel', 'trackLabel') then 300
      else 200
    end;

    if requested_content_item_id = 'page-home'
      and candidate_key = 'heroNote'
      and candidate_value = '' then
      continue;
    end if;

    if length(btrim(candidate_value)) not between 1 and maximum_length then
      raise exception 'A page wording field is blank or too long' using errcode = '22023';
    end if;
    if candidate_key = any(link_keys) then
      perform pac_dsd.assert_safe_page_link(candidate_value);
    else
      perform pac_dsd.assert_plain_page_text(candidate_value);
    end if;
  end loop;
end;
$$;


-- 0022_pac_equity_toolkit_surface.sql
-- Forward-only seed for the new toolkit companion. Requires migration 0018.
-- No existing definitions or append-only history are overwritten. Exact replay
-- preserves subsequent consultant revisions, withdrawals, and scoped publications.
-- This migration does not change runtime feature flags or official DHS systems.

do $pac_seed$
declare
  registry_seed constant jsonb := $pac_registry$[{"surfaceId":"equity-toolkit.home","routePattern":"/learn/equity-toolkit","staffLabel":"Equity Analysis Toolkit companion","scopePolicy":"inheritable","fieldContract":[{"key":"title","label":"title","kind":"long","required":true},{"key":"intro","label":"intro","kind":"long","required":true},{"key":"companionNote","label":"companionNote","kind":"long","required":true},{"key":"roleLabel","label":"roleLabel","kind":"long","required":true},{"key":"roleIntro","label":"roleIntro","kind":"long","required":true},{"key":"noRoleLabel","label":"noRoleLabel","kind":"long","required":true},{"key":"stageNavLabel","label":"stageNavLabel","kind":"long","required":true},{"key":"objectivesTitle","label":"objectivesTitle","kind":"long","required":true},{"key":"scenarioTitle","label":"scenarioTitle","kind":"long","required":true},{"key":"consequenceTitle","label":"consequenceTitle","kind":"long","required":true},{"key":"practiceLabel","label":"practiceLabel","kind":"long","required":true},{"key":"workLabel","label":"workLabel","kind":"long","required":true},{"key":"draftTitle","label":"draftTitle","kind":"long","required":true},{"key":"draftIntro","label":"draftIntro","kind":"long","required":true},{"key":"draftPrivacy","label":"draftPrivacy","kind":"long","required":true},{"key":"draftRetention","label":"draftRetention","kind":"long","required":true},{"key":"backLabel","label":"backLabel","kind":"long","required":true},{"key":"clearLabel","label":"clearLabel","kind":"long","required":true},{"key":"clearConfirmLabel","label":"clearConfirmLabel","kind":"long","required":true},{"key":"cancelLabel","label":"cancelLabel","kind":"long","required":true},{"key":"clearedMessage","label":"clearedMessage","kind":"long","required":true},{"key":"printLabel","label":"printLabel","kind":"long","required":true},{"key":"nextLabel","label":"nextLabel","kind":"long","required":true},{"key":"previousLabel","label":"previousLabel","kind":"long","required":true},{"key":"resourcesTitle","label":"resourcesTitle","kind":"long","required":true},{"key":"resourcesIntro","label":"resourcesIntro","kind":"long","required":true},{"key":"resourceTitle","label":"resourceTitle","kind":"long","required":true},{"key":"resourceIntro","label":"resourceIntro","kind":"long","required":true},{"key":"toolkitLabel","label":"toolkitLabel","kind":"long","required":true},{"key":"briefsLabel","label":"briefsLabel","kind":"long","required":true},{"key":"scenarioNote","label":"scenarioNote","kind":"long","required":true},{"key":"culturalContext","label":"culturalContext","kind":"long","required":true},{"key":"authorityNote","label":"authorityNote","kind":"long","required":true},{"key":"decisionTitle","label":"decisionTitle","kind":"long","required":true},{"key":"decisionIntro","label":"decisionIntro","kind":"long","required":true},{"key":"decisionObjectives","label":"decisionObjectives","kind":"string-list","required":true,"maxItems":5},{"key":"decisionScenario","label":"decisionScenario","kind":"long","required":true},{"key":"decisionChoicea","label":"decisionChoicea","kind":"long","required":true},{"key":"decisionConsequencea","label":"decisionConsequencea","kind":"long","required":true},{"key":"decisionChoiceb","label":"decisionChoiceb","kind":"long","required":true},{"key":"decisionConsequenceb","label":"decisionConsequenceb","kind":"long","required":true},{"key":"decisionChoicec","label":"decisionChoicec","kind":"long","required":true},{"key":"decisionConsequencec","label":"decisionConsequencec","kind":"long","required":true},{"key":"decisionDraftLabel","label":"decisionDraftLabel","kind":"long","required":true},{"key":"decisionDraftHelp","label":"decisionDraftHelp","kind":"long","required":true},{"key":"peopleTitle","label":"peopleTitle","kind":"long","required":true},{"key":"peopleIntro","label":"peopleIntro","kind":"long","required":true},{"key":"peopleObjectives","label":"peopleObjectives","kind":"string-list","required":true,"maxItems":5},{"key":"peopleScenario","label":"peopleScenario","kind":"long","required":true},{"key":"peopleChoicea","label":"peopleChoicea","kind":"long","required":true},{"key":"peopleConsequencea","label":"peopleConsequencea","kind":"long","required":true},{"key":"peopleChoiceb","label":"peopleChoiceb","kind":"long","required":true},{"key":"peopleConsequenceb","label":"peopleConsequenceb","kind":"long","required":true},{"key":"peopleChoicec","label":"peopleChoicec","kind":"long","required":true},{"key":"peopleConsequencec","label":"peopleConsequencec","kind":"long","required":true},{"key":"peopleDraftLabel","label":"peopleDraftLabel","kind":"long","required":true},{"key":"peopleDraftHelp","label":"peopleDraftHelp","kind":"long","required":true},{"key":"optionsTitle","label":"optionsTitle","kind":"long","required":true},{"key":"optionsIntro","label":"optionsIntro","kind":"long","required":true},{"key":"optionsObjectives","label":"optionsObjectives","kind":"string-list","required":true,"maxItems":5},{"key":"optionsScenario","label":"optionsScenario","kind":"long","required":true},{"key":"optionsChoicea","label":"optionsChoicea","kind":"long","required":true},{"key":"optionsConsequencea","label":"optionsConsequencea","kind":"long","required":true},{"key":"optionsChoiceb","label":"optionsChoiceb","kind":"long","required":true},{"key":"optionsConsequenceb","label":"optionsConsequenceb","kind":"long","required":true},{"key":"optionsChoicec","label":"optionsChoicec","kind":"long","required":true},{"key":"optionsConsequencec","label":"optionsConsequencec","kind":"long","required":true},{"key":"optionsDraftLabel","label":"optionsDraftLabel","kind":"long","required":true},{"key":"optionsDraftHelp","label":"optionsDraftHelp","kind":"long","required":true},{"key":"participationTitle","label":"participationTitle","kind":"long","required":true},{"key":"participationIntro","label":"participationIntro","kind":"long","required":true},{"key":"participationObjectives","label":"participationObjectives","kind":"string-list","required":true,"maxItems":5},{"key":"participationScenario","label":"participationScenario","kind":"long","required":true},{"key":"participationChoicea","label":"participationChoicea","kind":"long","required":true},{"key":"participationConsequencea","label":"participationConsequencea","kind":"long","required":true},{"key":"participationChoiceb","label":"participationChoiceb","kind":"long","required":true},{"key":"participationConsequenceb","label":"participationConsequenceb","kind":"long","required":true},{"key":"participationChoicec","label":"participationChoicec","kind":"long","required":true},{"key":"participationConsequencec","label":"participationConsequencec","kind":"long","required":true},{"key":"participationDraftLabel","label":"participationDraftLabel","kind":"long","required":true},{"key":"participationDraftHelp","label":"participationDraftHelp","kind":"long","required":true},{"key":"reviewTitle","label":"reviewTitle","kind":"long","required":true},{"key":"reviewIntro","label":"reviewIntro","kind":"long","required":true},{"key":"reviewObjectives","label":"reviewObjectives","kind":"string-list","required":true,"maxItems":5},{"key":"reviewScenario","label":"reviewScenario","kind":"long","required":true},{"key":"reviewChoicea","label":"reviewChoicea","kind":"long","required":true},{"key":"reviewConsequencea","label":"reviewConsequencea","kind":"long","required":true},{"key":"reviewChoiceb","label":"reviewChoiceb","kind":"long","required":true},{"key":"reviewConsequenceb","label":"reviewConsequenceb","kind":"long","required":true},{"key":"reviewChoicec","label":"reviewChoicec","kind":"long","required":true},{"key":"reviewConsequencec","label":"reviewConsequencec","kind":"long","required":true},{"key":"reviewDraftLabel","label":"reviewDraftLabel","kind":"long","required":true},{"key":"reviewDraftHelp","label":"reviewDraftHelp","kind":"long","required":true},{"key":"supportingResources","label":"Toolkit and related resource links","kind":"link-list","required":true,"maxItems":20},{"key":"leadershipLabel","label":"leadership: name","kind":"short","required":true},{"key":"leadershipContext","label":"leadership: work connection","kind":"long","required":true},{"key":"policyLabel","label":"policy: name","kind":"short","required":true},{"key":"policyContext","label":"policy: work connection","kind":"long","required":true},{"key":"serviceLabel","label":"service: name","kind":"short","required":true},{"key":"serviceContext","label":"service: work connection","kind":"long","required":true},{"key":"managementLabel","label":"management: name","kind":"short","required":true},{"key":"managementContext","label":"management: work connection","kind":"long","required":true},{"key":"workforceLabel","label":"workforce: name","kind":"short","required":true},{"key":"workforceContext","label":"workforce: work connection","kind":"long","required":true},{"key":"fiscalLabel","label":"fiscal: name","kind":"short","required":true},{"key":"fiscalContext","label":"fiscal: work connection","kind":"long","required":true},{"key":"dataLabel","label":"data: name","kind":"short","required":true},{"key":"dataContext","label":"data: work connection","kind":"long","required":true},{"key":"engagementLabel","label":"engagement: name","kind":"short","required":true},{"key":"engagementContext","label":"engagement: work connection","kind":"long","required":true},{"key":"communicationLabel","label":"communication: name","kind":"short","required":true},{"key":"communicationContext","label":"communication: work connection","kind":"long","required":true},{"key":"equityLabel","label":"equity: name","kind":"short","required":true},{"key":"equityContext","label":"equity: work connection","kind":"long","required":true}],"protectedFields":[],"requiredReviewDimensions":["language_alignment","factual_currentness","accessibility","scope","placement"],"approvedValues":{"title":"Equity Analysis Toolkit","intro":"Examine how a decision may affect people differently, consider alternatives, and prepare for a conversation about what should happen next.","companionNote":"These five learning stages are a program companion, not the official toolkit sequence. Optional practice does not replace the toolkit, required review, or engagement with affected people.","roleLabel":"Your area of work","roleIntro":"Choose an area to connect the example with your responsibilities. You can explore any area.","noRoleLabel":"Explore without choosing an area","stageNavLabel":"Learning stages","objectivesTitle":"After this stage, you can","scenarioTitle":"Try a fictional example","consequenceTitle":"What this choice brings into view","practiceLabel":"Optional practice","workLabel":"Your actual work","draftTitle":"Your working draft","draftIntro":"Keep your actual work separate from the fictional example. These notes support discussion; they are not an approval or a completed equity review.","draftPrivacy":"Use a general description of the work. Do not enter names, case details, or other confidential information. Keep any copy only in a location permitted for your work.","draftRetention":"Your notes disappear when you leave or reload this page. Print or save your draft before leaving if you want to keep a copy.","backLabel":"Learning and resources","clearLabel":"Clear my draft","clearConfirmLabel":"Clear all draft notes","cancelLabel":"Keep my notes","clearedMessage":"Your draft notes have been cleared.","printLabel":"Print or save my draft","nextLabel":"Next stage","previousLabel":"Previous stage","resourcesTitle":"Toolkit and related resources","resourcesIntro":"Open resources at any time. You do not need to finish a lesson or practice activity.","resourceTitle":"Official policy and related resources","resourceIntro":"The DHS equity policy and toolkit resource are available here without completing the learning stages. Follow DHS instructions for access to internal materials and any required review. This companion does not submit work to DHS or grant approval. DHS requirements should not be treated as requirements for every Minnesota agency.","toolkitLabel":"Open the Equity Analysis Toolkit","briefsLabel":"Explore community briefs","scenarioNote":"All people, records, and events in this example are fictional. The consequences illustrate questions to consider; they are qualitative examples, not predictions of real outcomes.","culturalContext":"Community briefs can help you ask more informed questions. They do not tell you what an individual believes, needs, or prefers. Confirm preferences with the person and involve affected communities in real decisions.","authorityNote":"The people responsible for the decision retain authority. A practice response cannot establish community agreement or replace direct engagement.","decisionTitle":"Describe the decision","decisionIntro":"Start with the decision itself: what is changing, what can still be changed, and who can decide. A clear scope helps people contribute while their input can still matter.","decisionObjectives":["Write a one-sentence description of the decision.","Distinguish fixed conditions from choices still open.","Identify who has decision authority.","Locate the related questions in the official toolkit."],"decisionScenario":"A service team is considering replacing mailed appointment reminders with text messages. Alex Rivera works changing shifts and shares one phone with Elena, who helps manage appointments and prefers written information in Spanish. These are their stated circumstances, not assumptions based on their names. What should the team clarify first?","decisionChoicea":"Choose text messages now and discuss implementation later.","decisionConsequencea":"In this fictional continuation, Elena raises the shared-phone concern after the proposal has been presented as settled. Ask which choices remain open and whether people can still influence them.","decisionChoiceb":"Define the reminder decision, its limits, and who can authorize a change.","decisionConsequenceb":"The team separates the reminder method from rules it has no authority to change. It can now ask people about options that are genuinely open, while confirming applicable requirements with the person responsible.","decisionChoicec":"Keep the existing process without further discussion.","decisionConsequencec":"Another fictional household reports unreliable mail delivery. Keeping the process also has effects worth examining; the team still needs to understand the problem and its authority to respond.","decisionDraftLabel":"The decision and its limits","decisionDraftHelp":"Describe the decision, what can change, and who has authority. Name any requirement that still needs to be confirmed.","peopleTitle":"Consider who may be affected","peopleIntro":"Look for differences in access, benefits, and burdens. Separate what the evidence shows from what you are assuming, and identify whose experience is missing.","peopleObjectives":["Identify people who may experience the decision differently.","Separate evidence from assumptions.","Name an information gap or missing perspective.","Write a respectful question to learn more."],"peopleScenario":"The fictional records show that a text reached Alex's phone. They do not show whether Elena could read it in time. Another household member uses a screen reader, and a different household prefers mail for privacy. What information would you seek?","peopleChoicea":"Treat successful delivery as evidence that the reminder was usable.","peopleConsequencea":"The delivery record answers a narrow question. It cannot establish who read the message, whether it was understandable, or whether using it was private and accessible.","peopleChoiceb":"Ask staff which reminder method most people prefer.","peopleConsequenceb":"Staff describe recurring difficulties, which helps identify questions. Their experience does not establish each person's preferences or replace hearing directly from people using the service.","peopleChoicec":"Combine available records with accessible conversations about preferences and barriers.","peopleConsequencec":"Elena explains when she can access the shared phone. Other people describe different needs. The team has richer information but still checks who could not participate and avoids treating one family as representative of a community.","peopleDraftLabel":"People, evidence, and unanswered questions","peopleDraftHelp":"Note potential differences in experience, the evidence available, and whose perspective you still need. Avoid identifying individual clients.","optionsTitle":"Compare possible approaches","optionsIntro":"Compare workable alternatives, including the current approach. Consider who gains convenience, who takes on additional work, and what could make each approach more accessible.","optionsObjectives":["Describe at least two feasible approaches.","Identify a potential benefit and burden of each.","Explain how an adjustment addresses a specific barrier.","State what remains uncertain before a choice is made."],"optionsScenario":"The team considers three approaches. In the fictional example, Alex wants texts, Elena needs information she can read in Spanish, and another household relies on paper reminders. Choose an approach to examine, not a final answer.","optionsChoicea":"Use text messages as the only reminder method.","optionsConsequencea":"Alex sees a reminder quickly during a break, but Elena cannot access the shared phone when she needs it. The team must examine language, shared-device access, privacy, and alternatives for people who cannot use texts.","optionsChoiceb":"Continue mailing every reminder.","optionsConsequenceb":"A household that prefers paper keeps its familiar method. Another household receives a reminder late. Keeping mail does not resolve all access concerns, and the team needs evidence about those remaining barriers.","optionsChoicec":"Offer a choice of reminder methods and confirm communication preferences.","optionsConsequencec":"Different households can request different methods. Staff then identify the work needed to record, honor, and update those preferences. Choice deserves examination alongside staffing, accessibility, privacy, and applicable requirements; it is not automatically the best answer in every setting.","optionsDraftLabel":"Options and tradeoffs","optionsDraftHelp":"Compare two or more approaches. Include possible benefits, burdens, adjustments, and uncertainties rather than predicting results.","participationTitle":"Plan participation and action","participationIntro":"Identify who should help shape the decision and what would make participation possible. Explain what people can influence and how they will hear what happened to their input.","participationObjectives":["Identify who should help shape the decision.","Propose an accessible way to seek participation.","Assign a responsible person to a proposed action.","Explain how participants will hear what happened to their input."],"participationScenario":"Before recommending a reminder approach, the team wants to hear from service users. Alex cannot attend a daytime meeting. Elena would prefer a conversation in Spanish. Which engagement plan would you examine?","participationChoicea":"Send one English-only online questionnaire.","participationConsequencea":"In the fictional responses, people comfortable with that channel are heard more readily. The team has not established what people excluded by language, disability access, connectivity, or confidence with forms would say.","participationChoiceb":"Ask an advisory group to speak for every household.","participationConsequenceb":"The group contributes useful experience and questions. Its members cannot represent every household's circumstances. The team still needs to identify missing perspectives and accessible ways to hear them.","participationChoicec":"Offer several accessible ways to participate and explain what remains open.","participationConsequencec":"People have more ways to contribute, and the team plans language and disability access with participants. It still needs time, responsible staff, and a clear account of how input affected the decision. This practice cannot supply actual community agreement.","participationDraftLabel":"Participation and next actions","participationDraftHelp":"Identify people to involve, participation supports, decisions they can influence, responsible staff, and how you will report back.","reviewTitle":"Review and revisit","reviewIntro":"Plan how people will examine what happens after a decision. Choose information that can reveal problems, name its limits, and agree on when the decision needs another look.","reviewObjectives":["Identify an observable signal worth reviewing.","Explain what that signal cannot establish.","Name who will review the information.","Specify a condition that would prompt reconsideration."],"reviewScenario":"Suppose the responsible decision-makers authorize a limited change after the required review and engagement. The team now needs a follow-up plan. What would you recommend examining?","reviewChoicea":"Count delivered messages and call the change successful if delivery improves.","reviewConsequencea":"The count helps assess delivery but does not establish comprehension, access, privacy, or fair outcomes. It could miss a problem even when more messages reach their destinations.","reviewChoiceb":"Wait for complaints before scheduling a review.","reviewConsequenceb":"Complaints may reveal an important problem, but some people may not know how or feel able to raise one. Without a planned review, silence could be mistaken for evidence that the approach works for everyone.","reviewChoicec":"Review several signals with responsible staff and affected people at an agreed time.","reviewConsequencec":"The team considers delivery, reported usability, staff workload, and people not reached. It names the limits of each source and agrees what would trigger reconsideration. Those observations support human judgment rather than proving that one change caused an outcome.","reviewDraftLabel":"Review responsibilities and reconsideration","reviewDraftHelp":"Name useful signals, their limits, a review date, responsible people, and a condition that would prompt another discussion.","supportingResources":[{"label":"DHS equity policy","href":"https://mn.gov/dhs/assets/equity-policy_tcm1053-646921.pdf"},{"label":"Equity Analysis Toolkit resource and access details","href":"/library/ext-dhs-equity-toolkit"},{"label":"Minnesota community briefs","href":"/minnesota-communities"},{"label":"Learning for your work","href":"/my-work/explore"}],"leadershipLabel":"Executive and division leadership","leadershipContext":"Consider the decision authority, unresolved tradeoffs, and responsibility for follow-through. Ask what evidence and engagement are needed before a direction is approved.","policyLabel":"Policy and program analysis","policyContext":"Compare the reminder options, distinguish policy requirements from local choices, and describe uncertainty in the recommendation.","serviceLabel":"Eligibility and service delivery","serviceContext":"Consider what a person must do to receive and use a reminder. Record barriers for the responsible decision-maker without assuming authority to change policy.","managementLabel":"Supervision and management","managementContext":"Examine staff capacity, consistent practice, and how staff can raise concerns. Identify the support needed to honor communication preferences.","workforceLabel":"Hiring and workforce development","workforceContext":"Consider the skills, learning time, and support staff need to provide accessible service. Examine whether expectations create unequal access to development opportunities.","fiscalLabel":"Budgets, grants, and contracts","fiscalContext":"Examine implementation costs and work shifted to households or staff. Identify resource questions without inventing cost estimates or assuming the least expensive option is the fairest.","dataLabel":"Data, research, and quality","dataContext":"Distinguish message delivery from usable communication. Examine missing information, the limits of comparisons, and whose experiences the available records cannot show.","engagementLabel":"Community engagement and partnership","engagementContext":"Plan how affected people can influence the reminder decision. Consider language, disability access, timing, trust, and how participants will hear what changed.","communicationLabel":"Communication and accessibility","communicationContext":"Examine whether each reminder is understandable and usable in the needed language and format. Plan appropriate translation, accessibility review, and review with service users.","equityLabel":"Equity practice and organizational change","equityContext":"Connect a specific access barrier with the wider decision process. Identify responsible partners and how engagement and follow-through will remain part of the work."}}]$pac_registry$::jsonb;
  seed jsonb;
  seed_surface_id text;
  seed_scope_id text;
  seed_fields jsonb;
  seed_protected text[];
  seed_reviews text[];
  seed_document jsonb;
  seed_revision_id uuid;
  seed_publish boolean;
  review_dimension text;
  existing_definition pac_dsd.surface_definitions%rowtype;
begin
  for seed in select value from jsonb_array_elements(registry_seed)
  loop
    seed_surface_id := seed ->> 'surfaceId';
    if seed_surface_id <> 'equity-toolkit.home' or seed ->> 'scopePolicy' <> 'inheritable' then
      raise exception 'This migration only registers the inheritable toolkit companion';
    end if;
    seed_publish := seed_surface_id not like 'community-brief.%';
    seed_fields := seed -> 'fieldContract';
    seed_protected := array(
      select value from jsonb_array_elements_text(coalesce(seed -> 'protectedFields', '[]'::jsonb))
    );
    seed_reviews := array(
      select value from jsonb_array_elements_text(seed -> 'requiredReviewDimensions')
    );
    seed_scope_id := case when seed ->> 'scopePolicy' = 'dsd' then 'dsd' else 'one-dhs' end;

    insert into pac_dsd.surface_definitions (
      surface_id, route_pattern, staff_label, scope_policy, schema_version,
      field_contract, protected_fields, required_review_dimensions,
      linked_content_item_id, active, registered_by
    ) values (
      seed_surface_id,
      seed ->> 'routePattern',
      seed ->> 'staffLabel',
      seed ->> 'scopePolicy',
      1,
      seed_fields,
      seed_protected,
      seed_reviews,
      null,
      true,
      'pac-forward-migration-0022'
    )
    on conflict (surface_id) do nothing;

    select * into strict existing_definition
    from pac_dsd.surface_definitions where surface_id = seed_surface_id;
    if existing_definition.route_pattern is distinct from seed ->> 'routePattern'
      or existing_definition.staff_label is distinct from seed ->> 'staffLabel'
      or existing_definition.scope_policy is distinct from seed ->> 'scopePolicy'
      or existing_definition.schema_version <> 1
      or existing_definition.field_contract is distinct from seed_fields
      or existing_definition.protected_fields is distinct from seed_protected
      or existing_definition.required_review_dimensions is distinct from seed_reviews
      or existing_definition.active is distinct from true then
      raise exception 'Existing editable surface % does not match the registered application contract', seed_surface_id
        using errcode = '55000';
    end if;

    seed_document := jsonb_build_object(
      'schemaVersion', 1,
      'surfaceId', seed_surface_id,
      'scope', seed_scope_id,
      'values', seed -> 'approvedValues'
    );
    perform pac_dsd.assert_valid_surface_document(seed_surface_id, seed_scope_id, seed_document);

    select revision.revision_id into seed_revision_id
    from pac_dsd.surface_revisions revision
    where revision.surface_id = seed_surface_id
      and revision.scope_id = seed_scope_id
      and revision.document = seed_document
      and revision.change_note = 'Initial owner-approved wording for governed review.'
    order by revision.revision_number
    limit 1;

    if seed_revision_id is null then
      if exists (
        select 1 from pac_dsd.surface_revisions revision
        where revision.surface_id = seed_surface_id and revision.scope_id = seed_scope_id
      ) then
        raise exception 'Existing editable surface % is missing its approved baseline', seed_surface_id
          using errcode = '55000';
      end if;

      insert into pac_dsd.surface_revisions (
        surface_id, scope_id, revision_number, document, change_note,
        required_review_dimensions, created_by, based_on_revision_id
      ) values (
        seed_surface_id, seed_scope_id, 1, seed_document,
        'Initial owner-approved wording for governed review.', seed_reviews,
        'pac-forward-migration-0022', null
      ) returning revision_id into seed_revision_id;

      foreach review_dimension in array seed_reviews
      loop
        insert into pac_dsd.surface_reviews (
          revision_id, dimension, status, note, reviewer_role, reviewer_id
        ) values (
          seed_revision_id, review_dimension,
          case when seed_publish then 'pass' else 'pending' end,
          case
            when seed_publish then 'Approved baseline wording registered with the application.'
            else 'Review is required before this community wording can be published.'
          end,
          'publishing_approver', 'pac-consultant-workspace-owner'
        );
      end loop;

      if seed_publish then
        insert into pac_dsd.surface_publication_decisions (
          surface_id, scope_id, revision_id, decision, gate_snapshot, reason, decided_by
        ) values (
          seed_surface_id, seed_scope_id, seed_revision_id, 'publish',
          jsonb_build_object(
            'requiredReviewsComplete', true,
            'registeredFieldsChecked', true,
            'staffLanguageChecked', true,
            'plainTextChecked', true,
            'iconsChecked', true,
            'exactApprovedCopyCaptured', true,
            'explicitOwnerApproval', true,
            'seedMigration', '0022_pac_equity_toolkit_surface.sql'
          ),
          'Initial owner-approved staff wording.',
          'pac-forward-migration-0022'
        );

        insert into pac_dsd.surface_change_events (
          surface_id, scope_id, revision_id, publication_decision_id,
          action, detail, actor_id, actor_role
        )
        select seed_surface_id, seed_scope_id, seed_revision_id,
          decision_record.publication_decision_id, 'published',
          jsonb_build_object('initialApprovedCopy', true, 'staffCopyChanged', true),
          'pac-forward-migration-0022', 'migration'
        from pac_dsd.surface_publication_decisions decision_record
        where decision_record.surface_id = seed_surface_id
          and decision_record.scope_id = seed_scope_id
          and decision_record.revision_id = seed_revision_id
          and decision_record.decision = 'publish'
        order by decision_record.publication_decision_id desc
        limit 1;
      else
        insert into pac_dsd.surface_change_events (
          surface_id, scope_id, revision_id, action, detail, actor_id, actor_role
        ) values (
          seed_surface_id, seed_scope_id, seed_revision_id, 'draft_created',
          jsonb_build_object(
            'initialOwnerApprovedIngestion', true,
            'publicationPending', true,
            'representationReviewPending', true,
            'staffPublicationUnchanged', true
          ),
          'pac-forward-migration-0022', 'migration'
        );
      end if;
    elsif seed_publish and not exists (
      select 1 from pac_dsd.surface_publication_decisions decision_record
      where decision_record.surface_id = seed_surface_id
        and decision_record.scope_id = seed_scope_id
        and decision_record.revision_id = seed_revision_id
        and decision_record.decision = 'publish'
    ) then
      raise exception 'Approved editable surface % has no preserved publication decision', seed_surface_id
        using errcode = '55000';
    end if;
  end loop;
end;
$pac_seed$;


-- 0023_pac_surface_review_chronology.sql
-- Preserve append-only review history while ordering decisions within a single
-- publication transaction by the time each review was actually recorded.
-- now() is transaction-stable and could tie pending and accepted reviews.

ALTER TABLE pac_dsd.surface_reviews ALTER COLUMN recorded_at SET DEFAULT clock_timestamp();


-- 0024_pac_historical_author_wording.sql

-- Preserve the Harlem Renaissance writer's name in source material.
-- Only the technical-wording check uses this validation-only copy. The exact,
-- case-sensitive whole name is exempt; other uses of Claude and all other
-- checks remain unchanged. This does not rewrite or publish any content.

create or replace function pac_dsd.assert_plain_page_text(candidate text)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
declare
  trimmed_candidate text;
  parsed_candidate jsonb;
  icon_pattern text;
begin
  if candidate is null or length(btrim(candidate)) = 0 then
    raise exception 'Page wording cannot be blank' using errcode = '22023';
  end if;
  if candidate ~ '(^|[\n\r])[[:space:]]{0,3}(#{1,6}|[-+*]|[0-9]+\.)[[:space:]]+[^[:space:]]'
    or candidate ~ '(^|[\n\r])[[:space:]]{0,3}(```|~~~)'
    or candidate ~ '\*\*[^*\n\r]+\*\*'
    or candidate ~ '`[^`\n\r]+`'
    or candidate ~ '\[[^]\n\r]+\]\([^()\n\r]+\)'
    or candidate ~ '(^|[\n\r])[[:space:]]{0,3}>[[:space:]]+[^[:space:]]'
    or candidate ~ '(^|[\n\r])[[:space:]]{0,3}[0-9]+\)[[:space:]]+[^[:space:]]'
    or candidate ~ '(^|[\n\r])[[:space:]]{0,3}(-{3,}|_{3,}|\*{3,})[[:space:]]*($|[\n\r])'
    or candidate ~ '(^|[\n\r])[[:space:]]*\|[^\n\r]+\|[[:space:]]*($|[\n\r])'
    or candidate ~ '(^|[[:space:](])(\*[^*\n\r]+\*|_[^_\n\r]+_)($|[[:space:]).,;:!?])' then
    raise exception 'Page wording must use plain text' using errcode = '22023';
  end if;

  trimmed_candidate := btrim(candidate);
  if (left(trimmed_candidate, 1) = '{' and right(trimmed_candidate, 1) = '}')
    or (left(trimmed_candidate, 1) = '[' and right(trimmed_candidate, 1) = ']') then
    begin
      parsed_candidate := trimmed_candidate::jsonb;
    exception when invalid_text_representation then
      parsed_candidate := null;
    end;
    if jsonb_typeof(parsed_candidate) in ('object', 'array') then
      raise exception 'Page wording must not contain serialized data' using errcode = '22023';
    end if;
  end if;

  if regexp_replace(candidate, '\mClaude[[:space:]]+McKay\M', 'historical author', 'g') ~* '(\mAI\M|\martificial intelligence\M|\mLLM\M|\mGPT([ -]?[0-9A-Za-z]+)?\M|\mChatGPT\M|\mClaude\M|\mAnthropic\M|\mOpenAI\M|\mGemini\M|\mCopilot\M|\mPerplexity\M|\mVercel\M|\mchatbot\M|\mAI assistant\M|\mdigital twin\M|\mmulti-?agent\M|\morchestrator\M|\mdispatcher\M|\mspecialist agent\M|\mmindset twin\M|\msystem prompt\M|\membeddings?\M|\mvector (search|store)\M|\mRAG\M|\minference\M|\mtemperature\M|\mmodel registry\M|\mprovider (adapter|route)\M|\mautonomy level\M|\magentic\M|\mAPI\M|\mendpoint\M|\m(local|session) storage\M|\mbrowser tab\M|\menvironment variables?\M|\mdeployment\M|\mruntime\M|\mserver-side\M|\mbackend\M|\mfrontend\M|\mserialized\M|\mpayload\M|\mmetadata\M|\mfixture\M|\mdebug(ging)?\M|\mbuild pipeline\M|\mprovenance\M|\mhallucinat(e|ed|ion|ions)\M)' then
    raise exception 'Page wording includes technical product language that is not staff-facing' using errcode = '22023';
  end if;

  icon_pattern := '[' || chr(9728) || '-' || chr(10175)
    || chr(11008) || '-' || chr(11263)
    || chr(126976) || '-' || chr(129791) || ']';
  if candidate ~ icon_pattern then
    raise exception 'Page wording must not contain icons' using errcode = '22023';
  end if;
end;
$$;


-- 0025_pac_page_review_clock.sql
-- Preserve append-only page review history while ordering pending and completed
-- reviews by their actual recording time within a single release transaction.

ALTER TABLE pac_dsd.review_records ALTER COLUMN recorded_at SET DEFAULT clock_timestamp();


-- 0027_pac_owner_release_legacy_archive.sql
-- Owner-only preservation of the exact pre-contract connection-verification
-- record. This is not an application work-object carrier or a staff resource.

CREATE TABLE IF NOT EXISTS pac_dsd.owner_release_legacy_archive (
  archive_key text PRIMARY KEY,
  source_table text NOT NULL,
  original_row jsonb NOT NULL,
  archived_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  archived_by text NOT NULL,
  reason text NOT NULL
);
ALTER TABLE pac_dsd.owner_release_legacy_archive ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pac_dsd.owner_release_legacy_archive FROM PUBLIC,pac_dsd_app_runtime;
DO $$ DECLARE role_name text; BEGIN
  FOREACH role_name IN ARRAY ARRAY['anon','authenticated'] LOOP
    IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=role_name) THEN
      EXECUTE format('revoke all on pac_dsd.owner_release_legacy_archive from %I',role_name);
    END IF;
  END LOOP;
END $$;
COMMENT ON TABLE pac_dsd.owner_release_legacy_archive IS
  'Owner-only recovery archive for the exact named legacy verification record moved out of active runtime persistence during the approved production release.';


-- 0028_pac_runtime_pool_capacity.sql
-- Local session pooling and hosted transaction pooling can each retain up to
-- fifteen backend connections. Keep a bounded allowance for both during a
-- release without changing the runtime role's data or administration rights.

do $$
declare
  available_connections integer;
begin
  available_connections := current_setting('max_connections')::integer
    - current_setting('superuser_reserved_connections')::integer
    - coalesce(nullif(current_setting('reserved_connections', true), ''), '0')::integer;
  if available_connections - 32 < 20 then
    raise exception 'Runtime pooling requires at least twenty connections to remain outside the application allowance.';
  end if;
  if not exists (
    select 1 from pg_roles where rolname = 'pac_dsd_app_runtime'
      and not rolsuper and not rolcreaterole and not rolcreatedb
      and not rolreplication and not rolbypassrls
      and rolconnlimit between 1 and 32
  ) then
    raise exception 'The restricted runtime role does not match the expected bounded configuration.';
  end if;
  alter role pac_dsd_app_runtime connection limit 32;
end $$;


-- 0029_pac_openai_research.sql
-- Admit a second public research service to the existing bounded policy/usage contracts.
-- Preserve every other check, all privileges, and existing records.
do $migration$
declare prior text; revised text;
begin
  select pg_get_functiondef('pac_dsd.assert_runtime_work_object_contract(text,text,jsonb)'::regprocedure) into prior;
  revised := replace(prior, '''perplexity_agent'', ''fixture''', '''perplexity_agent'', ''openai_web'', ''fixture''');
  if revised = prior then raise exception 'Research provider contract anchor was not found'; end if;
  execute revised;
end;
$migration$;


-- 0030_pac_ask_response_records.sql
-- Dedicated owner-observability records; never reuse transcript-free work objects.
-- The trusted server enforces owner authorization for reads and deletion.
create table pac_dsd.ask_response_records (
  record_id uuid primary key,
  created_at timestamptz not null,
  expires_at timestamptz,
  record jsonb not null,
  constraint ask_record_contract check ((
    jsonb_typeof(record) = 'object'
    and octet_length(record::text) <= 1048576
    and record ?& array['id','traceId','createdAt','programScope','researchMode','status','httpStatus','question','questionOmittedReason','response','researchStatus','expiresAt']
    and (record - array['id','traceId','createdAt','programScope','researchMode','status','httpStatus','question','questionOmittedReason','response','researchStatus','expiresAt']) = '{}'::jsonb
    and (record->>'id')::uuid = record_id
    and (record->>'traceId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    and (record->>'createdAt')::timestamptz = created_at
    and ((record->>'expiresAt')::timestamptz is not distinct from expires_at)
    and record->>'programScope' in ('one-dhs','dsd')
    and record->>'researchMode' in ('auto','program_only','web_results','current_web','deep_research')
    and record->>'status' in ('answered','limited','refused','unavailable','failed')
    and record->>'researchStatus' in ('not_requested','used','not_connected','failed')
    and jsonb_typeof(record->'httpStatus') = 'number'
    and (record->>'httpStatus')::integer between 100 and 599
    and (
      (jsonb_typeof(record->'question') = 'string' and length(record->>'question') between 1 and 4000 and record->'questionOmittedReason' = 'null'::jsonb)
      or (record->'question' = 'null'::jsonb and record->>'questionOmittedReason' = 'private_information')
    )
    and jsonb_typeof(record->'response') = 'object'
    and (
      (jsonb_typeof(record->'response'->'error') = 'string' and ((record->'response') - 'error') = '{}'::jsonb)
      or (record->'response'->>'kind' = 'answer' and jsonb_typeof(record->'response'->'answer') = 'object'
        and ((record->'response'->'answer') - array['shortAnswer','whyItMatters','sources','limits','nextActions','questions','conflict','consultation','pathSuggestion','notice','publicResearch']) = '{}'::jsonb
        and (record->'response'->'answer') ?& array['shortAnswer','whyItMatters','sources','limits','nextActions']
        and jsonb_typeof(record->'response'->'answer'->'shortAnswer') = 'string'
        and jsonb_typeof(record->'response'->'answer'->'whyItMatters') = 'string'
        and jsonb_typeof(record->'response'->'answer'->'sources') = 'array'
        and jsonb_typeof(record->'response'->'answer'->'limits') = 'array'
        and jsonb_typeof(record->'response'->'answer'->'nextActions') = 'array'
        and ((record->'response') - array['kind','answer']) = '{}'::jsonb)
      or (record->'response'->>'kind' = 'refusal' and jsonb_typeof(record->'response'->'safety') = 'object'
        and ((record->'response'->'safety') - array['message','redirect','alternatives']) = '{}'::jsonb
        and ((record->'response') - array['kind','safety']) = '{}'::jsonb)
    )
  ) is true)
);
create index ask_response_records_page_idx on pac_dsd.ask_response_records(created_at desc,record_id desc);
create index ask_response_records_expiry_idx on pac_dsd.ask_response_records(expires_at) where expires_at is not null;
alter table pac_dsd.ask_response_records enable row level security;
revoke all on pac_dsd.ask_response_records from public,pac_dsd_app_runtime;

create function pac_dsd.append_ask_response_record(p_record jsonb) returns void
language plpgsql security definer set search_path=pg_catalog,pac_dsd as $$
declare existing jsonb;
begin
  insert into pac_dsd.ask_response_records(record_id,created_at,expires_at,record)
  values ((p_record->>'id')::uuid,(p_record->>'createdAt')::timestamptz,(p_record->>'expiresAt')::timestamptz,p_record)
  on conflict(record_id) do nothing;
  select record into existing from pac_dsd.ask_response_records where record_id=(p_record->>'id')::uuid;
  if existing is distinct from p_record then raise exception 'ASK record is immutable'; end if;
end $$;
create function pac_dsd.list_ask_response_records(p_limit integer,p_before_at timestamptz,p_before_id uuid,p_now timestamptz)
returns table(record jsonb) language plpgsql security definer set search_path=pg_catalog,pac_dsd as $$
begin
  if p_limit is null or p_limit < 1 or p_limit > 101 or p_now is null or ((p_before_at is null) <> (p_before_id is null)) then raise exception 'Invalid record page'; end if;
  return query select r.record from pac_dsd.ask_response_records r
    where (r.expires_at is null or r.expires_at > p_now)
      and (p_before_at is null or (r.created_at,r.record_id) < (p_before_at,p_before_id))
    order by r.created_at desc,r.record_id desc limit p_limit;
end $$;
create function pac_dsd.delete_ask_response_records(p_ids jsonb) returns integer
language plpgsql security definer set search_path=pg_catalog,pac_dsd as $$
declare deleted integer;
begin
  if p_ids is null or jsonb_typeof(p_ids) <> 'array' or jsonb_array_length(p_ids) < 1 or jsonb_array_length(p_ids)>100 then raise exception 'Invalid record selection'; end if;
  delete from pac_dsd.ask_response_records where record_id in (select value::uuid from jsonb_array_elements_text(p_ids));
  get diagnostics deleted=row_count;
  return deleted;
end $$;
create function pac_dsd.purge_expired_ask_response_records(p_now timestamptz) returns integer
language plpgsql security definer set search_path=pg_catalog,pac_dsd as $$
declare deleted integer;
begin
  if p_now is null then raise exception 'Invalid record cleanup time'; end if;
  delete from pac_dsd.ask_response_records where record_id in (
    select record_id from pac_dsd.ask_response_records where expires_at <= p_now order by expires_at limit 1000
  );
  get diagnostics deleted=row_count;
  return deleted;
end $$;
revoke all on function pac_dsd.append_ask_response_record(jsonb) from public;
revoke all on function pac_dsd.list_ask_response_records(integer,timestamptz,uuid,timestamptz) from public;
revoke all on function pac_dsd.delete_ask_response_records(jsonb) from public;
revoke all on function pac_dsd.purge_expired_ask_response_records(timestamptz) from public;
grant execute on function pac_dsd.append_ask_response_record(jsonb) to pac_dsd_app_runtime;
grant execute on function pac_dsd.list_ask_response_records(integer,timestamptz,uuid,timestamptz) to pac_dsd_app_runtime;
grant execute on function pac_dsd.delete_ask_response_records(jsonb) to pac_dsd_app_runtime;
grant execute on function pac_dsd.purge_expired_ask_response_records(timestamptz) to pac_dsd_app_runtime;


-- 0031_pac_owner_approved_surface_saves.sql
-- Owner-authenticated input carries the program owner's standing content approval.
-- Structural validation remains mandatory and is recorded separately from human
-- factual/accessibility review. This migration fabricates no review outcomes.

create table if not exists pac_dsd.surface_owner_approvals (
  revision_id uuid primary key,
  surface_id text not null,
  scope_id text not null check (scope_id in ('one-dhs', 'dsd')),
  document_sha256 text not null check (document_sha256 ~ '^[a-f0-9]{64}$'),
  approval_basis text not null check (approval_basis = 'standing_owner_approval_on_input'),
  approved_by text not null,
  recorded_at timestamptz not null default clock_timestamp(),
  foreign key (revision_id, surface_id, scope_id)
    references pac_dsd.surface_revisions(revision_id, surface_id, scope_id)
);

alter table pac_dsd.surface_owner_approvals enable row level security;
revoke all privileges on pac_dsd.surface_owner_approvals from public, pac_dsd_app_runtime;
drop trigger if exists surface_owner_approvals_append_only on pac_dsd.surface_owner_approvals;
create trigger surface_owner_approvals_append_only
before update or delete on pac_dsd.surface_owner_approvals
for each row execute function pac_dsd.prevent_surface_history_change();

comment on table pac_dsd.surface_owner_approvals is
  'Immutable approval basis for exact wording saved through the authenticated owner application boundary; this is not an independent factual or accessibility review.';

create or replace function pac_dsd.enforce_surface_publication_gate()
returns trigger
language plpgsql
set search_path = pg_catalog, pac_dsd
as $$
declare
  definition pac_dsd.surface_definitions%rowtype;
  revision pac_dsd.surface_revisions%rowtype;
begin
  select * into strict definition from pac_dsd.surface_definitions
  where surface_id = new.surface_id and active = true;
  if new.decision = 'inherit' and definition.scope_policy <> 'inheritable' then
    raise exception 'This page area does not permit inherited wording' using errcode = '42501';
  end if;
  if new.revision_id is not null then
    select * into revision from pac_dsd.surface_revisions where revision_id = new.revision_id;
    if not found or revision.surface_id <> new.surface_id then
      raise exception 'Publishing decision revision does not belong to this page area' using errcode = '22023';
    end if;
    if new.decision = 'publish' and revision.scope_id <> new.scope_id then
      raise exception 'Published wording must belong to the exact program scope' using errcode = '22023';
    end if;
    if new.decision = 'withdraw' and revision.scope_id <> new.scope_id
      and not (definition.scope_policy = 'inheritable' and new.scope_id = 'dsd' and revision.scope_id = 'one-dhs') then
      raise exception 'Withdrawn wording must be visible in the requested program scope' using errcode = '22023';
    end if;
  end if;
  if new.decision = 'publish' then
    perform pac_dsd.assert_valid_surface_document(new.surface_id, new.scope_id, revision.document);
    if exists (
      select 1 from pac_dsd.surface_owner_approvals approval
      where approval.revision_id = revision.revision_id
        and approval.surface_id = new.surface_id and approval.scope_id = new.scope_id
        and approval.document_sha256 = revision.document_sha256
        and approval.approval_basis = 'standing_owner_approval_on_input'
    ) then
      new.gate_snapshot := new.gate_snapshot || jsonb_build_object(
        'approvalBasis', 'standing_owner_approval_on_input',
        'ownerApprovalRevisionId', revision.revision_id,
        'automaticValidation', jsonb_build_object(
          'registeredFields', true, 'scope', true, 'protectedFields', true,
          'plainTextFormat', true, 'safeLinkSyntax', true),
        'independentFactualReviewPerformed', false,
        'independentAccessibilityAuditPerformed', false
      );
    elsif exists (
    select 1 from unnest(revision.required_review_dimensions) required(dimension)
    left join lateral (
      select review.status from pac_dsd.surface_reviews review
      where review.revision_id = revision.revision_id and review.dimension = required.dimension
      order by review.recorded_at desc, review.review_id desc limit 1
    ) current_review on true
    where current_review.status is null or current_review.status not in ('pass', 'not_applicable')
  ) then
    raise exception 'Every required review must be complete before publishing' using errcode = '55000';
    end if;
  end if;
  if length(btrim(new.reason)) = 0 or length(new.reason) > 1000 then
    raise exception 'A brief publishing reason is required' using errcode = '22023';
  end if;
  perform pac_dsd.assert_plain_page_text(new.reason);
  return new;
end;
$$;

create or replace function pac_dsd.save_owner_approved_surface(
  requested_scope_id text,
  requested_surface_id text,
  expected_base_revision_id uuid,
  expected_publication_decision_id bigint,
  requested_document jsonb,
  requested_change_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  definition pac_dsd.surface_definitions%rowtype;
  current_state jsonb;
  current_base_revision_id uuid;
  current_decision_id bigint;
  next_revision_id uuid;
  next_revision_number integer;
  next_decision_id bigint;
  saved_document_hash text;
begin
  perform pac_dsd.assert_surface_request(requested_scope_id, requested_surface_id, true);
  perform pac_dsd.assert_valid_surface_document(requested_surface_id, requested_scope_id, requested_document);
  if requested_change_note is not null and length(btrim(requested_change_note)) > 1000 then
    raise exception 'The change note is too long' using errcode = '22023';
  end if;
  if length(btrim(coalesce(requested_change_note, ''))) > 0 then
    perform pac_dsd.assert_plain_page_text(requested_change_note);
  end if;

  perform pg_advisory_xact_lock(hashtextextended(requested_surface_id || ':' || requested_scope_id, 0));
  select * into strict definition from pac_dsd.surface_definitions
  where surface_id = requested_surface_id and active = true;
  current_state := pac_dsd.read_surface_editing_state(requested_scope_id, requested_surface_id);
  current_base_revision_id := nullif(current_state ->> 'expectedRevisionId', '')::uuid;
  current_decision_id := nullif(current_state #>> '{latestDecision,publicationDecisionId}', '')::bigint;
  if current_base_revision_id is distinct from expected_base_revision_id
    or current_decision_id is distinct from expected_publication_decision_id then
    raise exception 'Page wording or availability changed after it was opened' using errcode = '40001';
  end if;

  select coalesce(max(revision.revision_number), 0) + 1 into next_revision_number
  from pac_dsd.surface_revisions revision
  where revision.surface_id = requested_surface_id and revision.scope_id = requested_scope_id;
  insert into pac_dsd.surface_revisions (
    surface_id, scope_id, revision_number, document, change_note,
    required_review_dimensions, created_by, based_on_revision_id
  ) values (
    requested_surface_id, requested_scope_id, next_revision_number, requested_document,
    coalesce(nullif(btrim(requested_change_note), ''), 'Wording saved by the program owner.'),
    definition.required_review_dimensions, 'pac-consultant-workspace-owner', current_base_revision_id
  ) returning revision_id, document_sha256 into next_revision_id, saved_document_hash;

  insert into pac_dsd.surface_owner_approvals (
    revision_id, surface_id, scope_id, document_sha256, approval_basis, approved_by
  ) values (
    next_revision_id, requested_surface_id, requested_scope_id, saved_document_hash,
    'standing_owner_approval_on_input', 'pac-consultant-workspace-owner'
  );
  insert into pac_dsd.surface_publication_decisions (
    surface_id, scope_id, revision_id, decision, gate_snapshot, reason, decided_by
  ) values (
    requested_surface_id, requested_scope_id, next_revision_id, 'publish',
    jsonb_build_object(
      'ownerApprovedSave', true, 'explicitOwnerDecision', true,
      'replacedScopeDecisionId', current_decision_id,
      'basedOnRevisionId', current_base_revision_id
    ), 'Wording saved with the program owner''s standing approval.', 'pac-consultant-workspace-owner'
  ) returning publication_decision_id into next_decision_id;
  insert into pac_dsd.surface_change_events (
    surface_id, scope_id, revision_id, publication_decision_id, action, detail, actor_id, actor_role
  ) values (
    requested_surface_id, requested_scope_id, next_revision_id, next_decision_id, 'published',
    jsonb_build_object(
      'staffCopyChanged', true, 'ownerApprovedSave', true,
      'approvalBasis', 'standing_owner_approval_on_input',
      'automaticValidationCompleted', true,
      'independentFactualReviewPerformed', false,
      'independentAccessibilityAuditPerformed', false
    ), 'pac-consultant-workspace-owner', 'owner'
  );
  return pac_dsd.read_surface_editing_state(requested_scope_id, requested_surface_id);
end;
$$;

revoke all privileges on function pac_dsd.save_owner_approved_surface(text,text,uuid,bigint,jsonb,text) from public;
grant execute on function pac_dsd.save_owner_approved_surface(text,text,uuid,bigint,jsonb,text) to pac_dsd_app_runtime;
comment on function pac_dsd.save_owner_approved_surface(text,text,uuid,bigint,jsonb,text) is
  'Owner API only: validate and atomically save/publish exact scoped wording using standing owner approval, preserving immutable history and optimistic concurrency.';


-- 0032_pac_owner_approved_page_copy_saves.sql
-- Home/footer owner input carries the owner's standing content approval.
-- Preserve all earlier wording, source objects, drafts, reviews and decisions.
-- No factual review or accessibility audit is invented by this saving path.

create table pac_dsd.page_block_owner_approvals (
  revision_id uuid primary key references pac_dsd.content_revisions(revision_id),
  content_item_id text not null references pac_dsd.content_items(content_item_id),
  scope_id text not null references pac_dsd.program_scopes(scope_id),
  payload_sha256 text not null check(payload_sha256 ~ '^[a-f0-9]{64}$'),
  approval_basis text not null check(approval_basis='standing_owner_approval_on_input'),
  approved_by text not null,
  recorded_at timestamptz not null default clock_timestamp(),
  check(content_item_id in ('page-home','site-footer')),
  check(scope_id in ('one-dhs','dsd'))
);
alter table pac_dsd.page_block_owner_approvals enable row level security;
revoke all privileges on pac_dsd.page_block_owner_approvals from public,pac_dsd_app_runtime;
create trigger page_block_owner_approvals_append_only
before update or delete on pac_dsd.page_block_owner_approvals
for each row execute function pac_dsd.prevent_surface_history_change();
comment on table pac_dsd.page_block_owner_approvals is
  'Immutable owner approval for an exact Home/footer revision; not a factual or accessibility review.';

create function pac_dsd.page_block_has_owner_approval(
  requested_content_item_id text, requested_revision_id uuid, requested_scope_id text default null
) returns boolean language sql stable security definer
set search_path=pg_catalog,pac_dsd set row_security=off as $$
  select exists (
    select 1 from pac_dsd.page_block_owner_approvals approval
    join pac_dsd.content_revisions revision on revision.revision_id=approval.revision_id
      and revision.content_item_id=approval.content_item_id
    join pac_dsd.content_items item on item.content_item_id=approval.content_item_id
    where approval.revision_id=requested_revision_id
      and approval.content_item_id=requested_content_item_id
      and requested_content_item_id in ('page-home','site-footer')
      and approval.scope_id=item.default_scope_id
      and (requested_scope_id is null or approval.scope_id=requested_scope_id)
      and revision.canonical_payload->>'scope'=case when approval.scope_id='dsd' then 'dsd' else 'agencywide' end
      and revision.payload_sha256=approval.payload_sha256
      and approval.approval_basis='standing_owner_approval_on_input'
  );
$$;

create or replace function pac_dsd.page_block_revision_is_staff_exposable(
  requested_content_item_id text,
  requested_revision_id uuid
)
returns boolean
language sql
stable
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
  select exists (
    select 1
    from pac_dsd.content_items item
    join pac_dsd.content_revisions revision
      on revision.content_item_id = item.content_item_id
    where item.content_item_id = requested_content_item_id
      and revision.revision_id = requested_revision_id
      and requested_content_item_id = any(array['page-home', 'site-footer']::text[])
      and item.content_kind = 'internal'
      and item.default_scope_id = 'one-dhs'
      and item.restricted = true
      and item.retired_at is null
      and item.sensitivity_class = 'S1'
      and revision.sensitivity_class = 'S1'
      and revision.ordinary_indexing_allowed = true
      and revision.model_context_allowed = false
      and cardinality(revision.limitations) > 0
      and not exists (
        select 1 from unnest(revision.limitations) limitation(value)
        where nullif(btrim(limitation.value), '') is null
      )
      and revision.canonical_payload ->> 'id' = requested_content_item_id
      and revision.canonical_payload ->> 'status' = 'approved'
      and (
        (revision.canonical_payload ->> 'accessibility' = 'reviewed'
      and cardinality(revision.required_review_dimensions) > 0
      and not exists (
        select 1
        from unnest(revision.required_review_dimensions) required(dimension)
        left join lateral (
          select review.status
          from pac_dsd.review_records review
          where review.revision_id = revision.revision_id
            and review.dimension = required.dimension
          order by review.recorded_at desc, review.review_id desc
          limit 1
        ) current_review on true
        where current_review.status is null
          or current_review.status not in ('pass', 'not_applicable')
      ))
        or (revision.canonical_payload ->> 'accessibility' = 'pending'
          and pac_dsd.page_block_has_owner_approval(requested_content_item_id, requested_revision_id))
      )
      and exists (
        select 1 from pac_dsd.revision_sources source_link
        where source_link.revision_id = revision.revision_id
      )
      and not exists (
        select 1
        from pac_dsd.revision_sources source_link
        left join pac_dsd.source_items source
          on source.source_item_id = source_link.source_item_id
        left join pac_dsd.source_carriers carrier
          on carrier.carrier_id = source.carrier_id
        where source_link.revision_id = revision.revision_id
          and (
            source.source_item_id is null
            or source.carrier_id is null
            or carrier.carrier_id is null
            or carrier.sensitivity_class <> 'S1'
            or source.sensitivity_class <> 'S1'
            or source.deidentification_status not in ('not_needed', 'verified')
            or source.ordinary_indexing_allowed is distinct from true
            or source.model_context_allowed is distinct from false
            or source.owner_approval_status <> 'owner_approved_for_ingestion'
            or source.accounting_status <> 'accounted'
            or source.access_scope <> 'staff_candidate'
          )
      )
      and not exists (
        select 1
        from pac_dsd.revision_assets asset_link
        left join pac_dsd.assets asset on asset.asset_id = asset_link.asset_id
        where asset_link.revision_id = revision.revision_id
          and (
            asset.asset_id is null
            or asset.sensitivity_class not in ('S0', 'S1')
          )
      )
  );
$$;

create or replace function pac_dsd.enforce_publication_gate()
returns trigger
language plpgsql
set search_path = pg_catalog, pac_dsd
as $$
declare
  revision_item_id text;
  required_dimension text;
  latest_status text;
  linked_sources integer;
  unapproved_sources integer;
begin
  select content_item_id into revision_item_id
  from pac_dsd.content_revisions
  where revision_id = new.revision_id;

  if revision_item_id is distinct from new.content_item_id then
    raise exception 'Revision % does not belong to content item %', new.revision_id, new.content_item_id;
  end if;

  if new.decision <> 'publish' then
    return new;
  end if;

  if pac_dsd.page_block_has_owner_approval(new.content_item_id, new.revision_id, new.scope_id) then
    perform pac_dsd.assert_valid_page_block_copy(
      new.content_item_id,
      (select canonical_payload -> 'copy' from pac_dsd.content_revisions where revision_id = new.revision_id)
    );
    if not pac_dsd.page_block_revision_is_staff_exposable(new.content_item_id, new.revision_id) then
      raise exception 'Owner wording does not meet the page publication contract' using errcode = '22023';
    end if;
    new.gate_snapshot := new.gate_snapshot || jsonb_build_object(
      'approvalBasis', 'standing_owner_approval_on_input',
      'ownerApprovalRevisionId', new.revision_id,
      'independentFactualReviewPerformed', false,
      'independentAccessibilityAuditPerformed', false
    );
  else
  for required_dimension in
    select unnest(required_review_dimensions)
    from pac_dsd.content_revisions
    where revision_id = new.revision_id
  loop
    select status into latest_status
    from pac_dsd.current_revision_reviews
    where revision_id = new.revision_id and dimension = required_dimension;

    if latest_status is null or latest_status not in ('pass', 'not_applicable') then
      raise exception 'Revision % cannot publish: % review is %',
        new.revision_id, required_dimension, coalesce(latest_status, 'missing');
    end if;
  end loop;

  end if;

  select count(*) into linked_sources
  from pac_dsd.revision_sources
  where revision_id = new.revision_id;

  if linked_sources = 0 then
    raise exception 'Revision % cannot publish: no accounted source is linked', new.revision_id;
  end if;

  select count(*) into unapproved_sources
  from pac_dsd.revision_sources rs
  join pac_dsd.source_items si on si.source_item_id = rs.source_item_id
  where rs.revision_id = new.revision_id
    and (
      si.owner_approval_status <> 'owner_approved_for_ingestion'
      or si.accounting_status <> 'accounted'
    );

  if unapproved_sources > 0 then
    raise exception 'Revision % cannot publish: a linked source is missing or not approved for ingestion', new.revision_id;
  end if;

  return new;
end;
$$;


create function pac_dsd.save_owner_approved_page_block(
  requested_scope_id text,
  requested_content_item_id text,
  expected_base_revision_id uuid,
  expected_publication_decision_id bigint,
  requested_copy jsonb,
  requested_change_note text default null
) returns jsonb language plpgsql security definer
set search_path=pg_catalog,pac_dsd set row_security=off as $$
declare
  current_state jsonb;
  current_revision_id uuid;
  current_decision_id bigint;
  release_revision_id uuid := gen_random_uuid();
  release_revision_number integer;
  release_payload jsonb;
  release_hash text;
  release_carrier_id uuid;
  release_source_id text;
  release_source_payload jsonb;
  new_decision_id bigint;
begin
  perform pac_dsd.assert_page_block_mutation_allowed(requested_scope_id,requested_content_item_id);
  perform pac_dsd.assert_valid_page_block_copy(requested_content_item_id,requested_copy);
  if requested_change_note is not null and length(btrim(requested_change_note))>1000 then
    raise exception 'The change note is too long' using errcode='22023';
  end if;
  if length(btrim(coalesce(requested_change_note,'')))>0 then
    perform pac_dsd.assert_plain_page_text(requested_change_note);
  end if;

  -- Share the same row lock as draft, publication, restore and withdrawal.
  perform 1 from pac_dsd.content_items item
    where item.content_item_id=requested_content_item_id and item.sensitivity_class='S1'
    for update;
  if not found then raise exception 'This page area is not available' using errcode='P0002'; end if;
  current_state := pac_dsd.read_page_block_editing_state(requested_scope_id,requested_content_item_id);
  if current_state is null then raise exception 'This page area is not available' using errcode='P0002'; end if;
  current_revision_id := (current_state->>'expectedRevisionId')::uuid;
  current_decision_id := (current_state->>'publicationDecisionId')::bigint;
  if current_revision_id is distinct from expected_base_revision_id
    or current_decision_id is distinct from expected_publication_decision_id then
    raise exception 'Page wording or availability changed after it was opened' using errcode='40001';
  end if;

  select coalesce(max(revision_number),0)+1 into release_revision_number
    from pac_dsd.content_revisions where content_item_id=requested_content_item_id;
  release_payload := jsonb_build_object(
    'id',requested_content_item_id,
    'blockType',case when requested_content_item_id='page-home' then 'home' else 'footer' end,
    'status','approved','accessibility','pending',
    'scope',case when requested_scope_id='dsd' then 'dsd' else 'agencywide' end,
    'version',release_revision_number::text,'copy',requested_copy
  );
  release_source_id := 'page-owner-save-' || release_revision_id::text;
  release_source_payload := jsonb_build_object(
    'kind','owner_approved_page_copy','contentItemId',requested_content_item_id,
    'scopeId',requested_scope_id,'releaseRevisionId',release_revision_id,'copy',requested_copy
  );
  insert into pac_dsd.source_carriers(
    logical_key,media_type,original_name,byte_count,raw_blob_sha256,
    external_locator,captured_by,sensitivity_class
  ) values(
    'page-owner-save:' || release_revision_id::text,'application/json',requested_content_item_id || '-owner-save.json',
    octet_length(convert_to(release_source_payload::text,'UTF8')),
    encode(pac_dsd.digest(convert_to(release_source_payload::text,'UTF8'),'sha256'),'hex'),
    jsonb_build_object('kind','owner_approved_page_copy','revisionId',release_revision_id),
    'pac-consultant-workspace-owner','S1'
  ) returning carrier_id into release_carrier_id;
  insert into pac_dsd.source_items(
    source_item_id,source_business_id,carrier_id,source_version,source_pointer,title,
    normalized_payload,normalized_item_sha256,hash_algorithm,hash_algorithm_version,
    owner_approval_status,accounting_status,access_scope,sensitivity_class,
    deidentification_status,ordinary_indexing_allowed,model_context_allowed
  ) values(
    release_source_id,release_source_id,release_carrier_id,'1','owner-save/' || release_revision_id::text,
    case when requested_content_item_id='page-home' then 'Owner-approved Home wording' else 'Owner-approved footer wording' end,
    release_source_payload,encode(pac_dsd.digest(convert_to(release_source_payload::text,'UTF8'),'sha256'),'hex'),
    'sha256','1','owner_approved_for_ingestion','accounted','staff_candidate','S1','not_needed',true,false
  );
  insert into pac_dsd.content_revisions(
    revision_id,content_item_id,revision_number,canonical_payload,change_summary,
    required_review_dimensions,created_by,based_on_revision_id,sensitivity_class,
    ordinary_indexing_allowed,model_context_allowed,limitations
  ) values(
    release_revision_id,requested_content_item_id,release_revision_number,release_payload,
    coalesce(nullif(btrim(requested_change_note),''),'Wording saved by the program owner.'),
    array['language_alignment','factual_currentness','accessibility','scope','placement']::text[],
    'pac-consultant-workspace-owner',current_revision_id,'S1',true,false,
    array['Owner-approved page wording. An independent factual review and accessibility audit were not performed for this revision.']::text[]
  ) returning payload_sha256 into release_hash;
  insert into pac_dsd.revision_sources(revision_id,source_item_id,relationship,note)
    values(release_revision_id,release_source_id,'primary','Exact wording supplied through the authenticated owner editor.');
  insert into pac_dsd.revision_assets(revision_id,asset_id,purpose,staff_label,sort_order)
    select release_revision_id,asset_id,purpose,staff_label,sort_order
    from pac_dsd.revision_assets where revision_id=current_revision_id;
  insert into pac_dsd.page_block_owner_approvals(
    revision_id,content_item_id,scope_id,payload_sha256,approval_basis,approved_by
  ) values(
    release_revision_id,requested_content_item_id,requested_scope_id,release_hash,
    'standing_owner_approval_on_input','pac-consultant-workspace-owner'
  );
  if not pac_dsd.page_block_revision_is_staff_exposable(requested_content_item_id,release_revision_id) then
    raise exception 'The wording or a linked asset does not meet the page publication contract' using errcode='22023';
  end if;
  insert into pac_dsd.publication_decisions(
    content_item_id,revision_id,scope_id,decision,gate_snapshot,decided_by,reason,
    sensitivity_class,unauthenticated_exposure_permitted,exposure_reason
  ) values(
    requested_content_item_id,release_revision_id,requested_scope_id,'publish',
    jsonb_build_object(
      'ownerApprovedSave',true,'approvalBasis','standing_owner_approval_on_input',
      'basedOnRevisionId',current_revision_id,'replacedScopeDecisionId',current_decision_id,
      'linkedSourceItemId',release_source_id,'exactReleaseCopyCaptured',true,
      'automaticValidation',jsonb_build_object('registeredFields',true,'scope',true,'plainTextFormat',true,'safeLinkSyntax',true),
      'independentFactualReviewPerformed',false,'independentAccessibilityAuditPerformed',false
    ),
    'pac-consultant-workspace-owner','Wording saved with the program owner''s standing approval.',
    'S1',true,'Owner-approved page wording for ordinary staff access.'
  ) returning publication_decision_id into new_decision_id;
  insert into pac_dsd.change_events(actor_id,actor_role,scope_id,object_type,object_id,action,detail)
    values('pac-consultant-workspace-owner','owner',requested_scope_id,'page_block',requested_content_item_id,'published',
      jsonb_build_object(
        'ownerApprovedSave',true,'approvalBasis','standing_owner_approval_on_input',
        'basedOnRevisionId',current_revision_id,'releaseRevisionId',release_revision_id,
        'publicationDecisionId',new_decision_id,'automaticValidationCompleted',true,
        'independentFactualReviewPerformed',false,'independentAccessibilityAuditPerformed',false
      ));
  return pac_dsd.read_page_block_editing_state(requested_scope_id,requested_content_item_id);
end;
$$;
revoke all privileges on function pac_dsd.page_block_has_owner_approval(text,uuid,text) from public,pac_dsd_app_runtime;
revoke all privileges on function pac_dsd.save_owner_approved_page_block(text,text,uuid,bigint,jsonb,text) from public;
grant execute on function pac_dsd.save_owner_approved_page_block(text,text,uuid,bigint,jsonb,text) to pac_dsd_app_runtime;
comment on function pac_dsd.save_owner_approved_page_block(text,text,uuid,bigint,jsonb,text) is
  'Owner API only: atomically save and publish the exact Home/footer revision, with standing owner approval and no invented review results.';
-- A withdrawn block has no current revision; its history still needs a boolean.
do $page_history$
declare definition text; corrected text;
begin
  select pg_get_functiondef('pac_dsd.read_page_block_editing_state(text,text)'::regprocedure) into definition;
  corrected := replace(definition,
    '''isCurrent'', revision.revision_id = published_revision_id',
    '''isCurrent'', coalesce(revision.revision_id = published_revision_id, false)');
  if corrected = definition then raise exception 'Page history boolean anchor was not found'; end if;
  execute corrected;
end;
$page_history$;


-- 0033_pac_owner_approved_domain_resources.sql
-- Exact restoration of the owner's approved domain-resource originals.
-- Original candidate/source rows remain immutable and restricted. No new review is invented.

create table pac_dsd.resource_owner_approvals (
  revision_id uuid primary key references pac_dsd.content_revisions(revision_id),
  content_item_id text not null references pac_dsd.content_items(content_item_id),
  scope_id text not null references pac_dsd.program_scopes(scope_id) check(scope_id='one-dhs'),
  payload_sha256 text not null check(payload_sha256 ~ '^[a-f0-9]{64}$'),
  original_revision_id uuid not null references pac_dsd.content_revisions(revision_id),
  original_source_id text not null references pac_dsd.source_items(source_item_id),
  approval_basis text not null check(approval_basis='standing_owner_approval_on_input'),
  approved_by text not null,
  recorded_at timestamptz not null default clock_timestamp()
);
alter table pac_dsd.resource_owner_approvals enable row level security;
revoke all on pac_dsd.resource_owner_approvals from public,pac_dsd_app_runtime;
create trigger resource_owner_approvals_append_only before update or delete on pac_dsd.resource_owner_approvals
for each row execute function pac_dsd.prevent_immutable_change();
create function pac_dsd.resource_revision_has_owner_approval(item_id text, version_id uuid, requested_scope text)
returns boolean language sql stable security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
 select exists(select 1 from pac_dsd.resource_owner_approvals a
 join pac_dsd.content_revisions r on r.revision_id=a.revision_id and r.content_item_id=a.content_item_id
 join pac_dsd.content_revisions original on original.revision_id=a.original_revision_id and original.content_item_id=a.content_item_id
 join pac_dsd.source_items source on source.source_item_id=a.original_source_id
 where a.content_item_id=item_id and a.revision_id=version_id and a.scope_id=requested_scope
 and a.payload_sha256=r.payload_sha256 and a.approval_basis='standing_owner_approval_on_input'
 and r.canonical_payload=original.canonical_payload#>'{richOriginal,contentItem}'
 and r.canonical_payload=source.normalized_payload#>'{richOriginal,contentItem}'
 and original.canonical_payload->>'assetKind'='domain_resource'
 and original.canonical_payload#>>'{donor,commit}'='5680911e68dcf07414de5f003b18ac8e813a8cb1'
 and r.canonical_payload->>'status'='approved' and r.canonical_payload->>'scope'='agencywide');
$$;
revoke all on function pac_dsd.resource_revision_has_owner_approval(text,uuid,text) from public,pac_dsd_app_runtime;

create or replace function pac_dsd.enforce_publication_gate()
returns trigger
language plpgsql
set search_path = pg_catalog, pac_dsd
as $$
declare
  revision_item_id text;
  required_dimension text;
  latest_status text;
  linked_sources integer;
  unapproved_sources integer;
begin
  select content_item_id into revision_item_id
  from pac_dsd.content_revisions
  where revision_id = new.revision_id;

  if revision_item_id is distinct from new.content_item_id then
    raise exception 'Revision % does not belong to content item %', new.revision_id, new.content_item_id;
  end if;

  if new.decision <> 'publish' then
    return new;
  end if;

  if pac_dsd.page_block_has_owner_approval(new.content_item_id, new.revision_id, new.scope_id) then
    perform pac_dsd.assert_valid_page_block_copy(
      new.content_item_id,
      (select canonical_payload -> 'copy' from pac_dsd.content_revisions where revision_id = new.revision_id)
    );
    if not pac_dsd.page_block_revision_is_staff_exposable(new.content_item_id, new.revision_id) then
      raise exception 'Owner wording does not meet the page publication contract' using errcode = '22023';
    end if;
    new.gate_snapshot := new.gate_snapshot || jsonb_build_object(
      'approvalBasis', 'standing_owner_approval_on_input',
      'ownerApprovalRevisionId', new.revision_id,
      'independentFactualReviewPerformed', false,
      'independentAccessibilityAuditPerformed', false
    );
  elsif pac_dsd.resource_revision_has_owner_approval(new.content_item_id,new.revision_id,new.scope_id) then
    perform pac_dsd.assert_resource_staff_release(new.revision_id);
    new.gate_snapshot := new.gate_snapshot || jsonb_build_object(
      'approvalBasis','standing_owner_approval_on_input',
      'ownerApprovalRevisionId',new.revision_id,
      'exactOriginalContentPreserved',true,
      'independentFactualReviewPerformed',false,
      'independentAccessibilityAuditPerformed',false);
  else
  for required_dimension in
    select unnest(required_review_dimensions)
    from pac_dsd.content_revisions
    where revision_id = new.revision_id
  loop
    select status into latest_status
    from pac_dsd.current_revision_reviews
    where revision_id = new.revision_id and dimension = required_dimension;

    if latest_status is null or latest_status not in ('pass', 'not_applicable') then
      raise exception 'Revision % cannot publish: % review is %',
        new.revision_id, required_dimension, coalesce(latest_status, 'missing');
    end if;
  end loop;

  end if;

  select count(*) into linked_sources
  from pac_dsd.revision_sources
  where revision_id = new.revision_id;

  if linked_sources = 0 then
    raise exception 'Revision % cannot publish: no accounted source is linked', new.revision_id;
  end if;

  select count(*) into unapproved_sources
  from pac_dsd.revision_sources rs
  join pac_dsd.source_items si on si.source_item_id = rs.source_item_id
  where rs.revision_id = new.revision_id
    and (
      si.owner_approval_status <> 'owner_approved_for_ingestion'
      or si.accounting_status <> 'accounted'
    );

  if unapproved_sources > 0 then
    raise exception 'Revision % cannot publish: a linked source is missing or not approved for ingestion', new.revision_id;
  end if;

  return new;
end;
$$;

-- Setup-only recovery function. Staff and ordinary runtime requests cannot create
-- source projections or claim that a recovered item is approved.
create function pac_dsd.release_owner_approved_domain_resource(
  requested_item_id text, expected_original_revision_id uuid, expected_original_hash text
) returns jsonb language plpgsql security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
declare
 original pac_dsd.content_revisions%rowtype;
 original_source pac_dsd.source_items%rowtype;
 item pac_dsd.content_items%rowtype;
 prior pac_dsd.publication_decisions%rowtype;
 payload jsonb;
 release_id uuid := gen_random_uuid();
 release_number integer;
 release_hash text;
 source_id text;
 carrier_id uuid;
 decision_id bigint;
begin
 select * into item from pac_dsd.content_items where content_item_id=requested_item_id for update;
 if item.content_kind is distinct from 'resource' or item.default_scope_id is distinct from 'one-dhs' or item.retired_at is not null then
  raise exception 'An intact agencywide domain resource is required' using errcode='22023';
 end if;
 select * into original from pac_dsd.content_revisions where revision_id=expected_original_revision_id and content_item_id=requested_item_id;
 if original.revision_id is null or original.payload_sha256 is distinct from expected_original_hash then
  raise exception 'The recovered original changed' using errcode='40001';
 end if;
 if original.canonical_payload->>'assetKind' is distinct from 'domain_resource'
  or original.canonical_payload->>'sourceClass' is distinct from 'authored'
  or original.canonical_payload#>>'{donor,commit}' is distinct from '5680911e68dcf07414de5f003b18ac8e813a8cb1'
  or original.canonical_payload#>>'{richOriginal,releaseRecord,status}' is distinct from 'approved_static' then
  raise exception 'Only the pinned owner-approved domain originals may use this release' using errcode='22023';
 end if;
 payload := original.canonical_payload#>'{richOriginal,contentItem}';
 if payload->>'id' is distinct from requested_item_id or payload->>'scope' is distinct from 'agencywide'
  or payload->>'status' is distinct from 'approved' or payload->>'accessibility' is distinct from 'pending' then
  raise exception 'The original resource contract is incomplete' using errcode='22023';
 end if;
 select s.* into original_source from pac_dsd.source_items s join pac_dsd.revision_sources rs using(source_item_id)
 where rs.revision_id=original.revision_id and s.normalized_payload#>'{richOriginal,contentItem}'=payload
 and s.owner_approval_status='owner_approved_for_ingestion' and s.accounting_status='accounted'
 order by s.source_item_id limit 1;
 if original_source.source_item_id is null then raise exception 'The accounted original source is missing' using errcode='22023'; end if;
 select * into prior from pac_dsd.publication_decisions where content_item_id=requested_item_id and scope_id='one-dhs' order by publication_decision_id desc limit 1;
 if prior.publication_decision_id is not null then
  if prior.decision='publish' and pac_dsd.resource_revision_has_owner_approval(requested_item_id,prior.revision_id,'one-dhs') then
   return jsonb_build_object('contentItemId',requested_item_id,'revisionId',prior.revision_id,'publicationDecisionId',prior.publication_decision_id,'replayed',true);
  end if;
  raise exception 'Preserve the existing owner publication or withdrawal decision' using errcode='40001';
 end if;
 if exists(select 1 from pac_dsd.content_revisions r where r.content_item_id=requested_item_id and r.revision_number>original.revision_number) then
  raise exception 'Preserve the existing newer resource revision' using errcode='40001';
 end if;
 release_hash := encode(sha256(convert_to(payload::text,'UTF8')),'hex');
 source_id := 'owner-domain-release:'||requested_item_id||':'||release_hash;
 insert into pac_dsd.source_carriers(logical_key,media_type,original_name,byte_count,raw_blob_sha256,external_locator,captured_by,sensitivity_class)
 values(source_id,'application/json',requested_item_id||'.json',octet_length(convert_to(payload::text,'UTF8')),release_hash,
