create or replace function pac_dsd.assert_valid_surface_document(
  requested_surface_id text,
  requested_scope_id text,
  requested_document jsonb
)
returns void
language plpgsql
stable
set search_path = pg_catalog, pac_dsd
as $$
declare
  definition pac_dsd.surface_definitions%rowtype;
  field_definition jsonb;
  field_key text;
  field_kind text;
  field_required boolean;
  field_maximum integer;
  item_maximum integer;
  field_value jsonb;
  text_value text;
  list_item jsonb;
  block_item jsonb;
  link_item jsonb;
  block_type text;
  expected_keys text[];
begin
  perform pac_dsd.assert_surface_request(requested_scope_id, requested_surface_id, true);
  select * into strict definition
  from pac_dsd.surface_definitions
  where surface_id = requested_surface_id and active = true;

  if requested_document is null or jsonb_typeof(requested_document) <> 'object'
    or octet_length(convert_to(requested_document::text, 'UTF8')) > 1000000 then
    raise exception 'Page wording must be a complete, reasonably sized document' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_object_keys(requested_document) actual(name)
    where actual.name <> all(array['schemaVersion', 'surfaceId', 'scope', 'values']::text[])
  ) or not requested_document ?& array['schemaVersion', 'surfaceId', 'scope', 'values']::text[] then
    raise exception 'Page wording document fields are not allowed' using errcode = '22023';
  end if;
  if jsonb_typeof(requested_document -> 'schemaVersion') <> 'number'
    or (requested_document ->> 'schemaVersion')::integer <> definition.schema_version
    or requested_document ->> 'surfaceId' <> requested_surface_id
    or requested_document ->> 'scope' <> requested_scope_id
    or jsonb_typeof(requested_document -> 'values') <> 'object' then
    raise exception 'Page wording document identity does not match this page area' using errcode = '22023';
  end if;

  select array_agg(field ->> 'key' order by ordinal)
  into expected_keys
  from jsonb_array_elements(definition.field_contract) with ordinality registered(field, ordinal);
  if expected_keys is null
    or not (requested_document -> 'values') ?& expected_keys
    or exists (
      select 1 from jsonb_object_keys(requested_document -> 'values') actual(name)
      where actual.name <> all(expected_keys)
    ) then
    raise exception 'Page wording fields do not match this page area' using errcode = '22023';
  end if;

  for field_definition in select value from jsonb_array_elements(definition.field_contract)
  loop
    field_key := field_definition ->> 'key';
    field_kind := field_definition ->> 'kind';
    field_required := coalesce((field_definition ->> 'required')::boolean, true);
    field_maximum := coalesce((field_definition ->> 'maxLength')::integer,
      case when field_kind = 'short' then 500 when field_kind = 'url' then 2000 else 10000 end);
    item_maximum := coalesce((field_definition ->> 'maxItems')::integer, 100);
    field_value := requested_document -> 'values' -> field_key;

    if field_kind = 'course-pack' then
      if requested_surface_id not like 'course.%' or field_value#>>'{course,id}' <> substring(requested_surface_id from 8) then
        raise exception 'Course identity does not match the publication' using errcode='22023';
      end if;
      perform pac_dsd.assert_course_schema(field_value, pac_dsd.course_pack_schema());
      if (select count(*) from jsonb_array_elements(field_value#>'{course,lessons}')) <>
         (select count(distinct lesson->>'id') from jsonb_array_elements(field_value#>'{course,lessons}') lesson) then
        raise exception 'Course lesson identifiers must be unique' using errcode='22023';
      end if;
      for block_item in select block from jsonb_array_elements(field_value#>'{course,lessons}') lesson cross join lateral jsonb_array_elements(lesson->'blocks') block loop
        if block_item->>'type'='knowledgeCheck' and not exists(select 1 from jsonb_array_elements(block_item->'options') option where option->'correct'='true'::jsonb) then
          raise exception 'Course knowledge check requires a correct answer' using errcode='22023';
        end if;
        if block_item->>'type'='sorting' and exists(select 1 from jsonb_array_elements(block_item->'items') item where not (block_item->'categories') @> jsonb_build_array(item->>'category')) then
          raise exception 'Course sorting category is not available' using errcode='22023';
        end if;
      end loop;
      continue;
    end if;

    if field_kind in ('short', 'long', 'url') then
      if jsonb_typeof(field_value) <> 'string' then
        raise exception 'A page wording field has the wrong kind of value' using errcode = '22023';
      end if;
      text_value := field_value #>> '{}';
      if length(text_value) > field_maximum or (field_required and length(btrim(text_value)) = 0) then
        raise exception 'A page wording field is blank or too long' using errcode = '22023';
      end if;
      if length(btrim(text_value)) > 0 then
        if field_kind = 'url' then
          perform pac_dsd.assert_safe_page_link(text_value);
        else
          perform pac_dsd.assert_plain_page_text(text_value);
        end if;
      end if;
      continue;
    end if;

    if jsonb_typeof(field_value) <> 'array'
      or jsonb_array_length(field_value) > item_maximum
      or (field_required and jsonb_array_length(field_value) = 0) then
      raise exception 'A page wording list is empty, too long, or has the wrong kind of value' using errcode = '22023';
    end if;

    if field_kind = 'string-list' then
      for list_item in select value from jsonb_array_elements(field_value)
      loop
        if jsonb_typeof(list_item) <> 'string' then
          raise exception 'A page wording list must contain text' using errcode = '22023';
        end if;
        text_value := list_item #>> '{}';
        if length(btrim(text_value)) = 0 or length(text_value) > field_maximum then
          raise exception 'A page wording list item is blank or too long' using errcode = '22023';
        end if;
        perform pac_dsd.assert_plain_page_text(text_value);
      end loop;
    elsif field_kind = 'link-list' then
      for link_item in select value from jsonb_array_elements(field_value)
      loop
        if jsonb_typeof(link_item) <> 'object'
          or not link_item ?& array['label', 'href']::text[]
          or exists (
            select 1 from jsonb_object_keys(link_item) actual(name)
            where actual.name <> all(array['label', 'href']::text[])
          ) or jsonb_typeof(link_item -> 'label') <> 'string'
          or jsonb_typeof(link_item -> 'href') <> 'string' then
          raise exception 'A page wording link has fields that are not allowed' using errcode = '22023';
        end if;
        text_value := link_item ->> 'label';
        if length(btrim(text_value)) = 0 or length(text_value) > field_maximum then
          raise exception 'A page wording link label is blank or too long' using errcode = '22023';
        end if;
        perform pac_dsd.assert_plain_page_text(text_value);
        perform pac_dsd.assert_safe_page_link(link_item ->> 'href');
      end loop;
    elsif field_kind = 'rich-blocks' then
      for block_item in select value from jsonb_array_elements(field_value)
      loop
        if jsonb_typeof(block_item) <> 'object' or jsonb_typeof(block_item -> 'type') <> 'string' then
          raise exception 'A structured page section has fields that are not allowed' using errcode = '22023';
        end if;
        block_type := block_item ->> 'type';
        if block_type = 'heading' then
          if not block_item ?& array['type', 'level', 'text']::text[]
            or exists (
              select 1 from jsonb_object_keys(block_item) actual(name)
              where actual.name <> all(array['type', 'level', 'text']::text[])
            ) or jsonb_typeof(block_item -> 'level') <> 'number'
            or (block_item ->> 'level')::integer not in (2, 3)
            or jsonb_typeof(block_item -> 'text') <> 'string' then
            raise exception 'A structured heading has fields that are not allowed' using errcode = '22023';
          end if;
          text_value := block_item ->> 'text';
          if length(btrim(text_value)) = 0 or length(text_value) > field_maximum then
            raise exception 'A structured heading is blank or too long' using errcode = '22023';
          end if;
          perform pac_dsd.assert_plain_page_text(text_value);
        elsif block_type = 'paragraph' then
          if not block_item ?& array['type', 'text']::text[]
            or exists (
              select 1 from jsonb_object_keys(block_item) actual(name)
              where actual.name <> all(array['type', 'text']::text[])
            ) or jsonb_typeof(block_item -> 'text') <> 'string' then
            raise exception 'A structured paragraph has fields that are not allowed' using errcode = '22023';
          end if;
          text_value := block_item ->> 'text';
          if length(btrim(text_value)) = 0 or length(text_value) > field_maximum then
            raise exception 'A structured paragraph is blank or too long' using errcode = '22023';
          end if;
          perform pac_dsd.assert_plain_page_text(text_value);
        elsif block_type in ('bullet-list', 'numbered-list') then
          if not block_item ?& array['type', 'items']::text[]
            or exists (
              select 1 from jsonb_object_keys(block_item) actual(name)
              where actual.name <> all(array['type', 'items']::text[])
            ) or jsonb_typeof(block_item -> 'items') <> 'array'
            or jsonb_array_length(block_item -> 'items') not between 1 and item_maximum then
            raise exception 'A structured list has fields that are not allowed' using errcode = '22023';
          end if;
          for list_item in select value from jsonb_array_elements(block_item -> 'items')
          loop
            if jsonb_typeof(list_item) <> 'string' then
              raise exception 'A structured list must contain text' using errcode = '22023';
            end if;
            text_value := list_item #>> '{}';
            if length(btrim(text_value)) = 0 or length(text_value) > field_maximum then
              raise exception 'A structured list item is blank or too long' using errcode = '22023';
            end if;
            perform pac_dsd.assert_plain_page_text(text_value);
          end loop;
        elsif block_type = 'link-list' then
          if not block_item ?& array['type', 'items']::text[]
            or exists (
              select 1 from jsonb_object_keys(block_item) actual(name)
              where actual.name <> all(array['type', 'items']::text[])
            ) or jsonb_typeof(block_item -> 'items') <> 'array'
            or jsonb_array_length(block_item -> 'items') not between 1 and item_maximum then
            raise exception 'A structured link list has fields that are not allowed' using errcode = '22023';
          end if;
          for link_item in select value from jsonb_array_elements(block_item -> 'items')
          loop
            if jsonb_typeof(link_item) <> 'object'
              or not link_item ?& array['label', 'href']::text[]
              or exists (
                select 1 from jsonb_object_keys(link_item) actual(name)
                where actual.name <> all(array['label', 'href']::text[])
              ) or jsonb_typeof(link_item -> 'label') <> 'string'
              or jsonb_typeof(link_item -> 'href') <> 'string' then
              raise exception 'A structured link has fields that are not allowed' using errcode = '22023';
            end if;
            text_value := link_item ->> 'label';
            if length(btrim(text_value)) = 0 or length(text_value) > field_maximum then
              raise exception 'A structured link label is blank or too long' using errcode = '22023';
            end if;
            perform pac_dsd.assert_plain_page_text(text_value);
            perform pac_dsd.assert_safe_page_link(link_item ->> 'href');
          end loop;
        else
          raise exception 'A structured page section is not allowed' using errcode = '22023';
        end if;
      end loop;
    else
      raise exception 'A registered page wording field kind is not supported' using errcode = '22023';
    end if;
  end loop;
end;
$$;
create or replace function pac_dsd.enforce_surface_definition_contract()
returns trigger
language plpgsql
set search_path = pg_catalog, pac_dsd
as $$
declare
  field_definition jsonb;
  field_key text;
  field_kind text;
  keys text[] := '{}'::text[];
  protected_key text;
begin
  if new.route_pattern <> '*' and new.route_pattern !~ '^/[^[:space:][:cntrl:]<>"\\]*$' then
    raise exception 'Registered page route is not safe' using errcode = '22023';
  end if;
  perform pac_dsd.assert_plain_page_text(new.staff_label);
  if cardinality(new.required_review_dimensions) <>
    (select count(distinct dimension) from unnest(new.required_review_dimensions) dimension) then
    raise exception 'Registered reviews must be unique' using errcode = '22023';
  end if;

  for field_definition in select value from jsonb_array_elements(new.field_contract)
  loop
    if jsonb_typeof(field_definition) <> 'object'
      or not field_definition ?& array['key', 'label', 'kind']::text[]
      or exists (
        select 1 from jsonb_object_keys(field_definition) actual(name)
        where actual.name <> all(array[
          'key', 'label', 'kind', 'required', 'maxLength', 'maxItems', 'group', 'helpText'
        ]::text[])
      ) then
      raise exception 'Registered page field contract is not allowed' using errcode = '22023';
    end if;
    field_key := field_definition ->> 'key';
    field_kind := field_definition ->> 'kind';
    if field_key !~ '^[a-z][a-zA-Z0-9_]{0,99}$'
      or field_kind not in ('short', 'long', 'url', 'string-list', 'link-list', 'rich-blocks', 'course-pack')
      or jsonb_typeof(field_definition -> 'label') <> 'string'
      or (field_definition ? 'required' and jsonb_typeof(field_definition -> 'required') <> 'boolean')
      or (field_definition ? 'maxLength' and (
        jsonb_typeof(field_definition -> 'maxLength') <> 'number'
        or (field_definition ->> 'maxLength')::integer not between 1 and 100000
      ))
      or (
        field_definition ? 'maxItems' and (
          jsonb_typeof(field_definition -> 'maxItems') <> 'number'
          or (field_definition ->> 'maxItems')::integer not between 1 and 500
        )
      ) then
      raise exception 'Registered page field contract is not allowed' using errcode = '22023';
    end if;
    if field_key = any(keys) then
      raise exception 'Registered page field keys must be unique' using errcode = '22023';
    end if;
    keys := array_append(keys, field_key);
    perform pac_dsd.assert_plain_page_text(field_definition ->> 'label');
    if field_definition ? 'group' then perform pac_dsd.assert_plain_page_text(field_definition ->> 'group'); end if;
    if field_definition ? 'helpText' then perform pac_dsd.assert_plain_page_text(field_definition ->> 'helpText'); end if;
  end loop;

  foreach protected_key in array new.protected_fields
  loop
    if protected_key !~ '^[a-z][a-zA-Z0-9_]{0,99}$' or protected_key = any(keys) then
      raise exception 'Protected fields cannot be editable' using errcode = '22023';
    end if;
  end loop;
  if cardinality(new.protected_fields) <>
    (select count(distinct protected) from unnest(new.protected_fields) protected) then
    raise exception 'Protected page fields must be unique' using errcode = '22023';
  end if;
  return new;
end;
$$;
revoke all on function pac_dsd.assert_course_schema(jsonb,jsonb) from public,pac_dsd_app_runtime;
revoke all on function pac_dsd.course_pack_schema() from public,pac_dsd_app_runtime;


-- 0037_pac_course_schema_parameter.sql
-- Qualify the course payload independently of JSON iterator value columns.

create or replace function pac_dsd.assert_course_schema(value jsonb, contract jsonb)
returns void language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
declare payload alias for $1; expected text; entry record; candidate jsonb; matched integer:=0; number_value numeric;
begin
  if payload is null then raise exception 'A course payload is missing' using errcode='22023'; end if;
  if contract ? 'oneOf' then
    for candidate in select jsonb_array_elements(contract->'oneOf') loop
      begin perform pac_dsd.assert_course_schema(payload,candidate); matched:=matched+1;
      exception when sqlstate '22023' then null; end;
    end loop;
    if matched<>1 then raise exception 'Course interaction does not match its registered type' using errcode='22023';end if;
    return;
  end if;
  expected:=contract->>'type';
  if expected='integer' then
    if jsonb_typeof(payload)<>'number' or (payload#>>'{}')::numeric<>trunc((payload#>>'{}')::numeric) then raise exception 'Course integer required' using errcode='22023';end if;
  elsif expected is not null and jsonb_typeof(payload)<>expected then raise exception 'Course payload type does not match' using errcode='22023';end if;
  if contract ? 'const' and payload<>contract->'const' then raise exception 'Course fixed payload does not match' using errcode='22023';end if;
  if contract ? 'enum' and not exists(select 1 from jsonb_array_elements(contract->'enum') item where item=payload) then raise exception 'Course payload is not registered' using errcode='22023';end if;
  if expected='object' then
    if exists(select 1 from jsonb_array_elements_text(coalesce(contract->'required','[]')) key where not payload ? key) then raise exception 'Required course field is missing' using errcode='22023';end if;
    for entry in select * from jsonb_each(payload) loop
      if coalesce(contract->'properties','{}') ? entry.key then perform pac_dsd.assert_course_schema(entry.value,contract->'properties'->entry.key);
      elsif contract->'additionalProperties'='false'::jsonb then raise exception 'Course field is not registered' using errcode='22023';end if;
      if entry.key in ('href','src','coverImage','introAudio') and jsonb_typeof(entry.value)='string' and entry.value#>>'{}' not in ('','#') then
        perform pac_dsd.assert_safe_page_link(entry.value#>>'{}');
      end if;
    end loop;
  elsif expected='array' then
    if jsonb_array_length(payload)<coalesce((contract->>'minItems')::integer,0) or jsonb_array_length(payload)>coalesce((contract->>'maxItems')::integer,500) then raise exception 'Course list length does not match' using errcode='22023';end if;
    if contract ? 'items' then for candidate in select jsonb_array_elements(payload) loop perform pac_dsd.assert_course_schema(candidate,contract->'items');end loop;end if;
  elsif expected='string' then
    if length(payload#>>'{}')>coalesce((contract->>'maxLength')::integer,100000) then raise exception 'Course text is too long' using errcode='22023';end if;
    if contract ? 'pattern' and (payload#>>'{}')!~(contract->>'pattern') then raise exception 'Course identifier is not valid' using errcode='22023';end if;
  elsif expected in ('number','integer') then
    number_value:=(payload#>>'{}')::numeric;
    if (contract ? 'minimum' and number_value<(contract->>'minimum')::numeric) or (contract ? 'maximum' and number_value>(contract->>'maximum')::numeric) or (contract ? 'exclusiveMinimum' and number_value<=(contract->>'exclusiveMinimum')::numeric) then raise exception 'Course number is out of range' using errcode='22023';end if;
  end if;
end;$$;


-- 0038_pac_course_validation_receipts.sql
-- Record structured course validation without claiming its authored HTML is plain text.

create or replace function pac_dsd.enforce_surface_publication_gate()
returns trigger
language plpgsql
set search_path = pg_catalog, pac_dsd
as $$
declare
  definition pac_dsd.surface_definitions%rowtype;
  revision pac_dsd.surface_revisions%rowtype;
begin
  select * into strict definition from pac_dsd.surface_definitions
  where surface_id = new.surface_id and active = true;
  if new.decision = 'inherit' and definition.scope_policy <> 'inheritable' then
    raise exception 'This page area does not permit inherited wording' using errcode = '42501';
  end if;
  if new.revision_id is not null then
    select * into revision from pac_dsd.surface_revisions where revision_id = new.revision_id;
    if not found or revision.surface_id <> new.surface_id then
      raise exception 'Publishing decision revision does not belong to this page area' using errcode = '22023';
    end if;
    if new.decision = 'publish' and revision.scope_id <> new.scope_id then
      raise exception 'Published wording must belong to the exact program scope' using errcode = '22023';
    end if;
    if new.decision = 'withdraw' and revision.scope_id <> new.scope_id
      and not (definition.scope_policy = 'inheritable' and new.scope_id = 'dsd' and revision.scope_id = 'one-dhs') then
      raise exception 'Withdrawn wording must be visible in the requested program scope' using errcode = '22023';
    end if;
  end if;
  if new.decision = 'publish' then
    perform pac_dsd.assert_valid_surface_document(new.surface_id, new.scope_id, revision.document);
    if exists (
      select 1 from pac_dsd.surface_owner_approvals approval
      where approval.revision_id = revision.revision_id
        and approval.surface_id = new.surface_id and approval.scope_id = new.scope_id
        and approval.document_sha256 = revision.document_sha256
        and approval.approval_basis = 'standing_owner_approval_on_input'
    ) then
      new.gate_snapshot := new.gate_snapshot || jsonb_build_object(
        'approvalBasis', 'standing_owner_approval_on_input',
        'ownerApprovalRevisionId', revision.revision_id,
        'automaticValidation', jsonb_build_object(
          'registeredFields', true, 'scope', true, 'protectedFields', true,
          'plainTextFormat', case when new.surface_id like 'course.%' then null else true end,
          'structuredCourseFormat', case when new.surface_id like 'course.%' then true else null end, 'safeLinkSyntax', true),
        'independentFactualReviewPerformed', false,
        'independentAccessibilityAuditPerformed', false
      );
    elsif exists (
    select 1 from unnest(revision.required_review_dimensions) required(dimension)
    left join lateral (
      select review.status from pac_dsd.surface_reviews review
      where review.revision_id = revision.revision_id and review.dimension = required.dimension
      order by review.recorded_at desc, review.review_id desc limit 1
    ) current_review on true
    where current_review.status is null or current_review.status not in ('pass', 'not_applicable')
  ) then
    raise exception 'Every required review must be complete before publishing' using errcode = '55000';
    end if;
  end if;
  if length(btrim(new.reason)) = 0 or length(new.reason) > 1000 then
    raise exception 'A brief publishing reason is required' using errcode = '22023';
  end if;
  perform pac_dsd.assert_plain_page_text(new.reason);
  return new;
end;
$$;


-- 0039_pac_program_work_records.sql

-- Extend registered decision families while preserving all earlier contracts.
alter function pac_dsd.assert_runtime_work_object_contract(text,text,jsonb) rename to assert_runtime_work_object_contract_pre_program_v1;
alter function pac_dsd.assert_runtime_idempotency_receipt_contract(text,text,text,jsonb) rename to assert_runtime_idempotency_receipt_contract_pre_program_v1;
alter function pac_dsd.assert_runtime_rate_limit_request(text,text,integer,integer) rename to assert_runtime_rate_limit_request_pre_program_v1;

create function pac_dsd.assert_program_string(payload jsonb, field_name text, minimum_length integer, maximum_length integer, required boolean default true)
returns void language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
begin
  if not (payload ? field_name) and not required then return; end if;
  if jsonb_typeof(payload->field_name) is distinct from 'string'
    or length(payload->>field_name) not between minimum_length and maximum_length then
    raise exception 'Invalid program string field: %', field_name using errcode='22023';
  end if;
end $$;

create function pac_dsd.assert_program_instant(payload jsonb, field_name text, required boolean default true)
returns void language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
begin
  if not (payload ? field_name) and not required then return; end if;
  if pac_dsd.jsonb_is_instant(payload->field_name) is distinct from true
    or (payload->>field_name) !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?Z$' then
    raise exception 'Invalid program timestamp' using errcode='22023';
  end if;
end $$;

create function pac_dsd.assert_program_receipt(payload jsonb)
returns void language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
declare reference jsonb;
begin
  perform pac_dsd.assert_allowed_jsonb_keys(payload,array['title','body','evidenceLevel','method','references','contentHash']);
  if not (payload ?& array['title','body','evidenceLevel','method','references','contentHash']) then raise exception 'Incomplete program receipt' using errcode='22023'; end if;
  perform pac_dsd.assert_program_string(payload,'title',1,180);
  perform pac_dsd.assert_program_string(payload,'body',20,18000);
  perform pac_dsd.assert_program_string(payload,'evidenceLevel',1,30);
  perform pac_dsd.assert_program_string(payload,'method',1,40);
  perform pac_dsd.assert_program_string(payload,'contentHash',64,64);
  if payload->>'evidenceLevel' not in ('delivery','application','benefit')
    or payload->>'method' not in ('generated_artifact','program_record_review','source_check','owner_report')
    or payload->>'contentHash' !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(payload->'references') is distinct from 'array' then raise exception 'Invalid program receipt' using errcode='22023'; end if;
  if jsonb_array_length(payload->'references') > 20 then raise exception 'Too many program references' using errcode='22023'; end if;
  for reference in select value from jsonb_array_elements(payload->'references') loop
    perform pac_dsd.assert_allowed_jsonb_keys(reference,array['label','href']);
    perform pac_dsd.assert_program_string(reference,'label',0,240);
    perform pac_dsd.assert_program_string(reference,'href',1,1500);
    if reference->>'href' !~ '^(/[^/]|/$|https://)' then raise exception 'Invalid program reference route' using errcode='22023'; end if;
  end loop;
end $$;

create function pac_dsd.assert_runtime_work_object_contract(requested_kind text, requested_object_id text, payload jsonb)
returns void language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
declare field_name text; item jsonb;
begin
  perform pac_dsd.assert_no_prohibited_profile_fields(payload);
  if requested_kind is distinct from 'decision' or requested_object_id !~ '^program_(task|event|outcome):' then
    perform pac_dsd.assert_runtime_work_object_contract_pre_program_v1(requested_kind,requested_object_id,payload); return;
  end if;
  if payload is null or jsonb_typeof(payload) <> 'object' or requested_object_id is null or length(requested_object_id)>180 then raise exception 'Invalid program work object' using errcode='22023'; end if;
  if requested_object_id like 'program_task:%' then
    perform pac_dsd.assert_allowed_jsonb_keys(payload,array['recordType','id','createdAt','functionId','outcomeIds','kind','title','objective','agentId','sourceId','dueAt','eligible','exclusionReason','source','evidenceMode']);
    if not (payload ?& array['recordType','id','createdAt','functionId','outcomeIds','kind','title','objective','agentId','dueAt','eligible','source','evidenceMode']) then raise exception 'Incomplete program task' using errcode='22023'; end if;
    perform pac_dsd.assert_jsonb_scalar_types(payload,array['recordType','id','functionId','kind','agentId','source','evidenceMode'],array['eligible'],array[]::text[]);
    if payload->>'recordType' is distinct from 'program_task' or payload->>'id' !~ '^task-[a-f0-9]{32}$' or requested_object_id is distinct from 'program_task:'||(payload->>'id')
      or payload->>'kind' not in ('work_preparation','cadence_review','outcome_followup','source_review')
      or payload->>'agentId' not in ('program_orchestrator','ask_concierge','ci_guide','librarian','a11y_reviewer','consult_intake','graduation_coach','embed_advisor','content_sentinel','eval_steward')
      or payload->>'source' not in ('owner','cadence','staff_result','program_maintenance')
      or payload->>'evidenceMode' not in ('operational','verification')
      or (payload->>'eligible'='false' and coalesce(payload->>'exclusionReason','')='') then raise exception 'Invalid program task' using errcode='22023'; end if;
    perform pac_dsd.assert_program_string(payload,'functionId',1,60);
    perform pac_dsd.assert_program_string(payload,'title',5,180);
    perform pac_dsd.assert_program_string(payload,'objective',10,3000);
    perform pac_dsd.assert_program_string(payload,'sourceId',0,180,false);
    perform pac_dsd.assert_program_string(payload,'exclusionReason',0,300,false);
    perform pac_dsd.assert_program_instant(payload,'createdAt');
    perform pac_dsd.assert_program_instant(payload,'dueAt');
    perform pac_dsd.assert_jsonb_string_array(payload->'outcomeIds');
    if jsonb_array_length(payload->'outcomeIds')>7 then raise exception 'Too many program outcomes' using errcode='22023'; end if;
    for item in select value from jsonb_array_elements(payload->'outcomeIds') loop
      if length(item#>>'{}')>60 then raise exception 'Invalid program outcome identifier' using errcode='22023'; end if;
    end loop;
    return;
  end if;  if requested_object_id like 'program_event:%' then
    perform pac_dsd.assert_allowed_jsonb_keys(payload,array['recordType','id','taskId','at','phase','attempt','actor','note','receipt','disposition','followUpAt','humanMinutes']);
    if not (payload ?& array['recordType','id','taskId','at','phase','attempt','actor','note']) then raise exception 'Incomplete program event' using errcode='22023'; end if;
    perform pac_dsd.assert_jsonb_scalar_types(payload,array['recordType','id','taskId','phase','actor','disposition'],array[]::text[],array['attempt','humanMinutes']);
    if payload->>'recordType' is distinct from 'program_event'
      or payload->>'id' !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
      or requested_object_id is distinct from 'program_event:'||(payload->>'id')
      or payload->>'taskId' !~ '^task-[a-f0-9]{32}$'
      or payload->>'phase' not in ('started','completed','failed','applied','reviewed','cancelled','retry_requested')
      or payload->>'actor' not in ('agent','owner')
      or pac_dsd.jsonb_is_safe_integer(payload->'attempt',0) is distinct from true
      or (payload->>'attempt')::numeric>10000
      or (payload->>'phase'='completed' and not (payload ? 'receipt'))
      or (payload->>'phase' in ('applied','reviewed','cancelled','retry_requested') and payload->>'actor'<>'owner')
      or (payload ? 'disposition' and payload->>'disposition' not in ('retain','revise','stop','not_yet_known'))
      or (payload ? 'humanMinutes' and (payload->>'humanMinutes')::numeric not between 0 and 100000) then raise exception 'Invalid program event' using errcode='22023'; end if;
    perform pac_dsd.assert_program_string(payload,'note',0,3000);
    perform pac_dsd.assert_program_instant(payload,'at');
    perform pac_dsd.assert_program_instant(payload,'followUpAt',false);
    if payload ? 'receipt' then perform pac_dsd.assert_program_receipt(payload->'receipt'); end if;
    return;
  end if;
  if requested_object_id like 'program_outcome:%' then
    perform pac_dsd.assert_allowed_jsonb_keys(payload,array['schemaVersion','id','createdAt','evidenceStatus','programScope','problem','action','adoptedChange','observedResult','evidenceUrl','followUp','reviewDate','decision','consent','sourceRoute','outcomeId']);
    if not (payload ?& array['schemaVersion','id','createdAt','evidenceStatus','programScope','problem','action','adoptedChange','observedResult','followUp','decision','consent']) then raise exception 'Incomplete program outcome' using errcode='22023'; end if;
    perform pac_dsd.assert_jsonb_scalar_types(payload,array['id','evidenceStatus','programScope','decision','reviewDate','sourceRoute','outcomeId'],array['consent'],array['schemaVersion']);
    if payload->'schemaVersion' is distinct from '1'::jsonb or payload->'consent' is distinct from 'true'::jsonb
      or payload->>'id' !~ '^program-outcome-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or requested_object_id is distinct from 'program_outcome:'||(payload->>'id')
      or payload->>'evidenceStatus' is distinct from 'self_reported'
      or payload->>'programScope' not in ('one-dhs','dsd')
      or payload->>'decision' not in ('retain','revise','stop','not_yet_known')
      or (payload ? 'outcomeId' and payload->>'outcomeId' not in ('staff_capability','capability_transfer','access','workplace_culture','institutional_application','organizational_memory','agency_coherence')) then raise exception 'Invalid program outcome' using errcode='22023'; end if;
    foreach field_name in array array['problem','action','adoptedChange','followUp'] loop
      perform pac_dsd.assert_program_string(payload,field_name,1,1500);
      if btrim(payload->>field_name)='' then raise exception 'Blank program outcome' using errcode='22023'; end if;
    end loop;
    perform pac_dsd.assert_program_string(payload,'observedResult',1,2000);
    if btrim(payload->>'observedResult')='' then raise exception 'Blank program outcome' using errcode='22023'; end if;
    perform pac_dsd.assert_program_instant(payload,'createdAt');
    perform pac_dsd.assert_program_string(payload,'evidenceUrl',1,1000,false);
    perform pac_dsd.assert_program_string(payload,'sourceRoute',1,200,false);
    if payload ? 'reviewDate' then
      if payload->>'reviewDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or ((payload->>'reviewDate')::date)::text <> payload->>'reviewDate' then raise exception 'Invalid outcome review date' using errcode='22023'; end if;
    end if;
    if payload ? 'sourceRoute' and payload->>'sourceRoute' !~ '^/(practice|courses|learn|areas|one-dsd|support)(/[a-z0-9-]+)*$' then raise exception 'Invalid outcome source route' using errcode='22023'; end if;
    if payload ? 'evidenceUrl' and (
      payload->>'evidenceUrl' !~ '^https://[^/@?#[:space:]]+(/[^?#[:space:]]*)?$'
      or payload->>'evidenceUrl' ~* '^https://(localhost([:/]|$)|127\.|10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.|\[|[^/]*\.(local|internal)([:/]|$))'
    ) then raise exception 'Invalid public outcome evidence link' using errcode='22023'; end if;
    return;
  end if;
  raise exception 'Unregistered program record' using errcode='22023';
end $$;
create function pac_dsd.assert_runtime_idempotency_receipt_contract(requested_idempotency_key text, requested_kind text, requested_object_id text, payload jsonb)
returns void language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
begin
  if requested_kind is distinct from 'decision' or requested_object_id !~ '^program_(task|event|outcome):' then
    perform pac_dsd.assert_runtime_idempotency_receipt_contract_pre_program_v1(requested_idempotency_key,requested_kind,requested_object_id,payload); return;
  end if;
  perform pac_dsd.assert_no_prohibited_profile_fields(payload);
  perform pac_dsd.assert_allowed_jsonb_keys(payload,array['work_kind','object_id']);
  if not (payload ?& array['work_kind','object_id'])
    or payload->>'work_kind' is distinct from requested_kind or payload->>'object_id' is distinct from requested_object_id
    or jsonb_typeof(payload->'work_kind') is distinct from 'string' or jsonb_typeof(payload->'object_id') is distinct from 'string'
    or requested_idempotency_key is null or not (
      (requested_object_id ~ '^program_task:task-[a-f0-9]{32}$' and requested_idempotency_key ~ '^program-task:[a-f0-9]{64}$')
      or (requested_object_id ~ '^program_event:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$' and requested_idempotency_key ~ '^program-event:[a-f0-9]{64}$')
      or (requested_object_id ~ '^program_outcome:program-outcome-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        and requested_idempotency_key = 'program-outcome:'||substring(requested_object_id from length('program_outcome:program-outcome-')+1))
    ) then raise exception 'Invalid program idempotency contract' using errcode='22023'; end if;
end $$;

create function pac_dsd.assert_runtime_rate_limit_request(requested_scope text, requested_subject_hash text, requested_limit integer, requested_window_seconds integer)
returns void language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
begin
  if requested_scope is distinct from 'staff-program-outcome' then
    perform pac_dsd.assert_runtime_rate_limit_request_pre_program_v1(requested_scope,requested_subject_hash,requested_limit,requested_window_seconds); return;
  end if;
  if requested_subject_hash is null or requested_subject_hash !~ '^[a-f0-9]{64}$'
    or requested_limit is distinct from 10 or requested_window_seconds is distinct from 600 then
    raise exception 'Invalid program outcome rate limit' using errcode='22023';
  end if;
end $$;
alter table pac_dsd.runtime_rate_limits drop constraint runtime_rate_limits_registered_identity;
alter table pac_dsd.runtime_rate_limits add constraint runtime_rate_limits_registered_identity check (
  scope in ('staff-ask','owner-login','consultation-intake','consultation-tracking','staff-program-outcome')
  and subject_hash ~ '^[a-f0-9]{64}$'
);

-- Validate the new tool using the unchanged audit envelope rules; the stored
-- event retains its actual program.work_execute name, never the comparison name.
alter function pac_dsd.assert_runtime_audit_event_contract(jsonb) rename to assert_runtime_audit_event_contract_pre_program_v1;
create function pac_dsd.assert_runtime_audit_event_contract(payload jsonb)
returns void language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
begin
  perform pac_dsd.assert_no_prohibited_profile_fields(payload);
  if payload->>'tool_name'='program.work_execute' and jsonb_typeof(payload->'tool_name')='string' then
    perform pac_dsd.assert_runtime_audit_event_contract_pre_program_v1(jsonb_set(payload,'{tool_name}','"orchestrator.run_cycle"'::jsonb));
  else
    perform pac_dsd.assert_runtime_audit_event_contract_pre_program_v1(payload);
  end if;
end $$;

create function pac_dsd.prevent_program_record_rewrite()
returns trigger language plpgsql set search_path=pg_catalog,pac_dsd as $$
begin
  if (old.work_kind='decision' and old.object_id ~ '^program_(task|event|outcome):')
    or (new.work_kind='decision' and new.object_id ~ '^program_(task|event|outcome):') then
    if old.work_kind is distinct from new.work_kind or old.object_id is distinct from new.object_id
      or old.value is distinct from new.value or old.created_at is distinct from new.created_at then
      raise exception 'Program records are immutable; append a new event' using errcode='22023';
    end if;
  end if;
  return new;
end $$;
create trigger immutable_program_record before update on pac_dsd.runtime_work_objects
for each row execute function pac_dsd.prevent_program_record_rewrite();

revoke all on function pac_dsd.assert_program_string(jsonb,text,integer,integer,boolean) from public,pac_dsd_app_runtime;
revoke all on function pac_dsd.assert_program_instant(jsonb,text,boolean) from public,pac_dsd_app_runtime;
revoke all on function pac_dsd.assert_program_receipt(jsonb) from public,pac_dsd_app_runtime;
revoke all on function pac_dsd.assert_runtime_work_object_contract(text,text,jsonb) from public,pac_dsd_app_runtime;
revoke all on function pac_dsd.assert_runtime_idempotency_receipt_contract(text,text,text,jsonb) from public,pac_dsd_app_runtime;
revoke all on function pac_dsd.assert_runtime_rate_limit_request(text,text,integer,integer) from public,pac_dsd_app_runtime;
revoke all on function pac_dsd.assert_runtime_audit_event_contract(jsonb) from public,pac_dsd_app_runtime;
revoke all on function pac_dsd.prevent_program_record_rewrite() from public,pac_dsd_app_runtime;


-- 0040_pac_program_event_lifecycle.sql

-- Add an explicitly bounded, deterministic published-resource review task.
alter function pac_dsd.assert_runtime_work_object_contract(text,text,jsonb) rename to assert_runtime_work_object_contract_pre_program_cas_v1;
create function pac_dsd.assert_runtime_work_object_contract(requested_kind text, requested_object_id text, payload jsonb)
returns void language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
begin
  if requested_kind='decision' and requested_object_id like 'program_task:%' and payload->>'kind'='resource_review' then
    perform pac_dsd.assert_runtime_work_object_contract_pre_program_cas_v1(requested_kind,requested_object_id,jsonb_set(payload,'{kind}','"source_review"'::jsonb));
  else
    perform pac_dsd.assert_runtime_work_object_contract_pre_program_cas_v1(requested_kind,requested_object_id,payload);
  end if;
end $$;

create function pac_dsd.program_event_transition_valid(payload jsonb)
returns boolean language plpgsql volatile security definer set search_path=pg_catalog,pac_dsd as $$
declare task jsonb; latest jsonb; execution jsonb; current_status text; current_attempt integer; phase text; actor text; attempted integer;
begin
  perform pac_dsd.assert_runtime_work_object_contract('decision','program_event:'||(payload->>'id'),payload);
  select value into task from pac_dsd.runtime_work_objects
    where work_kind='decision' and object_id='program_task:'||(payload->>'taskId') for update;
  if task is null then return false; end if;
  select value into latest from pac_dsd.runtime_work_objects
    where work_kind='decision' and object_id like 'program_event:%' and value->>'taskId'=payload->>'taskId'
    order by value->>'at' desc, (value->>'attempt')::integer desc, value->>'id' desc limit 1;
  select value into execution from pac_dsd.runtime_work_objects
    where work_kind='decision' and object_id like 'program_event:%' and value->>'taskId'=payload->>'taskId'
      and value->>'phase' in ('started','completed','failed','cancelled','retry_requested')
    order by value->>'at' desc, (value->>'attempt')::integer desc, value->>'id' desc limit 1;
  select coalesce(max((value->>'attempt')::integer),0) into current_attempt from pac_dsd.runtime_work_objects
    where work_kind='decision' and object_id like 'program_event:%' and value->>'taskId'=payload->>'taskId';
  if latest is not null and payload->>'at'<=latest->>'at' then return false; end if;
  current_status:=coalesce(execution->>'phase','queued');
  phase:=payload->>'phase';actor:=payload->>'actor';attempted:=(payload->>'attempt')::integer;
  if payload ? 'receipt' and payload->'receipt'->>'contentHash' is distinct from encode(sha256(convert_to(payload->'receipt'->>'body','UTF8')),'hex') then return false; end if;
  if phase='started' then
    return actor='agent' and attempted=current_attempt+1 and (
      current_status in ('queued','retry_requested') or (current_status='failed' and current_attempt<3) or
      (current_status='started' and (payload->>'at')::timestamptz-(execution->>'at')::timestamptz>=interval '10 minutes'));
  end if;
  if phase in ('completed','failed') then
    return actor='agent' and current_status='started' and attempted=current_attempt and
      (phase<>'completed' or payload->'receipt'->>'evidenceLevel'='delivery');
  end if;
  if actor<>'owner' or attempted<>current_attempt or payload ? 'receipt' then return false; end if;
  if phase='cancelled' then return current_status<>'cancelled'; end if;
  if phase='retry_requested' then return current_status in ('failed','cancelled','completed'); end if;
  return phase in ('applied','reviewed') and current_status='completed' and execution ? 'receipt';
end $$;

create function pac_dsd.enforce_program_event_insert()
returns trigger language plpgsql security definer set search_path=pg_catalog,pac_dsd as $$
begin
  if new.work_kind='decision' and new.object_id like 'program_event:%' then
    if pac_dsd.program_event_transition_valid(new.value) is distinct from true then
      raise exception 'Invalid program event transition' using errcode='22023';
    end if;
  end if;
  return new;
end $$;
create trigger program_event_lifecycle before insert on pac_dsd.runtime_work_objects
for each row execute function pac_dsd.enforce_program_event_insert();

create function pac_dsd.append_program_event(requested_task_id text, expected_event_id text, payload jsonb)
returns table(applied boolean, reason text, event_value jsonb)
language plpgsql volatile security definer set search_path=pg_catalog,pac_dsd as $$
declare task jsonb; prior jsonb; latest jsonb;
begin
  perform pac_dsd.assert_runtime_work_object_contract('decision','program_event:'||(payload->>'id'),payload);
  if requested_task_id is distinct from payload->>'taskId' then
    return query select false,'invalid_transition'::text,null::jsonb;return;
  end if;
  select value into task from pac_dsd.runtime_work_objects
    where work_kind='decision' and object_id='program_task:'||requested_task_id for update;
  if task is null then return query select false,'not_found'::text,null::jsonb;return;end if;
  select value into prior from pac_dsd.runtime_work_objects where work_kind='decision' and object_id='program_event:'||(payload->>'id');
  if prior is not null then
    if prior=payload then return query select true,'replayed'::text,prior;
    else return query select false,'conflict'::text,prior;end if;
    return;
  end if;
  select value into latest from pac_dsd.runtime_work_objects
    where work_kind='decision' and object_id like 'program_event:%' and value->>'taskId'=requested_task_id
    order by value->>'at' desc, (value->>'attempt')::integer desc, value->>'id' desc limit 1;
  if (latest->>'id') is distinct from expected_event_id then return query select false,'conflict'::text,latest;return;end if;
  if pac_dsd.program_event_transition_valid(payload) is distinct from true then
    return query select false,'invalid_transition'::text,latest;return;
  end if;
  insert into pac_dsd.runtime_work_objects(work_kind,object_id,value) values('decision','program_event:'||(payload->>'id'),payload);
  return query select true,'applied'::text,payload;
end $$;

revoke all on function pac_dsd.assert_runtime_work_object_contract(text,text,jsonb) from public,pac_dsd_app_runtime;
revoke all on function pac_dsd.program_event_transition_valid(jsonb) from public,pac_dsd_app_runtime;
revoke all on function pac_dsd.enforce_program_event_insert() from public,pac_dsd_app_runtime;
revoke all on function pac_dsd.append_program_event(text,text,jsonb) from public;
grant execute on function pac_dsd.append_program_event(text,text,jsonb) to pac_dsd_app_runtime;


-- 0041_pac_ask_practice_artifact.sql
-- Optional ASK-to-Practice drafts. Existing response records and narrow storage functions remain valid.
create function pac_dsd.valid_ask_practice_artifact(a jsonb) returns boolean
language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
declare item record; source jsonb; entry jsonb;
begin
  if jsonb_typeof(a) is distinct from 'object'
    or octet_length(a::text)>12000
    or not (a ?& array['schemaVersion','artifactId','revisionId','parentRevisionId','traceId','createdAt','context','pathId','pathContract','title','values','sources'])
    or (a - array['schemaVersion','artifactId','revisionId','parentRevisionId','traceId','createdAt','context','pathId','pathContract','title','values','sources']) <> '{}'::jsonb
    or a->'schemaVersion' <> '1'::jsonb
    or jsonb_typeof(a->'context') <> 'string'
    or jsonb_typeof(a->'pathId') <> 'string'
    or jsonb_typeof(a->'pathContract') <> 'string'
    or a->>'context' not in ('one_dhs','one_dsd')
    or a->>'pathId' !~ '^gp-([1-9]|10|11)$'
    or a->>'pathContract' !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(a->'title') <> 'string' or length(a->>'title') not between 1 and 300
    or jsonb_typeof(a->'values') <> 'object'
    or jsonb_typeof(a->'sources') <> 'array'
  then return false; end if;
  if (select count(*) from jsonb_object_keys(a->'values')) not between 1 and 30 or jsonb_array_length(a->'sources')>10 then return false; end if;
  foreach source in array array[a->'artifactId',a->'revisionId',a->'traceId'] loop
    if jsonb_typeof(source) <> 'string' or (source#>>'{}') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then return false; end if;
  end loop;
  if a->'parentRevisionId' <> 'null'::jsonb and (jsonb_typeof(a->'parentRevisionId') <> 'string' or a->>'parentRevisionId' !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') then return false; end if;
  if jsonb_typeof(a->'createdAt') <> 'string' or a->>'createdAt' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?Z$' then return false; end if;
  perform (a->>'createdAt')::timestamptz;
  for item in select key,value from jsonb_each(a->'values') loop
    if item.key !~ '^[a-z][a-z0-9_]{0,79}$' then return false; end if;
    if jsonb_typeof(item.value)='string' then
      if length(item.value#>>'{}')>3000 then return false; end if;
    elsif jsonb_typeof(item.value)='array' then
      if jsonb_array_length(item.value)>20 then return false; end if;
      for entry in select value from jsonb_array_elements(item.value) loop
        if jsonb_typeof(entry)<>'string' or length(entry#>>'{}')>500 then return false; end if;
      end loop;
    else return false;
    end if;
  end loop;
  for source in select value from jsonb_array_elements(a->'sources') loop
    if jsonb_typeof(source)<>'object' or not(source ?& array['id','title','href']) or (source-array['id','title','href'])<>'{}'::jsonb
      or jsonb_typeof(source->'id')<>'string' or length(source->>'id') not between 1 and 200
      or jsonb_typeof(source->'title')<>'string' or length(source->>'title') not between 1 and 300
      or jsonb_typeof(source->'href')<>'string' or length(source->>'href')>1000
      or source->>'href' ~ '[[:space:][:cntrl:]]' or position(chr(92) in source->>'href')>0
      or not (source->>'href' ~ '^/($|[^/])' or source->>'href' ~ '^https://')
    then return false; end if;
  end loop;
  return true;
exception when others then return false;
end $$;
revoke all on function pac_dsd.valid_ask_practice_artifact(jsonb) from public;

alter table pac_dsd.ask_response_records drop constraint ask_record_contract;
alter table pac_dsd.ask_response_records add constraint ask_record_contract check ((
    jsonb_typeof(record) = 'object'
    and octet_length(record::text) <= 1048576
    and record ?& array['id','traceId','createdAt','programScope','researchMode','status','httpStatus','question','questionOmittedReason','response','researchStatus','expiresAt']
    and (record - array['id','traceId','createdAt','programScope','researchMode','status','httpStatus','question','questionOmittedReason','response','researchStatus','expiresAt']) = '{}'::jsonb
    and (record->>'id')::uuid = record_id
    and (record->>'traceId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    and (record->>'createdAt')::timestamptz = created_at
    and ((record->>'expiresAt')::timestamptz is not distinct from expires_at)
    and record->>'programScope' in ('one-dhs','dsd')
    and record->>'researchMode' in ('auto','program_only','web_results','current_web','deep_research')
    and record->>'status' in ('answered','limited','refused','unavailable','failed')
    and record->>'researchStatus' in ('not_requested','used','not_connected','failed')
    and jsonb_typeof(record->'httpStatus') = 'number'
    and (record->>'httpStatus')::integer between 100 and 599
    and (
      (jsonb_typeof(record->'question') = 'string' and length(record->>'question') between 1 and 4000 and record->'questionOmittedReason' = 'null'::jsonb)
      or (record->'question' = 'null'::jsonb and record->>'questionOmittedReason' = 'private_information')
    )
    and jsonb_typeof(record->'response') = 'object'
    and (
      (jsonb_typeof(record->'response'->'error') = 'string' and ((record->'response') - 'error') = '{}'::jsonb)
      or (record->'response'->>'kind' = 'answer' and jsonb_typeof(record->'response'->'answer') = 'object'
        and ((record->'response'->'answer') - array['shortAnswer','whyItMatters','sources','limits','nextActions','questions','conflict','consultation','pathSuggestion','notice','publicResearch','practiceArtifact']) = '{}'::jsonb
        and (record->'response'->'answer') ?& array['shortAnswer','whyItMatters','sources','limits','nextActions']
        and jsonb_typeof(record->'response'->'answer'->'shortAnswer') = 'string'
        and jsonb_typeof(record->'response'->'answer'->'whyItMatters') = 'string'
        and jsonb_typeof(record->'response'->'answer'->'sources') = 'array'
        and jsonb_typeof(record->'response'->'answer'->'limits') = 'array'
        and jsonb_typeof(record->'response'->'answer'->'nextActions') = 'array'
        and (not ((record->'response'->'answer') ? 'practiceArtifact') or (pac_dsd.valid_ask_practice_artifact(record->'response'->'answer'->'practiceArtifact') is true and record->'response'->'answer'->'practiceArtifact'->>'traceId' = record->>'traceId' and record->'response'->'answer'->'practiceArtifact'->>'context' = case record->>'programScope' when 'dsd' then 'one_dsd' else 'one_dhs' end))
        and ((record->'response') - array['kind','answer']) = '{}'::jsonb)
      or (record->'response'->>'kind' = 'refusal' and jsonb_typeof(record->'response'->'safety') = 'object'
        and ((record->'response'->'safety') - array['message','redirect','alternatives']) = '{}'::jsonb
        and ((record->'response') - array['kind','safety']) = '{}'::jsonb)
    )
  ) is true);


-- 0042_pac_named_contributor_identity.sql

-- Local named-contributor adaptation, owner authorized 2026-09-08.
-- Selective donor identity lineage0021/0022/0023; existing owner functions and grants remain intact.
-- Hosted PostgreSQL may grant its creator administrative control without INHERIT or SET.
-- Only that unusable migration-owner membership is permitted; runtime role paths remain denied.
do $role$ begin
if not exists(select 1 from pg_roles where rolname='pac_dsd_contributor_runtime') then
create role pac_dsd_contributor_runtime login noinherit nosuperuser nocreatedb nocreaterole noreplication nobypassrls connection limit 20; end if;
if not exists(select 1 from pg_roles where rolname='pac_dsd_contributor_runtime' and rolcanlogin and not rolinherit and not rolsuper and not rolcreatedb and not rolcreaterole and not rolreplication and not rolbypassrls and rolconnlimit between 1 and 20)
or exists(select 1 from pg_auth_members m join pg_roles r on r.oid=m.member join pg_roles g on g.oid=m.roleid where (r.rolname='pac_dsd_contributor_runtime' or g.rolname='pac_dsd_contributor_runtime')
  and not (g.rolname='pac_dsd_contributor_runtime' and r.rolname=current_user
    and m.admin_option and not m.inherit_option and not m.set_option)) then raise exception 'Unsafe existing pac_dsd_contributor_runtime role' using errcode='42501'; end if;
execute format('grant connect on database %I to pac_dsd_contributor_runtime',current_database()); end $role$;
alter role pac_dsd_contributor_runtime set statement_timeout='10s';
alter role pac_dsd_contributor_runtime set lock_timeout='5s';
alter role pac_dsd_contributor_runtime set idle_in_transaction_session_timeout='10s';
grant usage on schema pac_dsd to pac_dsd_contributor_runtime;


-- DEC-021 through DEC-023 require a named, revocable program identity and an
-- exact role/scope grant at the instant of every protected action. The shared
-- consultant key is intentionally not represented here and cannot satisfy any
-- of these functions.

create table if not exists pac_dsd.program_accounts (
  account_id uuid primary key default gen_random_uuid(),
  environment text not null check (environment in ('local', 'preview', 'production')),
  sign_in_id text not null check (
    sign_in_id = lower(sign_in_id)
    and sign_in_id ~ '^[a-z0-9][a-z0-9._-]{2,63}$'
  ),
  display_name text not null check (
    char_length(display_name) between 2 and 120
    and display_name = btrim(display_name)
    and display_name !~ '[[:cntrl:]]'
  ),
  created_at timestamptz not null default clock_timestamp(),
  identity_contract_version text not null default 'program-identity-v1'
    check (identity_contract_version = 'program-identity-v1'),
  unique (environment, sign_in_id)
);

create table if not exists pac_dsd.program_account_state_events (
  account_state_event_id bigint generated always as identity primary key,
  account_id uuid not null references pac_dsd.program_accounts(account_id),
  state text not null check (state in ('active', 'suspended', 'revoked')),
  reason text not null check (
    char_length(reason) between 3 and 500
    and reason = btrim(reason)
    and reason !~ '[[:cntrl:]]'
  ),
  recorded_at timestamptz not null default clock_timestamp(),
  recorded_by_account_id uuid references pac_dsd.program_accounts(account_id),
  recorded_by_session_id uuid,
  activation_invitation_id uuid,
  supersedes_account_state_event_id bigint unique
    references pac_dsd.program_account_state_events(account_state_event_id),
  check (
    (recorded_by_account_id is not null and recorded_by_session_id is not null and activation_invitation_id is null)
    or (recorded_by_account_id is null and recorded_by_session_id is null and activation_invitation_id is not null)
  )
);

create unique index if not exists program_account_initial_state_idx
  on pac_dsd.program_account_state_events(account_id)
  where supersedes_account_state_event_id is null;

create table if not exists pac_dsd.program_account_invitations (
  invitation_id uuid primary key default gen_random_uuid(),
  environment text not null check (environment in ('local', 'preview', 'production')),
  activation_evidence_id text not null check (
    activation_evidence_id ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
  ),
  activation_bundle_sha256 text not null check (activation_bundle_sha256 ~ '^[a-f0-9]{64}$'),
  invitation_type text not null check (
    invitation_type in ('bootstrap_owner', 'new_account', 'credential_reset', 'owner_recovery')
  ),
  sign_in_id text not null check (
    sign_in_id = lower(sign_in_id)
    and sign_in_id ~ '^[a-z0-9][a-z0-9._-]{2,63}$'
  ),
  display_name text not null check (
    char_length(display_name) between 2 and 120
    and display_name = btrim(display_name)
    and display_name !~ '[[:cntrl:]]'
  ),
  target_account_id uuid references pac_dsd.program_accounts(account_id),
  issued_at timestamptz not null default clock_timestamp(),
  issued_by_authorization_id uuid,
  bootstrap_evidence_id text,
  check (
    (invitation_type = 'bootstrap_owner'
      and target_account_id is null
      and issued_by_authorization_id is null
      and bootstrap_evidence_id ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$')
    or (invitation_type = 'new_account'
      and target_account_id is null
      and issued_by_authorization_id is not null
      and bootstrap_evidence_id is null)
    or (invitation_type = 'credential_reset'
      and target_account_id is not null
      and issued_by_authorization_id is not null
      and bootstrap_evidence_id is null)
    or (invitation_type = 'owner_recovery'
      and target_account_id is not null
      and issued_by_authorization_id is null
      and bootstrap_evidence_id ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$')
  )
);

create table if not exists pac_dsd.program_account_invitation_secrets (
  invitation_id uuid primary key references pac_dsd.program_account_invitations(invitation_id),
  token_digest text not null unique check (token_digest ~ '^[a-f0-9]{64}$'),
  expires_at timestamptz not null
);

create table if not exists pac_dsd.program_account_invitation_closures (
  invitation_id uuid primary key references pac_dsd.program_account_invitations(invitation_id),
  outcome text not null check (outcome in ('accepted', 'revoked', 'expired', 'superseded')),
  account_id uuid references pac_dsd.program_accounts(account_id),
  closed_at timestamptz not null default clock_timestamp(),
  closed_by_account_id uuid references pac_dsd.program_accounts(account_id),
  closed_by_session_id uuid,
  recovery_evidence_id text check (
    recovery_evidence_id is null
    or recovery_evidence_id ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
  ),
  reason text not null check (
    char_length(reason) between 3 and 500
    and reason = btrim(reason)
    and reason !~ '[[:cntrl:]]'
  ),
  check (
    (outcome = 'accepted' and account_id is not null and closed_by_account_id is null and closed_by_session_id is null and recovery_evidence_id is null)
    or (outcome = 'revoked' and account_id is null and closed_by_account_id is not null and closed_by_session_id is not null and recovery_evidence_id is null)
    or (outcome = 'expired' and account_id is null and closed_by_account_id is null and closed_by_session_id is null and recovery_evidence_id is null)
    or (outcome = 'superseded' and account_id is null and closed_by_account_id is null and closed_by_session_id is null and recovery_evidence_id is not null)
  )
);

create table if not exists pac_dsd.program_account_credentials (
  credential_id uuid primary key default gen_random_uuid(),
  account_id uuid not null references pac_dsd.program_accounts(account_id),
  credential_version integer not null check (credential_version > 0),
  invitation_id uuid not null unique references pac_dsd.program_account_invitations(invitation_id),
  issued_at timestamptz not null default clock_timestamp(),
  credential_contract_version text not null default 'pac-scrypt-v1'
    check (credential_contract_version = 'pac-scrypt-v1'),
  unique (account_id, credential_version)
);

create table if not exists pac_dsd.program_account_credential_secrets (
  credential_id uuid primary key references pac_dsd.program_account_credentials(credential_id) on delete cascade,
  credential_hash text not null check (
    credential_hash ~ E'^\\$pac-scrypt\\$v=1\\$ln=17\\$r=8\\$p=1\\$[A-Za-z0-9_-]{22}\\$[A-Za-z0-9_-]{43}$'
  )
);

create table if not exists pac_dsd.program_account_sessions (
  session_id uuid primary key default gen_random_uuid(),
  account_id uuid not null references pac_dsd.program_accounts(account_id),
  credential_id uuid not null references pac_dsd.program_account_credentials(credential_id),
  token_digest text not null unique check (token_digest ~ '^[a-f0-9]{64}$'),
  audience text not null check (audience = 'pac-protected-workspace'),
  environment text not null check (environment in ('local', 'preview', 'production')),
  activation_evidence_id text not null check (
    activation_evidence_id ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
  ),
  activation_bundle_sha256 text not null check (activation_bundle_sha256 ~ '^[a-f0-9]{64}$'),
  issued_at timestamptz not null default clock_timestamp(),
  expires_at timestamptz not null,
  check (expires_at > issued_at and expires_at <= issued_at + interval '8 hours 1 minute')
);

create index if not exists program_account_sessions_expiry_idx
  on pac_dsd.program_account_sessions(expires_at, session_id);

create table if not exists pac_dsd.program_account_session_revocations (
  session_id uuid primary key references pac_dsd.program_account_sessions(session_id) on delete cascade,
  revoked_at timestamptz not null default clock_timestamp(),
  reason text not null check (
    char_length(reason) between 3 and 240
    and reason = btrim(reason)
    and reason !~ '[[:cntrl:]]'
  ),
  revoked_by_account_id uuid references pac_dsd.program_accounts(account_id),
  revoked_by_session_id uuid,
  check (
    (revoked_by_account_id is null and revoked_by_session_id is null)
    or (revoked_by_account_id is not null and revoked_by_session_id is not null)
  )
);

-- Preserve historical access grants without fabricating protected identity
-- evidence. Every protected-v1 grant must bind an exact account and the named
-- owner session that issued it. Historical rows remain visibly legacy.
alter table pac_dsd.access_grants
  add column if not exists account_id uuid references pac_dsd.program_accounts(account_id),
  add column if not exists environment text,
  add column if not exists expires_at timestamptz,
  add column if not exists issued_by_account_id uuid references pac_dsd.program_accounts(account_id),
  add column if not exists issued_by_session_id uuid,
  add column if not exists grant_reason text,
  add column if not exists grant_contract_version text,
  add column if not exists revoked_by_account_id uuid references pac_dsd.program_accounts(account_id),
  add column if not exists revoked_by_session_id uuid,
  add column if not exists revocation_reason text;

alter table pac_dsd.access_grants
  drop constraint if exists access_grants_role_key_check;
alter table pac_dsd.access_grants
  add constraint access_grants_role_key_check check (
    role_key in (
      'staff_user', 'content_contributor', 'program_steward',
      'publishing_approver', 'equity_director', 'one_dsd_team_member', 'owner'
    )
  ) not valid;
alter table pac_dsd.access_grants validate constraint access_grants_role_key_check;

alter table pac_dsd.access_grants
  add constraint access_grants_protected_v1_contract check (
    grant_contract_version is null
    or (
      grant_contract_version = 'protected-v1'
      and account_id is not null
      and environment in ('local', 'preview', 'production')
      and principal_id = account_id::text
      and issued_by_account_id is not null
      and issued_by_session_id is not null
      and granted_by = issued_by_account_id::text
      and grant_reason is not null
      and char_length(grant_reason) between 3 and 500
      and grant_reason = btrim(grant_reason)
      and grant_reason !~ '[[:cntrl:]]'
      and (expires_at is null or expires_at > granted_at)
      and (
        (role_key = 'owner' and scope_id = 'one-dhs-pac')
        or (
          role_key in ('content_contributor', 'program_steward', 'publishing_approver')
          and scope_id in ('one-dhs', 'dsd')
        )
        or (role_key = 'one_dsd_team_member' and scope_id = 'one-dsd-team')
      )
      and (
        revoked_at is null
        or (
          revoked_by is not null
          and revoked_by_account_id is not null
          and revoked_by_session_id is not null
          and revoked_by = revoked_by_account_id::text
          and revocation_reason is not null
          and char_length(revocation_reason) between 3 and 500
          and revocation_reason = btrim(revocation_reason)
          and revocation_reason !~ '[[:cntrl:]]'
        )
      )
    )
  ) not valid;
alter table pac_dsd.access_grants validate constraint access_grants_protected_v1_contract;

create table if not exists pac_dsd.protected_action_authorizations (
  authorization_id uuid primary key default gen_random_uuid(),
  account_id uuid not null references pac_dsd.program_accounts(account_id),
  session_id uuid not null,
  credential_id uuid not null,
  environment text not null check (environment in ('local', 'preview', 'production')),
  activation_evidence_id text not null check (
    activation_evidence_id ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
  ),
  activation_bundle_sha256 text not null check (activation_bundle_sha256 ~ '^[a-f0-9]{64}$'),
  session_issued_at timestamptz not null,
  session_expires_at timestamptz not null,
  grant_id uuid not null references pac_dsd.access_grants(grant_id),
  requested_scope_id text not null references pac_dsd.program_scopes(scope_id),
  effective_grant_scope_id text not null references pac_dsd.program_scopes(scope_id),
  required_role_key text not null check (
    required_role_key in (
      'content_contributor', 'program_steward', 'publishing_approver',
      'equity_director', 'one_dsd_team_member', 'owner'
    )
  ),
  effective_grant_role_key text not null,
  action_kind text not null check (
    action_kind in (
      'account_invite', 'credential_reset_invite', 'invitation_revoke',
      'account_suspend', 'account_reactivate', 'account_revoke',
      'grant_issue', 'grant_revoke', 'contribution_submit',
      'specialist_review', 'approval_record', 'publication_publish',
      'publication_withdraw', 'publication_republish', 'correction_record',
      'protected_upload', 'formal_compliance_record', 'owner_transfer'
    )
  ),
  target_type text not null check (
    target_type in ('account', 'invitation', 'grant', 'content_item', 'content_revision', 'review', 'publication', 'source_object', 'compliance_record')
  ),
  target_id text not null check (
    char_length(target_id) between 1 and 160
    and target_id ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{0,159}$'
  ),
  request_fingerprint text not null check (request_fingerprint ~ '^[a-f0-9]{64}$'),
  authorized_at timestamptz not null default clock_timestamp(),
  authorization_contract_version text not null default 'protected-action-v1'
    check (authorization_contract_version = 'protected-action-v1'),
  check (required_role_key = effective_grant_role_key),
  check (session_expires_at > session_issued_at)
);

create table if not exists pac_dsd.protected_action_consumptions (
  authorization_id uuid primary key references pac_dsd.protected_action_authorizations(authorization_id),
  action_kind text not null,
  result_record_type text not null check (
    result_record_type in (
      'account_state_event', 'owner_transfer', 'invitation', 'grant',
      'content_revision', 'review', 'publication', 'source_object', 'compliance_record'
    )
  ),
  requested_target_id text not null check (
    char_length(requested_target_id) between 1 and 160
    and requested_target_id ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{0,159}$'
  ),
  action_record_id text not null check (
    char_length(action_record_id) between 1 and 160
    and action_record_id ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{0,159}$'
  ),
  consumed_at timestamptz not null default clock_timestamp(),
  unique (action_kind, result_record_type, action_record_id)
);

alter table pac_dsd.program_account_invitations
  add constraint program_account_invitations_authorization_fk
  foreign key (issued_by_authorization_id)
  references pac_dsd.protected_action_authorizations(authorization_id)
  not valid;
alter table pac_dsd.program_account_invitations
  validate constraint program_account_invitations_authorization_fk;

alter table pac_dsd.program_account_state_events
  add constraint program_account_state_activation_invitation_fk
  foreign key (activation_invitation_id)
  references pac_dsd.program_account_invitations(invitation_id)
  not valid;
alter table pac_dsd.program_account_state_events
  validate constraint program_account_state_activation_invitation_fk;

-- All identity, credential metadata, grant/action evidence, and invitation
-- history is append-only. Short-lived bearer-secret tables are removed only by
-- their narrowly scoped lifecycle functions.
do $$
declare
  table_name text;
begin
  foreach table_name in array array[
    'program_accounts',
    'program_account_state_events',
    'program_account_invitations',
    'program_account_invitation_closures',
    'program_account_credentials',
    'protected_action_authorizations',
    'protected_action_consumptions'
  ]
  loop
    execute format('drop trigger if exists immutable_guard on pac_dsd.%I', table_name);
    execute format(
      'create trigger immutable_guard before update or delete on pac_dsd.%I for each row execute function pac_dsd.prevent_immutable_change()',
      table_name
    );
  end loop;
end;
$$;

create or replace function pac_dsd.prevent_protected_access_grant_mutation()
returns trigger
language plpgsql
set search_path = pg_catalog, pac_dsd
as $$
begin
  if tg_op = 'DELETE' then
    raise exception 'Access grants are retained; revoke a grant instead' using errcode = '55000';
  end if;
  if old.grant_contract_version = 'protected-v1' then
    if old.revoked_at is not null
      or new.revoked_at is null
      or (to_jsonb(new) - array[
        'revoked_at', 'revoked_by', 'revoked_by_account_id',
        'revoked_by_session_id', 'revocation_reason'
      ]) is distinct from (to_jsonb(old) - array[
        'revoked_at', 'revoked_by', 'revoked_by_account_id',
        'revoked_by_session_id', 'revocation_reason'
      ]) then
      raise exception 'A protected access grant permits only one attributed revocation' using errcode = '55000';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists protected_access_grant_mutation_guard on pac_dsd.access_grants;
create trigger protected_access_grant_mutation_guard
before update or delete on pac_dsd.access_grants
for each row execute function pac_dsd.prevent_protected_access_grant_mutation();

create unique index if not exists access_grants_one_protected_owner_idx
  on pac_dsd.access_grants(environment, role_key)
  where role_key = 'owner'
    and grant_contract_version = 'protected-v1'
    and revoked_at is null;

create or replace function pac_dsd.assert_program_account_invitation_secret()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  issued timestamptz;
begin
  select invitation.issued_at into issued
  from pac_dsd.program_account_invitations invitation
  where invitation.invitation_id = new.invitation_id;
  if issued is null
    or new.expires_at <= issued + interval '5 minutes'
    or new.expires_at > issued + interval '7 days' then
    raise exception 'Invitation expiry is outside the approved window' using errcode = '22023';
  end if;
  return new;
end;
$$;

drop trigger if exists program_account_invitation_secret_guard
  on pac_dsd.program_account_invitation_secrets;
create trigger program_account_invitation_secret_guard
before insert or update on pac_dsd.program_account_invitation_secrets
for each row execute function pac_dsd.assert_program_account_invitation_secret();

create or replace function pac_dsd.assert_program_account_state_event()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  current_event pac_dsd.program_account_state_events%rowtype;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-account:' || new.account_id::text, 0)
  );
  select state_event.* into current_event
  from pac_dsd.program_account_state_events state_event
  where state_event.account_id = new.account_id
    and not exists (
      select 1 from pac_dsd.program_account_state_events child
      where child.supersedes_account_state_event_id = state_event.account_state_event_id
    )
  order by state_event.account_state_event_id desc
  limit 1;

  if current_event.account_state_event_id is null then
    if new.supersedes_account_state_event_id is not null
      or new.activation_invitation_id is null
      or new.state <> 'active' then
      raise exception 'An account must begin active through its accepted invitation' using errcode = '40001';
    end if;
  else
    if new.supersedes_account_state_event_id is distinct from current_event.account_state_event_id
      or new.activation_invitation_id is not null
      or new.recorded_by_account_id is null
      or new.recorded_by_session_id is null then
      raise exception 'An account-state change must supersede the exact current state' using errcode = '40001';
    end if;
    if current_event.state = 'revoked' then
      raise exception 'A revoked account cannot be reactivated' using errcode = '42501';
    end if;
    if new.state = current_event.state then
      raise exception 'An account-state change must change the current state' using errcode = '22023';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists program_account_state_event_guard on pac_dsd.program_account_state_events;
create trigger program_account_state_event_guard
before insert on pac_dsd.program_account_state_events
for each row execute function pac_dsd.assert_program_account_state_event();

create or replace function pac_dsd.assert_protected_action_consumption()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  selected_authorization pac_dsd.protected_action_authorizations%rowtype;
begin
  select * into selected_authorization
  from pac_dsd.protected_action_authorizations stored
  where stored.authorization_id = new.authorization_id
  for update;
  if selected_authorization.authorization_id is null
    or new.action_kind is distinct from selected_authorization.action_kind
    or new.requested_target_id is distinct from selected_authorization.target_id
    or not (
      (new.action_kind in ('account_suspend', 'account_reactivate', 'account_revoke')
        and new.result_record_type = 'account_state_event')
      or (new.action_kind = 'owner_transfer' and new.result_record_type = 'owner_transfer')
      or (new.action_kind in ('account_invite', 'credential_reset_invite', 'invitation_revoke')
        and new.result_record_type = 'invitation')
      or (new.action_kind in ('grant_issue', 'grant_revoke') and new.result_record_type = 'grant')
      or (new.action_kind in ('contribution_submit', 'correction_record')
        and new.result_record_type = 'content_revision')
      or (new.action_kind in ('specialist_review', 'approval_record') and new.result_record_type = 'review')
      or (new.action_kind in ('publication_publish', 'publication_withdraw', 'publication_republish')
        and new.result_record_type = 'publication')
      or (new.action_kind = 'protected_upload' and new.result_record_type = 'source_object')
      or (new.action_kind = 'formal_compliance_record' and new.result_record_type = 'compliance_record')
    ) then
    raise exception 'Protected action consumption does not match its authorization' using errcode = '22023';
  end if;
  return new;
end;
$$;

create or replace function pac_dsd.assert_protected_action_authorization_shape()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
begin
  if not (
    (new.required_role_key = 'owner'
      and new.action_kind in ('account_invite', 'credential_reset_invite', 'invitation_revoke')
      and new.target_type = 'invitation')
    or (new.required_role_key = 'owner'
      and new.action_kind in ('account_suspend', 'account_reactivate', 'account_revoke', 'owner_transfer')
      and new.target_type = 'account')
    or (new.required_role_key = 'owner'
      and new.action_kind in ('grant_issue', 'grant_revoke')
      and new.target_type = 'grant')
    or (new.required_role_key in ('content_contributor', 'one_dsd_team_member')
      and new.action_kind = 'contribution_submit'
      and new.target_type = 'content_item')
    or (new.required_role_key = 'program_steward'
      and new.action_kind = 'specialist_review'
      and new.target_type = 'content_item')
    or (new.required_role_key = 'program_steward'
      and new.action_kind = 'correction_record'
      and new.target_type = 'content_item')
    or (new.required_role_key = 'publishing_approver'
      and new.action_kind = 'approval_record'
      and new.target_type = 'content_item')
    or (new.required_role_key = 'publishing_approver'
      and new.action_kind in ('publication_publish', 'publication_withdraw', 'publication_republish')
      and new.target_type = 'content_item')
    or (new.required_role_key = 'equity_director'
      and new.action_kind = 'protected_upload'
      and new.target_type = 'source_object')
    or (new.required_role_key = 'equity_director'
      and new.action_kind = 'formal_compliance_record'
      and new.target_type = 'compliance_record')
  ) then
    raise exception 'Protected action role, action, and target do not match the approved matrix'
      using errcode = '22023';
  end if;
  return new;
end;
$$;

drop trigger if exists protected_action_authorization_shape_guard
  on pac_dsd.protected_action_authorizations;
create trigger protected_action_authorization_shape_guard
before insert on pac_dsd.protected_action_authorizations
for each row execute function pac_dsd.assert_protected_action_authorization_shape();

create or replace function pac_dsd.protected_action_fingerprint(
  requested_action_kind text,
  requested_payload jsonb
)
returns text
language sql
immutable
security definer
set search_path = pg_catalog, pac_dsd
as $$
  select encode(pac_dsd.digest(convert_to(
    jsonb_build_object(
      'domain', 'pac_dsd:protected-action-request:db-v2',
      'actionKind', requested_action_kind,
      'payload', requested_payload
    )::text,
    'UTF8'
  ), 'sha256'), 'hex');
$$;

drop trigger if exists protected_action_consumption_guard on pac_dsd.protected_action_consumptions;
create trigger protected_action_consumption_guard
before insert on pac_dsd.protected_action_consumptions
for each row execute function pac_dsd.assert_protected_action_consumption();

create or replace function pac_dsd.program_account_is_active(requested_account_id uuid)
returns boolean
language sql
stable
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
  select coalesce((
    select state_event.state = 'active'
    from pac_dsd.program_account_state_events state_event
    where state_event.account_id = requested_account_id
    order by state_event.account_state_event_id desc
    limit 1
  ), false);
$$;

create or replace function pac_dsd.lookup_program_login_credential(
  requested_sign_in_id text,
  requested_environment text
)
returns table (
  account_id uuid,
  display_name text,
  credential_id uuid,
  credential_hash text
)
language plpgsql
stable
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
begin
  if requested_sign_in_id is null
    or requested_sign_in_id <> lower(requested_sign_in_id)
    or requested_sign_in_id !~ '^[a-z0-9][a-z0-9._-]{2,63}$'
    or requested_environment not in ('local', 'preview', 'production') then
    return;
  end if;
  return query
  select account.account_id, account.display_name, credential.credential_id, secret.credential_hash
  from pac_dsd.program_accounts account
  join lateral (
    select stored.*
    from pac_dsd.program_account_credentials stored
    where stored.account_id = account.account_id
    order by stored.credential_version desc
    limit 1
  ) credential on true
  join pac_dsd.program_account_credential_secrets secret
    on secret.credential_id = credential.credential_id
  where account.sign_in_id = requested_sign_in_id
    and account.environment = requested_environment
    and pac_dsd.program_account_is_active(account.account_id);
end;
$$;

create or replace function pac_dsd.start_program_account_session(
  requested_account_id uuid,
  requested_credential_id uuid,
  requested_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text
)
returns table (
  session_id uuid,
  account_id uuid,
  display_name text,
  expires_at timestamptz
)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  selected_account pac_dsd.program_accounts%rowtype;
  selected_credential pac_dsd.program_account_credentials%rowtype;
  created_session pac_dsd.program_account_sessions%rowtype;
begin
  if requested_token_digest !~ '^[a-f0-9]{64}$'
    or requested_environment not in ('local', 'preview', 'production')
    or requested_activation_evidence_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
    or requested_activation_bundle_sha256 !~ '^[a-f0-9]{64}$' then
    raise exception 'Invalid protected-session request' using errcode = '22023';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-account:' || requested_account_id::text, 0)
  );
  select * into selected_account
  from pac_dsd.program_accounts account
  where account.account_id = requested_account_id;
  select * into selected_credential
  from pac_dsd.program_account_credentials credential
  where credential.account_id = requested_account_id
  order by credential.credential_version desc
  limit 1;
  if selected_account.account_id is null
    or selected_account.environment <> requested_environment
    or not pac_dsd.program_account_is_active(requested_account_id)
    or selected_credential.credential_id is distinct from requested_credential_id
    or not exists (
      select 1 from pac_dsd.program_account_credential_secrets secret
      where secret.credential_id = requested_credential_id
    ) then
    raise exception 'Protected sign-in is not available' using errcode = '42501';
  end if;
  insert into pac_dsd.program_account_sessions (
    account_id, credential_id, token_digest, audience, environment,
    activation_evidence_id, activation_bundle_sha256, expires_at
  ) values (
    requested_account_id,
    requested_credential_id,
    requested_token_digest,
    'pac-protected-workspace',
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256,
    clock_timestamp() + interval '8 hours'
  ) returning * into created_session;
  return query select
    created_session.session_id,
    selected_account.account_id,
    selected_account.display_name,
    created_session.expires_at;
end;
$$;

create or replace function pac_dsd.read_program_account_session(
  requested_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text
)
returns table (
  session_id uuid,
  account_id uuid,
  sign_in_id text,
  display_name text,
  credential_id uuid,
  issued_at timestamptz,
  expires_at timestamptz,
  grants jsonb
)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
begin
  if requested_token_digest !~ '^[a-f0-9]{64}$'
    or requested_environment not in ('local', 'preview', 'production')
    or requested_activation_evidence_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
    or requested_activation_bundle_sha256 !~ '^[a-f0-9]{64}$' then
    return;
  end if;
  return query
  select
    session.session_id,
    account.account_id,
    account.sign_in_id,
    account.display_name,
    session.credential_id,
    session.issued_at,
    session.expires_at,
    coalesce((
      select jsonb_agg(jsonb_build_object(
        'grant_id', grant_record.grant_id,
        'scope_id', grant_record.scope_id,
        'role_key', grant_record.role_key,
        'expires_at', grant_record.expires_at
      ) order by grant_record.scope_id, grant_record.role_key, grant_record.grant_id)
      from pac_dsd.access_grants grant_record
      where grant_record.account_id = account.account_id
        and grant_record.environment = requested_environment
        and grant_record.grant_contract_version = 'protected-v1'
        and grant_record.revoked_at is null
        and (grant_record.expires_at is null or grant_record.expires_at > statement_timestamp())
    ), '[]'::jsonb)
  from pac_dsd.program_account_sessions session
  join pac_dsd.program_accounts account on account.account_id = session.account_id
  join pac_dsd.program_account_credentials credential
    on credential.credential_id = session.credential_id
  where session.token_digest = requested_token_digest
    and session.environment = requested_environment
    and session.activation_evidence_id = requested_activation_evidence_id
    and session.activation_bundle_sha256 = requested_activation_bundle_sha256
    and account.environment = requested_environment
    and session.audience = 'pac-protected-workspace'
    and session.expires_at > statement_timestamp()
    and pac_dsd.program_account_is_active(account.account_id)
    and not exists (
      select 1 from pac_dsd.program_account_session_revocations revoked
      where revoked.session_id = session.session_id
    )
    and credential.credential_version = (
      select max(latest.credential_version)
      from pac_dsd.program_account_credentials latest
      where latest.account_id = account.account_id
    )
    and exists (
      select 1 from pac_dsd.program_account_credential_secrets secret
      where secret.credential_id = credential.credential_id
    );
end;
$$;

create or replace function pac_dsd.end_program_account_session(
  requested_token_digest text,
  requested_environment text
)
returns boolean
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  selected_session pac_dsd.program_account_sessions%rowtype;
begin
  if requested_token_digest !~ '^[a-f0-9]{64}$'
    or requested_environment not in ('local', 'preview', 'production') then
    return false;
  end if;
  select * into selected_session
  from pac_dsd.program_account_sessions session
  where session.token_digest = requested_token_digest
    and session.environment = requested_environment
  for update;
  if selected_session.session_id is null then return false; end if;
  insert into pac_dsd.program_account_session_revocations (
    session_id, reason, revoked_by_account_id, revoked_by_session_id
  ) values (
    selected_session.session_id,
    'Signed out by the account holder.',
    selected_session.account_id,
    selected_session.session_id
  ) on conflict (session_id) do nothing;
  return true;
end;
$$;

create or replace function pac_dsd.bootstrap_program_owner_invitation(
  requested_environment text,
  requested_sign_in_id text,
  requested_display_name text,
  requested_token_digest text,
  requested_expires_at timestamptz,
  requested_evidence_id text,
  requested_activation_bundle_sha256 text
)
returns table (invitation_id uuid, expires_at timestamptz)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  created_invitation_id uuid := gen_random_uuid();
begin
  if session_user in ('pac_dsd_contributor_runtime', 'anon', 'authenticated') then
    raise exception 'Owner bootstrap requires the migration-owner connection' using errcode = '42501';
  end if;
  if requested_sign_in_id is null
    or requested_sign_in_id <> lower(requested_sign_in_id)
    or requested_sign_in_id !~ '^[a-z0-9][a-z0-9._-]{2,63}$'
    or requested_display_name is null
    or requested_display_name <> btrim(requested_display_name)
    or char_length(requested_display_name) not between 2 and 120
    or requested_display_name ~ '[[:cntrl:]]'
    or requested_token_digest !~ '^[a-f0-9]{64}$'
    or requested_environment not in ('local', 'preview', 'production')
    or requested_evidence_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
    or requested_activation_bundle_sha256 !~ '^[a-f0-9]{64}$'
    or requested_expires_at <= clock_timestamp() + interval '5 minutes'
    or requested_expires_at > clock_timestamp() + interval '7 days' then
    raise exception 'Invalid owner-bootstrap invitation' using errcode = '22023';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-owner-bootstrap:' || requested_environment, 0)
  );
  if exists (
    select 1 from pac_dsd.access_grants grant_record
    where grant_record.role_key = 'owner'
      and grant_record.scope_id = 'one-dhs-pac'
      and grant_record.environment = requested_environment
      and grant_record.grant_contract_version = 'protected-v1'
  ) or exists (
    select 1
    from pac_dsd.program_account_invitations invitation
    left join pac_dsd.program_account_invitation_closures closure
      on closure.invitation_id = invitation.invitation_id
    where invitation.invitation_type = 'bootstrap_owner'
      and invitation.environment = requested_environment
      and closure.invitation_id is null
  ) then
    raise exception 'The one-time program-owner bootstrap is already claimed or pending' using errcode = '42501';
  end if;
  if exists (
    select 1 from pac_dsd.program_accounts account
    where account.sign_in_id = requested_sign_in_id
      and account.environment = requested_environment
  ) then
    raise exception 'The requested sign-in identifier is not available' using errcode = '23505';
  end if;
  insert into pac_dsd.program_account_invitations (
    invitation_id, environment, activation_evidence_id, activation_bundle_sha256,
    invitation_type, sign_in_id, display_name, bootstrap_evidence_id
  ) values (
    created_invitation_id,
    requested_environment,
    requested_evidence_id,
    requested_activation_bundle_sha256,
    'bootstrap_owner',
    requested_sign_in_id,
    requested_display_name,
    requested_evidence_id
  );
  insert into pac_dsd.program_account_invitation_secrets (
    invitation_id, token_digest, expires_at
  ) values (
    created_invitation_id, requested_token_digest, requested_expires_at
  );
  return query select created_invitation_id, requested_expires_at;
end;
$$;

create or replace function pac_dsd.accept_program_account_invitation(
  requested_token_digest text,
  requested_credential_hash text,
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text
)
returns table (
  session_id uuid,
  account_id uuid,
  sign_in_id text,
  display_name text,
  expires_at timestamptz,
  bootstrap_owner boolean
)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  selected_invitation pac_dsd.program_account_invitations%rowtype;
  selected_secret pac_dsd.program_account_invitation_secrets%rowtype;
  selected_account pac_dsd.program_accounts%rowtype;
  created_account_id uuid;
  created_credential_id uuid := gen_random_uuid();
  created_session_id uuid := gen_random_uuid();
  next_credential_version integer;
  session_expiry timestamptz := clock_timestamp() + interval '8 hours';
  is_bootstrap boolean := false;
begin
  if requested_token_digest !~ '^[a-f0-9]{64}$'
    or requested_session_token_digest !~ '^[a-f0-9]{64}$'
    or requested_token_digest = requested_session_token_digest
    or requested_environment not in ('local', 'preview', 'production')
    or requested_activation_evidence_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
    or requested_activation_bundle_sha256 !~ '^[a-f0-9]{64}$'
    or requested_credential_hash !~ E'^\\$pac-scrypt\\$v=1\\$ln=17\\$r=8\\$p=1\\$[A-Za-z0-9_-]{22}\\$[A-Za-z0-9_-]{43}$' then
    raise exception 'Invalid invitation acceptance request' using errcode = '22023';
  end if;
  -- Discover only the immutable lock key before taking a row lock. Every path
  -- that invalidates an invitation takes its canonical advisory lock before it
  -- touches the bearer-secret row; acceptance must use the same order to avoid
  -- a secret-row/account-lock deadlock with reset, recovery, state, or transfer.
  select invitation.* into selected_invitation
  from pac_dsd.program_account_invitation_secrets secret
  join pac_dsd.program_account_invitations invitation
    on invitation.invitation_id = secret.invitation_id
  where secret.token_digest = requested_token_digest;
  if selected_invitation.invitation_id is null then
    raise exception 'Invitation is invalid or no longer available' using errcode = '42501';
  end if;

  if selected_invitation.invitation_type = 'bootstrap_owner' then
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'pac-program-owner-bootstrap:' || selected_invitation.environment,
        0
      )
    );
  elsif selected_invitation.invitation_type = 'new_account' then
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'pac-program-sign-in:' || selected_invitation.environment || ':' || selected_invitation.sign_in_id,
        0
      )
    );
  elsif selected_invitation.invitation_type in ('credential_reset', 'owner_recovery') then
    if selected_invitation.target_account_id is null then
      raise exception 'Invitation is invalid or no longer available' using errcode = '42501';
    end if;
    if selected_invitation.invitation_type = 'owner_recovery' then
      perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
          'pac-program-owner:' || selected_invitation.environment,
          0
        )
      );
    end if;
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'pac-program-account:' || selected_invitation.target_account_id::text,
        0
      )
    );
  else
    raise exception 'Invitation is invalid or no longer available' using errcode = '42501';
  end if;

  select secret.* into selected_secret
  from pac_dsd.program_account_invitation_secrets secret
  where secret.token_digest = requested_token_digest
  for update;
  if selected_secret.invitation_id is null then
    raise exception 'Invitation is invalid or no longer available' using errcode = '42501';
  end if;
  select invitation.* into selected_invitation
  from pac_dsd.program_account_invitations invitation
  where invitation.invitation_id = selected_secret.invitation_id;
  if selected_invitation.invitation_id is null
    or selected_invitation.environment <> requested_environment
    or selected_invitation.activation_evidence_id <> requested_activation_evidence_id
    or selected_invitation.activation_bundle_sha256 <> requested_activation_bundle_sha256
    or selected_secret.expires_at <= clock_timestamp()
    or exists (
      select 1 from pac_dsd.program_account_invitation_closures closure
      where closure.invitation_id = selected_invitation.invitation_id
    ) then
    raise exception 'Invitation is invalid or no longer available' using errcode = '42501';
  end if;

  if selected_invitation.invitation_type in ('bootstrap_owner', 'new_account') then
    if exists (
      select 1 from pac_dsd.program_accounts account
      where account.sign_in_id = selected_invitation.sign_in_id
        and account.environment = requested_environment
    ) then
      raise exception 'The invited sign-in identifier is no longer available' using errcode = '23505';
    end if;
    if selected_invitation.invitation_type = 'bootstrap_owner' and exists (
      select 1 from pac_dsd.access_grants grant_record
      where grant_record.role_key = 'owner'
        and grant_record.scope_id = 'one-dhs-pac'
        and grant_record.environment = requested_environment
        and grant_record.grant_contract_version = 'protected-v1'
    ) then
      raise exception 'The one-time owner bootstrap has already been completed' using errcode = '42501';
    end if;
    insert into pac_dsd.program_accounts (environment, sign_in_id, display_name)
    values (requested_environment, selected_invitation.sign_in_id, selected_invitation.display_name)
    returning * into selected_account;
    created_account_id := selected_account.account_id;
    insert into pac_dsd.program_account_state_events (
      account_id, state, reason, activation_invitation_id
    ) values (
      created_account_id,
      'active',
      'Account activated by accepting its one-time program invitation.',
      selected_invitation.invitation_id
    );
    next_credential_version := 1;
    is_bootstrap := selected_invitation.invitation_type = 'bootstrap_owner';
  else
    created_account_id := selected_invitation.target_account_id;
    select * into selected_account
    from pac_dsd.program_accounts account
    where account.account_id = created_account_id;
    if selected_account.account_id is null
      or selected_account.environment <> requested_environment
      or selected_account.sign_in_id is distinct from selected_invitation.sign_in_id
      or selected_account.display_name is distinct from selected_invitation.display_name
      or not pac_dsd.program_account_is_active(created_account_id) then
      raise exception 'The credential-reset invitation is no longer valid' using errcode = '42501';
    end if;
    if selected_invitation.invitation_type = 'owner_recovery'
      and not exists (
        select 1
        from pac_dsd.access_grants owner_grant
        where owner_grant.account_id = created_account_id
          and owner_grant.environment = requested_environment
          and owner_grant.scope_id = 'one-dhs-pac'
          and owner_grant.role_key = 'owner'
          and owner_grant.grant_contract_version = 'protected-v1'
          and owner_grant.revoked_at is null
          and (owner_grant.expires_at is null or owner_grant.expires_at > clock_timestamp())
          and owner_grant.granted_at <= selected_invitation.issued_at
      ) then
      raise exception 'The owner-recovery invitation is no longer valid' using errcode = '42501';
    end if;
    select coalesce(max(credential.credential_version), 0) + 1
    into next_credential_version
    from pac_dsd.program_account_credentials credential
    where credential.account_id = created_account_id;
  end if;

  insert into pac_dsd.program_account_credentials (
    credential_id, account_id, credential_version, invitation_id
  ) values (
    created_credential_id,
    created_account_id,
    next_credential_version,
    selected_invitation.invitation_id
  );
  delete from pac_dsd.program_account_credential_secrets secret
  using pac_dsd.program_account_credentials credential
  where secret.credential_id = credential.credential_id
    and credential.account_id = created_account_id;
  insert into pac_dsd.program_account_credential_secrets (credential_id, credential_hash)
  values (created_credential_id, requested_credential_hash);

  insert into pac_dsd.program_account_sessions (
    session_id, account_id, credential_id, token_digest, audience, environment,
    activation_evidence_id, activation_bundle_sha256, expires_at
  ) values (
    created_session_id,
    created_account_id,
    created_credential_id,
    requested_session_token_digest,
    'pac-protected-workspace',
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256,
    session_expiry
  );

  if selected_invitation.invitation_type in ('credential_reset', 'owner_recovery') then
    insert into pac_dsd.program_account_invitation_closures (
      invitation_id, outcome, closed_by_account_id, closed_by_session_id, reason
    )
    select sibling.invitation_id,
      'revoked',
      created_account_id,
      created_session_id,
      'A newer credential reset was accepted; this earlier reset code was invalidated.'
    from pac_dsd.program_account_invitations sibling
    join pac_dsd.program_account_invitation_secrets sibling_secret
      on sibling_secret.invitation_id = sibling.invitation_id
    where sibling.invitation_type in ('credential_reset', 'owner_recovery')
      and sibling.target_account_id = created_account_id
      and sibling.environment = requested_environment
      and sibling.invitation_id <> selected_invitation.invitation_id
      and not exists (
        select 1 from pac_dsd.program_account_invitation_closures closure
        where closure.invitation_id = sibling.invitation_id
      )
    on conflict on constraint program_account_invitation_closures_pkey do nothing;
    delete from pac_dsd.program_account_invitation_secrets sibling_secret
    using pac_dsd.program_account_invitations sibling,
      pac_dsd.program_account_invitation_closures closure
    where sibling_secret.invitation_id = sibling.invitation_id
      and closure.invitation_id = sibling.invitation_id
      and sibling.invitation_type in ('credential_reset', 'owner_recovery')
      and sibling.target_account_id = created_account_id
      and sibling.environment = requested_environment
      and sibling.invitation_id <> selected_invitation.invitation_id;
  end if;

  if is_bootstrap then
    insert into pac_dsd.access_grants (
      principal_id, scope_id, role_key, granted_by, account_id, environment,
      issued_by_account_id, issued_by_session_id, grant_reason,
      grant_contract_version
    ) values (
      created_account_id::text,
      'one-dhs-pac',
      'owner',
      created_account_id::text,
      created_account_id,
      requested_environment,
      created_account_id,
      created_session_id,
      'One-time owner bootstrap accepted under the recorded activation evidence.',
      'protected-v1'
    );
  end if;

  insert into pac_dsd.program_account_invitation_closures (
    invitation_id, outcome, account_id, reason
  ) values (
    selected_invitation.invitation_id,
    'accepted',
    created_account_id,
    'One-time invitation accepted and its bearer secret destroyed.'
  );
  delete from pac_dsd.program_account_invitation_secrets
  where invitation_id = selected_invitation.invitation_id;

  return query select
    created_session_id,
    selected_account.account_id,
    selected_account.sign_in_id,
    selected_account.display_name,
    session_expiry,
    is_bootstrap;
end;
$$;

create or replace function pac_dsd.authorize_protected_action(
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text,
  requested_scope_id text,
  requested_role_key text,
  requested_action_kind text,
  requested_target_type text,
  requested_target_id text,
  requested_fingerprint text
)
returns uuid
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  selected_session pac_dsd.program_account_sessions%rowtype;
  selected_credential pac_dsd.program_account_credentials%rowtype;
  selected_grant pac_dsd.access_grants%rowtype;
  selected_grant_id uuid;
  created_authorization_id uuid;
begin
  if requested_session_token_digest !~ '^[a-f0-9]{64}$'
    or requested_environment not in ('local', 'preview', 'production')
    or requested_activation_evidence_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
    or requested_activation_bundle_sha256 !~ '^[a-f0-9]{64}$'
    or requested_role_key not in (
      'content_contributor', 'program_steward', 'publishing_approver',
      'equity_director', 'one_dsd_team_member', 'owner'
    )
    or requested_action_kind not in (
      'account_invite', 'credential_reset_invite', 'invitation_revoke',
      'account_suspend', 'account_reactivate', 'account_revoke',
      'grant_issue', 'grant_revoke', 'contribution_submit',
      'specialist_review', 'approval_record', 'publication_publish',
      'publication_withdraw', 'publication_republish', 'correction_record',
      'protected_upload', 'formal_compliance_record', 'owner_transfer'
    )
    or requested_target_type not in (
      'account', 'invitation', 'grant', 'content_item', 'content_revision', 'review',
      'publication', 'source_object', 'compliance_record'
    )
    or requested_target_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{0,159}$'
    or requested_fingerprint !~ '^[a-f0-9]{64}$' then
    raise exception 'Invalid protected-action authorization request' using errcode = '22023';
  end if;

  select * into selected_session
  from pac_dsd.program_account_sessions session
  where session.token_digest = requested_session_token_digest
    and session.environment = requested_environment
    and session.activation_evidence_id = requested_activation_evidence_id
    and session.activation_bundle_sha256 = requested_activation_bundle_sha256;
  if selected_session.session_id is null then
    raise exception 'A verified individual session is required' using errcode = 'PAI01';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-account:' || selected_session.account_id::text, 0)
  );
  select * into selected_session
  from pac_dsd.program_account_sessions session
  where session.session_id = selected_session.session_id
  for update;
  select * into selected_credential
  from pac_dsd.program_account_credentials credential
  where credential.account_id = selected_session.account_id
  order by credential.credential_version desc
  limit 1;
  if selected_session.expires_at <= clock_timestamp()
    or selected_session.audience <> 'pac-protected-workspace'
    or exists (
      select 1 from pac_dsd.program_account_session_revocations revoked
      where revoked.session_id = selected_session.session_id
    )
    or not pac_dsd.program_account_is_active(selected_session.account_id)
    or not exists (
      select 1 from pac_dsd.program_accounts account
      where account.account_id = selected_session.account_id
        and account.environment = requested_environment
    )
    or selected_credential.credential_id is distinct from selected_session.credential_id
    or not exists (
      select 1 from pac_dsd.program_account_credential_secrets secret
      where secret.credential_id = selected_session.credential_id
    ) then
    raise exception 'The individual session is expired or revoked' using errcode = 'PAI01';
  end if;

  with recursive ancestry as (
    select scope.scope_id, scope.parent_scope_id, 0 as depth
    from pac_dsd.program_scopes scope
    where scope.scope_id = requested_scope_id and scope.active = true
    union all
    select parent.scope_id, parent.parent_scope_id, child.depth + 1
    from pac_dsd.program_scopes parent
    join ancestry child on child.parent_scope_id = parent.scope_id
    where parent.active = true
  )
  select grant_record.grant_id into selected_grant_id
  from ancestry
  join pac_dsd.access_grants grant_record on grant_record.scope_id = ancestry.scope_id
  where grant_record.account_id = selected_session.account_id
    and grant_record.environment = requested_environment
    and grant_record.principal_id = selected_session.account_id::text
    and grant_record.role_key = requested_role_key
    and grant_record.grant_contract_version = 'protected-v1'
    and grant_record.revoked_at is null
    and (grant_record.expires_at is null or grant_record.expires_at > clock_timestamp())
  order by ancestry.depth, grant_record.granted_at desc, grant_record.grant_id
  limit 1;
  if selected_grant_id is null then
    raise exception 'The individual does not hold the required role for this scope' using errcode = 'PAA01';
  end if;
  select * into selected_grant
  from pac_dsd.access_grants grant_record
  where grant_record.grant_id = selected_grant_id
  for update;
  if selected_grant.revoked_at is not null
    or (selected_grant.expires_at is not null and selected_grant.expires_at <= clock_timestamp())
    or selected_grant.account_id is distinct from selected_session.account_id
    or selected_grant.environment is distinct from requested_environment
    or selected_grant.role_key is distinct from requested_role_key then
    raise exception 'The required grant is no longer active' using errcode = 'PAA01';
  end if;

  insert into pac_dsd.protected_action_authorizations (
    account_id, session_id, credential_id, environment,
    activation_evidence_id, activation_bundle_sha256,
    session_issued_at, session_expires_at,
    grant_id, requested_scope_id,
    effective_grant_scope_id, required_role_key, effective_grant_role_key,
    action_kind, target_type, target_id, request_fingerprint
  ) values (
    selected_session.account_id,
    selected_session.session_id,
    selected_session.credential_id,
    selected_session.environment,
    selected_session.activation_evidence_id,
    selected_session.activation_bundle_sha256,
    selected_session.issued_at,
    selected_session.expires_at,
    selected_grant.grant_id,
    requested_scope_id,
    selected_grant.scope_id,
    requested_role_key,
    selected_grant.role_key,
    requested_action_kind,
    requested_target_type,
    requested_target_id,
    requested_fingerprint
  ) returning authorization_id into created_authorization_id;
  return created_authorization_id;
end;
$$;

create or replace function pac_dsd.consume_protected_action(
  requested_authorization_id uuid,
  requested_result_record_type text,
  requested_action_record_id text
)
returns void
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  selected_authorization pac_dsd.protected_action_authorizations%rowtype;
begin
  select * into selected_authorization
  from pac_dsd.protected_action_authorizations stored
  where stored.authorization_id = requested_authorization_id
  for update;
  if selected_authorization.authorization_id is null
    or requested_result_record_type not in (
      'account_state_event', 'owner_transfer', 'invitation', 'grant',
      'content_revision', 'review', 'publication', 'source_object', 'compliance_record'
    )
    or requested_action_record_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{0,159}$' then
    raise exception 'Invalid protected-action consumption' using errcode = '22023';
  end if;
  insert into pac_dsd.protected_action_consumptions (
    authorization_id, action_kind, result_record_type, requested_target_id, action_record_id
  ) values (
    selected_authorization.authorization_id,
    selected_authorization.action_kind,
    requested_result_record_type,
    selected_authorization.target_id,
    requested_action_record_id
  );
end;
$$;

create or replace function pac_dsd.create_program_account_invitation(
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text,
  requested_sign_in_id text,
  requested_display_name text,
  requested_token_digest text,
  requested_expires_at timestamptz
)
returns table (invitation_id uuid, expires_at timestamptz)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  created_invitation_id uuid := gen_random_uuid();
  created_authorization_id uuid;
begin
  if requested_sign_in_id is null
    or requested_sign_in_id <> lower(requested_sign_in_id)
    or requested_sign_in_id !~ '^[a-z0-9][a-z0-9._-]{2,63}$'
    or requested_display_name is null
    or requested_display_name <> btrim(requested_display_name)
    or char_length(requested_display_name) not between 2 and 120
    or requested_display_name ~ '[[:cntrl:]]'
    or requested_token_digest !~ '^[a-f0-9]{64}$'
    or requested_expires_at <= clock_timestamp() + interval '5 minutes'
    or requested_expires_at > clock_timestamp() + interval '7 days' then
    raise exception 'Invalid account invitation' using errcode = '22023';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'pac-program-sign-in:' || requested_environment || ':' || requested_sign_in_id,
      0
    )
  );
  created_authorization_id := pac_dsd.authorize_protected_action(
    requested_session_token_digest,
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256,
    'one-dhs-pac',
    'owner',
    'account_invite',
    'invitation',
    created_invitation_id::text,
    pac_dsd.protected_action_fingerprint(
      'account_invite',
      jsonb_build_object(
        'environment', requested_environment,
        'invitationId', created_invitation_id,
        'signInId', requested_sign_in_id,
        'displayName', requested_display_name,
        'expiresAt', requested_expires_at
      )
    )
  );
  if exists (
    select 1 from pac_dsd.program_accounts account
    where account.sign_in_id = requested_sign_in_id
      and account.environment = requested_environment
  ) or exists (
    select 1
    from pac_dsd.program_account_invitations invitation
    join pac_dsd.program_account_invitation_secrets secret
      on secret.invitation_id = invitation.invitation_id
    where invitation.sign_in_id = requested_sign_in_id
      and invitation.environment = requested_environment
      and secret.expires_at > clock_timestamp()
  ) then
    raise exception 'The requested sign-in identifier is not available' using errcode = '23505';
  end if;
  insert into pac_dsd.program_account_invitations (
    invitation_id, environment, activation_evidence_id, activation_bundle_sha256,
    invitation_type, sign_in_id, display_name,
    issued_by_authorization_id
  ) values (
    created_invitation_id,
    requested_environment,
    (select stored.activation_evidence_id from pac_dsd.protected_action_authorizations stored
      where stored.authorization_id = created_authorization_id),
    (select stored.activation_bundle_sha256 from pac_dsd.protected_action_authorizations stored
      where stored.authorization_id = created_authorization_id),
    'new_account',
    requested_sign_in_id,
    requested_display_name,
    created_authorization_id
  );
  insert into pac_dsd.program_account_invitation_secrets (
    invitation_id, token_digest, expires_at
  ) values (
    created_invitation_id, requested_token_digest, requested_expires_at
  );
  perform pac_dsd.consume_protected_action(created_authorization_id, 'invitation', created_invitation_id::text);
  return query select created_invitation_id, requested_expires_at;
end;
$$;

create or replace function pac_dsd.create_program_credential_reset_invitation(
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text,
  requested_account_id uuid,
  requested_token_digest text,
  requested_expires_at timestamptz
)
returns table (invitation_id uuid, expires_at timestamptz)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  created_invitation_id uuid := gen_random_uuid();
  created_authorization_id uuid;
  selected_authorization pac_dsd.protected_action_authorizations%rowtype;
  selected_account pac_dsd.program_accounts%rowtype;
begin
  if requested_token_digest !~ '^[a-f0-9]{64}$'
    or requested_expires_at <= clock_timestamp() + interval '5 minutes'
    or requested_expires_at > clock_timestamp() + interval '24 hours' then
    raise exception 'Invalid credential-reset invitation' using errcode = '22023';
  end if;
  created_authorization_id := pac_dsd.authorize_protected_action(
    requested_session_token_digest,
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256,
    'one-dhs-pac',
    'owner',
    'credential_reset_invite',
    'invitation',
    created_invitation_id::text,
    pac_dsd.protected_action_fingerprint(
      'credential_reset_invite',
      jsonb_build_object(
        'environment', requested_environment,
        'invitationId', created_invitation_id,
        'accountId', requested_account_id,
        'expiresAt', requested_expires_at
      )
    )
  );
  select * into selected_authorization
  from pac_dsd.protected_action_authorizations stored
  where stored.authorization_id = created_authorization_id;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-account:' || requested_account_id::text, 0)
  );
  select * into selected_account
  from pac_dsd.program_accounts account
  where account.account_id = requested_account_id
    and account.environment = requested_environment;
  if selected_account.account_id is null or not pac_dsd.program_account_is_active(requested_account_id) then
    raise exception 'The account is not available for credential reset' using errcode = '42501';
  end if;
  insert into pac_dsd.program_account_invitation_closures (
    invitation_id, outcome, closed_by_account_id, closed_by_session_id, reason
  )
  select prior.invitation_id,
    'revoked',
    selected_authorization.account_id,
    selected_authorization.session_id,
    'A newer credential-reset invitation replaced this code.'
  from pac_dsd.program_account_invitations prior
  join pac_dsd.program_account_invitation_secrets prior_secret
    on prior_secret.invitation_id = prior.invitation_id
  where prior.invitation_type in ('credential_reset', 'owner_recovery')
    and prior.target_account_id = requested_account_id
    and prior.environment = requested_environment
    and not exists (
      select 1 from pac_dsd.program_account_invitation_closures closure
      where closure.invitation_id = prior.invitation_id
    )
  on conflict on constraint program_account_invitation_closures_pkey do nothing;
  delete from pac_dsd.program_account_invitation_secrets prior_secret
  using pac_dsd.program_account_invitations prior,
    pac_dsd.program_account_invitation_closures closure
  where prior_secret.invitation_id = prior.invitation_id
    and closure.invitation_id = prior.invitation_id
    and prior.invitation_type in ('credential_reset', 'owner_recovery')
    and prior.target_account_id = requested_account_id
    and prior.environment = requested_environment;
  insert into pac_dsd.program_account_invitations (
    invitation_id, environment, activation_evidence_id, activation_bundle_sha256,
    invitation_type, sign_in_id, display_name,
    target_account_id, issued_by_authorization_id
  ) values (
    created_invitation_id,
    requested_environment,
    (select stored.activation_evidence_id from pac_dsd.protected_action_authorizations stored
      where stored.authorization_id = created_authorization_id),
    (select stored.activation_bundle_sha256 from pac_dsd.protected_action_authorizations stored
      where stored.authorization_id = created_authorization_id),
    'credential_reset',
    selected_account.sign_in_id,
    selected_account.display_name,
    selected_account.account_id,
    created_authorization_id
  );
  insert into pac_dsd.program_account_invitation_secrets (
    invitation_id, token_digest, expires_at
  ) values (
    created_invitation_id, requested_token_digest, requested_expires_at
  );
  perform pac_dsd.consume_protected_action(created_authorization_id, 'invitation', created_invitation_id::text);
  return query select created_invitation_id, requested_expires_at;
end;
$$;

create or replace function pac_dsd.issue_program_access_grant(
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text,
  requested_account_id uuid,
  requested_scope_id text,
  requested_role_key text,
  requested_expires_at timestamptz,
  requested_reason text
)
returns table (
  grant_id uuid,
  account_id uuid,
  scope_id text,
  role_key text,
  granted_at timestamptz,
  expires_at timestamptz
)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  created_grant_id uuid := gen_random_uuid();
  created_authorization_id uuid;
  selected_authorization pac_dsd.protected_action_authorizations%rowtype;
  created_grant pac_dsd.access_grants%rowtype;
begin
  if requested_role_key not in (
      'content_contributor', 'program_steward', 'publishing_approver',
      'one_dsd_team_member'
    )
    or (
      requested_role_key in ('content_contributor', 'program_steward', 'publishing_approver')
      and requested_scope_id not in ('one-dhs', 'dsd')
    )
    or (requested_role_key = 'one_dsd_team_member' and requested_scope_id <> 'one-dsd-team')
    or requested_reason is null
    or requested_reason <> btrim(requested_reason)
    or char_length(requested_reason) not between 3 and 500
    or requested_reason ~ '[[:cntrl:]]'
    or (requested_expires_at is not null and requested_expires_at <= clock_timestamp()) then
    raise exception 'Invalid role/scope grant request' using errcode = '22023';
  end if;
  created_authorization_id := pac_dsd.authorize_protected_action(
    requested_session_token_digest,
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256,
    requested_scope_id,
    'owner',
    'grant_issue',
    'grant',
    created_grant_id::text,
    pac_dsd.protected_action_fingerprint(
      'grant_issue',
      jsonb_build_object(
        'environment', requested_environment,
        'grantId', created_grant_id,
        'accountId', requested_account_id,
        'scopeId', requested_scope_id,
        'roleKey', requested_role_key,
        'expiresAt', requested_expires_at,
        'reason', requested_reason
      )
    )
  );
  select * into selected_authorization
  from pac_dsd.protected_action_authorizations stored
  where stored.authorization_id = created_authorization_id;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-account:' || requested_account_id::text, 0)
  );
  if not exists (
    select 1 from pac_dsd.program_accounts account
    where account.account_id = requested_account_id
      and account.environment = requested_environment
  ) or not pac_dsd.program_account_is_active(requested_account_id) then
    raise exception 'The account is not active' using errcode = '42501';
  end if;
  insert into pac_dsd.access_grants (
    grant_id, principal_id, scope_id, role_key, granted_by, account_id, environment,
    expires_at, issued_by_account_id, issued_by_session_id, grant_reason,
    grant_contract_version
  ) values (
    created_grant_id,
    requested_account_id::text,
    requested_scope_id,
    requested_role_key,
    selected_authorization.account_id::text,
    requested_account_id,
    requested_environment,
    requested_expires_at,
    selected_authorization.account_id,
    selected_authorization.session_id,
    requested_reason,
    'protected-v1'
  ) returning * into created_grant;
  perform pac_dsd.consume_protected_action(created_authorization_id, 'grant', created_grant_id::text);
  return query select
    created_grant.grant_id,
    created_grant.account_id,
    created_grant.scope_id,
    created_grant.role_key,
    created_grant.granted_at,
    created_grant.expires_at;
end;
$$;

create or replace function pac_dsd.revoke_program_access_grant(
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text,
  requested_grant_id uuid,
  requested_reason text
)
returns boolean
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  selected_grant pac_dsd.access_grants%rowtype;
  created_authorization_id uuid;
  selected_authorization pac_dsd.protected_action_authorizations%rowtype;
begin
  if requested_reason is null
    or requested_reason <> btrim(requested_reason)
    or char_length(requested_reason) not between 3 and 500
    or requested_reason ~ '[[:cntrl:]]' then
    raise exception 'Invalid grant-revocation reason' using errcode = '22023';
  end if;
  select * into selected_grant
  from pac_dsd.access_grants grant_record
  where grant_record.grant_id = requested_grant_id;
  if selected_grant.grant_id is null
    or selected_grant.grant_contract_version <> 'protected-v1'
    or selected_grant.environment <> requested_environment
    or selected_grant.role_key = 'owner' then
    raise exception 'The protected grant is not revocable through this operation' using errcode = '42501';
  end if;
  created_authorization_id := pac_dsd.authorize_protected_action(
    requested_session_token_digest,
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256,
    selected_grant.scope_id,
    'owner',
    'grant_revoke',
    'grant',
    requested_grant_id::text,
    pac_dsd.protected_action_fingerprint(
      'grant_revoke',
      jsonb_build_object(
        'environment', requested_environment,
        'grantId', requested_grant_id,
        'reason', requested_reason
      )
    )
  );
  select * into selected_authorization
  from pac_dsd.protected_action_authorizations stored
  where stored.authorization_id = created_authorization_id;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-account:' || selected_grant.account_id::text, 0)
  );
  select * into selected_grant
  from pac_dsd.access_grants grant_record
  where grant_record.grant_id = requested_grant_id
  for update;
  if selected_grant.revoked_at is not null then
    raise exception 'The grant has already been revoked' using errcode = '40001';
  end if;
  update pac_dsd.access_grants
  set revoked_at = clock_timestamp(),
      revoked_by = selected_authorization.account_id::text,
      revoked_by_account_id = selected_authorization.account_id,
      revoked_by_session_id = selected_authorization.session_id,
      revocation_reason = requested_reason
  where grant_id = requested_grant_id;
  perform pac_dsd.consume_protected_action(created_authorization_id, 'grant', requested_grant_id::text);
  return true;
end;
$$;

create or replace function pac_dsd.revoke_program_account_invitation(
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text,
  requested_invitation_id uuid,
  requested_reason text
)
returns boolean
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  created_authorization_id uuid;
  selected_authorization pac_dsd.protected_action_authorizations%rowtype;
begin
  if requested_reason is null
    or requested_reason <> btrim(requested_reason)
    or char_length(requested_reason) not between 3 and 500
    or requested_reason ~ '[[:cntrl:]]' then
    raise exception 'Invalid invitation-revocation reason' using errcode = '22023';
  end if;
  if not exists (
    select 1 from pac_dsd.program_account_invitations invitation
    where invitation.invitation_id = requested_invitation_id
      and invitation.environment = requested_environment
  ) then
    raise exception 'The invitation is not available in this environment' using errcode = '42501';
  end if;
  created_authorization_id := pac_dsd.authorize_protected_action(
    requested_session_token_digest,
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256,
    'one-dhs-pac',
    'owner',
    'invitation_revoke',
    'invitation',
    requested_invitation_id::text,
    pac_dsd.protected_action_fingerprint(
      'invitation_revoke',
      jsonb_build_object(
        'environment', requested_environment,
        'invitationId', requested_invitation_id,
        'reason', requested_reason
      )
    )
  );
  select * into selected_authorization
  from pac_dsd.protected_action_authorizations stored
  where stored.authorization_id = created_authorization_id;
  perform 1 from pac_dsd.program_account_invitation_secrets secret
  where secret.invitation_id = requested_invitation_id
  for update;
  if not found or exists (
    select 1 from pac_dsd.program_account_invitation_closures closure
    where closure.invitation_id = requested_invitation_id
  ) then
    raise exception 'The invitation is already closed or unavailable' using errcode = '40001';
  end if;
  insert into pac_dsd.program_account_invitation_closures (
    invitation_id, outcome, closed_by_account_id, closed_by_session_id, reason
  ) values (
    requested_invitation_id,
    'revoked',
    selected_authorization.account_id,
    selected_authorization.session_id,
    requested_reason
  );
  delete from pac_dsd.program_account_invitation_secrets
  where invitation_id = requested_invitation_id;
  perform pac_dsd.consume_protected_action(created_authorization_id, 'invitation', requested_invitation_id::text);
  return true;
end;
$$;

create or replace function pac_dsd.change_program_account_state(
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text,
  requested_account_id uuid,
  requested_state text,
  requested_reason text
)
returns table (account_state_event_id bigint, state text, recorded_at timestamptz)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  action_kind text;
  created_authorization_id uuid;
  selected_authorization pac_dsd.protected_action_authorizations%rowtype;
  current_event pac_dsd.program_account_state_events%rowtype;
  created_event pac_dsd.program_account_state_events%rowtype;
begin
  action_kind := case requested_state
    when 'suspended' then 'account_suspend'
    when 'active' then 'account_reactivate'
    when 'revoked' then 'account_revoke'
    else null
  end;
  if action_kind is null
    or requested_reason is null
    or requested_reason <> btrim(requested_reason)
    or char_length(requested_reason) not between 3 and 500
    or (requested_state = 'revoked' and char_length(requested_reason) > 483)
    or requested_reason ~ '[[:cntrl:]]' then
    raise exception 'Invalid account-state request' using errcode = '22023';
  end if;
  created_authorization_id := pac_dsd.authorize_protected_action(
    requested_session_token_digest,
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256,
    'one-dhs-pac',
    'owner',
    action_kind,
    'account',
    requested_account_id::text,
    pac_dsd.protected_action_fingerprint(
      action_kind,
      jsonb_build_object(
        'environment', requested_environment,
        'accountId', requested_account_id,
        'state', requested_state,
        'reason', requested_reason
      )
    )
  );
  select * into selected_authorization
  from pac_dsd.protected_action_authorizations stored
  where stored.authorization_id = created_authorization_id;
  if requested_account_id = selected_authorization.account_id then
    raise exception 'The global owner cannot change the state of the active owner account from its own session' using errcode = '42501';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-account:' || requested_account_id::text, 0)
  );
  if not exists (
    select 1 from pac_dsd.program_accounts account
    where account.account_id = requested_account_id
      and account.environment = requested_environment
  ) then
    raise exception 'The account is not available in this environment' using errcode = '42501';
  end if;
  select * into current_event
  from pac_dsd.program_account_state_events state_event
  where state_event.account_id = requested_account_id
  order by state_event.account_state_event_id desc
  limit 1;
  if current_event.account_state_event_id is null then
    raise exception 'The account does not exist' using errcode = 'P0002';
  end if;
  insert into pac_dsd.program_account_state_events (
    account_id, state, reason, recorded_by_account_id, recorded_by_session_id,
    supersedes_account_state_event_id
  ) values (
    requested_account_id,
    requested_state,
    requested_reason,
    selected_authorization.account_id,
    selected_authorization.session_id,
    current_event.account_state_event_id
  ) returning * into created_event;
  insert into pac_dsd.program_account_invitation_closures (
    invitation_id, outcome, closed_by_account_id, closed_by_session_id, reason
  )
  select reset_invitation.invitation_id,
    'revoked',
    selected_authorization.account_id,
    selected_authorization.session_id,
    'The account state changed; every earlier credential-reset code was invalidated.'
  from pac_dsd.program_account_invitations reset_invitation
  join pac_dsd.program_account_invitation_secrets reset_secret
    on reset_secret.invitation_id = reset_invitation.invitation_id
  where reset_invitation.invitation_type in ('credential_reset', 'owner_recovery')
    and reset_invitation.target_account_id = requested_account_id
    and reset_invitation.environment = requested_environment
    and not exists (
      select 1 from pac_dsd.program_account_invitation_closures closure
      where closure.invitation_id = reset_invitation.invitation_id
    )
  on conflict on constraint program_account_invitation_closures_pkey do nothing;
  delete from pac_dsd.program_account_invitation_secrets reset_secret
  using pac_dsd.program_account_invitations reset_invitation,
    pac_dsd.program_account_invitation_closures closure
  where reset_secret.invitation_id = reset_invitation.invitation_id
    and closure.invitation_id = reset_invitation.invitation_id
    and reset_invitation.invitation_type in ('credential_reset', 'owner_recovery')
    and reset_invitation.target_account_id = requested_account_id
    and reset_invitation.environment = requested_environment;

  insert into pac_dsd.program_account_session_revocations (
    session_id, reason, revoked_by_account_id, revoked_by_session_id
  )
  select session.session_id,
    'Account state changed; a fresh sign-in is required.',
    selected_authorization.account_id,
    selected_authorization.session_id
  from pac_dsd.program_account_sessions session
  where session.account_id = requested_account_id
    and not exists (
      select 1 from pac_dsd.program_account_session_revocations revoked
      where revoked.session_id = session.session_id
    );

  if requested_state = 'revoked' then
    delete from pac_dsd.program_account_credential_secrets secret
    using pac_dsd.program_account_credentials credential
    where secret.credential_id = credential.credential_id
      and credential.account_id = requested_account_id;
    update pac_dsd.access_grants
    set revoked_at = clock_timestamp(),
        revoked_by = selected_authorization.account_id::text,
        revoked_by_account_id = selected_authorization.account_id,
        revoked_by_session_id = selected_authorization.session_id,
        revocation_reason = 'Account revoked: ' || requested_reason
    where account_id = requested_account_id
      and grant_contract_version = 'protected-v1'
      and revoked_at is null
      and role_key <> 'owner';
  end if;
  perform pac_dsd.consume_protected_action(
    created_authorization_id,
    'account_state_event',
    created_event.account_state_event_id::text
  );
  return query select
    created_event.account_state_event_id,
    created_event.state,
    created_event.recorded_at;
end;
$$;

create or replace function pac_dsd.relinquish_program_owner(
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text,
  requested_reason text,
  requested_fingerprint text
)
returns boolean
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  created_authorization_id uuid;
  selected_authorization pac_dsd.protected_action_authorizations%rowtype;
  selected_account_id uuid;
  current_event pac_dsd.program_account_state_events%rowtype;
  owner_grant pac_dsd.access_grants%rowtype;
begin
  if requested_reason is null
    or requested_reason <> btrim(requested_reason)
    or char_length(requested_reason) not between 3 and 500
    or requested_reason ~ '[[:cntrl:]]' then
    raise exception 'Invalid owner-revocation reason' using errcode = '22023';
  end if;
  select session.account_id into selected_account_id
  from pac_dsd.program_account_sessions session
  where session.token_digest = requested_session_token_digest
    and session.environment = requested_environment;
  if selected_account_id is null then
    raise exception 'A verified owner session is required' using errcode = '42501';
  end if;
  created_authorization_id := pac_dsd.authorize_protected_action(
    requested_session_token_digest,
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256,
    'one-dhs-pac',
    'owner',
    'account_revoke',
    'account',
    selected_account_id::text,
    pac_dsd.protected_action_fingerprint(
      'account_revoke',
      jsonb_build_object(
        'environment', requested_environment,
        'accountId', selected_account_id,
        'reason', requested_reason,
        'operation', 'owner_relinquishment'
      )
    )
  );
  select * into selected_authorization
  from pac_dsd.protected_action_authorizations stored
  where stored.authorization_id = created_authorization_id;
  select * into current_event
  from pac_dsd.program_account_state_events state_event
  where state_event.account_id = selected_authorization.account_id
  order by state_event.account_state_event_id desc
  limit 1;
  select * into owner_grant
  from pac_dsd.access_grants grant_record
  where grant_record.account_id = selected_authorization.account_id
    and grant_record.scope_id = 'one-dhs-pac'
    and grant_record.environment = requested_environment
    and grant_record.role_key = 'owner'
    and grant_record.grant_contract_version = 'protected-v1'
    and grant_record.revoked_at is null
  for update;
  if current_event.account_state_event_id is null or owner_grant.grant_id is null then
    raise exception 'The global owner authority is not active' using errcode = '42501';
  end if;
  insert into pac_dsd.program_account_state_events (
    account_id, state, reason, recorded_by_account_id, recorded_by_session_id,
    supersedes_account_state_event_id
  ) values (
    selected_authorization.account_id,
    'revoked',
    requested_reason,
    selected_authorization.account_id,
    selected_authorization.session_id,
    current_event.account_state_event_id
  );
  update pac_dsd.access_grants
  set revoked_at = clock_timestamp(),
      revoked_by = selected_authorization.account_id::text,
      revoked_by_account_id = selected_authorization.account_id,
      revoked_by_session_id = selected_authorization.session_id,
      revocation_reason = requested_reason
  where account_id = selected_authorization.account_id
    and grant_contract_version = 'protected-v1'
    and revoked_at is null;
  insert into pac_dsd.program_account_session_revocations (
    session_id, reason, revoked_by_account_id, revoked_by_session_id
  )
  select session.session_id,
    'Global owner authority was revoked.',
    selected_authorization.account_id,
    selected_authorization.session_id
  from pac_dsd.program_account_sessions session
  where session.account_id = selected_authorization.account_id
    and not exists (
      select 1 from pac_dsd.program_account_session_revocations revoked
      where revoked.session_id = session.session_id
    );
  perform pac_dsd.consume_protected_action(
    created_authorization_id,
    'account_state_event',
    current_event.account_state_event_id::text
  );
  return true;
end;
$$;

create or replace function pac_dsd.read_program_access_overview(
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  viewer_session_id uuid;
  viewer_account_id uuid;
  result jsonb;
begin
  select session.session_id, session.account_id
  into viewer_session_id, viewer_account_id
  from pac_dsd.read_program_account_session(
    requested_session_token_digest,
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256
  ) session;
  if viewer_session_id is null or not exists (
    select 1
    from pac_dsd.access_grants grant_record
    where grant_record.account_id = viewer_account_id
      and grant_record.scope_id = 'one-dhs-pac'
      and grant_record.environment = requested_environment
      and grant_record.role_key = 'owner'
      and grant_record.grant_contract_version = 'protected-v1'
      and grant_record.revoked_at is null
      and (grant_record.expires_at is null or grant_record.expires_at > statement_timestamp())
  ) then
    raise exception 'Global owner access is required' using errcode = '42501';
  end if;
  select jsonb_build_object(
    'accounts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'account_id', account.account_id,
        'sign_in_id', account.sign_in_id,
        'display_name', account.display_name,
        'state', current_state.state,
        'created_at', account.created_at
      ) order by account.display_name, account.account_id)
      from pac_dsd.program_accounts account
      join lateral (
        select state_event.state
        from pac_dsd.program_account_state_events state_event
        where state_event.account_id = account.account_id
        order by state_event.account_state_event_id desc
        limit 1
      ) current_state on true
      where account.environment = requested_environment
    ), '[]'::jsonb),
    'grants', coalesce((
      select jsonb_agg(jsonb_build_object(
        'grant_id', grant_record.grant_id,
        'account_id', grant_record.account_id,
        'scope_id', grant_record.scope_id,
        'role_key', grant_record.role_key,
        'granted_at', grant_record.granted_at,
        'expires_at', grant_record.expires_at,
        'revoked_at', grant_record.revoked_at
      ) order by grant_record.granted_at, grant_record.grant_id)
      from pac_dsd.access_grants grant_record
      where grant_record.grant_contract_version = 'protected-v1'
        and grant_record.environment = requested_environment
    ), '[]'::jsonb),
    'open_invitations', coalesce((
      select jsonb_agg(jsonb_build_object(
        'invitation_id', invitation.invitation_id,
        'invitation_type', invitation.invitation_type,
        'sign_in_id', invitation.sign_in_id,
        'display_name', invitation.display_name,
        'issued_at', invitation.issued_at,
        'expires_at', secret.expires_at
      ) order by invitation.issued_at, invitation.invitation_id)
      from pac_dsd.program_account_invitations invitation
      join pac_dsd.program_account_invitation_secrets secret
        on secret.invitation_id = invitation.invitation_id
      where secret.expires_at > statement_timestamp()
        and invitation.environment = requested_environment
        and not exists (
          select 1 from pac_dsd.program_account_invitation_closures closure
          where closure.invitation_id = invitation.invitation_id
        )
    ), '[]'::jsonb)
  ) into result;
  return result;
end;
$$;

create or replace function pac_dsd.purge_expired_program_security_records()
returns table (expired_invitations_closed integer, expired_sessions_deleted integer)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  closed_count integer := 0;
  deleted_count integer := 0;
begin
  with candidates as materialized (
    select secret.invitation_id
    from pac_dsd.program_account_invitation_secrets secret
    where secret.expires_at <= clock_timestamp()
    order by secret.expires_at, secret.invitation_id
    for update skip locked
    limit 10000
  ), recorded as (
    insert into pac_dsd.program_account_invitation_closures (
      invitation_id, outcome, reason
    )
    select invitation_id, 'expired', 'Invitation expired before it was accepted.'
    from candidates
    on conflict on constraint program_account_invitation_closures_pkey do nothing
    returning invitation_id
  ), removed as (
    delete from pac_dsd.program_account_invitation_secrets secret
    using candidates
    where secret.invitation_id = candidates.invitation_id
    returning secret.invitation_id
  )
  select count(*)::integer into closed_count from recorded;

  with candidates as materialized (
    select session.session_id
    from pac_dsd.program_account_sessions session
    where session.expires_at <= clock_timestamp() - interval '10 minutes'
    order by session.expires_at, session.session_id
    for update skip locked
    limit 10000
  ), removed as (
    delete from pac_dsd.program_account_sessions session
    using candidates
    where session.session_id = candidates.session_id
    returning session.session_id
  )
  select count(*)::integer into deleted_count from removed;
  expired_invitations_closed := closed_count;
  expired_sessions_deleted := deleted_count;
  return next;
end;
$$;

create or replace function pac_dsd.attest_program_identity_runtime_boundary()
returns table (
  runtime_role text,
  session_role text,
  account_table_denied boolean,
  authorization_allocator_denied boolean,
  authorization_consumer_denied boolean,
  rate_limit_policy_denied boolean
)
language sql
stable
security invoker
set search_path = pg_catalog, pac_dsd
as $$
  select
    current_user::text,
    session_user::text,
    not pg_catalog.has_table_privilege(current_user, 'pac_dsd.program_accounts', 'select'),
    not pg_catalog.has_function_privilege(
      current_user,
      'pac_dsd.authorize_protected_action(text,text,text,text,text,text,text,text,text,text)',
      'execute'
    ),
    not pg_catalog.has_function_privilege(
      current_user,
      'pac_dsd.consume_protected_action(uuid,text,text)',
      'execute'
    ),
    not pg_catalog.has_function_privilege(
      current_user,
      'pac_dsd.assert_runtime_rate_limit_request(text,text,integer,integer)',
      'execute'
    );
$$;

-- The application role can reach only the finite, session-aware entry points.
-- It cannot inspect credential/token tables, manufacture actor identifiers, or
-- call the internal authorization allocator directly.
do $$
declare
  table_name text;
  role_name text;
begin
  foreach table_name in array array[
    'program_accounts',
    'program_account_state_events',
    'program_account_invitations',
    'program_account_invitation_secrets',
    'program_account_invitation_closures',
    'program_account_credentials',
    'program_account_credential_secrets',
    'program_account_sessions',
    'program_account_session_revocations',
    'protected_action_authorizations',
    'protected_action_consumptions'
  ]
  loop
    execute format('alter table pac_dsd.%I enable row level security', table_name);
    execute format('revoke all privileges on pac_dsd.%I from public', table_name);
    if exists (select 1 from pg_catalog.pg_roles where rolname = 'pac_dsd_contributor_runtime') then
      execute format('revoke all privileges on pac_dsd.%I from pac_dsd_contributor_runtime', table_name);
    end if;
    foreach role_name in array array['anon', 'authenticated']
    loop
      if exists (select 1 from pg_catalog.pg_roles where rolname = role_name) then
        execute format('revoke all privileges on pac_dsd.%I from %I', table_name, role_name);
      end if;
    end loop;
  end loop;
end;
$$;

revoke all privileges on function pac_dsd.prevent_protected_access_grant_mutation() from public, pac_dsd_contributor_runtime;
revoke all privileges on function pac_dsd.assert_program_account_invitation_secret() from public, pac_dsd_contributor_runtime;
revoke all privileges on function pac_dsd.assert_program_account_state_event() from public, pac_dsd_contributor_runtime;
revoke all privileges on function pac_dsd.assert_protected_action_consumption() from public, pac_dsd_contributor_runtime;
revoke all privileges on function pac_dsd.program_account_is_active(uuid) from public, pac_dsd_contributor_runtime;
revoke all privileges on function pac_dsd.lookup_program_login_credential(text, text) from public;
revoke all privileges on function pac_dsd.start_program_account_session(uuid, uuid, text, text, text, text) from public;
revoke all privileges on function pac_dsd.read_program_account_session(text, text, text, text) from public;
revoke all privileges on function pac_dsd.end_program_account_session(text, text) from public;
revoke all privileges on function pac_dsd.bootstrap_program_owner_invitation(text, text, text, text, timestamptz, text, text) from public, pac_dsd_contributor_runtime;
revoke all privileges on function pac_dsd.accept_program_account_invitation(text, text, text, text, text, text) from public;
revoke all privileges on function pac_dsd.authorize_protected_action(text, text, text, text, text, text, text, text, text, text) from public, pac_dsd_contributor_runtime;
revoke all privileges on function pac_dsd.consume_protected_action(uuid, text, text) from public, pac_dsd_contributor_runtime;
revoke all privileges on function pac_dsd.create_program_account_invitation(text, text, text, text, text, text, text, timestamptz) from public;
revoke all privileges on function pac_dsd.create_program_credential_reset_invitation(text, text, text, text, uuid, text, timestamptz) from public;
revoke all privileges on function pac_dsd.issue_program_access_grant(text, text, text, text, uuid, text, text, timestamptz, text) from public;
revoke all privileges on function pac_dsd.revoke_program_access_grant(text, text, text, text, uuid, text) from public;
revoke all privileges on function pac_dsd.revoke_program_account_invitation(text, text, text, text, uuid, text) from public;
revoke all privileges on function pac_dsd.change_program_account_state(text, text, text, text, uuid, text, text) from public;
revoke all privileges on function pac_dsd.relinquish_program_owner(text, text, text, text, text, text) from public;
revoke all privileges on function pac_dsd.read_program_access_overview(text, text, text, text) from public;
revoke all privileges on function pac_dsd.purge_expired_program_security_records() from public;
revoke all privileges on function pac_dsd.assert_runtime_rate_limit_request(text, text, integer, integer) from public, pac_dsd_contributor_runtime;
revoke all privileges on function pac_dsd.attest_program_identity_runtime_boundary() from public, pac_dsd_contributor_runtime;

do $$
begin
  if exists (select 1 from pg_catalog.pg_roles where rolname = 'pac_dsd_contributor_runtime') then
    -- Credential lookup and session minting are intentionally withheld here.
    -- Migration 0022 installs a separately isolated authentication broker; no
    -- committed migration state may make the general runtime an authenticator.
    grant execute on function pac_dsd.read_program_account_session(text, text, text, text) to pac_dsd_contributor_runtime;
    grant execute on function pac_dsd.end_program_account_session(text, text) to pac_dsd_contributor_runtime;
    grant execute on function pac_dsd.accept_program_account_invitation(text, text, text, text, text, text) to pac_dsd_contributor_runtime;
grant execute on function pac_dsd.create_program_account_invitation(text, text, text, text, text, text, text, timestamptz) to pac_dsd_contributor_runtime;
grant execute on function pac_dsd.create_program_credential_reset_invitation(text, text, text, text, uuid, text, timestamptz) to pac_dsd_contributor_runtime;
grant execute on function pac_dsd.issue_program_access_grant(text, text, text, text, uuid, text, text, timestamptz, text) to pac_dsd_contributor_runtime;
grant execute on function pac_dsd.revoke_program_access_grant(text, text, text, text, uuid, text) to pac_dsd_contributor_runtime;
grant execute on function pac_dsd.revoke_program_account_invitation(text, text, text, text, uuid, text) to pac_dsd_contributor_runtime;
grant execute on function pac_dsd.change_program_account_state(text, text, text, text, uuid, text, text) to pac_dsd_contributor_runtime;
    grant execute on function pac_dsd.relinquish_program_owner(text, text, text, text, text, text) to pac_dsd_contributor_runtime;
    grant execute on function pac_dsd.read_program_access_overview(text, text, text, text) to pac_dsd_contributor_runtime;
    grant execute on function pac_dsd.purge_expired_program_security_records() to pac_dsd_contributor_runtime;
    grant execute on function pac_dsd.attest_program_identity_runtime_boundary() to pac_dsd_contributor_runtime;
  end if;
end;
$$;

do $$
declare
  role_name text;
  signature text;
begin
  foreach role_name in array array['anon', 'authenticated']
  loop
    if exists (select 1 from pg_catalog.pg_roles where rolname = role_name) then
      foreach signature in array array[
        'pac_dsd.lookup_program_login_credential(text,text)',
        'pac_dsd.start_program_account_session(uuid,uuid,text,text,text,text)',
        'pac_dsd.read_program_account_session(text,text,text,text)',
        'pac_dsd.end_program_account_session(text,text)',
        'pac_dsd.bootstrap_program_owner_invitation(text,text,text,text,timestamptz,text,text)',
        'pac_dsd.accept_program_account_invitation(text,text,text,text,text,text)',
        'pac_dsd.authorize_protected_action(text,text,text,text,text,text,text,text,text,text)',
        'pac_dsd.consume_protected_action(uuid,text,text)',
    'pac_dsd.create_program_account_invitation(text,text,text,text,text,text,text,timestamptz)',
    'pac_dsd.create_program_credential_reset_invitation(text,text,text,text,uuid,text,timestamptz)',
    'pac_dsd.issue_program_access_grant(text,text,text,text,uuid,text,text,timestamptz,text)',
    'pac_dsd.revoke_program_access_grant(text,text,text,text,uuid,text)',
    'pac_dsd.revoke_program_account_invitation(text,text,text,text,uuid,text)',
    'pac_dsd.change_program_account_state(text,text,text,text,uuid,text,text)',
        'pac_dsd.relinquish_program_owner(text,text,text,text,text,text)',
        'pac_dsd.read_program_access_overview(text,text,text,text)',
        'pac_dsd.purge_expired_program_security_records()'
        ,'pac_dsd.attest_program_identity_runtime_boundary()'
      ]
      loop
        execute format('revoke all privileges on function %s from %I', signature, role_name);
      end loop;
    end if;
  end loop;
end;
$$;

comment on table pac_dsd.program_accounts is
  'Named protected-work identities only; no private learning, practice history, ideology, participation, or staff profile is attached.';
comment on table pac_dsd.program_account_invitations is
  'Owner-issued invitation metadata. The one-time bearer digest is isolated and destroyed on closure.';
comment on table pac_dsd.program_account_credentials is
  'Versioned credential metadata; only the current memory-hard verifier remains in the separately restricted secret table.';
comment on table pac_dsd.program_account_sessions is
  'Short-lived opaque individual protected-work sessions; browser tokens are never stored.';
comment on table pac_dsd.protected_action_authorizations is
  'Immutable action-time proof of the named account, exact session, exact credential, exact grant, role, and scope.';
comment on table pac_dsd.protected_action_consumptions is
  'One-use binding from an action-time authorization to the exact protected action record.';
comment on function pac_dsd.bootstrap_program_owner_invitation(text, text, text, text, timestamptz, text, text) is
  'One-time migration-owner bootstrap only; never callable by the application runtime role.';
comment on function pac_dsd.authorize_protected_action(text, text, text, text, text, text, text, text, text, text) is
  'Internal transaction-time authorization allocator; callers cannot supply actor, effective role, or effective grant.';


-- 0043_pac_contributor_authentication_boundary.sql

-- Local named-contributor adaptation, owner authorized 2026-09-08.
-- Selective donor identity lineage0021/0022/0023; existing owner functions and grants remain intact.
-- Hosted PostgreSQL may grant its creator administrative control without INHERIT or SET.
-- Only that unusable migration-owner membership is permitted; runtime role paths remain denied.
do $role$ begin
if not exists(select 1 from pg_roles where rolname='pac_dsd_authentication_broker') then
create role pac_dsd_authentication_broker login noinherit nosuperuser nocreatedb nocreaterole noreplication nobypassrls connection limit 20; end if;
if not exists(select 1 from pg_roles where rolname='pac_dsd_authentication_broker' and rolcanlogin and not rolinherit and not rolsuper and not rolcreatedb and not rolcreaterole and not rolreplication and not rolbypassrls and rolconnlimit between 1 and 20)
or exists(select 1 from pg_auth_members m join pg_roles r on r.oid=m.member join pg_roles g on g.oid=m.roleid where (r.rolname='pac_dsd_authentication_broker' or g.rolname='pac_dsd_authentication_broker')
  and not (g.rolname='pac_dsd_authentication_broker' and r.rolname=current_user
    and m.admin_option and not m.inherit_option and not m.set_option)) then raise exception 'Unsafe existing pac_dsd_authentication_broker role' using errcode='42501'; end if;
execute format('grant connect on database %I to pac_dsd_authentication_broker',current_database()); end $role$;
alter role pac_dsd_authentication_broker set statement_timeout='10s';
alter role pac_dsd_authentication_broker set lock_timeout='5s';
alter role pac_dsd_authentication_broker set idle_in_transaction_session_timeout='10s';


-- Password verification is an intentionally separate trust boundary. The
-- ordinary application role must never be able to combine a verifier lookup
-- with session creation and thereby impersonate a named account. A dedicated
-- broker role receives only three functions in a schema the runtime cannot use.
create schema if not exists pac_dsd_auth;
revoke all privileges on schema pac_dsd_auth from public;
revoke all privileges on all tables in schema pac_dsd_auth from public;
revoke all privileges on all sequences in schema pac_dsd_auth from public;
revoke all privileges on all functions in schema pac_dsd_auth from public;
do $$
declare
  role_name text;
begin
  if not exists (
    select 1
    from pg_catalog.pg_namespace namespace
    where namespace.nspname = 'pac_dsd_auth'
      and namespace.nspowner = (select oid from pg_catalog.pg_roles where rolname = current_user)
  ) then
    raise exception 'The pac_dsd_auth schema must be owned by the approved migration role'
      using errcode = '42501';
  end if;
  if exists (
    select 1
    from pg_catalog.pg_class relation
    join pg_catalog.pg_namespace namespace on namespace.oid = relation.relnamespace
    where namespace.nspname = 'pac_dsd_auth'
      and relation.relowner <> (select oid from pg_catalog.pg_roles where rolname = current_user)
    union all
    select 1
    from pg_catalog.pg_proc procedure
    join pg_catalog.pg_namespace namespace on namespace.oid = procedure.pronamespace
    where namespace.nspname = 'pac_dsd_auth'
      and procedure.proowner <> (select oid from pg_catalog.pg_roles where rolname = current_user)
  ) then
    raise exception 'Every pre-existing pac_dsd_auth object must be owned by the approved migration role'
      using errcode = '42501';
  end if;

  for role_name in
    select role_record.rolname
    from pg_catalog.pg_roles role_record
    where role_record.rolname <> current_user
  loop
    execute format('revoke all privileges on schema pac_dsd_auth from %I', role_name);
    execute format('revoke all privileges on all tables in schema pac_dsd_auth from %I', role_name);
    execute format('revoke all privileges on all sequences in schema pac_dsd_auth from %I', role_name);
    execute format('revoke all privileges on all functions in schema pac_dsd_auth from %I', role_name);
  end loop;
end;
$$;
alter default privileges in schema pac_dsd_auth revoke all privileges on tables from public;
alter default privileges in schema pac_dsd_auth revoke all privileges on sequences from public;
alter default privileges in schema pac_dsd_auth revoke all privileges on functions from public;

create table if not exists pac_dsd.database_installation_identity (
  singleton text primary key default 'primary' check (singleton = 'primary'),
  installation_id uuid not null unique default gen_random_uuid(),
  created_at timestamptz not null default clock_timestamp()
);
insert into pac_dsd.database_installation_identity (singleton)
values ('primary')
on conflict (singleton) do nothing;
alter table pac_dsd.database_installation_identity enable row level security;
revoke all privileges on table pac_dsd.database_installation_identity from public, pac_dsd_contributor_runtime;

create table if not exists pac_dsd.protected_feature_activation_events (
  activation_event_id bigint generated always as identity primary key,
  environment text not null check (environment in ('local', 'preview', 'production')),
  feature_key text not null check (feature_key in ('protected_identity', 'protected_contribution')),
  state text not null check (state in ('active', 'inactive')),
  evidence_id text not null check (evidence_id ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'),
  activation_bundle_sha256 text not null check (activation_bundle_sha256 ~ '^[a-f0-9]{64}$'),
  reason text not null check (
    char_length(reason) between 3 and 500
    and reason = btrim(reason)
    and reason !~ '[[:cntrl:]]'
  ),
  recorded_at timestamptz not null default clock_timestamp()
);

create index if not exists protected_feature_activation_current_idx
  on pac_dsd.protected_feature_activation_events(
    environment, feature_key, activation_event_id desc
  );

create or replace function pac_dsd.record_protected_feature_activation(
  requested_environment text,
  requested_feature_key text,
  requested_state text,
  requested_evidence_id text,
  requested_activation_bundle_sha256 text,
  requested_reason text
)
returns bigint
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  created_event_id bigint;
begin
  if session_user in ('pac_dsd_contributor_runtime','pac_dsd_contributor_runtime','pac_dsd_authentication_broker')
    or requested_environment is null
    or requested_environment not in ('local', 'preview', 'production')
    or requested_feature_key not in ('protected_identity', 'protected_contribution')
    or requested_state not in ('active', 'inactive')
    or requested_evidence_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
    or requested_activation_bundle_sha256 !~ '^[a-f0-9]{64}$'
    or requested_reason is null
    or requested_reason <> btrim(requested_reason)
    or char_length(requested_reason) not between 3 and 500
    or requested_reason ~ '[[:cntrl:]]' then
    raise exception 'Invalid protected-feature activation event' using errcode = '22023';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'pac-protected-feature:' || requested_environment || ':' || requested_feature_key,
      0
    )
  );
  insert into pac_dsd.protected_feature_activation_events (
    environment, feature_key, state, evidence_id,
    activation_bundle_sha256, reason
  ) values (
    requested_environment, requested_feature_key, requested_state,
    requested_evidence_id, requested_activation_bundle_sha256, requested_reason
  ) returning activation_event_id into created_event_id;
  return created_event_id;
end;
$$;

-- A protected content change carries both the named-session authorization from
-- 0021 and the exact dependent-feature evidence rechecked by the application
-- immediately before this transaction. The table is append-only and contains
-- no submitted content, bearer, passphrase, question, or learning activity.
create table if not exists pac_dsd.protected_mutation_feature_evidence (
  authorization_id uuid primary key
    references pac_dsd.protected_action_authorizations(authorization_id),
  activation_event_id bigint not null
    references pac_dsd.protected_feature_activation_events(activation_event_id),
  feature_key text not null check (feature_key = 'protected_contribution'),
  environment text not null check (environment in ('local', 'preview', 'production')),
  evidence_id text not null check (evidence_id ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'),
  activation_bundle_sha256 text not null check (activation_bundle_sha256 ~ '^[a-f0-9]{64}$'),
  recorded_at timestamptz not null default clock_timestamp()
);

create table if not exists pac_dsd.program_owner_transfers (
  transfer_id uuid primary key default gen_random_uuid(),
  environment text not null check (environment in ('local', 'preview', 'production')),
  authorization_id uuid not null unique
    references pac_dsd.protected_action_authorizations(authorization_id),
  from_account_id uuid not null references pac_dsd.program_accounts(account_id),
  to_account_id uuid not null references pac_dsd.program_accounts(account_id),
  from_grant_id uuid not null references pac_dsd.access_grants(grant_id),
  to_grant_id uuid not null unique references pac_dsd.access_grants(grant_id),
  reason text not null check (
    char_length(reason) between 3 and 500
    and reason = btrim(reason)
    and reason !~ '[[:cntrl:]]'
  ),
  transferred_at timestamptz not null default clock_timestamp(),
  check (from_account_id <> to_account_id)
);

create or replace function pac_dsd.prevent_named_protected_evidence_mutation()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
as $$
begin
  raise exception 'Named protected evidence is append-only' using errcode = '42501';
end;
$$;
create or replace function pac_dsd.transfer_program_owner(
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text,
  requested_successor_account_id uuid,
  requested_reason text
)
returns table (
  transfer_id uuid,
  from_account_id uuid,
  to_account_id uuid,
  transferred_at timestamptz
)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  created_authorization_id uuid;
  selected_authorization pac_dsd.protected_action_authorizations%rowtype;
  current_owner_grant pac_dsd.access_grants%rowtype;
  successor_account pac_dsd.program_accounts%rowtype;
  successor_grant_id uuid := gen_random_uuid();
  created_transfer pac_dsd.program_owner_transfers%rowtype;
begin
  if requested_environment is null
    or requested_environment not in ('local', 'preview', 'production')
    or requested_successor_account_id is null
    or requested_reason is null
    or requested_reason <> btrim(requested_reason)
    or char_length(requested_reason) not between 3 and 471
    or requested_reason ~ '[[:cntrl:]]' then
    raise exception 'Invalid owner-transfer reason' using errcode = '22023';
  end if;
  -- Recovery uses this same first lock. Keeping one global ordering prevents a
  -- transfer/recovery advisory-lock and owner-grant row-lock deadlock.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-owner:' || requested_environment, 0)
  );
  created_authorization_id := pac_dsd.authorize_protected_action(
    requested_session_token_digest,
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256,
    'one-dhs-pac',
    'owner',
    'owner_transfer',
    'account',
    requested_successor_account_id::text,
    pac_dsd.protected_action_fingerprint(
      'owner_transfer',
      jsonb_build_object(
        'successorAccountId', requested_successor_account_id,
        'reason', requested_reason,
        'environment', requested_environment
      )
    )
  );
  select * into selected_authorization
  from pac_dsd.protected_action_authorizations stored
  where stored.authorization_id = created_authorization_id;
  if requested_successor_account_id = selected_authorization.account_id then
    raise exception 'The successor must be a different named account' using errcode = '22023';
  end if;
  select * into current_owner_grant
  from pac_dsd.access_grants grant_record
  where grant_record.grant_id = selected_authorization.grant_id
    and grant_record.account_id = selected_authorization.account_id
    and grant_record.environment = requested_environment
    and grant_record.scope_id = 'one-dhs-pac'
    and grant_record.role_key = 'owner'
    and grant_record.grant_contract_version = 'protected-v1'
    and grant_record.revoked_at is null
  for update;
  if current_owner_grant.grant_id is null then
    raise exception 'The current owner authority is no longer active' using errcode = '42501';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-account:' || requested_successor_account_id::text, 0)
  );
  select * into successor_account
  from pac_dsd.program_accounts account
  where account.account_id = requested_successor_account_id
    and account.environment = requested_environment;
  if successor_account.account_id is null
    or not pac_dsd.program_account_is_active(requested_successor_account_id) then
    raise exception 'The successor account must be active in this environment' using errcode = '42501';
  end if;

  update pac_dsd.access_grants
  set revoked_at = clock_timestamp(),
      revoked_by = selected_authorization.account_id::text,
      revoked_by_account_id = selected_authorization.account_id,
      revoked_by_session_id = selected_authorization.session_id,
      revocation_reason = 'Owner authority transferred: ' || requested_reason
  where grant_id = current_owner_grant.grant_id
    and revoked_at is null;
  if not found then
    raise exception 'The owner authority changed during transfer' using errcode = '40001';
  end if;

  insert into pac_dsd.access_grants (
    grant_id, principal_id, scope_id, role_key, granted_by, account_id,
    environment, issued_by_account_id, issued_by_session_id, grant_reason,
    grant_contract_version
  ) values (
    successor_grant_id,
    successor_account.account_id::text,
    'one-dhs-pac',
    'owner',
    selected_authorization.account_id::text,
    successor_account.account_id,
    requested_environment,
    selected_authorization.account_id,
    selected_authorization.session_id,
    'Owner authority transferred: ' || requested_reason,
    'protected-v1'
  );

  insert into pac_dsd.program_owner_transfers (
    environment, authorization_id, from_account_id, to_account_id,
    from_grant_id, to_grant_id, reason
  ) values (
    requested_environment,
    created_authorization_id,
    selected_authorization.account_id,
    successor_account.account_id,
    current_owner_grant.grant_id,
    successor_grant_id,
    requested_reason
  ) returning * into created_transfer;

  insert into pac_dsd.program_account_invitation_closures (
    invitation_id, outcome, closed_by_account_id, closed_by_session_id, reason
  )
  select invitation.invitation_id,
    'revoked',
    selected_authorization.account_id,
    selected_authorization.session_id,
    'Owner authority transferred; every unaccepted code issued by the outgoing owner was invalidated.'
  from pac_dsd.program_account_invitations invitation
  join pac_dsd.program_account_invitation_secrets secret
    on secret.invitation_id = invitation.invitation_id
  left join pac_dsd.protected_action_authorizations issuer
    on issuer.authorization_id = invitation.issued_by_authorization_id
  where invitation.environment = requested_environment
    and (
      issuer.account_id = selected_authorization.account_id
      or invitation.invitation_type = 'owner_recovery'
    )
    and not exists (
      select 1 from pac_dsd.program_account_invitation_closures closure
      where closure.invitation_id = invitation.invitation_id
    )
  on conflict on constraint program_account_invitation_closures_pkey do nothing;
  delete from pac_dsd.program_account_invitation_secrets secret
  using pac_dsd.program_account_invitations invitation,
    pac_dsd.program_account_invitation_closures closure
  where secret.invitation_id = invitation.invitation_id
    and closure.invitation_id = invitation.invitation_id
    and invitation.environment = requested_environment
    and closure.outcome = 'revoked'
    and closure.closed_by_account_id = selected_authorization.account_id
    and closure.closed_by_session_id = selected_authorization.session_id;

  insert into pac_dsd.program_account_session_revocations (
    session_id, reason, revoked_by_account_id, revoked_by_session_id
  )
  select session.session_id,
    'Owner authority transferred; a fresh named sign-in is required.',
    selected_authorization.account_id,
    selected_authorization.session_id
  from pac_dsd.program_account_sessions session
  where session.account_id in (
      selected_authorization.account_id,
      successor_account.account_id
    )
    and not exists (
      select 1 from pac_dsd.program_account_session_revocations revoked
      where revoked.session_id = session.session_id
    );
  perform pac_dsd.consume_protected_action(
    created_authorization_id,
    'owner_transfer',
    created_transfer.transfer_id::text
  );
  return query select
    created_transfer.transfer_id,
    created_transfer.from_account_id,
    created_transfer.to_account_id,
    created_transfer.transferred_at;
end;
$$;

-- Recovery rotates only the credential of the existing active owner. It does
-- not create an account or owner grant, and the application role cannot call it.
create or replace function pac_dsd.create_program_owner_recovery_invitation(
  requested_environment text,
  requested_owner_account_id uuid,
  requested_token_digest text,
  requested_expires_at timestamptz,
  requested_recovery_evidence_id text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text
)
returns table (invitation_id uuid, expires_at timestamptz)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  owner_account pac_dsd.program_accounts%rowtype;
  created_invitation_id uuid := gen_random_uuid();
begin
  if session_user = 'pac_dsd_contributor_runtime'
    or requested_environment not in ('local', 'preview', 'production')
    or requested_token_digest !~ '^[a-f0-9]{64}$'
    or requested_recovery_evidence_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
    or requested_activation_evidence_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
    or requested_activation_bundle_sha256 !~ '^[a-f0-9]{64}$'
    or requested_expires_at <= clock_timestamp() + interval '5 minutes'
    or requested_expires_at > clock_timestamp() + interval '7 days' then
    raise exception 'Invalid owner-recovery invitation request' using errcode = '22023';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-owner:' || requested_environment, 0)
  );
  -- Match the account lock taken by ordinary authorization before touching
  -- credential, session, or grant rows. This makes recovery wait for an
  -- in-flight owner action and then prevents a session/grant FK deadlock while
  -- the incident-containment revocations are recorded.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-account:' || requested_owner_account_id::text, 0)
  );
  select account.* into owner_account
  from pac_dsd.program_accounts account
  join pac_dsd.access_grants owner_grant
    on owner_grant.account_id = account.account_id
  where account.account_id = requested_owner_account_id
    and account.environment = requested_environment
    and owner_grant.environment = requested_environment
    and owner_grant.scope_id = 'one-dhs-pac'
    and owner_grant.role_key = 'owner'
    and owner_grant.grant_contract_version = 'protected-v1'
    and owner_grant.revoked_at is null
    and (owner_grant.expires_at is null or owner_grant.expires_at > clock_timestamp())
  for update of account, owner_grant;
  if owner_account.account_id is null
    or not pac_dsd.program_account_is_active(owner_account.account_id) then
    raise exception 'Recovery is limited to the existing active owner account'
      using errcode = '42501';
  end if;

  insert into pac_dsd.program_account_invitation_closures (
    invitation_id, outcome, recovery_evidence_id, reason
  )
  select distinct prior.invitation_id,
    'superseded',
    requested_recovery_evidence_id,
    'Migration-owner recovery invalidated this unaccepted code before issuing a fresh owner recovery code.'
  from pac_dsd.program_account_invitations prior
  join pac_dsd.program_account_invitation_secrets secret
    on secret.invitation_id = prior.invitation_id
  left join pac_dsd.protected_action_authorizations issuer
    on issuer.authorization_id = prior.issued_by_authorization_id
  where prior.environment = requested_environment
    and (
      prior.target_account_id = owner_account.account_id
      or issuer.account_id = owner_account.account_id
    )
    and not exists (
      select 1 from pac_dsd.program_account_invitation_closures closure
      where closure.invitation_id = prior.invitation_id
    )
  on conflict on constraint program_account_invitation_closures_pkey do nothing;
  delete from pac_dsd.program_account_invitation_secrets secret
  using pac_dsd.program_account_invitations prior,
    pac_dsd.program_account_invitation_closures closure
  where secret.invitation_id = prior.invitation_id
    and closure.invitation_id = prior.invitation_id
    and prior.environment = requested_environment
    and closure.outcome = 'superseded'
    and closure.recovery_evidence_id = requested_recovery_evidence_id;

  -- Recovery is also incident containment. Once the migration owner issues a
  -- code, the possibly compromised credential and every live owner session are
  -- unusable. Acceptance creates a new credential and session atomically.
  delete from pac_dsd.program_account_credential_secrets secret
  using pac_dsd.program_account_credentials credential
  where secret.credential_id = credential.credential_id
    and credential.account_id = owner_account.account_id;
  insert into pac_dsd.program_account_session_revocations (session_id, reason)
  select owner_session.session_id,
    'Owner recovery was initiated; a new credential is required.'
  from pac_dsd.program_account_sessions owner_session
  where owner_session.account_id = owner_account.account_id
    and owner_session.environment = requested_environment
    and not exists (
      select 1
      from pac_dsd.program_account_session_revocations revoked
      where revoked.session_id = owner_session.session_id
    );

  insert into pac_dsd.program_account_invitations (
    invitation_id, environment, activation_evidence_id,
    activation_bundle_sha256, invitation_type, sign_in_id, display_name,
    target_account_id, bootstrap_evidence_id
  ) values (
    created_invitation_id,
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256,
    'owner_recovery',
    owner_account.sign_in_id,
    owner_account.display_name,
    owner_account.account_id,
    requested_recovery_evidence_id
  );
  insert into pac_dsd.program_account_invitation_secrets (
    invitation_id, token_digest, expires_at
  ) values (
    created_invitation_id,
    requested_token_digest,
    requested_expires_at
  );
  return query select created_invitation_id, requested_expires_at;
end;
$$;

-- The old self-relinquishment operation could strand administration. Remove it
-- entirely; runtime succession must use the atomic transfer above.
revoke all privileges on function pac_dsd.relinquish_program_owner(text, text, text, text, text, text)
  from public, pac_dsd_contributor_runtime;
drop function pac_dsd.relinquish_program_owner(text, text, text, text, text, text);

alter table pac_dsd.protected_mutation_feature_evidence enable row level security;
alter table pac_dsd.program_owner_transfers enable row level security;
alter table pac_dsd.protected_feature_activation_events enable row level security;
revoke all privileges on table pac_dsd.protected_mutation_feature_evidence from public, pac_dsd_contributor_runtime;
revoke all privileges on table pac_dsd.program_owner_transfers from public, pac_dsd_contributor_runtime;
revoke all privileges on table pac_dsd.protected_feature_activation_events from public, pac_dsd_contributor_runtime;

drop trigger if exists protected_mutation_feature_evidence_append_only
  on pac_dsd.protected_mutation_feature_evidence;
create trigger protected_mutation_feature_evidence_append_only
before update or delete on pac_dsd.protected_mutation_feature_evidence
for each row execute function pac_dsd.prevent_named_protected_evidence_mutation();

drop trigger if exists protected_feature_activation_events_append_only
  on pac_dsd.protected_feature_activation_events;
create trigger protected_feature_activation_events_append_only
before update or delete on pac_dsd.protected_feature_activation_events
for each row execute function pac_dsd.prevent_named_protected_evidence_mutation();

drop trigger if exists program_owner_transfers_append_only
  on pac_dsd.program_owner_transfers;
create trigger program_owner_transfers_append_only
before update or delete on pac_dsd.program_owner_transfers
for each row execute function pac_dsd.prevent_named_protected_evidence_mutation();

create or replace function pac_dsd.assert_exact_jsonb_keys(
  candidate jsonb,
  required_keys text[],
  allowed_keys text[]
)
returns void
language plpgsql
immutable
security definer
set search_path = pg_catalog, pac_dsd
as $$
begin
  if candidate is null
    or required_keys is null
    or allowed_keys is null
    or jsonb_typeof(candidate) is distinct from 'object'
    or exists (
      select 1 from jsonb_object_keys(candidate) supplied(key)
      where supplied.key <> all(allowed_keys)
    )
    or exists (
      select 1 from unnest(required_keys) required(key)
      where not candidate ? required.key
    ) then
    raise exception 'Protected mutation payload does not match its finite contract'
      using errcode = '22023';
  end if;
end;
$$;

revoke all privileges on function pac_dsd.record_protected_feature_activation(text,text,text,text,text,text) from public,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
revoke all privileges on function pac_dsd.create_program_owner_recovery_invitation(text,uuid,text,timestamptz,text,text,text) from public,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
revoke all privileges on function pac_dsd.assert_exact_jsonb_keys(jsonb,text[],text[]) from public,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
revoke all privileges on function pac_dsd.prevent_named_protected_evidence_mutation() from public,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
revoke all privileges on schema pac_dsd from pac_dsd_authentication_broker;
revoke all privileges on all tables in schema pac_dsd from pac_dsd_authentication_broker;
revoke all privileges on all sequences in schema pac_dsd from pac_dsd_authentication_broker;
revoke all privileges on all functions in schema pac_dsd from pac_dsd_authentication_broker;
alter role pac_dsd_authentication_broker set search_path=pac_dsd_auth,pg_catalog;


-- 0044_pac_named_identity_corrections_and_current_activation.sql

-- Local adaptation: latest identity activation is checked inside every named session operation.
create or replace function pac_dsd.program_identity_activation_is_current(requested_environment text,requested_evidence_id text,requested_bundle_sha256 text)
returns boolean language plpgsql volatile security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$ begin
if requested_environment is null or requested_environment not in ('local','preview','production') or requested_evidence_id is null or requested_bundle_sha256 is null then return false; end if;
perform pg_advisory_xact_lock_shared(hashtextextended('pac-protected-feature:' || requested_environment || ':protected_identity',0));
return exists(select 1 from pac_dsd.protected_feature_activation_events a where a.environment=requested_environment and a.feature_key='protected_identity'
and a.activation_event_id=(select max(b.activation_event_id) from pac_dsd.protected_feature_activation_events b where b.environment=requested_environment and b.feature_key='protected_identity')
and a.state='active' and a.evidence_id=requested_evidence_id and a.activation_bundle_sha256=requested_bundle_sha256); end; $$;
revoke all privileges on function pac_dsd.program_identity_activation_is_current(text,text,text) from public,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;


-- Identity details are a guarded current projection. Every correction is an
-- individually authorized, append-only event tied to the stable account UUID.
alter table pac_dsd.program_accounts
  add column if not exists identity_version integer not null default 1
    check (identity_version >= 1);

alter table pac_dsd.protected_action_authorizations
  drop constraint if exists protected_action_authorizations_action_kind_check;
alter table pac_dsd.protected_action_authorizations
  add constraint protected_action_authorizations_action_kind_check check (
    action_kind in (
      'account_invite', 'credential_reset_invite', 'invitation_revoke',
      'account_suspend', 'account_reactivate', 'account_revoke',
      'account_identity_correct', 'grant_issue', 'grant_revoke',
      'contribution_submit', 'specialist_review', 'approval_record',
      'publication_publish', 'publication_withdraw', 'publication_republish',
      'correction_record', 'protected_upload', 'formal_compliance_record',
      'owner_transfer'
    )
  ) not valid;
alter table pac_dsd.protected_action_authorizations
  validate constraint protected_action_authorizations_action_kind_check;

alter table pac_dsd.protected_action_consumptions
  drop constraint if exists protected_action_consumptions_result_record_type_check;
alter table pac_dsd.protected_action_consumptions
  add constraint protected_action_consumptions_result_record_type_check check (
    result_record_type in (
      'account_state_event', 'account_identity_correction', 'owner_transfer',
      'invitation', 'grant', 'content_revision', 'review', 'publication',
      'source_object', 'compliance_record'
    )
  ) not valid;
alter table pac_dsd.protected_action_consumptions
  validate constraint protected_action_consumptions_result_record_type_check;

create table if not exists pac_dsd.program_account_identity_corrections (
  correction_id uuid primary key default gen_random_uuid(),
  environment text not null check (environment in ('local', 'preview', 'production')),
  account_id uuid not null references pac_dsd.program_accounts(account_id),
  authorization_id uuid not null unique
    references pac_dsd.protected_action_authorizations(authorization_id),
  supersedes_correction_id uuid unique
    references pac_dsd.program_account_identity_corrections(correction_id),
  from_identity_version integer not null check (from_identity_version >= 1),
  to_identity_version integer not null,
  previous_sign_in_id text not null check (
    previous_sign_in_id = lower(previous_sign_in_id)
    and previous_sign_in_id ~ '^[a-z0-9][a-z0-9._-]{2,63}$'
  ),
  corrected_sign_in_id text not null check (
    corrected_sign_in_id = lower(corrected_sign_in_id)
    and corrected_sign_in_id ~ '^[a-z0-9][a-z0-9._-]{2,63}$'
  ),
  previous_display_name text not null check (
    char_length(previous_display_name) between 2 and 120
    and previous_display_name = btrim(previous_display_name)
    and previous_display_name !~ '[[:cntrl:]]'
  ),
  corrected_display_name text not null check (
    char_length(corrected_display_name) between 2 and 120
    and corrected_display_name = btrim(corrected_display_name)
    and corrected_display_name !~ '[[:cntrl:]]'
  ),
  reason text not null check (
    char_length(reason) between 3 and 500
    and reason = btrim(reason)
    and reason !~ '[[:cntrl:]]'
  ),
  corrected_at timestamptz not null default clock_timestamp(),
  correction_contract_version text not null default 'program-identity-correction-v1'
    check (correction_contract_version = 'program-identity-correction-v1'),
  unique (account_id, to_identity_version),
  check (to_identity_version = from_identity_version + 1),
  check (
    previous_sign_in_id is distinct from corrected_sign_in_id
    or previous_display_name is distinct from corrected_display_name
  )
);

create index if not exists program_identity_corrections_previous_sign_in_idx
  on pac_dsd.program_account_identity_corrections(environment, previous_sign_in_id);
create index if not exists program_identity_corrections_corrected_sign_in_idx
  on pac_dsd.program_account_identity_corrections(environment, corrected_sign_in_id);
create index if not exists program_identity_corrections_account_version_idx
  on pac_dsd.program_account_identity_corrections(account_id, to_identity_version desc);

alter table pac_dsd.program_account_identity_corrections enable row level security;
revoke all privileges on table pac_dsd.program_account_identity_corrections
  from public, pac_dsd_contributor_runtime;

do $$
declare
  role_name text;
begin
  foreach role_name in array array['pac_dsd_authentication_broker', 'anon', 'authenticated']
  loop
    if exists (select 1 from pg_catalog.pg_roles where rolname = role_name) then
      execute format(
        'revoke all privileges on table pac_dsd.program_account_identity_corrections from %I',
        role_name
      );
    end if;
  end loop;
end;
$$;

create or replace function pac_dsd.assert_protected_action_authorization_shape()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
begin
  if not (
    (new.required_role_key = 'owner'
      and new.action_kind in ('account_invite', 'credential_reset_invite', 'invitation_revoke')
      and new.target_type = 'invitation')
    or (new.required_role_key = 'owner'
      and new.action_kind in (
        'account_suspend', 'account_reactivate', 'account_revoke',
        'account_identity_correct', 'owner_transfer'
      )
      and new.target_type = 'account')
    or (new.required_role_key = 'owner'
      and new.action_kind in ('grant_issue', 'grant_revoke')
      and new.target_type = 'grant')
    or (new.required_role_key in ('content_contributor', 'one_dsd_team_member')
      and new.action_kind = 'contribution_submit'
      and new.target_type = 'content_item')
    or (new.required_role_key = 'program_steward'
      and new.action_kind in ('specialist_review', 'correction_record')
      and new.target_type = 'content_item')
    or (new.required_role_key = 'publishing_approver'
      and new.action_kind = 'approval_record'
      and new.target_type = 'content_item')
    or (new.required_role_key = 'publishing_approver'
      and new.action_kind in ('publication_publish', 'publication_withdraw', 'publication_republish')
      and new.target_type = 'content_item')
    or (new.required_role_key = 'equity_director'
      and new.action_kind = 'protected_upload'
      and new.target_type = 'source_object')
    or (new.required_role_key = 'equity_director'
      and new.action_kind = 'formal_compliance_record'
      and new.target_type = 'compliance_record')
  ) then
    raise exception 'Protected action role, action, and target do not match the approved matrix'
      using errcode = '22023';
  end if;
  return new;
end;
$$;

create or replace function pac_dsd.assert_protected_action_consumption()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  selected_authorization pac_dsd.protected_action_authorizations%rowtype;
begin
  select * into selected_authorization
  from pac_dsd.protected_action_authorizations stored
  where stored.authorization_id = new.authorization_id
  for update;
  if selected_authorization.authorization_id is null
    or new.action_kind is distinct from selected_authorization.action_kind
    or new.requested_target_id is distinct from selected_authorization.target_id
    or not (
      (new.action_kind in ('account_suspend', 'account_reactivate', 'account_revoke')
        and new.result_record_type = 'account_state_event')
      or (new.action_kind = 'account_identity_correct'
        and new.result_record_type = 'account_identity_correction')
      or (new.action_kind = 'owner_transfer' and new.result_record_type = 'owner_transfer')
      or (new.action_kind in ('account_invite', 'credential_reset_invite', 'invitation_revoke')
        and new.result_record_type = 'invitation')
      or (new.action_kind in ('grant_issue', 'grant_revoke') and new.result_record_type = 'grant')
      or (new.action_kind in ('contribution_submit', 'correction_record')
        and new.result_record_type = 'content_revision')
      or (new.action_kind in ('specialist_review', 'approval_record') and new.result_record_type = 'review')
      or (new.action_kind in ('publication_publish', 'publication_withdraw', 'publication_republish')
        and new.result_record_type = 'publication')
      or (new.action_kind = 'protected_upload' and new.result_record_type = 'source_object')
      or (new.action_kind = 'formal_compliance_record' and new.result_record_type = 'compliance_record')
    ) then
    raise exception 'Protected action consumption does not match its authorization' using errcode = '22023';
  end if;
  return new;
end;
$$;

create or replace function pac_dsd.authorize_protected_action(
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text,
  requested_scope_id text,
  requested_role_key text,
  requested_action_kind text,
  requested_target_type text,
  requested_target_id text,
  requested_fingerprint text
)
returns uuid
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  selected_session pac_dsd.program_account_sessions%rowtype;
  selected_credential pac_dsd.program_account_credentials%rowtype;
  selected_grant pac_dsd.access_grants%rowtype;
  selected_grant_id uuid;
  created_authorization_id uuid;
begin
  if not pac_dsd.program_identity_activation_is_current(requested_environment,requested_activation_evidence_id,requested_activation_bundle_sha256) then raise exception 'Named program identity is not active in this environment' using errcode='42501'; end if;
  if requested_session_token_digest !~ '^[a-f0-9]{64}$'
    or requested_environment not in ('local', 'preview', 'production')
    or requested_activation_evidence_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
    or requested_activation_bundle_sha256 !~ '^[a-f0-9]{64}$'
    or requested_role_key not in (
      'content_contributor', 'program_steward', 'publishing_approver',
      'equity_director', 'one_dsd_team_member', 'owner'
    )
    or requested_action_kind not in (
      'account_invite', 'credential_reset_invite', 'invitation_revoke',
      'account_suspend', 'account_reactivate', 'account_revoke',
      'account_identity_correct', 'grant_issue', 'grant_revoke',
      'contribution_submit', 'specialist_review', 'approval_record',
      'publication_publish', 'publication_withdraw', 'publication_republish',
      'correction_record', 'protected_upload', 'formal_compliance_record',
      'owner_transfer'
    )
    or requested_target_type not in (
      'account', 'invitation', 'grant', 'content_item', 'content_revision', 'review',
      'publication', 'source_object', 'compliance_record'
    )
    or requested_target_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{0,159}$'
    or requested_fingerprint !~ '^[a-f0-9]{64}$' then
    raise exception 'Invalid protected-action authorization request' using errcode = '22023';
  end if;

  select * into selected_session
  from pac_dsd.program_account_sessions session
  where session.token_digest = requested_session_token_digest
    and session.environment = requested_environment
    and session.activation_evidence_id = requested_activation_evidence_id
    and session.activation_bundle_sha256 = requested_activation_bundle_sha256;
  if selected_session.session_id is null then
    raise exception 'A verified individual session is required' using errcode = 'PAI01';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-account:' || selected_session.account_id::text, 0)
  );
  select * into selected_session
  from pac_dsd.program_account_sessions session
  where session.session_id = selected_session.session_id
  for update;
  select * into selected_credential
  from pac_dsd.program_account_credentials credential
  where credential.account_id = selected_session.account_id
  order by credential.credential_version desc
  limit 1;
  if selected_session.expires_at <= clock_timestamp()
    or selected_session.audience <> 'pac-protected-workspace'
    or exists (
      select 1 from pac_dsd.program_account_session_revocations revoked
      where revoked.session_id = selected_session.session_id
    )
    or not pac_dsd.program_account_is_active(selected_session.account_id)
    or not exists (
      select 1 from pac_dsd.program_accounts account
      where account.account_id = selected_session.account_id
        and account.environment = requested_environment
    )
    or selected_credential.credential_id is distinct from selected_session.credential_id
    or not exists (
      select 1 from pac_dsd.program_account_credential_secrets secret
      where secret.credential_id = selected_session.credential_id
    ) then
    raise exception 'The individual session is expired or revoked' using errcode = 'PAI01';
  end if;

  with recursive ancestry as (
    select scope.scope_id, scope.parent_scope_id, 0 as depth
    from pac_dsd.program_scopes scope
    where scope.scope_id = requested_scope_id and scope.active = true
    union all
    select parent.scope_id, parent.parent_scope_id, child.depth + 1
    from pac_dsd.program_scopes parent
    join ancestry child on child.parent_scope_id = parent.scope_id
    where parent.active = true
  )
  select grant_record.grant_id into selected_grant_id
  from ancestry
  join pac_dsd.access_grants grant_record on grant_record.scope_id = ancestry.scope_id
  where grant_record.account_id = selected_session.account_id
    and grant_record.environment = requested_environment
    and grant_record.principal_id = selected_session.account_id::text
    and grant_record.role_key = requested_role_key
    and grant_record.grant_contract_version = 'protected-v1'
    and grant_record.revoked_at is null
    and (grant_record.expires_at is null or grant_record.expires_at > clock_timestamp())
  order by ancestry.depth, grant_record.granted_at desc, grant_record.grant_id
  limit 1;
  if selected_grant_id is null then
    raise exception 'The individual does not hold the required role for this scope' using errcode = 'PAA01';
  end if;
  select * into selected_grant
  from pac_dsd.access_grants grant_record
  where grant_record.grant_id = selected_grant_id
  for update;
  if selected_grant.revoked_at is not null
    or (selected_grant.expires_at is not null and selected_grant.expires_at <= clock_timestamp())
    or selected_grant.account_id is distinct from selected_session.account_id
    or selected_grant.environment is distinct from requested_environment
    or selected_grant.role_key is distinct from requested_role_key then
    raise exception 'The required grant is no longer active' using errcode = 'PAA01';
  end if;

  insert into pac_dsd.protected_action_authorizations (
    account_id, session_id, credential_id, environment,
    activation_evidence_id, activation_bundle_sha256,
    session_issued_at, session_expires_at, grant_id, requested_scope_id,
    effective_grant_scope_id, required_role_key, effective_grant_role_key,
    action_kind, target_type, target_id, request_fingerprint
  ) values (
    selected_session.account_id, selected_session.session_id, selected_session.credential_id,
    selected_session.environment, selected_session.activation_evidence_id,
    selected_session.activation_bundle_sha256, selected_session.issued_at,
    selected_session.expires_at, selected_grant.grant_id, requested_scope_id,
    selected_grant.scope_id, requested_role_key, selected_grant.role_key,
    requested_action_kind, requested_target_type, requested_target_id, requested_fingerprint
  ) returning authorization_id into created_authorization_id;
  return created_authorization_id;
end;
$$;

create or replace function pac_dsd.consume_protected_action(
  requested_authorization_id uuid,
  requested_result_record_type text,
  requested_action_record_id text
)
returns void
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  selected_authorization pac_dsd.protected_action_authorizations%rowtype;
begin
  select * into selected_authorization
  from pac_dsd.protected_action_authorizations stored
  where stored.authorization_id = requested_authorization_id
  for update;
  if selected_authorization.authorization_id is null
    or requested_result_record_type not in (
      'account_state_event', 'account_identity_correction', 'owner_transfer',
      'invitation', 'grant', 'content_revision', 'review', 'publication',
      'source_object', 'compliance_record'
    )
    or requested_action_record_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{0,159}$' then
    raise exception 'Invalid protected-action consumption' using errcode = '22023';
  end if;
  insert into pac_dsd.protected_action_consumptions (
    authorization_id, action_kind, result_record_type, requested_target_id, action_record_id
  ) values (
    selected_authorization.authorization_id, selected_authorization.action_kind,
    requested_result_record_type, selected_authorization.target_id, requested_action_record_id
  );
end;
$$;

-- A sign-in ID remains attached to the same stable account for its entire
-- history. New-account invitations cannot reserve an ID formerly held by any
-- account; an existing account may deliberately return to one of its own IDs.
create or replace function pac_dsd.assert_program_account_sign_in_reservation()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
begin
  if tg_op = 'UPDATE' and new.sign_in_id is not distinct from old.sign_in_id then
    return new;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'pac-program-sign-in:' || new.environment || ':' || new.sign_in_id,
      0
    )
  );
  if exists (
    select 1
    from pac_dsd.program_account_identity_corrections correction
    where correction.environment = new.environment
      and correction.account_id <> new.account_id
      and new.sign_in_id in (
        correction.previous_sign_in_id,
        correction.corrected_sign_in_id
      )
  ) then
    raise exception 'The requested sign-in identifier belongs to another account history'
      using errcode = '23505';
  end if;
  return new;
end;
$$;

drop trigger if exists program_account_sign_in_reservation_guard on pac_dsd.program_accounts;
create trigger program_account_sign_in_reservation_guard
before insert or update of sign_in_id on pac_dsd.program_accounts
for each row execute function pac_dsd.assert_program_account_sign_in_reservation();

create or replace function pac_dsd.assert_program_invitation_sign_in_reservation()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
begin
  if new.invitation_type not in ('bootstrap_owner', 'new_account') then
    return new;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'pac-program-sign-in:' || new.environment || ':' || new.sign_in_id,
      0
    )
  );
  if exists (
    select 1
    from pac_dsd.program_account_identity_corrections correction
    where correction.environment = new.environment
      and new.sign_in_id in (
        correction.previous_sign_in_id,
        correction.corrected_sign_in_id
      )
  ) then
    raise exception 'The requested sign-in identifier is retained in account history'
      using errcode = '23505';
  end if;
  return new;
end;
$$;

drop trigger if exists program_invitation_sign_in_reservation_guard
  on pac_dsd.program_account_invitations;
create trigger program_invitation_sign_in_reservation_guard
before insert on pac_dsd.program_account_invitations
for each row execute function pac_dsd.assert_program_invitation_sign_in_reservation();

-- Replace the blanket account immutability rule with an exact correction-only
-- projection guard. Every other account mutation remains impossible.
drop trigger if exists immutable_guard on pac_dsd.program_accounts;

create or replace function pac_dsd.assert_program_account_identity_projection()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
begin
  if tg_op = 'DELETE' then
    raise exception 'Program accounts are retained' using errcode = '55000';
  end if;
  if new.identity_version <> old.identity_version + 1
    or (to_jsonb(new) - array['sign_in_id', 'display_name', 'identity_version'])
      is distinct from
      (to_jsonb(old) - array['sign_in_id', 'display_name', 'identity_version'])
    or not exists (
      select 1
      from pac_dsd.program_account_identity_corrections correction
      where correction.account_id = old.account_id
        and correction.environment = old.environment
        and correction.from_identity_version = old.identity_version
        and correction.to_identity_version = new.identity_version
        and correction.previous_sign_in_id = old.sign_in_id
        and correction.corrected_sign_in_id = new.sign_in_id
        and correction.previous_display_name = old.display_name
        and correction.corrected_display_name = new.display_name
    ) then
    raise exception 'A program account permits only an authorized identity projection update'
      using errcode = '55000';
  end if;
  return new;
end;
$$;

create trigger immutable_guard
before update or delete on pac_dsd.program_accounts
for each row execute function pac_dsd.assert_program_account_identity_projection();

drop trigger if exists immutable_guard on pac_dsd.program_account_identity_corrections;
create trigger immutable_guard
before update or delete on pac_dsd.program_account_identity_corrections
for each row execute function pac_dsd.prevent_immutable_change();

create or replace function pac_dsd.validate_program_account_identity_correction()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  expected_previous_id uuid;
  expected_fingerprint text;
begin
  select correction.correction_id into expected_previous_id
  from pac_dsd.program_account_identity_corrections correction
  where correction.account_id = new.account_id
    and correction.to_identity_version = new.from_identity_version;

  expected_fingerprint := pac_dsd.protected_action_fingerprint(
    'account_identity_correct',
    jsonb_build_object(
      'environment', new.environment,
      'accountId', new.account_id,
      'expectedIdentityVersion', new.from_identity_version,
      'currentSignInId', new.previous_sign_in_id,
      'correctedSignInId', new.corrected_sign_in_id,
      'correctedDisplayName', new.corrected_display_name,
      'reason', new.reason
    )
  );

  if (new.from_identity_version = 1 and new.supersedes_correction_id is not null)
    or (new.from_identity_version > 1 and (
      expected_previous_id is null
      or new.supersedes_correction_id is distinct from expected_previous_id
    ))
    or not exists (
      select 1
      from pac_dsd.program_accounts account
      where account.account_id = new.account_id
        and account.environment = new.environment
        and account.identity_version = new.to_identity_version
        and account.sign_in_id = new.corrected_sign_in_id
        and account.display_name = new.corrected_display_name
    )
    or not exists (
      select 1
      from pac_dsd.protected_action_authorizations authorized
      join pac_dsd.protected_action_consumptions consumption
        on consumption.authorization_id = authorized.authorization_id
      where authorized.authorization_id = new.authorization_id
        and authorized.environment = new.environment
        and authorized.requested_scope_id = 'one-dhs-pac'
        and authorized.required_role_key = 'owner'
        and authorized.action_kind = 'account_identity_correct'
        and authorized.target_type = 'account'
        and authorized.target_id = new.account_id::text
        and authorized.request_fingerprint = expected_fingerprint
        and consumption.result_record_type = 'account_identity_correction'
        and consumption.action_record_id = new.correction_id::text
    ) then
    raise exception 'Identity correction evidence is incomplete or inconsistent'
      using errcode = '55000';
  end if;
  return null;
end;
$$;

drop trigger if exists program_identity_correction_commit_guard
  on pac_dsd.program_account_identity_corrections;
create constraint trigger program_identity_correction_commit_guard
after insert on pac_dsd.program_account_identity_corrections
deferrable initially deferred
for each row execute function pac_dsd.validate_program_account_identity_correction();

create or replace function pac_dsd.correct_program_account_identity(
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text,
  requested_account_id uuid,
  requested_identity_version integer,
  requested_current_sign_in_id text,
  requested_corrected_sign_in_id text,
  requested_corrected_display_name text,
  requested_reason text
)
returns table (
  correction_id uuid,
  account_id uuid,
  identity_version integer,
  sign_in_id text,
  display_name text,
  corrected_at timestamptz
)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  created_correction_id uuid := gen_random_uuid();
  created_authorization_id uuid;
  selected_authorization pac_dsd.protected_action_authorizations%rowtype;
  selected_account pac_dsd.program_accounts%rowtype;
  previous_correction_id uuid;
  correction_time timestamptz := clock_timestamp();
begin
  if requested_environment not in ('local', 'preview', 'production')
    or requested_identity_version is null
    or requested_identity_version < 1
    or requested_current_sign_in_id is null
    or requested_current_sign_in_id <> lower(requested_current_sign_in_id)
    or requested_current_sign_in_id !~ '^[a-z0-9][a-z0-9._-]{2,63}$'
    or requested_corrected_sign_in_id is null
    or requested_corrected_sign_in_id <> lower(requested_corrected_sign_in_id)
    or requested_corrected_sign_in_id !~ '^[a-z0-9][a-z0-9._-]{2,63}$'
    or requested_corrected_display_name is null
    or requested_corrected_display_name <> btrim(requested_corrected_display_name)
    or char_length(requested_corrected_display_name) not between 2 and 120
    or requested_corrected_display_name ~ '[[:cntrl:]]'
    or requested_reason is null
    or requested_reason <> btrim(requested_reason)
    or char_length(requested_reason) not between 3 and 500
    or requested_reason ~ '[[:cntrl:]]' then
    raise exception 'Invalid identity-correction request' using errcode = '22023';
  end if;

  if requested_current_sign_in_id <> requested_corrected_sign_in_id then
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'pac-program-sign-in:' || requested_environment || ':' || requested_corrected_sign_in_id,
        0
      )
    );
  end if;

  created_authorization_id := pac_dsd.authorize_protected_action(
    requested_session_token_digest,
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256,
    'one-dhs-pac',
    'owner',
    'account_identity_correct',
    'account',
    requested_account_id::text,
    pac_dsd.protected_action_fingerprint(
      'account_identity_correct',
      jsonb_build_object(
        'environment', requested_environment,
        'accountId', requested_account_id,
        'expectedIdentityVersion', requested_identity_version,
        'currentSignInId', requested_current_sign_in_id,
        'correctedSignInId', requested_corrected_sign_in_id,
        'correctedDisplayName', requested_corrected_display_name,
        'reason', requested_reason
      )
    )
  );
  select * into selected_authorization
  from pac_dsd.protected_action_authorizations authorized
  where authorized.authorization_id = created_authorization_id;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-account:' || requested_account_id::text, 0)
  );
  select * into selected_account
  from pac_dsd.program_accounts account
  where account.account_id = requested_account_id
  for update;
  if selected_account.account_id is null
    or selected_account.environment <> requested_environment then
    raise exception 'The account is not available in this environment' using errcode = 'P0002';
  end if;
  if selected_account.identity_version <> requested_identity_version
    or selected_account.sign_in_id <> requested_current_sign_in_id then
    raise exception 'The account identity changed while the correction was prepared'
      using errcode = '40001';
  end if;
  if selected_account.sign_in_id = requested_corrected_sign_in_id
    and selected_account.display_name = requested_corrected_display_name then
    raise exception 'An identity correction must change the sign-in ID or display name'
      using errcode = '22023';
  end if;

  if selected_account.sign_in_id <> requested_corrected_sign_in_id then
    if exists (
      select 1
      from pac_dsd.program_accounts account
      where account.environment = requested_environment
        and account.sign_in_id = requested_corrected_sign_in_id
        and account.account_id <> requested_account_id
    ) or exists (
      select 1
      from pac_dsd.program_account_identity_corrections prior
      where prior.environment = requested_environment
        and prior.account_id <> requested_account_id
        and requested_corrected_sign_in_id in (
          prior.previous_sign_in_id,
          prior.corrected_sign_in_id
        )
    ) or exists (
      select 1
      from pac_dsd.program_account_invitations invitation
      join pac_dsd.program_account_invitation_secrets secret
        on secret.invitation_id = invitation.invitation_id
      where invitation.environment = requested_environment
        and invitation.invitation_type in ('bootstrap_owner', 'new_account')
        and invitation.sign_in_id = requested_corrected_sign_in_id
        and secret.expires_at > clock_timestamp()
        and not exists (
          select 1 from pac_dsd.program_account_invitation_closures closure
          where closure.invitation_id = invitation.invitation_id
        )
    ) then
      raise exception 'The requested sign-in identifier is not available' using errcode = '23505';
    end if;
  end if;

  select prior.correction_id into previous_correction_id
  from pac_dsd.program_account_identity_corrections prior
  where prior.account_id = requested_account_id
    and prior.to_identity_version = requested_identity_version;

  insert into pac_dsd.program_account_identity_corrections (
    correction_id, environment, account_id, authorization_id,
    supersedes_correction_id, from_identity_version, to_identity_version,
    previous_sign_in_id, corrected_sign_in_id,
    previous_display_name, corrected_display_name, reason, corrected_at
  ) values (
    created_correction_id, requested_environment, requested_account_id,
    created_authorization_id, previous_correction_id, requested_identity_version,
    requested_identity_version + 1, selected_account.sign_in_id,
    requested_corrected_sign_in_id, selected_account.display_name,
    requested_corrected_display_name, requested_reason, correction_time
  );

  update pac_dsd.program_accounts account
  set sign_in_id = requested_corrected_sign_in_id,
      display_name = requested_corrected_display_name,
      identity_version = requested_identity_version + 1
  where account.account_id = requested_account_id;

  insert into pac_dsd.program_account_invitation_closures (
    invitation_id, outcome, closed_by_account_id, closed_by_session_id, reason
  )
  select invitation.invitation_id, 'revoked', selected_authorization.account_id,
    selected_authorization.session_id,
    'Account identity was corrected; every earlier reset or recovery code was invalidated.'
  from pac_dsd.program_account_invitations invitation
  join pac_dsd.program_account_invitation_secrets secret
    on secret.invitation_id = invitation.invitation_id
  where invitation.invitation_type in ('credential_reset', 'owner_recovery')
    and invitation.target_account_id = requested_account_id
    and invitation.environment = requested_environment
    and not exists (
      select 1 from pac_dsd.program_account_invitation_closures closure
      where closure.invitation_id = invitation.invitation_id
    )
  on conflict on constraint program_account_invitation_closures_pkey do nothing;

  delete from pac_dsd.program_account_invitation_secrets secret
  using pac_dsd.program_account_invitations invitation,
    pac_dsd.program_account_invitation_closures closure
  where secret.invitation_id = invitation.invitation_id
    and closure.invitation_id = invitation.invitation_id
    and invitation.invitation_type in ('credential_reset', 'owner_recovery')
    and invitation.target_account_id = requested_account_id
    and invitation.environment = requested_environment;

  insert into pac_dsd.program_account_session_revocations (
    session_id, reason, revoked_by_account_id, revoked_by_session_id
  )
  select session.session_id,
    'Account identity was corrected; sign in again with the current sign-in ID.',
    selected_authorization.account_id,
    selected_authorization.session_id
  from pac_dsd.program_account_sessions session
  where session.account_id = requested_account_id
    and not exists (
      select 1 from pac_dsd.program_account_session_revocations revoked
      where revoked.session_id = session.session_id
    );

  perform pac_dsd.consume_protected_action(
    created_authorization_id,
    'account_identity_correction',
    created_correction_id::text
  );
  return query select
    created_correction_id,
    requested_account_id,
    requested_identity_version + 1,
    requested_corrected_sign_in_id,
    requested_corrected_display_name,
    correction_time;
end;
$$;

-- Ownership transfer binds the owner's typed successor identity to immutable
-- evidence and rechecks it while holding the successor account lock. An
-- identity correction racing the transfer therefore produces a retryable
-- refusal instead of transferring authority to a changed projection.
drop function if exists pac_dsd.transfer_program_owner(
  text, text, text, text, uuid, text
);
drop function if exists pac_dsd.transfer_program_owner(
  text, text, text, text, uuid, integer, text, text
);

create function pac_dsd.transfer_program_owner(
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text,
  requested_successor_account_id uuid,
  requested_successor_identity_version integer,
  requested_confirm_sign_in_id text,
  requested_reason text
)
returns table (
  transfer_id uuid,
  from_account_id uuid,
  to_account_id uuid,
  transferred_at timestamptz
)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  created_authorization_id uuid;
  selected_authorization pac_dsd.protected_action_authorizations%rowtype;
  current_owner_grant pac_dsd.access_grants%rowtype;
  successor_account pac_dsd.program_accounts%rowtype;
  successor_grant_id uuid := gen_random_uuid();
  created_transfer pac_dsd.program_owner_transfers%rowtype;
begin
  if requested_environment is null
    or requested_environment not in ('local', 'preview', 'production')
    or requested_successor_account_id is null
    or requested_successor_identity_version is null
    or requested_successor_identity_version < 1
    or requested_confirm_sign_in_id is null
    or requested_confirm_sign_in_id <> lower(requested_confirm_sign_in_id)
    or requested_confirm_sign_in_id !~ '^[a-z0-9][a-z0-9._-]{2,63}$'
    or requested_reason is null
    or requested_reason <> btrim(requested_reason)
    or char_length(requested_reason) not between 3 and 471
    or requested_reason ~ '[[:cntrl:]]' then
    raise exception 'Invalid owner-transfer request' using errcode = '22023';
  end if;
  -- Recovery uses this same first lock. Keeping one global ordering prevents a
  -- transfer/recovery advisory-lock and owner-grant row-lock deadlock.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-owner:' || requested_environment, 0)
  );
  created_authorization_id := pac_dsd.authorize_protected_action(
    requested_session_token_digest,
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256,
    'one-dhs-pac',
    'owner',
    'owner_transfer',
    'account',
    requested_successor_account_id::text,
    pac_dsd.protected_action_fingerprint(
      'owner_transfer',
      jsonb_build_object(
        'successorAccountId', requested_successor_account_id,
        'successorIdentityVersion', requested_successor_identity_version,
        'confirmSignInId', requested_confirm_sign_in_id,
        'reason', requested_reason,
        'environment', requested_environment
      )
    )
  );
  select * into selected_authorization
  from pac_dsd.protected_action_authorizations stored
  where stored.authorization_id = created_authorization_id;
  if requested_successor_account_id = selected_authorization.account_id then
    raise exception 'The successor must be a different named account' using errcode = '22023';
  end if;
  select * into current_owner_grant
  from pac_dsd.access_grants grant_record
  where grant_record.grant_id = selected_authorization.grant_id
    and grant_record.account_id = selected_authorization.account_id
    and grant_record.environment = requested_environment
    and grant_record.scope_id = 'one-dhs-pac'
    and grant_record.role_key = 'owner'
    and grant_record.grant_contract_version = 'protected-v1'
    and grant_record.revoked_at is null
  for update;
  if current_owner_grant.grant_id is null then
    raise exception 'The current owner authority is no longer active' using errcode = '42501';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-account:' || requested_successor_account_id::text, 0)
  );
  select * into successor_account
  from pac_dsd.program_accounts account
  where account.account_id = requested_successor_account_id
    and account.environment = requested_environment
  for update;
  if successor_account.account_id is null
    or not pac_dsd.program_account_is_active(requested_successor_account_id) then
    raise exception 'The successor account must be active in this environment' using errcode = '42501';
  end if;
  if successor_account.identity_version <> requested_successor_identity_version
    or successor_account.sign_in_id <> requested_confirm_sign_in_id then
    raise exception 'The successor identity changed while the transfer was prepared'
      using errcode = '40001';
  end if;

  update pac_dsd.access_grants
  set revoked_at = clock_timestamp(),
      revoked_by = selected_authorization.account_id::text,
      revoked_by_account_id = selected_authorization.account_id,
      revoked_by_session_id = selected_authorization.session_id,
      revocation_reason = 'Owner authority transferred: ' || requested_reason
  where grant_id = current_owner_grant.grant_id
    and revoked_at is null;
  if not found then
    raise exception 'The owner authority changed during transfer' using errcode = '40001';
  end if;

  insert into pac_dsd.access_grants (
    grant_id, principal_id, scope_id, role_key, granted_by, account_id,
    environment, issued_by_account_id, issued_by_session_id, grant_reason,
    grant_contract_version
  ) values (
    successor_grant_id,
    successor_account.account_id::text,
    'one-dhs-pac',
    'owner',
    selected_authorization.account_id::text,
    successor_account.account_id,
    requested_environment,
    selected_authorization.account_id,
    selected_authorization.session_id,
    'Owner authority transferred: ' || requested_reason,
    'protected-v1'
  );

  insert into pac_dsd.program_owner_transfers (
    environment, authorization_id, from_account_id, to_account_id,
    from_grant_id, to_grant_id, reason
  ) values (
    requested_environment,
    created_authorization_id,
    selected_authorization.account_id,
    successor_account.account_id,
    current_owner_grant.grant_id,
    successor_grant_id,
    requested_reason
  ) returning * into created_transfer;

  insert into pac_dsd.program_account_invitation_closures (
    invitation_id, outcome, closed_by_account_id, closed_by_session_id, reason
  )
  select invitation.invitation_id,
    'revoked',
    selected_authorization.account_id,
    selected_authorization.session_id,
    'Owner authority transferred; every unaccepted code issued by the outgoing owner was invalidated.'
  from pac_dsd.program_account_invitations invitation
  join pac_dsd.program_account_invitation_secrets secret
    on secret.invitation_id = invitation.invitation_id
  left join pac_dsd.protected_action_authorizations issuer
    on issuer.authorization_id = invitation.issued_by_authorization_id
  where invitation.environment = requested_environment
    and (
      issuer.account_id = selected_authorization.account_id
      or invitation.invitation_type = 'owner_recovery'
    )
    and not exists (
      select 1 from pac_dsd.program_account_invitation_closures closure
      where closure.invitation_id = invitation.invitation_id
    )
  on conflict on constraint program_account_invitation_closures_pkey do nothing;
  delete from pac_dsd.program_account_invitation_secrets secret
  using pac_dsd.program_account_invitations invitation,
    pac_dsd.program_account_invitation_closures closure
  where secret.invitation_id = invitation.invitation_id
    and closure.invitation_id = invitation.invitation_id
    and invitation.environment = requested_environment
    and closure.outcome = 'revoked'
    and closure.closed_by_account_id = selected_authorization.account_id
    and closure.closed_by_session_id = selected_authorization.session_id;

  insert into pac_dsd.program_account_session_revocations (
    session_id, reason, revoked_by_account_id, revoked_by_session_id
  )
  select session.session_id,
    'Owner authority transferred; a fresh named sign-in is required.',
    selected_authorization.account_id,
    selected_authorization.session_id
  from pac_dsd.program_account_sessions session
  where session.account_id in (
      selected_authorization.account_id,
      successor_account.account_id
    )
    and not exists (
      select 1 from pac_dsd.program_account_session_revocations revoked
      where revoked.session_id = session.session_id
    );
  perform pac_dsd.consume_protected_action(
    created_authorization_id,
    'owner_transfer',
    created_transfer.transfer_id::text
  );
  return query select
    created_transfer.transfer_id,
    created_transfer.from_account_id,
    created_transfer.to_account_id,
    created_transfer.transferred_at;
end;
$$;

-- A credential lookup carries the identity version into session creation.
-- Rechecking the sign-in ID and version under the account lock closes the
-- lookup-versus-correction race without exposing correction history.
drop function if exists pac_dsd.attest_program_identity_runtime_boundary();
drop function if exists pac_dsd_auth.attest_authentication_broker_boundary();
drop function if exists pac_dsd_auth.start_program_account_session(
  uuid, uuid, text, text, text, text
);
drop function if exists pac_dsd_auth.start_program_account_session(
  uuid, uuid, text, integer, text, text, text, text
);
drop function if exists pac_dsd_auth.lookup_program_login_credential(text, text);
drop function if exists pac_dsd.start_program_account_session(
  uuid, uuid, text, text, text, text
);
drop function if exists pac_dsd.start_program_account_session(
  uuid, uuid, text, integer, text, text, text, text
);
drop function if exists pac_dsd.lookup_program_login_credential(text, text);

create function pac_dsd.lookup_program_login_credential(
  requested_sign_in_id text,
  requested_environment text
)
returns table (
  account_id uuid,
  display_name text,
  credential_id uuid,
  credential_hash text,
  identity_version integer
)
language plpgsql
stable
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
begin
  if requested_sign_in_id is null
    or requested_sign_in_id <> lower(requested_sign_in_id)
    or requested_sign_in_id !~ '^[a-z0-9][a-z0-9._-]{2,63}$'
    or requested_environment not in ('local', 'preview', 'production') then
    return;
  end if;
  return query
  select account.account_id, account.display_name, credential.credential_id,
    secret.credential_hash, account.identity_version
  from pac_dsd.program_accounts account
  join lateral (
    select stored.*
    from pac_dsd.program_account_credentials stored
    where stored.account_id = account.account_id
    order by stored.credential_version desc
    limit 1
  ) credential on true
  join pac_dsd.program_account_credential_secrets secret
    on secret.credential_id = credential.credential_id
  where account.sign_in_id = requested_sign_in_id
    and account.environment = requested_environment
    and pac_dsd.program_account_is_active(account.account_id);
end;
$$;

create function pac_dsd.start_program_account_session(
  requested_account_id uuid,
  requested_credential_id uuid,
  requested_sign_in_id text,
  requested_identity_version integer,
  requested_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text
)
returns table (
  session_id uuid,
  account_id uuid,
  display_name text,
  expires_at timestamptz
)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  selected_account pac_dsd.program_accounts%rowtype;
  selected_credential pac_dsd.program_account_credentials%rowtype;
  created_session pac_dsd.program_account_sessions%rowtype;
begin
  if not pac_dsd.program_identity_activation_is_current(requested_environment,requested_activation_evidence_id,requested_activation_bundle_sha256) then raise exception 'Named program identity is not active in this environment' using errcode='42501'; end if;
  if requested_sign_in_id is null
    or requested_sign_in_id <> lower(requested_sign_in_id)
    or requested_sign_in_id !~ '^[a-z0-9][a-z0-9._-]{2,63}$'
    or requested_identity_version is null
    or requested_identity_version < 1
    or requested_token_digest !~ '^[a-f0-9]{64}$'
    or requested_environment not in ('local', 'preview', 'production')
    or requested_activation_evidence_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
    or requested_activation_bundle_sha256 !~ '^[a-f0-9]{64}$' then
    raise exception 'Invalid protected-session request' using errcode = '22023';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-account:' || requested_account_id::text, 0)
  );
  select * into selected_account
  from pac_dsd.program_accounts account
  where account.account_id = requested_account_id
  for update;
  select * into selected_credential
  from pac_dsd.program_account_credentials credential
  where credential.account_id = requested_account_id
  order by credential.credential_version desc
  limit 1;
  if selected_account.account_id is null
    or selected_account.environment <> requested_environment
    or selected_account.sign_in_id <> requested_sign_in_id
    or selected_account.identity_version <> requested_identity_version
    or not pac_dsd.program_account_is_active(requested_account_id)
    or selected_credential.credential_id is distinct from requested_credential_id
    or not exists (
      select 1 from pac_dsd.program_account_credential_secrets secret
      where secret.credential_id = requested_credential_id
    ) then
    raise exception 'Protected sign-in is not available' using errcode = '42501';
  end if;
  insert into pac_dsd.program_account_sessions (
    account_id, credential_id, token_digest, audience, environment,
    activation_evidence_id, activation_bundle_sha256, expires_at
  ) values (
    requested_account_id, requested_credential_id, requested_token_digest,
    'pac-protected-workspace', requested_environment,
    requested_activation_evidence_id, requested_activation_bundle_sha256,
    clock_timestamp() + interval '8 hours'
  ) returning * into created_session;
  return query select
    created_session.session_id,
    selected_account.account_id,
    selected_account.display_name,
    created_session.expires_at;
end;
$$;

create function pac_dsd_auth.lookup_program_login_credential(
  requested_sign_in_id text,
  requested_environment text
)
returns table (
  account_id uuid,
