  credential_id uuid,
  credential_hash text,
  identity_version integer
)
language sql
stable
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
  select *
  from pac_dsd.lookup_program_login_credential(
    requested_sign_in_id,
    requested_environment
  );
$$;

create function pac_dsd_auth.start_program_account_session(
  requested_account_id uuid,
  requested_credential_id uuid,
  requested_sign_in_id text,
  requested_identity_version integer,
