  );
$$;

drop trigger if exists close_expired_program_grant_before_issue
  on pac_dsd.access_grants;
drop function if exists pac_dsd.close_expired_program_grant_before_issue();

-- A replacement permission closes an expired predecessor through the ordinary
-- exact-target revocation operation. Both records therefore have their own
-- authorization, fingerprint, and consumption evidence inside one transaction.
create or replace function pac_dsd.issue_program_access_grant(
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text,
  requested_account_id uuid,
  requested_scope_id text,
  requested_role_key text,
  requested_expires_at timestamptz,
  requested_reason text
)
returns table (
  grant_id uuid,
  account_id uuid,
  scope_id text,
  role_key text,
  granted_at timestamptz,
  expires_at timestamptz
)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  created_grant_id uuid := gen_random_uuid();
  created_authorization_id uuid;
  selected_authorization pac_dsd.protected_action_authorizations%rowtype;
  created_grant pac_dsd.access_grants%rowtype;
  expired_predecessor_id uuid;
begin
  if requested_role_key not in (
      'content_contributor', 'program_steward', 'publishing_approver',
      'one_dsd_team_member'
    )
    or (
      requested_role_key in ('content_contributor', 'program_steward', 'publishing_approver')
      and requested_scope_id not in ('one-dhs', 'dsd')
    )
    or (requested_role_key = 'one_dsd_team_member' and requested_scope_id <> 'one-dsd-team')
    or requested_reason is null
    or requested_reason <> btrim(requested_reason)
    or char_length(requested_reason) not between 3 and 500
    or requested_reason ~ '[[:cntrl:]]'
    or (requested_expires_at is not null and requested_expires_at <= clock_timestamp()) then
    raise exception 'Invalid role/scope grant request' using errcode = '22023';
  end if;
  created_authorization_id := pac_dsd.authorize_protected_action(
    requested_session_token_digest,
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256,
    requested_scope_id,
    'owner',
    'grant_issue',
    'grant',
    created_grant_id::text,
    pac_dsd.protected_action_fingerprint(
      'grant_issue',
      jsonb_build_object(
        'environment', requested_environment,
        'grantId', created_grant_id,
        'accountId', requested_account_id,
        'scopeId', requested_scope_id,
        'roleKey', requested_role_key,
        'expiresAt', requested_expires_at,
        'reason', requested_reason
      )
    )
  );
  select * into selected_authorization
  from pac_dsd.protected_action_authorizations stored
  where stored.authorization_id = created_authorization_id;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-account:' || requested_account_id::text, 0)
  );
  if not exists (
    select 1 from pac_dsd.program_accounts account
    where account.account_id = requested_account_id
      and account.environment = requested_environment
  ) or not pac_dsd.program_account_is_active(requested_account_id) then
    raise exception 'The account is not active' using errcode = '42501';
  end if;

  select grant_record.grant_id into expired_predecessor_id
  from pac_dsd.access_grants grant_record
  where grant_record.account_id = requested_account_id
    and grant_record.environment = requested_environment
    and grant_record.scope_id = requested_scope_id
    and grant_record.role_key = requested_role_key
    and grant_record.grant_contract_version = 'protected-v1'
    and grant_record.revoked_at is null
    and grant_record.expires_at <= clock_timestamp()
  for update;
  if expired_predecessor_id is not null then
    perform pac_dsd.revoke_program_access_grant(
      requested_session_token_digest,
      requested_environment,
      requested_activation_evidence_id,
      requested_activation_bundle_sha256,
      expired_predecessor_id,
      'Expired permission closed atomically before its replacement was issued.'
    );
  end if;

  insert into pac_dsd.access_grants (
    grant_id, principal_id, scope_id, role_key, granted_by, account_id, environment,
    expires_at, issued_by_account_id, issued_by_session_id, grant_reason,
    grant_contract_version
  ) values (
    created_grant_id,
    requested_account_id::text,
    requested_scope_id,
    requested_role_key,
    selected_authorization.account_id::text,
    requested_account_id,
    requested_environment,
    requested_expires_at,
    selected_authorization.account_id,
    selected_authorization.session_id,
    requested_reason,
    'protected-v1'
  ) returning * into created_grant;
  perform pac_dsd.consume_protected_action(created_authorization_id, 'grant', created_grant_id::text);
  return query select
    created_grant.grant_id,
    created_grant.account_id,
    created_grant.scope_id,
    created_grant.role_key,
    created_grant.granted_at,
    created_grant.expires_at;
end;
$$;

-- Permanent revocation destroys the usable credential verifier. It therefore
-- requires a separately supplied, exact current sign-in ID and binds that
-- confirmation into the protected-action fingerprint.
drop function if exists pac_dsd.change_program_account_state(
  text, text, text, text, uuid, text, text
);
drop function if exists pac_dsd.change_program_account_state(
  text, text, text, text, uuid, text, text, text
);

create function pac_dsd.change_program_account_state(
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text,
  requested_account_id uuid,
  requested_state text,
  requested_reason text,
  requested_confirm_sign_in_id text
)
returns table (account_state_event_id bigint, state text, recorded_at timestamptz)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  action_kind text;
  created_authorization_id uuid;
  selected_authorization pac_dsd.protected_action_authorizations%rowtype;
  selected_account pac_dsd.program_accounts%rowtype;
  current_event pac_dsd.program_account_state_events%rowtype;
  created_event pac_dsd.program_account_state_events%rowtype;
begin
  action_kind := case requested_state
    when 'suspended' then 'account_suspend'
    when 'active' then 'account_reactivate'
    when 'revoked' then 'account_revoke'
    else null
  end;
  if action_kind is null
    or requested_reason is null
    or requested_reason <> btrim(requested_reason)
    or char_length(requested_reason) not between 3 and 500
    or (requested_state = 'revoked' and char_length(requested_reason) > 483)
    or requested_reason ~ '[[:cntrl:]]'
    or (requested_state = 'revoked' and (
      requested_confirm_sign_in_id is null
      or requested_confirm_sign_in_id <> lower(requested_confirm_sign_in_id)
      or requested_confirm_sign_in_id !~ '^[a-z0-9][a-z0-9._-]{2,63}$'
    ))
    or (requested_state <> 'revoked' and requested_confirm_sign_in_id is not null) then
    raise exception 'Invalid account-state request' using errcode = '22023';
  end if;
  created_authorization_id := pac_dsd.authorize_protected_action(
    requested_session_token_digest,
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256,
    'one-dhs-pac',
    'owner',
    action_kind,
    'account',
    requested_account_id::text,
    pac_dsd.protected_action_fingerprint(
      action_kind,
      jsonb_build_object(
        'environment', requested_environment,
        'accountId', requested_account_id,
        'state', requested_state,
        'reason', requested_reason,
        'confirmSignInId', requested_confirm_sign_in_id
      )
    )
  );
  select * into selected_authorization
  from pac_dsd.protected_action_authorizations stored
  where stored.authorization_id = created_authorization_id;
  if requested_account_id = selected_authorization.account_id then
    raise exception 'The global owner cannot change the state of the active owner account from its own session'
      using errcode = '42501';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pac-program-account:' || requested_account_id::text, 0)
  );
  select * into selected_account
  from pac_dsd.program_accounts account
  where account.account_id = requested_account_id
  for update;
  if selected_account.account_id is null
    or selected_account.environment <> requested_environment then
    raise exception 'The account is not available in this environment' using errcode = '42501';
  end if;
  if requested_state = 'revoked'
    and selected_account.sign_in_id <> requested_confirm_sign_in_id then
    raise exception 'The permanent-revocation confirmation does not match the current account'
      using errcode = '40001';
  end if;
  select * into current_event
  from pac_dsd.program_account_state_events state_event
  where state_event.account_id = requested_account_id
  order by state_event.account_state_event_id desc
  limit 1;
  if current_event.account_state_event_id is null then
    raise exception 'The account does not exist' using errcode = 'P0002';
  end if;
  if current_event.state = 'revoked' then
    raise exception 'A permanently revoked account cannot be restored or changed'
      using errcode = '42501';
  end if;
  if current_event.state = requested_state then
    raise exception 'The account is already in the requested state'
      using errcode = '22023';
  end if;
  insert into pac_dsd.program_account_state_events (
    account_id, state, reason, recorded_by_account_id, recorded_by_session_id,
    supersedes_account_state_event_id
  ) values (
    requested_account_id, requested_state, requested_reason,
    selected_authorization.account_id, selected_authorization.session_id,
    current_event.account_state_event_id
  ) returning * into created_event;

  insert into pac_dsd.program_account_invitation_closures (
    invitation_id, outcome, closed_by_account_id, closed_by_session_id, reason
  )
  select reset_invitation.invitation_id, 'revoked', selected_authorization.account_id,
    selected_authorization.session_id,
    'The account state changed; every earlier credential-reset code was invalidated.'
  from pac_dsd.program_account_invitations reset_invitation
  join pac_dsd.program_account_invitation_secrets reset_secret
    on reset_secret.invitation_id = reset_invitation.invitation_id
  where reset_invitation.invitation_type in ('credential_reset', 'owner_recovery')
    and reset_invitation.target_account_id = requested_account_id
    and reset_invitation.environment = requested_environment
    and not exists (
      select 1 from pac_dsd.program_account_invitation_closures closure
      where closure.invitation_id = reset_invitation.invitation_id
    )
  on conflict on constraint program_account_invitation_closures_pkey do nothing;
  delete from pac_dsd.program_account_invitation_secrets reset_secret
  using pac_dsd.program_account_invitations reset_invitation,
    pac_dsd.program_account_invitation_closures closure
  where reset_secret.invitation_id = reset_invitation.invitation_id
    and closure.invitation_id = reset_invitation.invitation_id
    and reset_invitation.invitation_type in ('credential_reset', 'owner_recovery')
    and reset_invitation.target_account_id = requested_account_id
    and reset_invitation.environment = requested_environment;

  insert into pac_dsd.program_account_session_revocations (
    session_id, reason, revoked_by_account_id, revoked_by_session_id
  )
  select session.session_id,
    'Account state changed; a fresh sign-in is required.',
    selected_authorization.account_id,
    selected_authorization.session_id
  from pac_dsd.program_account_sessions session
  where session.account_id = requested_account_id
    and not exists (
      select 1 from pac_dsd.program_account_session_revocations revoked
      where revoked.session_id = session.session_id
    );

  if requested_state = 'revoked' then
    delete from pac_dsd.program_account_credential_secrets secret
    using pac_dsd.program_account_credentials credential
    where secret.credential_id = credential.credential_id
      and credential.account_id = requested_account_id;
    update pac_dsd.access_grants
    set revoked_at = clock_timestamp(),
        revoked_by = selected_authorization.account_id::text,
        revoked_by_account_id = selected_authorization.account_id,
        revoked_by_session_id = selected_authorization.session_id,
        revocation_reason = 'Account revoked: ' || requested_reason
    where account_id = requested_account_id
      and grant_contract_version = 'protected-v1'
      and revoked_at is null
      and role_key <> 'owner';
  end if;
  perform pac_dsd.consume_protected_action(
    created_authorization_id,
    'account_state_event',
    created_event.account_state_event_id::text
  );
  return query select
    created_event.account_state_event_id,
    created_event.state,
    created_event.recorded_at;
end;
$$;

-- Resolve mutation targets exactly so authorization decisions never depend on
-- the account page that happens to be visible in the browser.
drop function if exists pac_dsd.read_program_account_admin_target(
  text, text, text, text, uuid
);

create function pac_dsd.read_program_account_admin_target(
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text,
  requested_account_id uuid
)
returns table (
  account_id uuid,
  sign_in_id text,
  display_name text,
  identity_version integer,
  state text,
  created_at timestamptz
)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  viewer_session_id uuid;
  viewer_account_id uuid;
begin
  select session.session_id, session.account_id
  into viewer_session_id, viewer_account_id
  from pac_dsd.read_program_account_session(
    requested_session_token_digest,
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256
  ) session;
  if viewer_session_id is null or not exists (
    select 1
    from pac_dsd.access_grants grant_record
    where grant_record.account_id = viewer_account_id
      and grant_record.scope_id = 'one-dhs-pac'
      and grant_record.environment = requested_environment
      and grant_record.role_key = 'owner'
      and grant_record.grant_contract_version = 'protected-v1'
      and grant_record.revoked_at is null
      and (grant_record.expires_at is null or grant_record.expires_at > statement_timestamp())
  ) then
    raise exception 'Global owner access is required' using errcode = '42501';
  end if;
  return query
  select account.account_id, account.sign_in_id, account.display_name,
    account.identity_version, current_state.state, account.created_at
  from pac_dsd.program_accounts account
  join lateral (
    select state_event.state
    from pac_dsd.program_account_state_events state_event
    where state_event.account_id = account.account_id
    order by state_event.account_state_event_id desc
    limit 1
  ) current_state on true
  where account.environment = requested_environment
    and account.account_id = requested_account_id;
end;
$$;

-- Return independently paged current accounts and invitations. Grants are
-- complete for the account page; historical grants and correction events stay
-- as operational evidence and never enter the browser.
drop function if exists pac_dsd.read_program_access_overview(text, text, text, text);
drop function if exists pac_dsd.read_program_access_overview(
  text, text, text, text, integer, integer, integer, integer
);

create function pac_dsd.read_program_access_overview(
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text,
  requested_account_offset integer,
  requested_account_limit integer,
  requested_invitation_offset integer,
  requested_invitation_limit integer
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  viewer_session_id uuid;
  viewer_account_id uuid;
  result jsonb;
begin
  if requested_account_offset is null
    or requested_account_offset not between 0 and 1000000
    or requested_account_limit is null
    or requested_account_limit not between 1 and 100
    or requested_invitation_offset is null
    or requested_invitation_offset not between 0 and 1000000
    or requested_invitation_limit is null
    or requested_invitation_limit not between 1 and 100 then
    raise exception 'Invalid program-access page request' using errcode = '22023';
  end if;
  select session.session_id, session.account_id
  into viewer_session_id, viewer_account_id
  from pac_dsd.read_program_account_session(
    requested_session_token_digest,
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256
  ) session;
  if viewer_session_id is null or not exists (
    select 1
    from pac_dsd.access_grants grant_record
    where grant_record.account_id = viewer_account_id
      and grant_record.scope_id = 'one-dhs-pac'
      and grant_record.environment = requested_environment
      and grant_record.role_key = 'owner'
      and grant_record.grant_contract_version = 'protected-v1'
      and grant_record.revoked_at is null
      and (grant_record.expires_at is null or grant_record.expires_at > statement_timestamp())
  ) then
    raise exception 'Global owner access is required' using errcode = '42501';
  end if;
  select jsonb_build_object(
    'accounts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'account_id', bounded.account_id,
        'sign_in_id', bounded.sign_in_id,
        'display_name', bounded.display_name,
        'identity_version', bounded.identity_version,
        'state', bounded.state,
        'created_at', bounded.created_at
      ) order by bounded.display_name, bounded.account_id)
      from (
        select account.account_id, account.sign_in_id, account.display_name,
          account.identity_version, current_state.state, account.created_at
        from pac_dsd.program_accounts account
        join lateral (
          select state_event.state
          from pac_dsd.program_account_state_events state_event
          where state_event.account_id = account.account_id
          order by state_event.account_state_event_id desc
          limit 1
        ) current_state on true
        where account.environment = requested_environment
        order by account.display_name, account.account_id
        offset requested_account_offset
        limit requested_account_limit
      ) bounded
    ), '[]'::jsonb),
    'grants', coalesce((
      select jsonb_agg(jsonb_build_object(
        'grant_id', bounded.grant_id,
        'account_id', bounded.account_id,
        'scope_id', bounded.scope_id,
        'role_key', bounded.role_key,
        'granted_at', bounded.granted_at,
        'expires_at', bounded.expires_at,
        'revoked_at', bounded.revoked_at
      ) order by bounded.granted_at, bounded.grant_id)
      from (
        select grant_record.grant_id, grant_record.account_id,
          grant_record.scope_id, grant_record.role_key,
          grant_record.granted_at, grant_record.expires_at,
          grant_record.revoked_at
        from pac_dsd.access_grants grant_record
        join (
          select account.account_id
          from pac_dsd.program_accounts account
          where account.environment = requested_environment
          order by account.display_name, account.account_id
          offset requested_account_offset
          limit requested_account_limit
        ) account_page on account_page.account_id = grant_record.account_id
        where grant_record.grant_contract_version = 'protected-v1'
          and grant_record.environment = requested_environment
          and grant_record.revoked_at is null
          and (grant_record.expires_at is null
            or grant_record.expires_at > statement_timestamp())
        order by grant_record.granted_at desc, grant_record.grant_id
      ) bounded
    ), '[]'::jsonb),
    'open_invitations', coalesce((
      select jsonb_agg(jsonb_build_object(
        'invitation_id', bounded.invitation_id,
        'invitation_type', bounded.invitation_type,
        'sign_in_id', bounded.sign_in_id,
        'display_name', bounded.display_name,
        'issued_at', bounded.issued_at,
        'expires_at', bounded.expires_at
      ) order by bounded.issued_at, bounded.invitation_id)
      from (
        select invitation.invitation_id, invitation.invitation_type,
          invitation.sign_in_id, invitation.display_name,
          invitation.issued_at, secret.expires_at
        from pac_dsd.program_account_invitations invitation
        join pac_dsd.program_account_invitation_secrets secret
          on secret.invitation_id = invitation.invitation_id
        where secret.expires_at > statement_timestamp()
          and invitation.environment = requested_environment
          and not exists (
            select 1 from pac_dsd.program_account_invitation_closures closure
            where closure.invitation_id = invitation.invitation_id
          )
        order by invitation.issued_at, invitation.invitation_id
        offset requested_invitation_offset
        limit requested_invitation_limit
      ) bounded
    ), '[]'::jsonb),
    'pagination', jsonb_build_object(
      'account_offset', requested_account_offset,
      'account_limit', requested_account_limit,
      'account_total', (
        select count(*)
        from pac_dsd.program_accounts account
        where account.environment = requested_environment
      ),
      'invitation_offset', requested_invitation_offset,
      'invitation_limit', requested_invitation_limit,
      'invitation_total', (
        select count(*)
        from pac_dsd.program_account_invitations invitation
        join pac_dsd.program_account_invitation_secrets secret
          on secret.invitation_id = invitation.invitation_id
        where secret.expires_at > statement_timestamp()
          and invitation.environment = requested_environment
          and not exists (
            select 1 from pac_dsd.program_account_invitation_closures closure
            where closure.invitation_id = invitation.invitation_id
          )
      )
    )
  ) into result;
  return result;
end;
$$;

create function pac_dsd.attest_program_identity_runtime_boundary()
returns table (
  runtime_role text,
  session_role text,
  installation_id uuid,
  identity_tables_denied boolean,
  authorization_allocator_denied boolean,
  authorization_consumer_denied boolean,
  rate_limit_policy_denied boolean,
  owner_recovery_allocator_denied boolean,
  feature_activation_allocator_denied boolean,
  legacy_content_mutations_denied boolean,
  login_credential_lookup_denied boolean,
  session_start_denied boolean,
  authentication_schema_denied boolean,
  authentication_functions_denied boolean,
  runtime_role_attributes_safe boolean,
  runtime_memberships_denied boolean
)
language sql
stable
security definer
set search_path = pg_catalog, pac_dsd
as $$
  select
    session_user::text,
    session_user::text,
    (select identity.installation_id
      from pac_dsd.database_installation_identity identity
      where identity.singleton = 'primary'),
    not exists (
      select 1
      from unnest(array[
        'program_accounts', 'program_account_state_events',
        'program_account_invitations', 'program_account_invitation_secrets',
        'program_account_invitation_closures', 'program_account_credentials',
        'program_account_credential_secrets', 'program_account_sessions',
        'program_account_session_revocations', 'protected_action_authorizations',
        'protected_action_consumptions', 'protected_mutation_feature_evidence',
        'program_owner_transfers', 'protected_feature_activation_events',
        'database_installation_identity', 'program_account_identity_corrections'
      ]::text[]) table_name
      cross join unnest(array[
        'SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'
      ]::text[]) privilege_name
      where pg_catalog.has_table_privilege(
        session_user,
        format('pac_dsd.%I', table_name),
        privilege_name
      )
    ),
    not pg_catalog.has_function_privilege(
      session_user,
      'pac_dsd.authorize_protected_action(text,text,text,text,text,text,text,text,text,text)',
      'execute'
    ),
    not pg_catalog.has_function_privilege(
      session_user,
      'pac_dsd.consume_protected_action(uuid,text,text)',
      'execute'
    ),
    not pg_catalog.has_function_privilege(
      session_user,
      'pac_dsd.assert_runtime_rate_limit_request(text,text,integer,integer)',
      'execute'
    ),
    not pg_catalog.has_function_privilege(
      session_user,
      'pac_dsd.create_program_owner_recovery_invitation(text,uuid,text,timestamp with time zone,text,text,text)',
      'execute'
    ),
    not pg_catalog.has_function_privilege(
      session_user,
      'pac_dsd.record_protected_feature_activation(text,text,text,text,text,text)',
      'execute'
    ),
    not exists (
      select 1
      from pg_catalog.pg_proc procedure
      join pg_catalog.pg_namespace namespace on namespace.oid = procedure.pronamespace
      where namespace.nspname = 'pac_dsd'
        and procedure.proname <> all(array['attest_program_identity_runtime_boundary','read_program_account_session','end_program_account_session','accept_program_account_invitation','create_program_account_invitation','create_program_credential_reset_invitation','issue_program_access_grant','revoke_program_access_grant','revoke_program_account_invitation','change_program_account_state','read_program_access_overview','purge_expired_program_security_records','correct_program_account_identity','transfer_program_owner','read_program_account_admin_target','run_protected_content_mutation','read_contributor_resource_editing_state','read_contributor_resource_release_state','list_contributor_resource_release_queue']::text[])
        and pg_catalog.has_function_privilege(session_user, procedure.oid, 'execute')
    ),
    not pg_catalog.has_function_privilege(
      session_user,
      'pac_dsd.lookup_program_login_credential(text,text)',
      'execute'
    ),
    not pg_catalog.has_function_privilege(
      session_user,
      'pac_dsd.start_program_account_session(uuid,uuid,text,integer,text,text,text,text)',
      'execute'
    ),
    not pg_catalog.has_schema_privilege(session_user, 'pac_dsd_auth', 'usage'),
    not exists (
      select 1
      from pg_catalog.pg_proc procedure
      join pg_catalog.pg_namespace namespace on namespace.oid = procedure.pronamespace
      where namespace.nspname = 'pac_dsd_auth'
        and pg_catalog.has_function_privilege(session_user, procedure.oid, 'execute')
    ),
    exists (
      select 1
      from pg_catalog.pg_roles role_record
      where role_record.rolname = session_user
        and role_record.rolcanlogin
        and not role_record.rolinherit
        and not role_record.rolsuper
        and not role_record.rolcreatedb
        and not role_record.rolcreaterole
        and not role_record.rolreplication
        and not role_record.rolbypassrls
        and role_record.rolconnlimit between 1 and 20
    ),
    not exists (
      select 1
      from pg_catalog.pg_auth_members membership
      join pg_catalog.pg_roles member_role on member_role.oid = membership.member
      join pg_catalog.pg_roles granted_role on granted_role.oid = membership.roleid
      where (member_role.rolname = session_user or granted_role.rolname = session_user)
        and not (
          granted_role.rolname = session_user
          and member_role.rolname = current_user
          and membership.admin_option
          and not membership.inherit_option
          and not membership.set_option
        )
    );
$$;

create function pac_dsd_auth.attest_authentication_broker_boundary()
returns table (
  broker_role text,
  session_role text,
  installation_id uuid,
  pac_schema_denied boolean,
  auth_schema_create_denied boolean,
  identity_tables_denied boolean,
  direct_login_functions_denied boolean,
  login_lookup_allowed boolean,
  session_start_allowed boolean,
  other_auth_functions_denied boolean,
  auth_objects_denied boolean,
  broker_role_attributes_safe boolean,
  broker_memberships_denied boolean
)
language sql
stable
security definer
set search_path = pg_catalog
as $$
  select
    session_user::text,
    session_user::text,
    (select identity.installation_id
      from pac_dsd.database_installation_identity identity
      where identity.singleton = 'primary'),
    not pg_catalog.has_schema_privilege(session_user, 'pac_dsd', 'usage'),
    not pg_catalog.has_schema_privilege(session_user, 'pac_dsd_auth', 'create'),
    not exists (
      select 1
      from pg_catalog.pg_class relation
      join pg_catalog.pg_namespace namespace on namespace.oid = relation.relnamespace
      cross join unnest(array[
        'SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'
      ]::text[]) privilege_name
      where namespace.nspname = 'pac_dsd'
        and relation.relname = any(array[
          'program_accounts', 'program_account_state_events',
          'program_account_invitations', 'program_account_invitation_secrets',
          'program_account_invitation_closures', 'program_account_credentials',
          'program_account_credential_secrets', 'program_account_sessions',
          'program_account_session_revocations', 'protected_action_authorizations',
          'protected_action_consumptions', 'program_account_identity_corrections'
        ]::text[])
        and pg_catalog.has_table_privilege(session_user, relation.oid, privilege_name)
    ),
    not exists (
      select 1
      from pg_catalog.pg_proc procedure
      join pg_catalog.pg_namespace namespace on namespace.oid = procedure.pronamespace
      where namespace.nspname = 'pac_dsd'
        and procedure.proname in (
          'lookup_program_login_credential',
          'start_program_account_session'
        )
        and pg_catalog.has_function_privilege(session_user, procedure.oid, 'execute')
    ),
    pg_catalog.has_function_privilege(
      session_user,
      'pac_dsd_auth.lookup_program_login_credential(text,text)',
      'execute'
    ),
    pg_catalog.has_function_privilege(
      session_user,
      'pac_dsd_auth.start_program_account_session(uuid,uuid,text,integer,text,text,text,text)',
      'execute'
    ),
    not exists (
      select 1
      from pg_catalog.pg_proc procedure
      join pg_catalog.pg_namespace namespace on namespace.oid = procedure.pronamespace
      where namespace.nspname = 'pac_dsd_auth'
        and procedure.oid not in (
          'pac_dsd_auth.lookup_program_login_credential(text,text)'::regprocedure::oid,
          'pac_dsd_auth.start_program_account_session(uuid,uuid,text,integer,text,text,text,text)'::regprocedure::oid,
          'pac_dsd_auth.attest_authentication_broker_boundary()'::regprocedure::oid
        )
        and pg_catalog.has_function_privilege(session_user, procedure.oid, 'execute')
    ),
    not exists (
      select 1
      from pg_catalog.pg_class relation
      join pg_catalog.pg_namespace namespace on namespace.oid = relation.relnamespace
      cross join unnest(array[
        'SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'
      ]::text[]) privilege_name
      where namespace.nspname = 'pac_dsd_auth'
        and relation.relkind in ('r', 'p', 'v', 'm', 'f')
        and pg_catalog.has_table_privilege(session_user, relation.oid, privilege_name)
    ) and not exists (
      select 1
      from pg_catalog.pg_class relation
      join pg_catalog.pg_namespace namespace on namespace.oid = relation.relnamespace
      cross join unnest(array['SELECT', 'UPDATE', 'USAGE']::text[]) privilege_name
      where namespace.nspname = 'pac_dsd_auth'
        and relation.relkind = 'S'
        and pg_catalog.has_sequence_privilege(session_user, relation.oid, privilege_name)
    ),
    exists (
      select 1
      from pg_catalog.pg_roles role_record
      where role_record.rolname = session_user
        and role_record.rolcanlogin
        and not role_record.rolinherit
        and not role_record.rolsuper
        and not role_record.rolcreatedb
        and not role_record.rolcreaterole
        and not role_record.rolreplication
        and not role_record.rolbypassrls
        and role_record.rolconnlimit between 1 and 20
    ),
    not exists (
      select 1
      from pg_catalog.pg_auth_members membership
      join pg_catalog.pg_roles member_role on member_role.oid = membership.member
      join pg_catalog.pg_roles granted_role on granted_role.oid = membership.roleid
      where (member_role.rolname = session_user or granted_role.rolname = session_user)
        and not (
          granted_role.rolname = session_user
          and member_role.rolname = current_user
          and membership.admin_option
          and not membership.inherit_option
          and not membership.set_option
        )
    );
$$;

-- Re-establish the two disjoint application boundaries after replacing the
-- login signatures. The broker receives login only; correction stays runtime
-- owner-only and neither role receives direct identity-table access.
revoke all privileges on function pac_dsd.lookup_program_login_credential(text, text)
  from public, pac_dsd_contributor_runtime;
revoke all privileges on function pac_dsd.start_program_account_session(
  uuid, uuid, text, integer, text, text, text, text
) from public, pac_dsd_contributor_runtime;
revoke all privileges on function pac_dsd.correct_program_account_identity(
  text, text, text, text, uuid, integer, text, text, text, text
) from public;
revoke all privileges on function pac_dsd.change_program_account_state(
  text, text, text, text, uuid, text, text, text
) from public;
revoke all privileges on function pac_dsd.transfer_program_owner(
  text, text, text, text, uuid, integer, text, text
) from public;
revoke all privileges on function pac_dsd.read_program_account_admin_target(
  text, text, text, text, uuid
) from public;
revoke all privileges on function pac_dsd.read_program_access_overview(
  text, text, text, text, integer, integer, integer, integer
) from public;
revoke all privileges on function pac_dsd.assert_program_account_sign_in_reservation()
  from public, pac_dsd_contributor_runtime;
revoke all privileges on function pac_dsd.assert_program_invitation_sign_in_reservation()
  from public, pac_dsd_contributor_runtime;
revoke all privileges on function pac_dsd.assert_program_account_identity_projection()
  from public, pac_dsd_contributor_runtime;
revoke all privileges on function pac_dsd.validate_program_account_identity_correction()
  from public, pac_dsd_contributor_runtime;
revoke all privileges on function pac_dsd.attest_program_identity_runtime_boundary()
  from public, pac_dsd_contributor_runtime;

do $$
declare
  role_name text;
begin
  if exists (select 1 from pg_catalog.pg_roles where rolname = 'pac_dsd_authentication_broker') then
    revoke all privileges on function pac_dsd.lookup_program_login_credential(text, text)
      from pac_dsd_authentication_broker;
    revoke all privileges on function pac_dsd.start_program_account_session(
      uuid, uuid, text, integer, text, text, text, text
    ) from pac_dsd_authentication_broker;
    revoke all privileges on function pac_dsd.correct_program_account_identity(
      text, text, text, text, uuid, integer, text, text, text, text
    ) from pac_dsd_authentication_broker;
    revoke all privileges on function pac_dsd.transfer_program_owner(
      text, text, text, text, uuid, integer, text, text
    ) from pac_dsd_authentication_broker;
    revoke all privileges on function pac_dsd.read_program_account_admin_target(
      text, text, text, text, uuid
    ) from pac_dsd_authentication_broker;
    revoke all privileges on function pac_dsd.read_program_access_overview(
      text, text, text, text, integer, integer, integer, integer
    ) from pac_dsd_authentication_broker;
  end if;

  if exists (select 1 from pg_catalog.pg_roles where rolname = 'pac_dsd_contributor_runtime') then
    grant execute on function pac_dsd.correct_program_account_identity(
      text, text, text, text, uuid, integer, text, text, text, text
    ) to pac_dsd_contributor_runtime;
    grant execute on function pac_dsd.change_program_account_state(
      text, text, text, text, uuid, text, text, text
    ) to pac_dsd_contributor_runtime;
    grant execute on function pac_dsd.transfer_program_owner(
      text, text, text, text, uuid, integer, text, text
    ) to pac_dsd_contributor_runtime;
    grant execute on function pac_dsd.read_program_account_admin_target(
      text, text, text, text, uuid
    ) to pac_dsd_contributor_runtime;
    grant execute on function pac_dsd.read_program_access_overview(
      text, text, text, text, integer, integer, integer, integer
    ) to pac_dsd_contributor_runtime;
    grant execute on function pac_dsd.attest_program_identity_runtime_boundary()
      to pac_dsd_contributor_runtime;
  end if;

  foreach role_name in array array['anon', 'authenticated']
  loop
    if exists (select 1 from pg_catalog.pg_roles where rolname = role_name) then
      execute format(
        'revoke all privileges on function pac_dsd.correct_program_account_identity(text,text,text,text,uuid,integer,text,text,text,text) from %I',
        role_name
      );
      execute format(
        'revoke all privileges on function pac_dsd.change_program_account_state(text,text,text,text,uuid,text,text,text) from %I',
        role_name
      );
      execute format(
        'revoke all privileges on function pac_dsd.transfer_program_owner(text,text,text,text,uuid,integer,text,text) from %I',
        role_name
      );
      execute format(
        'revoke all privileges on function pac_dsd.read_program_account_admin_target(text,text,text,text,uuid) from %I',
        role_name
      );
      execute format(
        'revoke all privileges on function pac_dsd.read_program_access_overview(text,text,text,text,integer,integer,integer,integer) from %I',
        role_name
      );
      execute format(
        'revoke all privileges on function pac_dsd.attest_program_identity_runtime_boundary() from %I',
        role_name
      );
    end if;
  end loop;
end;
$$;

revoke all privileges on schema pac_dsd_auth from public, pac_dsd_contributor_runtime, pac_dsd_authentication_broker;
revoke all privileges on all tables in schema pac_dsd_auth
  from public, pac_dsd_contributor_runtime, pac_dsd_authentication_broker;
revoke all privileges on all sequences in schema pac_dsd_auth
  from public, pac_dsd_contributor_runtime, pac_dsd_authentication_broker;
revoke all privileges on all functions in schema pac_dsd_auth
  from public, pac_dsd_contributor_runtime, pac_dsd_authentication_broker;
grant usage on schema pac_dsd_auth to pac_dsd_authentication_broker;
grant execute on function pac_dsd_auth.lookup_program_login_credential(text, text)
  to pac_dsd_authentication_broker;
grant execute on function pac_dsd_auth.start_program_account_session(
  uuid, uuid, text, integer, text, text, text, text
) to pac_dsd_authentication_broker;
grant execute on function pac_dsd_auth.attest_authentication_broker_boundary()
  to pac_dsd_authentication_broker;

comment on table pac_dsd.program_account_identity_corrections is
  'Append-only identity correction evidence for a stable named program account; not a user profile or staff-facing history.';
comment on function pac_dsd.correct_program_account_identity(
  text, text, text, text, uuid, integer, text, text, text, text
) is
  'Owner-only atomic identity correction: versioned projection, immutable evidence, reset-code closure, and target-session revocation.';
comment on function pac_dsd.transfer_program_owner(
  text, text, text, text, uuid, integer, text, text
) is
  'Owner-only atomic succession with database-locked identity-version and exact-sign-in confirmation.';
comment on function pac_dsd.read_program_access_overview(
  text, text, text, text, integer, integer, integer, integer
) is
  'Owner-only independently paged account and invitation overview; active grants are complete for the returned account page.';

create or replace function pac_dsd.read_program_account_session(
  requested_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text
)
returns table (
  session_id uuid,
  account_id uuid,
  sign_in_id text,
  display_name text,
  credential_id uuid,
  issued_at timestamptz,
  expires_at timestamptz,
  grants jsonb
)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
begin
  if not pac_dsd.program_identity_activation_is_current(requested_environment,requested_activation_evidence_id,requested_activation_bundle_sha256) then return; end if;
  if requested_token_digest !~ '^[a-f0-9]{64}$'
    or requested_environment not in ('local', 'preview', 'production')
    or requested_activation_evidence_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
    or requested_activation_bundle_sha256 !~ '^[a-f0-9]{64}$' then
    return;
  end if;
  return query
  select
    session.session_id,
    account.account_id,
    account.sign_in_id,
    account.display_name,
    session.credential_id,
    session.issued_at,
    session.expires_at,
    coalesce((
      select jsonb_agg(jsonb_build_object(
        'grant_id', grant_record.grant_id,
        'scope_id', grant_record.scope_id,
        'role_key', grant_record.role_key,
        'expires_at', grant_record.expires_at
      ) order by grant_record.scope_id, grant_record.role_key, grant_record.grant_id)
      from pac_dsd.access_grants grant_record
      where grant_record.account_id = account.account_id
        and grant_record.environment = requested_environment
        and grant_record.grant_contract_version = 'protected-v1'
        and grant_record.revoked_at is null
        and (grant_record.expires_at is null or grant_record.expires_at > statement_timestamp())
    ), '[]'::jsonb)
  from pac_dsd.program_account_sessions session
  join pac_dsd.program_accounts account on account.account_id = session.account_id
  join pac_dsd.program_account_credentials credential
    on credential.credential_id = session.credential_id
  where session.token_digest = requested_token_digest
    and session.environment = requested_environment
    and session.activation_evidence_id = requested_activation_evidence_id
    and session.activation_bundle_sha256 = requested_activation_bundle_sha256
    and account.environment = requested_environment
    and session.audience = 'pac-protected-workspace'
    and session.expires_at > statement_timestamp()
    and pac_dsd.program_account_is_active(account.account_id)
    and not exists (
      select 1 from pac_dsd.program_account_session_revocations revoked
      where revoked.session_id = session.session_id
    )
    and credential.credential_version = (
      select max(latest.credential_version)
      from pac_dsd.program_account_credentials latest
      where latest.account_id = account.account_id
    )
    and exists (
      select 1 from pac_dsd.program_account_credential_secrets secret
      where secret.credential_id = credential.credential_id
    );
end;
$$;

create or replace function pac_dsd.accept_program_account_invitation(
  requested_token_digest text,
  requested_credential_hash text,
  requested_session_token_digest text,
  requested_environment text,
  requested_activation_evidence_id text,
  requested_activation_bundle_sha256 text
)
returns table (
  session_id uuid,
  account_id uuid,
  sign_in_id text,
  display_name text,
  expires_at timestamptz,
  bootstrap_owner boolean
)
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  selected_invitation pac_dsd.program_account_invitations%rowtype;
  selected_secret pac_dsd.program_account_invitation_secrets%rowtype;
  selected_account pac_dsd.program_accounts%rowtype;
  created_account_id uuid;
  created_credential_id uuid := gen_random_uuid();
  created_session_id uuid := gen_random_uuid();
  next_credential_version integer;
  session_expiry timestamptz := clock_timestamp() + interval '8 hours';
  is_bootstrap boolean := false;
begin
  if not pac_dsd.program_identity_activation_is_current(requested_environment,requested_activation_evidence_id,requested_activation_bundle_sha256) then raise exception 'Named program identity is not active in this environment' using errcode='42501'; end if;
  if requested_token_digest !~ '^[a-f0-9]{64}$'
    or requested_session_token_digest !~ '^[a-f0-9]{64}$'
    or requested_token_digest = requested_session_token_digest
    or requested_environment not in ('local', 'preview', 'production')
    or requested_activation_evidence_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
    or requested_activation_bundle_sha256 !~ '^[a-f0-9]{64}$'
    or requested_credential_hash !~ E'^\\$pac-scrypt\\$v=1\\$ln=17\\$r=8\\$p=1\\$[A-Za-z0-9_-]{22}\\$[A-Za-z0-9_-]{43}$' then
    raise exception 'Invalid invitation acceptance request' using errcode = '22023';
  end if;
  -- Discover only the immutable lock key before taking a row lock. Every path
  -- that invalidates an invitation takes its canonical advisory lock before it
  -- touches the bearer-secret row; acceptance must use the same order to avoid
  -- a secret-row/account-lock deadlock with reset, recovery, state, or transfer.
  select invitation.* into selected_invitation
  from pac_dsd.program_account_invitation_secrets secret
  join pac_dsd.program_account_invitations invitation
    on invitation.invitation_id = secret.invitation_id
  where secret.token_digest = requested_token_digest;
  if selected_invitation.invitation_id is null then
    raise exception 'Invitation is invalid or no longer available' using errcode = '42501';
  end if;

  if selected_invitation.invitation_type = 'bootstrap_owner' then
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'pac-program-owner-bootstrap:' || selected_invitation.environment,
        0
      )
    );
  elsif selected_invitation.invitation_type = 'new_account' then
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'pac-program-sign-in:' || selected_invitation.environment || ':' || selected_invitation.sign_in_id,
        0
      )
    );
  elsif selected_invitation.invitation_type in ('credential_reset', 'owner_recovery') then
    if selected_invitation.target_account_id is null then
      raise exception 'Invitation is invalid or no longer available' using errcode = '42501';
    end if;
    if selected_invitation.invitation_type = 'owner_recovery' then
      perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
          'pac-program-owner:' || selected_invitation.environment,
          0
        )
      );
    end if;
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'pac-program-account:' || selected_invitation.target_account_id::text,
        0
      )
    );
  else
    raise exception 'Invitation is invalid or no longer available' using errcode = '42501';
  end if;

  select secret.* into selected_secret
  from pac_dsd.program_account_invitation_secrets secret
  where secret.token_digest = requested_token_digest
  for update;
  if selected_secret.invitation_id is null then
    raise exception 'Invitation is invalid or no longer available' using errcode = '42501';
  end if;
  select invitation.* into selected_invitation
  from pac_dsd.program_account_invitations invitation
  where invitation.invitation_id = selected_secret.invitation_id;
  if selected_invitation.invitation_id is null
    or selected_invitation.environment <> requested_environment
    or selected_invitation.activation_evidence_id <> requested_activation_evidence_id
    or selected_invitation.activation_bundle_sha256 <> requested_activation_bundle_sha256
    or selected_secret.expires_at <= clock_timestamp()
    or exists (
      select 1 from pac_dsd.program_account_invitation_closures closure
      where closure.invitation_id = selected_invitation.invitation_id
    ) then
    raise exception 'Invitation is invalid or no longer available' using errcode = '42501';
  end if;

  if selected_invitation.invitation_type in ('bootstrap_owner', 'new_account') then
    if exists (
      select 1 from pac_dsd.program_accounts account
      where account.sign_in_id = selected_invitation.sign_in_id
        and account.environment = requested_environment
    ) then
      raise exception 'The invited sign-in identifier is no longer available' using errcode = '23505';
    end if;
    if selected_invitation.invitation_type = 'bootstrap_owner' and exists (
      select 1 from pac_dsd.access_grants grant_record
      where grant_record.role_key = 'owner'
        and grant_record.scope_id = 'one-dhs-pac'
        and grant_record.environment = requested_environment
        and grant_record.grant_contract_version = 'protected-v1'
    ) then
      raise exception 'The one-time owner bootstrap has already been completed' using errcode = '42501';
    end if;
    insert into pac_dsd.program_accounts (environment, sign_in_id, display_name)
    values (requested_environment, selected_invitation.sign_in_id, selected_invitation.display_name)
    returning * into selected_account;
    created_account_id := selected_account.account_id;
    insert into pac_dsd.program_account_state_events (
      account_id, state, reason, activation_invitation_id
    ) values (
      created_account_id,
      'active',
      'Account activated by accepting its one-time program invitation.',
      selected_invitation.invitation_id
    );
    next_credential_version := 1;
    is_bootstrap := selected_invitation.invitation_type = 'bootstrap_owner';
  else
    created_account_id := selected_invitation.target_account_id;
    select * into selected_account
    from pac_dsd.program_accounts account
    where account.account_id = created_account_id;
    if selected_account.account_id is null
      or selected_account.environment <> requested_environment
      or selected_account.sign_in_id is distinct from selected_invitation.sign_in_id
      or selected_account.display_name is distinct from selected_invitation.display_name
      or not pac_dsd.program_account_is_active(created_account_id) then
      raise exception 'The credential-reset invitation is no longer valid' using errcode = '42501';
    end if;
    if selected_invitation.invitation_type = 'owner_recovery'
      and not exists (
        select 1
        from pac_dsd.access_grants owner_grant
        where owner_grant.account_id = created_account_id
          and owner_grant.environment = requested_environment
          and owner_grant.scope_id = 'one-dhs-pac'
          and owner_grant.role_key = 'owner'
          and owner_grant.grant_contract_version = 'protected-v1'
          and owner_grant.revoked_at is null
          and (owner_grant.expires_at is null or owner_grant.expires_at > clock_timestamp())
          and owner_grant.granted_at <= selected_invitation.issued_at
      ) then
      raise exception 'The owner-recovery invitation is no longer valid' using errcode = '42501';
    end if;
    select coalesce(max(credential.credential_version), 0) + 1
    into next_credential_version
    from pac_dsd.program_account_credentials credential
    where credential.account_id = created_account_id;
  end if;

  insert into pac_dsd.program_account_credentials (
    credential_id, account_id, credential_version, invitation_id
  ) values (
    created_credential_id,
    created_account_id,
    next_credential_version,
    selected_invitation.invitation_id
  );
  delete from pac_dsd.program_account_credential_secrets secret
  using pac_dsd.program_account_credentials credential
  where secret.credential_id = credential.credential_id
    and credential.account_id = created_account_id;
  insert into pac_dsd.program_account_credential_secrets (credential_id, credential_hash)
  values (created_credential_id, requested_credential_hash);

  insert into pac_dsd.program_account_sessions (
    session_id, account_id, credential_id, token_digest, audience, environment,
    activation_evidence_id, activation_bundle_sha256, expires_at
  ) values (
    created_session_id,
    created_account_id,
    created_credential_id,
    requested_session_token_digest,
    'pac-protected-workspace',
    requested_environment,
    requested_activation_evidence_id,
    requested_activation_bundle_sha256,
    session_expiry
  );

  if selected_invitation.invitation_type in ('credential_reset', 'owner_recovery') then
    insert into pac_dsd.program_account_invitation_closures (
      invitation_id, outcome, closed_by_account_id, closed_by_session_id, reason
    )
    select sibling.invitation_id,
      'revoked',
      created_account_id,
      created_session_id,
      'A newer credential reset was accepted; this earlier reset code was invalidated.'
    from pac_dsd.program_account_invitations sibling
    join pac_dsd.program_account_invitation_secrets sibling_secret
      on sibling_secret.invitation_id = sibling.invitation_id
    where sibling.invitation_type in ('credential_reset', 'owner_recovery')
      and sibling.target_account_id = created_account_id
      and sibling.environment = requested_environment
      and sibling.invitation_id <> selected_invitation.invitation_id
      and not exists (
        select 1 from pac_dsd.program_account_invitation_closures closure
        where closure.invitation_id = sibling.invitation_id
      )
    on conflict on constraint program_account_invitation_closures_pkey do nothing;
    delete from pac_dsd.program_account_invitation_secrets sibling_secret
    using pac_dsd.program_account_invitations sibling,
      pac_dsd.program_account_invitation_closures closure
    where sibling_secret.invitation_id = sibling.invitation_id
      and closure.invitation_id = sibling.invitation_id
      and sibling.invitation_type in ('credential_reset', 'owner_recovery')
      and sibling.target_account_id = created_account_id
      and sibling.environment = requested_environment
      and sibling.invitation_id <> selected_invitation.invitation_id;
  end if;

  if is_bootstrap then
    insert into pac_dsd.access_grants (
      principal_id, scope_id, role_key, granted_by, account_id, environment,
      issued_by_account_id, issued_by_session_id, grant_reason,
      grant_contract_version
    ) values (
      created_account_id::text,
      'one-dhs-pac',
      'owner',
      created_account_id::text,
      created_account_id,
      requested_environment,
      created_account_id,
      created_session_id,
      'One-time owner bootstrap accepted under the recorded activation evidence.',
      'protected-v1'
    );
  end if;

  insert into pac_dsd.program_account_invitation_closures (
    invitation_id, outcome, account_id, reason
  ) values (
    selected_invitation.invitation_id,
    'accepted',
    created_account_id,
    'One-time invitation accepted and its bearer secret destroyed.'
  );
  delete from pac_dsd.program_account_invitation_secrets
  where invitation_id = selected_invitation.invitation_id;

  return query select
    created_session_id,
    selected_account.account_id,
    selected_account.sign_in_id,
    selected_account.display_name,
    session_expiry,
    is_bootstrap;
end;
$$;

-- Retain every existing policy by delegating older scopes to its unchanged function.
alter function pac_dsd.assert_runtime_rate_limit_request(text,text,integer,integer) rename to assert_runtime_rate_limit_request_pre_identity_v1;
create function pac_dsd.assert_runtime_rate_limit_request(requested_scope text,requested_subject_hash text,requested_limit integer,requested_window_seconds integer)
returns void language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$ begin
if requested_scope is null or requested_subject_hash is null or requested_limit is null or requested_window_seconds is null then raise exception 'Invalid rate limit request' using errcode='22023'; end if;
if requested_scope not in ('program-login-network','program-login-account','program-invitation-network','program-invitation-code') then perform pac_dsd.assert_runtime_rate_limit_request_pre_identity_v1(requested_scope,requested_subject_hash,requested_limit,requested_window_seconds); return; end if;
if requested_subject_hash !~ '^[a-f0-9]{64}$' or requested_window_seconds<>900 or requested_limit<>(case requested_scope when 'program-login-network' then 40 when 'program-login-account' then 10 when 'program-invitation-network' then 20 else 10 end) then raise exception 'Invalid named sign-in rate limit' using errcode='22023'; end if; end; $$;
alter table pac_dsd.runtime_rate_limits drop constraint runtime_rate_limits_registered_identity;
alter table pac_dsd.runtime_rate_limits add constraint runtime_rate_limits_registered_identity check(scope in ('staff-ask','owner-login','consultation-intake','consultation-tracking','staff-program-outcome','program-login-network','program-login-account','program-invitation-network','program-invitation-code') and subject_hash ~ '^[a-f0-9]{64}$');
revoke all on function pac_dsd.assert_runtime_rate_limit_request(text,text,integer,integer) from public,pac_dsd_app_runtime,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
revoke all on function pac_dsd.assert_runtime_rate_limit_request_pre_identity_v1(text,text,integer,integer) from public,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;


-- 0045_pac_contributor_resource_workflow.sql
-- Named contributor resources. Existing owner functions and approval evidence remain intact.
-- No accounts, role memberships, invitations or activation evidence are created here.

alter table pac_dsd.content_revisions add column protected_authorization_id uuid references pac_dsd.protected_action_authorizations(authorization_id);
create index content_revisions_contributor_authorization_idx on pac_dsd.content_revisions(protected_authorization_id) where protected_authorization_id is not null;
alter table pac_dsd.review_records add column protected_authorization_id uuid references pac_dsd.protected_action_authorizations(authorization_id);
create index review_records_contributor_authorization_idx on pac_dsd.review_records(protected_authorization_id) where protected_authorization_id is not null;
alter table pac_dsd.publication_decisions add column protected_authorization_id uuid references pac_dsd.protected_action_authorizations(authorization_id);
create index publication_decisions_contributor_authorization_idx on pac_dsd.publication_decisions(protected_authorization_id) where protected_authorization_id is not null;
alter table pac_dsd.change_events add column protected_authorization_id uuid references pac_dsd.protected_action_authorizations(authorization_id);
create index change_events_contributor_authorization_idx on pac_dsd.change_events(protected_authorization_id) where protected_authorization_id is not null;

create or replace function pac_dsd.apply_contributor_resource_actor()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  selected_authorization pac_dsd.protected_action_authorizations%rowtype;
  authorization_setting text;
  linked_content_item_id text;
  carried_review pac_dsd.review_records%rowtype;
begin
  authorization_setting := current_setting('pac_dsd.protected_authorization_id', true);
  if authorization_setting is null or authorization_setting = '' then
    return new;
  end if;
  if authorization_setting !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    raise exception 'Invalid transaction-local protected authorization'
      using errcode = '22023';
  end if;
  select stored_authorization.* into selected_authorization
  from pac_dsd.protected_action_authorizations stored_authorization
  join pac_dsd.protected_mutation_feature_evidence feature_evidence
    on feature_evidence.authorization_id = stored_authorization.authorization_id
  where stored_authorization.authorization_id = authorization_setting::uuid
    and feature_evidence.feature_key = 'protected_contribution'
    and feature_evidence.environment = stored_authorization.environment
    and stored_authorization.target_type = 'content_item'
    and stored_authorization.session_expires_at > clock_timestamp()
    and not exists (
      select 1 from pac_dsd.protected_action_consumptions consumption
      where consumption.authorization_id = stored_authorization.authorization_id
    );
  if selected_authorization.authorization_id is null then
    raise exception 'Named protected authorization is unavailable for attribution'
      using errcode = '42501';
  end if;

  if tg_table_name = 'content_revisions' then
    if selected_authorization.action_kind not in (
      'contribution_submit', 'publication_publish', 'publication_republish'
    ) or new.content_item_id <> selected_authorization.target_id then
      raise exception 'Named authorization does not match the content revision'
        using errcode = '42501';
    end if;
    perform pac_dsd.assert_exact_resource_scope(selected_authorization.requested_scope_id, new.canonical_payload);
    new.created_by := selected_authorization.account_id::text;
    new.protected_authorization_id := selected_authorization.authorization_id;
  elsif tg_table_name = 'review_records' then
    select revision.content_item_id into linked_content_item_id
    from pac_dsd.content_revisions revision
    where revision.revision_id = new.revision_id;
    if linked_content_item_id is distinct from selected_authorization.target_id
      or (
        new.status = 'pending'
        and (
          selected_authorization.action_kind <> 'contribution_submit'
          or new.reviewer_id is not null
        )
      )
      or (
        new.status <> 'pending'
        and selected_authorization.action_kind not in (
          'specialist_review', 'publication_publish', 'publication_republish'
        )
      ) then
      raise exception 'Named authorization does not match the review record'
        using errcode = '42501';
    end if;
    -- A pending row is an unassigned review requirement, not a completed act
    -- by the contributor who created the draft. Preserve that distinction.
    if new.status <> 'pending' then
      if selected_authorization.action_kind in ('publication_publish', 'publication_republish') then
        select source.* into carried_review from pac_dsd.review_records source
        join pac_dsd.content_revisions source_revision on source_revision.revision_id=source.revision_id
        join pac_dsd.content_revisions release_revision on release_revision.revision_id=new.revision_id
        where source.review_id=(new.findings->>'carried_forward_from_review_id')::uuid
          and source_revision.content_item_id=selected_authorization.target_id
          and release_revision.based_on_revision_id=source.revision_id
          and source.dimension=new.dimension and source.status=new.status;
        if carried_review.review_id is null then
          raise exception 'The carried review must identify its original decision' using errcode='42501';
        end if;
        new.reviewer_id := carried_review.reviewer_id;
        new.reviewer_role := carried_review.reviewer_role;
        new.findings := new.findings || jsonb_build_object('carried_forward_by', selected_authorization.account_id::text);
      else
        new.reviewer_id := selected_authorization.account_id::text;
        new.reviewer_role := selected_authorization.required_role_key;
      end if;
    end if;
    new.protected_authorization_id := selected_authorization.authorization_id;
  elsif tg_table_name = 'publication_decisions' then
    if selected_authorization.action_kind not in (
      'publication_publish', 'publication_withdraw', 'publication_republish'
    ) or new.content_item_id <> selected_authorization.target_id
      or new.scope_id <> selected_authorization.requested_scope_id then
      raise exception 'Named authorization does not match the publication decision'
        using errcode = '42501';
    end if;
    new.decided_by := selected_authorization.account_id::text;
    new.gate_snapshot := (
      new.gate_snapshot - 'explicit_owner_decision'
    ) || jsonb_build_object(
      'explicit_publishing_approval', true,
      'authorized_role', selected_authorization.required_role_key
    );
    new.protected_authorization_id := selected_authorization.authorization_id;
  elsif tg_table_name = 'change_events' then
    if new.object_id <> selected_authorization.target_id or new.scope_id <> selected_authorization.requested_scope_id then
      raise exception 'Named authorization does not match the change record'
        using errcode = '42501';
    end if;
    new.actor_id := selected_authorization.account_id::text;
    new.actor_role := selected_authorization.required_role_key;
    new.protected_authorization_id := selected_authorization.authorization_id;
  else
    raise exception 'Named actor trigger is attached to an unregistered table'
      using errcode = '55000';
  end if;
  return new;
end;
$$;
create trigger content_revisions_contributor_actor before insert on pac_dsd.content_revisions for each row execute function pac_dsd.apply_contributor_resource_actor();
create trigger review_records_contributor_actor before insert on pac_dsd.review_records for each row execute function pac_dsd.apply_contributor_resource_actor();
create trigger publication_decisions_contributor_actor before insert on pac_dsd.publication_decisions for each row execute function pac_dsd.apply_contributor_resource_actor();
create trigger change_events_contributor_actor before insert on pac_dsd.change_events for each row execute function pac_dsd.apply_contributor_resource_actor();

create or replace function pac_dsd.run_protected_content_mutation(
  requested_session_token_digest text,
  requested_environment text,
  requested_identity_evidence_id text,
  requested_identity_bundle_sha256 text,
  requested_feature_evidence_id text,
  requested_feature_bundle_sha256 text,
  requested_scope_id text,
  requested_operation text,
  requested_target_id text,
  requested_payload jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  created_authorization_id uuid;
  selected_activation_event_id bigint;
  required_role text;
  action_kind text;
  target_type text;
  result_record_type text;
  request_fingerprint text;
  result_payload jsonb;
  result_record_id text;
begin
  if requested_session_token_digest is null
    or requested_session_token_digest !~ '^[a-f0-9]{64}$'
    or requested_environment is null
    or requested_environment not in ('local', 'preview', 'production')
    or requested_identity_evidence_id is null
    or requested_identity_evidence_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
    or requested_identity_bundle_sha256 is null
    or requested_identity_bundle_sha256 !~ '^[a-f0-9]{64}$'
    or requested_feature_evidence_id is null
    or requested_feature_evidence_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
    or requested_feature_bundle_sha256 is null
    or requested_feature_bundle_sha256 !~ '^[a-f0-9]{64}$'
    or requested_scope_id is null
    or requested_scope_id not in ('one-dhs', 'dsd')
    or requested_operation is null
    or requested_target_id is null
    or requested_target_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{0,159}$'
    or requested_payload is null
    or jsonb_typeof(requested_payload) is distinct from 'object' then
    raise exception 'Invalid protected content mutation boundary' using errcode = '22023';
  end if;

  case requested_operation
    when 'resource_draft_save' then
      perform pac_dsd.assert_exact_jsonb_keys(
        requested_payload,
        array['expectedRevisionId', 'fields', 'changeNote'],
        array['expectedRevisionId', 'fields', 'changeNote']
      );
      required_role := 'content_contributor';
      action_kind := 'contribution_submit';
      target_type := 'content_item';
      result_record_type := 'content_revision';
    when 'resource_review_record' then
      perform pac_dsd.assert_exact_jsonb_keys(
        requested_payload,
        array['revisionId', 'dimension', 'expectedPriorReviewId', 'decision', 'note'],
        array['revisionId', 'dimension', 'expectedPriorReviewId', 'decision', 'note']
      );
      required_role := 'program_steward';
      action_kind := 'specialist_review';
      target_type := 'content_item';
      result_record_type := 'review';
    when 'resource_publish', 'resource_withdraw', 'resource_republish' then
      if requested_operation = 'resource_withdraw' then
        perform pac_dsd.assert_exact_jsonb_keys(
          requested_payload,
          array['revisionId', 'expectedScopeDecisionId', 'reason'],
          array['revisionId', 'expectedScopeDecisionId', 'reason']
        );
        action_kind := 'publication_withdraw';
      else
        perform pac_dsd.assert_exact_jsonb_keys(
          requested_payload,
          array[
            'revisionId', 'expectedScopeDecisionId', 'reason', 'sensitivityClass',
            'unauthenticatedExposurePermitted', 'exposureReason'
          ],
          array[
            'revisionId', 'expectedScopeDecisionId', 'reason', 'sensitivityClass',
            'unauthenticatedExposurePermitted', 'exposureReason'
          ]
        );
        action_kind := case requested_operation
          when 'resource_publish' then 'publication_publish'
          else 'publication_republish'
        end;
      end if;
      required_role := 'publishing_approver';
      target_type := 'content_item';
      result_record_type := 'publication';
    else
      raise exception 'Protected content operation is not registered' using errcode = '22023';
  end case;

  if requested_operation = 'resource_draft_save'
    and (
      jsonb_typeof(requested_payload -> 'expectedRevisionId') is distinct from 'string'
      or requested_payload ->> 'expectedRevisionId'
        !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or jsonb_typeof(
        requested_payload -> 'fields'
      ) is distinct from 'object'
      or jsonb_typeof(requested_payload -> 'changeNote') not in ('string', 'null')
    ) then
    raise exception 'Protected draft payload has invalid value types' using errcode = '22023';
  end if;

  if requested_operation = 'resource_review_record'
    and (
      jsonb_typeof(requested_payload -> 'revisionId') is distinct from 'string'
      or requested_payload ->> 'revisionId'
        !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or jsonb_typeof(requested_payload -> 'dimension') is distinct from 'string'
      or requested_payload ->> 'dimension' not in (
        'language_alignment', 'factual_currentness', 'accessibility', 'scope', 'placement',
        'rights_and_consent', 'community_representation', 'legal_policy'
      )
      or jsonb_typeof(requested_payload -> 'expectedPriorReviewId') not in ('string', 'null')
      or (
        jsonb_typeof(requested_payload -> 'expectedPriorReviewId') = 'string'
        and requested_payload ->> 'expectedPriorReviewId'
          !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      )
      or jsonb_typeof(requested_payload -> 'decision') is distinct from 'string'
      or requested_payload ->> 'decision' not in ('pass', 'revise', 'blocked', 'not_applicable')
      or jsonb_typeof(requested_payload -> 'note') not in ('string', 'null')
    ) then
    raise exception 'Protected resource-review payload has invalid value types' using errcode = '22023';
  end if;

  if requested_operation in ('resource_publish', 'resource_republish')
    and (
      jsonb_typeof(requested_payload -> 'revisionId') is distinct from 'string'
      or requested_payload ->> 'revisionId'
        !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or jsonb_typeof(requested_payload -> 'expectedScopeDecisionId') not in ('string', 'null')
      or (
        jsonb_typeof(requested_payload -> 'expectedScopeDecisionId') = 'string'
        and requested_payload ->> 'expectedScopeDecisionId' !~ '^[0-9]{1,19}$'
      )
      or jsonb_typeof(requested_payload -> 'reason') is distinct from 'string'
      or jsonb_typeof(requested_payload -> 'sensitivityClass') is distinct from 'string'
      or requested_payload ->> 'sensitivityClass' not in ('S0', 'S1')
      or jsonb_typeof(requested_payload -> 'unauthenticatedExposurePermitted') is distinct from 'boolean'
      or requested_payload ->> 'unauthenticatedExposurePermitted' <> 'true'
      or jsonb_typeof(requested_payload -> 'exposureReason') is distinct from 'string'
    ) then
    raise exception 'Protected resource-publication payload has invalid value types' using errcode = '22023';
  end if;

  if requested_operation = 'resource_withdraw'
    and (
      jsonb_typeof(requested_payload -> 'revisionId') is distinct from 'string'
      or requested_payload ->> 'revisionId'
        !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or jsonb_typeof(requested_payload -> 'expectedScopeDecisionId') not in ('string', 'null')
      or (
        jsonb_typeof(requested_payload -> 'expectedScopeDecisionId') = 'string'
        and requested_payload ->> 'expectedScopeDecisionId' !~ '^[0-9]{1,19}$'
      )
      or jsonb_typeof(requested_payload -> 'reason') is distinct from 'string'
    ) then
    raise exception 'Protected resource-withdrawal payload has invalid value types' using errcode = '22023';
  end if;

  -- Hold a shared feature lock through authorization, mutation, attribution,
  -- and consumption. The activation recorder takes the matching exclusive
  -- lock, so an inactive event cannot return while an old-active widening
  -- publication is still able to commit behind it.
  perform pg_catalog.pg_advisory_xact_lock_shared(
    pg_catalog.hashtextextended(
      'pac-protected-feature:' || requested_environment || ':protected_contribution',
      0
    )
  );
  if not exists (
    select 1
    from pac_dsd.protected_feature_activation_events activation
    where activation.activation_event_id = (
      select max(current_event.activation_event_id)
      from pac_dsd.protected_feature_activation_events current_event
      where current_event.environment = requested_environment
        and current_event.feature_key = 'protected_contribution'
    )
      and (
        (
          activation.state = 'active'
          and activation.evidence_id = requested_feature_evidence_id
          and activation.activation_bundle_sha256 = requested_feature_bundle_sha256
        )
        or (
          -- An inactive control plane stops every exposure-widening mutation,
          -- but it must not strand an incident responder with harmful content
          -- still published. Containment remains limited to resource withdrawal
          -- operations, the publishing-approver grant checked below, and an
          -- evidence bundle that this environment previously activated.
          activation.state = 'inactive'
          and requested_operation = 'resource_withdraw'
          and exists (
            select 1
            from pac_dsd.protected_feature_activation_events prior_activation
            where prior_activation.environment = requested_environment
              and prior_activation.feature_key = 'protected_contribution'
              and prior_activation.state = 'active'
              and prior_activation.evidence_id = requested_feature_evidence_id
              and prior_activation.activation_bundle_sha256 = requested_feature_bundle_sha256
              and prior_activation.activation_event_id < activation.activation_event_id
          )
        )
      )
  ) then
    raise exception 'Protected contribution is not active under the database control plane'
      using errcode = 'PAF01';
  end if;
  select activation.activation_event_id into selected_activation_event_id
  from pac_dsd.protected_feature_activation_events activation
  where activation.activation_event_id = (
    select max(current_event.activation_event_id)
    from pac_dsd.protected_feature_activation_events current_event
    where current_event.environment = requested_environment
      and current_event.feature_key = 'protected_contribution'
  );

  request_fingerprint := pac_dsd.protected_action_fingerprint(
    action_kind,
    jsonb_build_object(
      'environment', requested_environment,
      'featureEvidenceId', requested_feature_evidence_id,
      'featureBundleSha256', requested_feature_bundle_sha256,
      'scopeId', requested_scope_id,
      'operation', requested_operation,
      'targetId', requested_target_id,
      'payload', requested_payload
    )
  );
  created_authorization_id := pac_dsd.authorize_protected_action(
    requested_session_token_digest,
    requested_environment,
    requested_identity_evidence_id,
    requested_identity_bundle_sha256,
    requested_scope_id,
    required_role,
    action_kind,
    target_type,
    requested_target_id,
    request_fingerprint
  );
  insert into pac_dsd.protected_mutation_feature_evidence (
    authorization_id, activation_event_id, feature_key, environment,
    evidence_id, activation_bundle_sha256
  ) values (
    created_authorization_id, selected_activation_event_id,
    'protected_contribution', requested_environment,
    requested_feature_evidence_id, requested_feature_bundle_sha256
  );
  perform pg_catalog.set_config(
    'pac_dsd.protected_authorization_id',
    created_authorization_id::text,
    true
  );

  if requested_operation = 'resource_draft_save' then
    select to_jsonb(created) into result_payload
    from pac_dsd.create_resource_draft(
      requested_scope_id,
      requested_target_id,
      (requested_payload ->> 'expectedRevisionId')::uuid,
      requested_payload -> 'fields',
      requested_payload ->> 'changeNote'
    ) created;
    result_record_id := result_payload ->> 'base_revision_id';
  elsif requested_operation = 'resource_review_record' then
    result_payload := pac_dsd.record_resource_review(
      requested_scope_id,
      requested_target_id,
      (requested_payload ->> 'revisionId')::uuid,
      requested_payload ->> 'dimension',
      (requested_payload ->> 'expectedPriorReviewId')::uuid,
      requested_payload ->> 'decision',
      requested_payload ->> 'note'
    );
    select review ->> 'reviewId' into result_record_id
    from jsonb_array_elements(coalesce(result_payload #> '{draft,reviews}', '[]'::jsonb)) review
    where review ->> 'dimension' = requested_payload ->> 'dimension'
    limit 1;
  elsif requested_operation = 'resource_publish' then
    result_payload := pac_dsd.publish_resource_draft(
      requested_scope_id,
      requested_target_id,
      (requested_payload ->> 'revisionId')::uuid,
      (requested_payload ->> 'expectedScopeDecisionId')::bigint,
      requested_payload ->> 'reason',
      requested_payload ->> 'sensitivityClass',
      (requested_payload ->> 'unauthenticatedExposurePermitted')::boolean,
      requested_payload ->> 'exposureReason'
    );
    result_record_id := result_payload ->> 'scopeDecisionId';
  elsif requested_operation = 'resource_withdraw' then
    result_payload := pac_dsd.withdraw_resource_publication(
      requested_scope_id,
      requested_target_id,
      (requested_payload ->> 'revisionId')::uuid,
      (requested_payload ->> 'expectedScopeDecisionId')::bigint,
      requested_payload ->> 'reason'
    );
    result_record_id := result_payload ->> 'scopeDecisionId';
  elsif requested_operation = 'resource_republish' then
    result_payload := pac_dsd.republish_resource_revision(
      requested_scope_id,
      requested_target_id,
      (requested_payload ->> 'revisionId')::uuid,
      (requested_payload ->> 'expectedScopeDecisionId')::bigint,
      requested_payload ->> 'reason',
      requested_payload ->> 'sensitivityClass',
      (requested_payload ->> 'unauthenticatedExposurePermitted')::boolean,
      requested_payload ->> 'exposureReason'
    );
    result_record_id := result_payload ->> 'scopeDecisionId';

  end if;

  if result_payload is null
    or result_record_id is null
    or result_record_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{0,159}$' then
    raise exception 'Protected mutation did not produce a valid result record'
      using errcode = '40001';
  end if;
  if result_record_type = 'content_revision' then
    if result_record_id !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or not exists (
        select 1
        from pac_dsd.content_revisions revision
        where revision.revision_id = result_record_id::uuid
          and revision.content_item_id = requested_target_id
          and revision.protected_authorization_id = created_authorization_id
      ) then
      raise exception 'Protected revision result is not linked to its authorization'
        using errcode = '40001';
    end if;
  elsif result_record_type = 'review' then
    if result_record_id !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or not exists (
        select 1
        from pac_dsd.review_records review
        join pac_dsd.content_revisions revision on revision.revision_id = review.revision_id
        where review.review_id = result_record_id::uuid
          and revision.content_item_id = requested_target_id
          and review.protected_authorization_id = created_authorization_id
      ) then
      raise exception 'Protected review result is not linked to its authorization'
        using errcode = '40001';
    end if;
  elsif result_record_type = 'publication' then
    if result_record_id !~ '^[0-9]{1,19}$'
      or not exists (
        select 1
        from pac_dsd.publication_decisions decision
        where decision.publication_decision_id = result_record_id::bigint
          and decision.content_item_id = requested_target_id
          and decision.protected_authorization_id = created_authorization_id
      ) then
      raise exception 'Protected publication result is not linked to its authorization'
        using errcode = '40001';
    end if;
  else
    raise exception 'Protected mutation returned an unregistered result type'
      using errcode = '40001';
  end if;
  perform pac_dsd.consume_protected_action(
    created_authorization_id,
    result_record_type,
    result_record_id
  );
  perform pg_catalog.set_config('pac_dsd.protected_authorization_id', '', true);
  return result_payload;
end;
$$;

-- Reads do not allocate action authorizations. They require a current named session,
-- current scoped grant and matching committed identity/contribution activation.
create function pac_dsd.assert_contributor_resource_read(
  token_digest text, environment_name text, identity_evidence text, identity_hash text,
  contribution_evidence text, contribution_hash text, requested_scope text
) returns void language plpgsql volatile security definer
set search_path=pg_catalog,pac_dsd set row_security=off as $$
declare named_session record; activation pac_dsd.protected_feature_activation_events%rowtype; allowed boolean;
begin
  if requested_scope is null or requested_scope not in ('one-dhs','dsd')
    or contribution_evidence is null or contribution_evidence !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,159}$'
    or contribution_hash is null or contribution_hash !~ '^[a-f0-9]{64}$' then
    raise exception 'Invalid resource read boundary' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock_shared(hashtextextended('pac-protected-feature:' || environment_name || ':protected_identity',0));
  perform pg_advisory_xact_lock_shared(hashtextextended('pac-protected-feature:' || environment_name || ':protected_contribution',0));
  if not exists (
    select 1 from pac_dsd.protected_feature_activation_events a
    where a.activation_event_id=(select max(b.activation_event_id) from pac_dsd.protected_feature_activation_events b
      where b.environment=environment_name and b.feature_key='protected_identity')
      and a.state='active' and a.evidence_id=identity_evidence and a.activation_bundle_sha256=identity_hash
  ) then raise exception 'Individual access is not active' using errcode='PAF01'; end if;
  select * into named_session from pac_dsd.read_program_account_session(token_digest,environment_name,identity_evidence,identity_hash);
  if named_session.session_id is null then raise exception 'A current individual session is required' using errcode='PAI01'; end if;
  select * into activation from pac_dsd.protected_feature_activation_events a
    where a.environment=environment_name and a.feature_key='protected_contribution'
    order by a.activation_event_id desc limit 1;
  if activation.activation_event_id is null or not (
    (activation.state='active' and activation.evidence_id=contribution_evidence and activation.activation_bundle_sha256=contribution_hash)
    or (activation.state='inactive' and exists(select 1 from pac_dsd.protected_feature_activation_events prior
      where prior.environment=environment_name and prior.feature_key='protected_contribution'
      and prior.state='active' and prior.evidence_id=contribution_evidence and prior.activation_bundle_sha256=contribution_hash
      and prior.activation_event_id<activation.activation_event_id))
  ) then raise exception 'Resource contributions are not active' using errcode='PAF01'; end if;
  with recursive ancestry as (
    select scope_id,parent_scope_id from pac_dsd.program_scopes where scope_id=requested_scope and active
    union all select p.scope_id,p.parent_scope_id from pac_dsd.program_scopes p join ancestry c on c.parent_scope_id=p.scope_id where p.active
  ) select exists(select 1 from ancestry a join pac_dsd.access_grants g on g.scope_id=a.scope_id
    where g.account_id=named_session.account_id and g.principal_id=named_session.account_id::text
    and g.environment=environment_name and g.grant_contract_version='protected-v1'
    and g.revoked_at is null and (g.expires_at is null or g.expires_at>clock_timestamp())
    and (g.role_key='publishing_approver' or (activation.state='active' and g.role_key in ('content_contributor','program_steward')))) into allowed;
  if not allowed then raise exception 'Current scoped contribution access is required' using errcode='PAA01'; end if;
end; $$;

create function pac_dsd.read_contributor_resource_editing_state(
  token_digest text, environment_name text, identity_evidence text, identity_hash text,
  contribution_evidence text, contribution_hash text, requested_scope text, requested_id text
) returns table(content_item_id text,published_revision_id uuid,base_revision_id uuid,editable_fields jsonb,has_unpublished_changes boolean)
language plpgsql volatile security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
begin
  perform pac_dsd.assert_contributor_resource_read(token_digest,environment_name,identity_evidence,identity_hash,contribution_evidence,contribution_hash,requested_scope);
  return query select * from pac_dsd.read_resource_editing_state(requested_scope,requested_id);
end; $$;
create function pac_dsd.read_contributor_resource_release_state(
  token_digest text, environment_name text, identity_evidence text, identity_hash text,
  contribution_evidence text, contribution_hash text, requested_scope text, requested_id text
) returns jsonb language plpgsql volatile security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
begin
  perform pac_dsd.assert_contributor_resource_read(token_digest,environment_name,identity_evidence,identity_hash,contribution_evidence,contribution_hash,requested_scope);
  return pac_dsd.read_resource_release_state(requested_scope,requested_id);
end; $$;
create function pac_dsd.list_contributor_resource_release_queue(
  token_digest text, environment_name text, identity_evidence text, identity_hash text,
  contribution_evidence text, contribution_hash text, requested_scope text
) returns table(content_item_id text,title text,has_draft boolean,ready_to_publish boolean,is_published boolean,changed_at timestamptz)
language plpgsql volatile security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
begin
  perform pac_dsd.assert_contributor_resource_read(token_digest,environment_name,identity_evidence,identity_hash,contribution_evidence,contribution_hash,requested_scope);
  return query select * from pac_dsd.list_resource_release_queue(requested_scope);
end; $$;

revoke all on function pac_dsd.apply_contributor_resource_actor() from public,pac_dsd_app_runtime,pac_dsd_contributor_runtime;
revoke all on function pac_dsd.assert_contributor_resource_read(text,text,text,text,text,text,text) from public,pac_dsd_app_runtime,pac_dsd_contributor_runtime;
revoke all on function pac_dsd.run_protected_content_mutation(text,text,text,text,text,text,text,text,text,jsonb) from public,pac_dsd_app_runtime;
revoke all on function pac_dsd.read_contributor_resource_editing_state(text,text,text,text,text,text,text,text) from public,pac_dsd_app_runtime;
revoke all on function pac_dsd.read_contributor_resource_release_state(text,text,text,text,text,text,text,text) from public,pac_dsd_app_runtime;
revoke all on function pac_dsd.list_contributor_resource_release_queue(text,text,text,text,text,text,text) from public,pac_dsd_app_runtime;
grant execute on function pac_dsd.run_protected_content_mutation(text,text,text,text,text,text,text,text,text,jsonb) to pac_dsd_contributor_runtime;
grant execute on function pac_dsd.read_contributor_resource_editing_state(text,text,text,text,text,text,text,text) to pac_dsd_contributor_runtime;
grant execute on function pac_dsd.read_contributor_resource_release_state(text,text,text,text,text,text,text,text) to pac_dsd_contributor_runtime;
grant execute on function pac_dsd.list_contributor_resource_release_queue(text,text,text,text,text,text,text) to pac_dsd_contributor_runtime;


-- 0046_pac_ask_deletion_and_restore_preparation.sql

-- Content-free deletion evidence. No question, answer, author, address or staff
-- identifier is retained here. This receipt alone is not an external backup journal.
create table pac_dsd.ask_response_deletions (
  record_id uuid primary key,
  deleted_at timestamptz not null default clock_timestamp(),
  reason text not null check(reason in ('owner_delete','retention_expired','restore_excluded'))
);
alter table pac_dsd.ask_response_deletions enable row level security;
revoke all on pac_dsd.ask_response_deletions from public,pac_dsd_app_runtime,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
create trigger ask_response_deletions_immutable before update or delete on pac_dsd.ask_response_deletions
for each row execute function pac_dsd.prevent_immutable_change();

create or replace function pac_dsd.append_ask_response_record(p_record jsonb) returns void
language plpgsql security definer set search_path=pg_catalog,pac_dsd as $$
declare existing jsonb; requested_id uuid := (p_record->>'id')::uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended('pac-ask-record:'||requested_id::text,0));
  if exists(select 1 from pac_dsd.ask_response_deletions where record_id=requested_id) then
    raise exception 'ASK record was deleted and cannot be restored by append.' using errcode='55000';
  end if;
  insert into pac_dsd.ask_response_records(record_id,created_at,expires_at,record)
  values(requested_id,(p_record->>'createdAt')::timestamptz,(p_record->>'expiresAt')::timestamptz,p_record)
  on conflict(record_id) do nothing;
  select record into existing from pac_dsd.ask_response_records where record_id=requested_id;
  if existing is distinct from p_record then raise exception 'ASK record is immutable'; end if;
end $$;

create or replace function pac_dsd.list_ask_response_records(p_limit integer,p_before_at timestamptz,p_before_id uuid,p_now timestamptz)
returns table(record jsonb) language plpgsql security definer set search_path=pg_catalog,pac_dsd as $$
begin
  if p_limit is null or p_limit<1 or p_limit>101 or p_now is null or ((p_before_at is null)<>(p_before_id is null)) then raise exception 'Invalid record page'; end if;
  return query select r.record from pac_dsd.ask_response_records r
  where not exists(select 1 from pac_dsd.ask_response_deletions d where d.record_id=r.record_id)
    and (r.expires_at is null or r.expires_at>p_now)
    and (p_before_at is null or (r.created_at,r.record_id)<(p_before_at,p_before_id))
  order by r.created_at desc,r.record_id desc limit p_limit;
end $$;

create or replace function pac_dsd.delete_ask_response_records(p_ids jsonb) returns integer
language plpgsql security definer set search_path=pg_catalog,pac_dsd as $$
declare deleted integer; requested_id uuid;
begin
  if p_ids is null or jsonb_typeof(p_ids)<>'array' or jsonb_array_length(p_ids)<1 or jsonb_array_length(p_ids)>100
    or exists(select 1 from jsonb_array_elements(p_ids) v where jsonb_typeof(v)<>'string') then raise exception 'Invalid record selection'; end if;
  for requested_id in select distinct value::uuid from jsonb_array_elements_text(p_ids) order by value::uuid loop
    perform pg_advisory_xact_lock(hashtextextended('pac-ask-record:'||requested_id::text,0));
    insert into pac_dsd.ask_response_deletions(record_id,reason) values(requested_id,'owner_delete') on conflict(record_id) do nothing;
  end loop;
  delete from pac_dsd.ask_response_records where record_id in(select value::uuid from jsonb_array_elements_text(p_ids));
  get diagnostics deleted=row_count; return deleted;
end $$;

create or replace function pac_dsd.purge_expired_ask_response_records(p_now timestamptz) returns integer
language plpgsql security definer set search_path=pg_catalog,pac_dsd as $$
declare requested_id uuid; deleted integer := 0; removed integer;
begin
  if p_now is null then raise exception 'Invalid record cleanup time'; end if;
  for requested_id in select record_id from pac_dsd.ask_response_records where expires_at<=p_now order by record_id limit 1000 loop
    perform pg_advisory_xact_lock(hashtextextended('pac-ask-record:'||requested_id::text,0));
    insert into pac_dsd.ask_response_deletions(record_id,reason) values(requested_id,'retention_expired') on conflict(record_id) do nothing;
    delete from pac_dsd.ask_response_records where record_id=requested_id and expires_at<=p_now;
    get diagnostics removed=row_count; deleted:=deleted+removed;
  end loop;
  return deleted;
end $$;

create table pac_dsd.program_recovery_preparations (
  recovery_id uuid primary key,
  environment text not null check(environment in ('local','preview','production')),
  prepared_at timestamptz not null default clock_timestamp(),
  ask_records_excluded integer not null check(ask_records_excluded>=0),
  named_sessions_revoked integer not null check(named_sessions_revoked>=0),
  invitation_secrets_removed integer not null check(invitation_secrets_removed>=0),
  credential_secrets_removed integer not null check(credential_secrets_removed>=0)
);
alter table pac_dsd.program_recovery_preparations enable row level security;
revoke all on pac_dsd.program_recovery_preparations from public,pac_dsd_app_runtime,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
create trigger program_recovery_preparations_immutable before update or delete on pac_dsd.program_recovery_preparations
for each row execute function pac_dsd.prevent_immutable_change();

-- Restored grants have no current authority merely because new credentials exist.
-- There is deliberately no application unlock. A later, independently verified
-- reconciliation is required before any named capability can be reactivated.
create function pac_dsd.enforce_restored_identity_quarantine() returns trigger
language plpgsql security definer set search_path=pg_catalog,pac_dsd as $$
begin
  if new.state='active' and exists(select 1 from pac_dsd.program_recovery_preparations where environment=new.environment) then
    raise exception 'Restored identity authority remains quarantined pending current grant reconciliation.' using errcode='55000';
  end if;
  return new;
end $$;
revoke all on function pac_dsd.enforce_restored_identity_quarantine() from public,pac_dsd_app_runtime,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
create trigger restored_identity_quarantine before insert on pac_dsd.protected_feature_activation_events
for each row execute function pac_dsd.enforce_restored_identity_quarantine();

-- Migration-owner-only preparation, run while the restored target has no traffic.
-- Without a surviving current deletion journal, exclude ALL restored ASK bodies.
-- Credentials and invitation tokens in an old backup are not current authority.
create function pac_dsd.prepare_isolated_program_restore(p_environment text,p_recovery_id uuid)
returns jsonb language plpgsql security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
declare prior pac_dsd.program_recovery_preparations%rowtype; activation pac_dsd.protected_feature_activation_events%rowtype;
  excluded integer; revoked integer; invitations integer; credentials integer;
begin
  if p_environment is null or p_environment not in ('local','preview','production') or p_recovery_id is null then
    raise exception 'Invalid isolated recovery preparation' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('pac-isolated-program-restore',0));
  select * into prior from pac_dsd.program_recovery_preparations where recovery_id=p_recovery_id;
  if found then
    if prior.environment<>p_environment then raise exception 'Recovery boundary mismatch'; end if;
    return to_jsonb(prior);
  end if;
  if exists(select 1 from pac_dsd.program_accounts where environment<>p_environment) then
    raise exception 'Recovery target contains a different named identity environment' using errcode='42501'; end if;
  for activation in
    select distinct on(feature_key) * from pac_dsd.protected_feature_activation_events
    where environment=p_environment order by feature_key,activation_event_id desc
  loop
    perform pac_dsd.record_protected_feature_activation(p_environment,activation.feature_key,'inactive',activation.evidence_id,activation.activation_bundle_sha256,'Isolated restore: current authority must be reconciled before access.');
  end loop;
  insert into pac_dsd.program_account_session_revocations(session_id,reason)
    select session_id,'Old backup session invalidated during isolated restore.'
    from pac_dsd.program_account_sessions where environment=p_environment on conflict(session_id) do nothing;
  get diagnostics revoked=row_count;
  insert into pac_dsd.program_account_invitation_closures(invitation_id,outcome,recovery_evidence_id,reason)
    select i.invitation_id,'superseded','restore:'||p_recovery_id::text,'Old backup invitation invalidated during isolated restore.'
    from pac_dsd.program_account_invitations i join pac_dsd.program_account_invitation_secrets s using(invitation_id)
    where i.environment=p_environment on conflict(invitation_id) do nothing;
  delete from pac_dsd.program_account_invitation_secrets s using pac_dsd.program_account_invitations i where s.invitation_id=i.invitation_id and i.environment=p_environment;
  get diagnostics invitations=row_count;
  delete from pac_dsd.program_account_credential_secrets s using pac_dsd.program_account_credentials c,pac_dsd.program_accounts a
    where s.credential_id=c.credential_id and c.account_id=a.account_id and a.environment=p_environment;
  get diagnostics credentials=row_count;
  lock table pac_dsd.ask_response_records in access exclusive mode;
  insert into pac_dsd.ask_response_deletions(record_id,reason)
    select record_id,'restore_excluded' from pac_dsd.ask_response_records on conflict(record_id) do nothing;
  delete from pac_dsd.ask_response_records; get diagnostics excluded=row_count;
  insert into pac_dsd.program_recovery_preparations(recovery_id,environment,ask_records_excluded,named_sessions_revoked,invitation_secrets_removed,credential_secrets_removed)
    values(p_recovery_id,p_environment,excluded,revoked,invitations,credentials);
  select * into prior from pac_dsd.program_recovery_preparations where recovery_id=p_recovery_id;
  return to_jsonb(prior);
end $$;
revoke all on function pac_dsd.prepare_isolated_program_restore(text,uuid) from public,pac_dsd_app_runtime,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
-- Existing owner API functions keep their exact runtime execute grants.
revoke all on function pac_dsd.append_ask_response_record(jsonb) from public,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
revoke all on function pac_dsd.list_ask_response_records(integer,timestamptz,uuid,timestamptz) from public,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
revoke all on function pac_dsd.delete_ask_response_records(jsonb) from public,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
revoke all on function pac_dsd.purge_expired_ask_response_records(timestamptz) from public,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;


-- 0047_pac_ask_evidence_claims.sql
-- Exact ASK evidence references. Older records without these optional fields remain valid.
-- This checks reference integrity and retained passages; it does not prove factual truth.
create function pac_dsd.valid_ask_source_evidence(e jsonb) returns boolean
language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
declare r jsonb; span jsonb;
begin
 if jsonb_typeof(e) is distinct from 'object' or not(e ?& array['version','evidenceId','documentId','contentHash','revisions','excerpt'])
 or (e-array['version','evidenceId','documentId','contentHash','revisions','excerpt'])<>'{}'::jsonb
 or e->'version'<>'1'::jsonb or jsonb_typeof(e->'documentId')<>'string' or length(e->>'documentId') not between 1 and 200
 or jsonb_typeof(e->'evidenceId')<>'string' or e->>'evidenceId' !~ '^[a-f0-9]{64}$'
 or jsonb_typeof(e->'contentHash')<>'string' or e->>'contentHash' !~ '^[a-f0-9]{64}$'
 or jsonb_typeof(e->'revisions')<>'array' or jsonb_array_length(e->'revisions') not between 1 and 32 then return false;end if;
 for r in select value from jsonb_array_elements(e->'revisions') loop
  if jsonb_typeof(r)<>'object' or not(r ?& array['sourceId','revisionId','payloadHash','scope'])
   or (r-array['sourceId','revisionId','payloadHash','scope'])<>'{}'::jsonb
   or jsonb_typeof(r->'sourceId')<>'string' or length(r->>'sourceId') not between 1 and 200
   or jsonb_typeof(r->'scope')<>'string' or length(r->>'scope') not between 1 and 60
   or jsonb_typeof(r->'payloadHash')<>'string' or r->>'payloadHash' !~ '^[a-f0-9]{64}$'
   or (r->'revisionId'<>'null'::jsonb and (jsonb_typeof(r->'revisionId')<>'string' or r->>'revisionId' !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'))
   then return false;end if;
 end loop;
 span=e->'excerpt';
 if jsonb_typeof(span)<>'object' or not(span ?& array['start','end','quote']) or (span-array['start','end','quote'])<>'{}'::jsonb
  or jsonb_typeof(span->'quote')<>'string' or length(span->>'quote') not between 1 and 1500
  or jsonb_typeof(span->'start')<>'number' or span->>'start' !~ '^[0-9]+$'
  or jsonb_typeof(span->'end')<>'number' or span->>'end' !~ '^[0-9]+$'
  or (span->>'end')::bigint-(span->>'start')::bigint<>length(span->>'quote')
 then return false;end if;
 return true;
exception when others then return false;
end $$;
revoke all on function pac_dsd.valid_ask_source_evidence(jsonb) from public;

create function pac_dsd.valid_ask_evidence_claims(a jsonb) returns boolean
language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
declare source jsonb; claim jsonb; ref jsonb; e jsonb; span jsonb;
begin
 for source in select value from jsonb_array_elements(a->'sources') loop
  if source ? 'evidence' and pac_dsd.valid_ask_source_evidence(source->'evidence') is not true then return false;end if;
 end loop;
 if not(a ? 'evidenceClaims') then return true;end if;
 if jsonb_typeof(a->'evidenceClaims')<>'array' or jsonb_array_length(a->'evidenceClaims')>12 then return false;end if;
 for claim in select value from jsonb_array_elements(a->'evidenceClaims') loop
  if jsonb_typeof(claim)<>'object' or not(claim ?& array['kind','text','references']) or (claim-array['kind','text','references'])<>'{}'::jsonb
   or claim->>'kind' not in ('source_excerpt','inference') or jsonb_typeof(claim->'kind')<>'string'
   or jsonb_typeof(claim->'text')<>'string' or length(claim->>'text') not between 1 and 4000
   or jsonb_typeof(claim->'references')<>'array' or jsonb_array_length(claim->'references') not between 1 and 4 then return false;end if;
  if claim->>'kind'='source_excerpt' and (jsonb_array_length(claim->'references')<>1 or claim->>'text'<>claim->'references'->0->>'quote') then return false;end if;
  for ref in select value from jsonb_array_elements(claim->'references') loop
   if jsonb_typeof(ref)<>'object' or not(ref ?& array['evidenceId','start','end','quote']) or (ref-array['evidenceId','start','end','quote'])<>'{}'::jsonb
    or jsonb_typeof(ref->'evidenceId')<>'string' or ref->>'evidenceId' !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(ref->'quote')<>'string' or length(ref->>'quote') not between 1 and 1500
    or jsonb_typeof(ref->'start')<>'number' or ref->>'start' !~ '^[0-9]+$'
    or jsonb_typeof(ref->'end')<>'number' or ref->>'end' !~ '^[0-9]+$'
    or (ref->>'end')::bigint-(ref->>'start')::bigint<>length(ref->>'quote') then return false;end if;
   select item->'evidence' into e from jsonb_array_elements(a->'sources') item where item->'evidence'->>'evidenceId'=ref->>'evidenceId' limit 1;
   if e is null then return false;end if;
   span=e->'excerpt';
   if (ref->>'start')::bigint<(span->>'start')::bigint or (ref->>'end')::bigint>(span->>'end')::bigint
    or substring(span->>'quote' from ((ref->>'start')::integer-(span->>'start')::integer+1) for length(ref->>'quote'))<>ref->>'quote'
   then return false;end if;
  end loop;
 end loop;
 return true;
exception when others then return false;
end $$;
revoke all on function pac_dsd.valid_ask_evidence_claims(jsonb) from public;

alter table pac_dsd.ask_response_records drop constraint ask_record_contract;
alter table pac_dsd.ask_response_records add constraint ask_record_contract check ((
    jsonb_typeof(record) = 'object'
    and octet_length(record::text) <= 1048576
    and record ?& array['id','traceId','createdAt','programScope','researchMode','status','httpStatus','question','questionOmittedReason','response','researchStatus','expiresAt']
    and (record - array['id','traceId','createdAt','programScope','researchMode','status','httpStatus','question','questionOmittedReason','response','researchStatus','expiresAt']) = '{}'::jsonb
    and (record->>'id')::uuid = record_id
    and (record->>'traceId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    and (record->>'createdAt')::timestamptz = created_at
    and ((record->>'expiresAt')::timestamptz is not distinct from expires_at)
    and record->>'programScope' in ('one-dhs','dsd')
    and record->>'researchMode' in ('auto','program_only','web_results','current_web','deep_research')
    and record->>'status' in ('answered','limited','refused','unavailable','failed')
    and record->>'researchStatus' in ('not_requested','used','not_connected','failed')
    and jsonb_typeof(record->'httpStatus') = 'number'
    and (record->>'httpStatus')::integer between 100 and 599
    and (
      (jsonb_typeof(record->'question') = 'string' and length(record->>'question') between 1 and 4000 and record->'questionOmittedReason' = 'null'::jsonb)
      or (record->'question' = 'null'::jsonb and record->>'questionOmittedReason' = 'private_information')
    )
    and jsonb_typeof(record->'response') = 'object'
    and (
      (jsonb_typeof(record->'response'->'error') = 'string' and ((record->'response') - 'error') = '{}'::jsonb)
      or (record->'response'->>'kind' = 'answer' and jsonb_typeof(record->'response'->'answer') = 'object'
        and ((record->'response'->'answer') - array['shortAnswer','whyItMatters','sources','limits','nextActions','questions','conflict','consultation','pathSuggestion','notice','publicResearch','practiceArtifact','evidenceClaims']) = '{}'::jsonb
        and (record->'response'->'answer') ?& array['shortAnswer','whyItMatters','sources','limits','nextActions']
        and jsonb_typeof(record->'response'->'answer'->'shortAnswer') = 'string'
        and jsonb_typeof(record->'response'->'answer'->'whyItMatters') = 'string'
        and jsonb_typeof(record->'response'->'answer'->'sources') = 'array'
        and jsonb_typeof(record->'response'->'answer'->'limits') = 'array'
        and jsonb_typeof(record->'response'->'answer'->'nextActions') = 'array'
        and pac_dsd.valid_ask_evidence_claims(record->'response'->'answer') is true
        and (not ((record->'response'->'answer') ? 'practiceArtifact') or (pac_dsd.valid_ask_practice_artifact(record->'response'->'answer'->'practiceArtifact') is true and record->'response'->'answer'->'practiceArtifact'->>'traceId' = record->>'traceId' and record->'response'->'answer'->'practiceArtifact'->>'context' = case record->>'programScope' when 'dsd' then 'one_dsd' else 'one_dhs' end))
        and ((record->'response') - array['kind','answer']) = '{}'::jsonb)
      or (record->'response'->>'kind' = 'refusal' and jsonb_typeof(record->'response'->'safety') = 'object'
        and ((record->'response'->'safety') - array['message','redirect','alternatives']) = '{}'::jsonb
        and ((record->'response') - array['kind','safety']) = '{}'::jsonb)
    )
  ) is true);


-- 0049_pac_page_text_overrides.sql
-- Universal inline editing. The consultant can change any visible text on any
-- page, in place, separately for the One DHS and One DSD views. Each saved
-- change is keyed by page route, view scope, and a stable element key, and keeps
-- the original wording so a change can be reverted.

do $$
begin
  if not exists (select 1 from pg_catalog.pg_roles where rolname = 'pac_dsd_app_runtime') then
    raise exception 'Required least-privilege role pac_dsd_app_runtime is missing';
  end if;
end;
$$;

do $$ begin
  if not exists (select 1 from pg_catalog.pg_roles where rolname = 'pac_dsd_owner_writer') then
    create role pac_dsd_owner_writer login noinherit nosuperuser nocreatedb nocreaterole nobypassrls;
  end if;
end; $$;
grant usage on schema pac_dsd to pac_dsd_owner_writer;

create table if not exists pac_dsd.page_text_overrides (
  scope_id text not null check (scope_id in ('one-dhs', 'dsd')),
  route text not null check (route ~ '^/[A-Za-z0-9_./\-]*$' and length(route) <= 300),
  element_key text not null check (length(element_key) between 1 and 200),
  original_text text not null check (length(original_text) <= 20000),
  replacement_text text not null check (length(replacement_text) <= 20000),
  updated_at timestamptz not null default now(),
  updated_by text not null default 'consultant',
  primary key (scope_id, route, element_key)
);

create or replace function pac_dsd.read_page_text_overrides(requested_scope_id text, requested_route text)
returns table (element_key text, original_text text, replacement_text text)
language sql
stable
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
  select o.element_key, o.original_text, o.replacement_text
  from pac_dsd.page_text_overrides o
  where o.scope_id = requested_scope_id and o.route = requested_route
  order by o.element_key;
$$;

-- Replaces the full set of overrides for one page and view. An entry whose
-- replacement equals its original is dropped, which is how a revert is saved.
create or replace function pac_dsd.save_page_text_overrides(
  requested_scope_id text,
  requested_route text,
  entries jsonb
)
returns integer
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  saved integer;
begin
  if requested_scope_id not in ('one-dhs', 'dsd') then
    raise exception 'Unknown program scope' using errcode = '22023';
  end if;
  if jsonb_typeof(entries) <> 'array' or jsonb_array_length(entries) > 2000 then
    raise exception 'Invalid page text entries' using errcode = '22023';
  end if;
  delete from pac_dsd.page_text_overrides o
  where o.scope_id = requested_scope_id and o.route = requested_route;
  insert into pac_dsd.page_text_overrides (scope_id, route, element_key, original_text, replacement_text)
  select requested_scope_id, requested_route,
    entry->>'key', entry->>'original', entry->>'text'
  from jsonb_array_elements(entries) as entry
  where entry ? 'key' and entry ? 'original' and entry ? 'text'
    and (entry->>'text') is distinct from (entry->>'original');
  get diagnostics saved = row_count;
  return saved;
end;
$$;

revoke all privileges on pac_dsd.page_text_overrides from public, pac_dsd_app_runtime;
revoke all on function pac_dsd.read_page_text_overrides(text, text) from public;
revoke all on function pac_dsd.save_page_text_overrides(text, text, jsonb) from public;
grant execute on function pac_dsd.read_page_text_overrides(text, text) to pac_dsd_app_runtime;
revoke all on function pac_dsd.save_page_text_overrides(text, text, jsonb) from pac_dsd_app_runtime;
grant execute on function pac_dsd.save_page_text_overrides(text, text, jsonb) to pac_dsd_owner_writer;


-- 0050_pac_consultant_override_clear_and_delete.sql
-- Consultant override for editing and deletion.
-- 1. Any page wording field may be cleared outright; the database no longer
--    refuses a blank field or an empty list.
-- 2. The consultant can delete a resource outright. The item is retired, which
--    removes it from every page and both program views at once. A restore
--    function exists so a mistaken deletion can be undone by the consultant.

do $$
begin
  if not exists (select 1 from pg_catalog.pg_roles where rolname = 'pac_dsd_app_runtime') then
    raise exception 'Required least-privilege role pac_dsd_app_runtime is missing';
  end if;
end;
$$;

create or replace function pac_dsd.assert_valid_surface_document(
  requested_surface_id text,
  requested_scope_id text,
  requested_document jsonb
)
returns void
language plpgsql
stable
set search_path = pg_catalog, pac_dsd
as $$
declare
  definition pac_dsd.surface_definitions%rowtype;
  field_definition jsonb;
  field_key text;
  field_kind text;
  field_required boolean;
  field_maximum integer;
  item_maximum integer;
  field_value jsonb;
  text_value text;
  list_item jsonb;
  block_item jsonb;
  link_item jsonb;
  block_type text;
  expected_keys text[];
begin
  perform pac_dsd.assert_surface_request(requested_scope_id, requested_surface_id, true);
  select * into strict definition
  from pac_dsd.surface_definitions
  where surface_id = requested_surface_id and active = true;

  if requested_document is null or jsonb_typeof(requested_document) <> 'object'
    or octet_length(convert_to(requested_document::text, 'UTF8')) > 1000000 then
    raise exception 'Page wording must be a complete, reasonably sized document' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_object_keys(requested_document) actual(name)
    where actual.name <> all(array['schemaVersion', 'surfaceId', 'scope', 'values']::text[])
  ) or not requested_document ?& array['schemaVersion', 'surfaceId', 'scope', 'values']::text[] then
    raise exception 'Page wording document fields are not allowed' using errcode = '22023';
  end if;
  if jsonb_typeof(requested_document -> 'schemaVersion') <> 'number'
    or (requested_document ->> 'schemaVersion')::integer <> definition.schema_version
    or requested_document ->> 'surfaceId' <> requested_surface_id
    or requested_document ->> 'scope' <> requested_scope_id
    or jsonb_typeof(requested_document -> 'values') <> 'object' then
    raise exception 'Page wording document identity does not match this page area' using errcode = '22023';
  end if;

  select array_agg(field ->> 'key' order by ordinal)
  into expected_keys
  from jsonb_array_elements(definition.field_contract) with ordinality registered(field, ordinal);
  if expected_keys is null
    or not (requested_document -> 'values') ?& expected_keys
    or exists (
      select 1 from jsonb_object_keys(requested_document -> 'values') actual(name)
      where actual.name <> all(expected_keys)
    ) then
    raise exception 'Page wording fields do not match this page area' using errcode = '22023';
  end if;

  for field_definition in select value from jsonb_array_elements(definition.field_contract)
  loop
    field_key := field_definition ->> 'key';
    field_kind := field_definition ->> 'kind';
    -- Consultant override: any field may be cleared outright. Nothing is required.
    field_required := false;
    field_maximum := coalesce((field_definition ->> 'maxLength')::integer,
      case when field_kind = 'short' then 500 when field_kind = 'url' then 2000 else 10000 end);
    item_maximum := coalesce((field_definition ->> 'maxItems')::integer, 100);
    field_value := requested_document -> 'values' -> field_key;

    if field_kind = 'course-pack' then
      if requested_surface_id not like 'course.%' or field_value#>>'{course,id}' <> substring(requested_surface_id from 8) then
        raise exception 'Course identity does not match the publication' using errcode='22023';
      end if;
      perform pac_dsd.assert_course_schema(field_value, pac_dsd.course_pack_schema());
      if (select count(*) from jsonb_array_elements(field_value#>'{course,lessons}')) <>
         (select count(distinct lesson->>'id') from jsonb_array_elements(field_value#>'{course,lessons}') lesson) then
        raise exception 'Course lesson identifiers must be unique' using errcode='22023';
      end if;
      for block_item in select block from jsonb_array_elements(field_value#>'{course,lessons}') lesson cross join lateral jsonb_array_elements(lesson->'blocks') block loop
        if block_item->>'type'='knowledgeCheck' and not exists(select 1 from jsonb_array_elements(block_item->'options') option where option->'correct'='true'::jsonb) then
          raise exception 'Course knowledge check requires a correct answer' using errcode='22023';
        end if;
        if block_item->>'type'='sorting' and exists(select 1 from jsonb_array_elements(block_item->'items') item where not (block_item->'categories') @> jsonb_build_array(item->>'category')) then
          raise exception 'Course sorting category is not available' using errcode='22023';
        end if;
      end loop;
      continue;
    end if;

    if field_kind in ('short', 'long', 'url') then
      if jsonb_typeof(field_value) <> 'string' then
        raise exception 'A page wording field has the wrong kind of value' using errcode = '22023';
      end if;
      text_value := field_value #>> '{}';
      if length(text_value) > field_maximum or (field_required and length(btrim(text_value)) = 0) then
        raise exception 'A page wording field is blank or too long' using errcode = '22023';
      end if;
      if length(btrim(text_value)) > 0 then
        if field_kind = 'url' then
          perform pac_dsd.assert_safe_page_link(text_value);
        else
          perform pac_dsd.assert_plain_page_text(text_value);
        end if;
      end if;
      continue;
    end if;

    if jsonb_typeof(field_value) <> 'array'
      or jsonb_array_length(field_value) > item_maximum
      or (field_required and jsonb_array_length(field_value) = 0) then
      raise exception 'A page wording list is empty, too long, or has the wrong kind of value' using errcode = '22023';
    end if;

    if field_kind = 'string-list' then
      for list_item in select value from jsonb_array_elements(field_value)
      loop
        if jsonb_typeof(list_item) <> 'string' then
          raise exception 'A page wording list must contain text' using errcode = '22023';
        end if;
        text_value := list_item #>> '{}';
        if length(btrim(text_value)) = 0 or length(text_value) > field_maximum then
          raise exception 'A page wording list item is blank or too long' using errcode = '22023';
        end if;
        perform pac_dsd.assert_plain_page_text(text_value);
      end loop;
    elsif field_kind = 'link-list' then
      for link_item in select value from jsonb_array_elements(field_value)
      loop
        if jsonb_typeof(link_item) <> 'object'
          or not link_item ?& array['label', 'href']::text[]
          or exists (
            select 1 from jsonb_object_keys(link_item) actual(name)
            where actual.name <> all(array['label', 'href']::text[])
          ) or jsonb_typeof(link_item -> 'label') <> 'string'
          or jsonb_typeof(link_item -> 'href') <> 'string' then
          raise exception 'A page wording link has fields that are not allowed' using errcode = '22023';
        end if;
        text_value := link_item ->> 'label';
        if length(btrim(text_value)) = 0 or length(text_value) > field_maximum then
          raise exception 'A page wording link label is blank or too long' using errcode = '22023';
        end if;
        perform pac_dsd.assert_plain_page_text(text_value);
        perform pac_dsd.assert_safe_page_link(link_item ->> 'href');
      end loop;
    elsif field_kind = 'rich-blocks' then
      for block_item in select value from jsonb_array_elements(field_value)
      loop
        if jsonb_typeof(block_item) <> 'object' or jsonb_typeof(block_item -> 'type') <> 'string' then
          raise exception 'A structured page section has fields that are not allowed' using errcode = '22023';
        end if;
        block_type := block_item ->> 'type';
        if block_type = 'heading' then
          if not block_item ?& array['type', 'level', 'text']::text[]
            or exists (
              select 1 from jsonb_object_keys(block_item) actual(name)
              where actual.name <> all(array['type', 'level', 'text']::text[])
            ) or jsonb_typeof(block_item -> 'level') <> 'number'
            or (block_item ->> 'level')::integer not in (2, 3)
            or jsonb_typeof(block_item -> 'text') <> 'string' then
            raise exception 'A structured heading has fields that are not allowed' using errcode = '22023';
          end if;
          text_value := block_item ->> 'text';
          if length(btrim(text_value)) = 0 or length(text_value) > field_maximum then
            raise exception 'A structured heading is blank or too long' using errcode = '22023';
          end if;
          perform pac_dsd.assert_plain_page_text(text_value);
        elsif block_type = 'paragraph' then
          if not block_item ?& array['type', 'text']::text[]
            or exists (
              select 1 from jsonb_object_keys(block_item) actual(name)
              where actual.name <> all(array['type', 'text']::text[])
            ) or jsonb_typeof(block_item -> 'text') <> 'string' then
            raise exception 'A structured paragraph has fields that are not allowed' using errcode = '22023';
          end if;
          text_value := block_item ->> 'text';
          if length(btrim(text_value)) = 0 or length(text_value) > field_maximum then
            raise exception 'A structured paragraph is blank or too long' using errcode = '22023';
          end if;
          perform pac_dsd.assert_plain_page_text(text_value);
        elsif block_type in ('bullet-list', 'numbered-list') then
          if not block_item ?& array['type', 'items']::text[]
            or exists (
              select 1 from jsonb_object_keys(block_item) actual(name)
              where actual.name <> all(array['type', 'items']::text[])
            ) or jsonb_typeof(block_item -> 'items') <> 'array'
            or jsonb_array_length(block_item -> 'items') not between 1 and item_maximum then
            raise exception 'A structured list has fields that are not allowed' using errcode = '22023';
          end if;
          for list_item in select value from jsonb_array_elements(block_item -> 'items')
          loop
            if jsonb_typeof(list_item) <> 'string' then
              raise exception 'A structured list must contain text' using errcode = '22023';
            end if;
            text_value := list_item #>> '{}';
            if length(btrim(text_value)) = 0 or length(text_value) > field_maximum then
              raise exception 'A structured list item is blank or too long' using errcode = '22023';
            end if;
            perform pac_dsd.assert_plain_page_text(text_value);
          end loop;
        elsif block_type = 'link-list' then
          if not block_item ?& array['type', 'items']::text[]
            or exists (
              select 1 from jsonb_object_keys(block_item) actual(name)
              where actual.name <> all(array['type', 'items']::text[])
            ) or jsonb_typeof(block_item -> 'items') <> 'array'
            or jsonb_array_length(block_item -> 'items') not between 1 and item_maximum then
            raise exception 'A structured link list has fields that are not allowed' using errcode = '22023';
          end if;
          for link_item in select value from jsonb_array_elements(block_item -> 'items')
          loop
            if jsonb_typeof(link_item) <> 'object'
              or not link_item ?& array['label', 'href']::text[]
              or exists (
                select 1 from jsonb_object_keys(link_item) actual(name)
                where actual.name <> all(array['label', 'href']::text[])
              ) or jsonb_typeof(link_item -> 'label') <> 'string'
              or jsonb_typeof(link_item -> 'href') <> 'string' then
              raise exception 'A structured link has fields that are not allowed' using errcode = '22023';
            end if;
            text_value := link_item ->> 'label';
            if length(btrim(text_value)) = 0 or length(text_value) > field_maximum then
              raise exception 'A structured link label is blank or too long' using errcode = '22023';
            end if;
            perform pac_dsd.assert_plain_page_text(text_value);
            perform pac_dsd.assert_safe_page_link(link_item ->> 'href');
          end loop;
        else
          raise exception 'A structured page section is not allowed' using errcode = '22023';
        end if;
      end loop;
    else
      raise exception 'A registered page wording field kind is not supported' using errcode = '22023';
    end if;
  end loop;
end;
$$;


create or replace function pac_dsd.delete_content_item_outright(
  requested_content_item_id text,
  requested_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  item pac_dsd.content_items%rowtype;
begin
  select * into item
  from pac_dsd.content_items i
  where i.content_item_id = requested_content_item_id
  for update;
  if not found then
    raise exception 'This item is not available' using errcode = 'P0002';
  end if;
  if item.retired_at is not null then
    return jsonb_build_object('contentItemId', item.content_item_id, 'deleted', true, 'alreadyDeleted', true);
  end if;

  update pac_dsd.content_items
  set retired_at = now(), retired_by = 'practice-workspace-owner'
  where content_item_id = requested_content_item_id;

  insert into pac_dsd.change_events (
    actor_id, actor_role, scope_id, object_type, object_id, action, detail
  ) values (
    'practice-workspace-owner', 'owner', item.default_scope_id, 'content_item',
    requested_content_item_id, 'content_item_deleted',
    jsonb_build_object('reason', left(coalesce(btrim(requested_reason), ''), 500), 'outright', true)
  );

  return jsonb_build_object('contentItemId', item.content_item_id, 'deleted', true, 'alreadyDeleted', false);
end;
$$;

create or replace function pac_dsd.restore_content_item(requested_content_item_id text)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  item pac_dsd.content_items%rowtype;
begin
  select * into item from pac_dsd.content_items i where i.content_item_id = requested_content_item_id for update;
  if not found then
    raise exception 'This item is not available' using errcode = 'P0002';
  end if;
  update pac_dsd.content_items set retired_at = null, retired_by = null where content_item_id = requested_content_item_id;
  insert into pac_dsd.change_events (actor_id, actor_role, scope_id, object_type, object_id, action, detail)
  values ('practice-workspace-owner', 'owner', item.default_scope_id, 'content_item', requested_content_item_id, 'content_item_restored', '{}'::jsonb);
  return jsonb_build_object('contentItemId', item.content_item_id, 'restored', true);
end;
$$;

create or replace function pac_dsd.read_deleted_content_items()
returns table (content_item_id text, staff_label text, content_kind text, retired_at timestamptz)
language sql
stable
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
  select i.content_item_id, i.staff_label, i.content_kind, i.retired_at
  from pac_dsd.content_items i
  where i.retired_at is not null
  order by i.retired_at desc;
$$;

revoke all on function pac_dsd.delete_content_item_outright(text, text) from public;
revoke all on function pac_dsd.restore_content_item(text) from public;
revoke all on function pac_dsd.read_deleted_content_items() from public;
revoke all on function pac_dsd.delete_content_item_outright(text, text) from pac_dsd_app_runtime;
grant execute on function pac_dsd.delete_content_item_outright(text, text) to pac_dsd_owner_writer;
revoke all on function pac_dsd.restore_content_item(text) from pac_dsd_app_runtime;
grant execute on function pac_dsd.restore_content_item(text) to pac_dsd_owner_writer;
grant execute on function pac_dsd.read_deleted_content_items() to pac_dsd_app_runtime;


-- 0051_pac_consultant_media_and_new_resources.sql
-- Consultant media and new resources.
-- 1. Media files (images, infographics, video, documents) stored in the database.
-- 2. Page image replacements: any image on any page can be swapped per view.
-- 3. Resource media: images, video, and documents attached to a resource.
-- 4. New resources written by the consultant, published outright.

do $$
begin
  if not exists (select 1 from pg_catalog.pg_roles where rolname = 'pac_dsd_app_runtime') then
    raise exception 'Required least-privilege role pac_dsd_app_runtime is missing';
  end if;
end;
$$;

create table if not exists pac_dsd.media_files (
  media_id uuid primary key default gen_random_uuid(),
  file_name text not null check (length(file_name) between 1 and 300),
  mime_type text not null check (length(mime_type) between 3 and 200),
  byte_size integer not null check (byte_size between 1 and 60000000),
  content bytea not null,
  alt_text text not null default '' check (length(alt_text) <= 2000),
  uploaded_by text not null default 'consultant',
  uploaded_at timestamptz not null default now()
);

create table if not exists pac_dsd.page_image_overrides (
  scope_id text not null check (scope_id in ('one-dhs', 'dsd')),
  route text not null check (route ~ '^/[A-Za-z0-9_./\-]*$' and length(route) <= 300),
  image_key text not null check (length(image_key) between 1 and 2000),
  media_id uuid not null references pac_dsd.media_files(media_id),
  alt_text text not null default '' check (length(alt_text) <= 2000),
  updated_at timestamptz not null default now(),
  primary key (scope_id, route, image_key)
);

create table if not exists pac_dsd.resource_media (
  resource_media_id uuid primary key default gen_random_uuid(),
  content_item_id text not null references pac_dsd.content_items(content_item_id),
  kind text not null check (kind in ('image', 'video', 'document')),
  media_id uuid references pac_dsd.media_files(media_id),
  external_url text check (external_url is null or (external_url ~ '^https://' and length(external_url) <= 2000)),
  title text not null default '' check (length(title) <= 300),
  alt_text text not null default '' check (length(alt_text) <= 2000),
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  check (media_id is not null or external_url is not null)
);
create index if not exists resource_media_item_idx on pac_dsd.resource_media(content_item_id, sort_order, created_at);

create or replace function pac_dsd.save_media_file(p_file_name text, p_mime_type text, p_content bytea, p_alt_text text)
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  new_id uuid;
begin
  if p_content is null or length(p_content) = 0 then
    raise exception 'The file is empty' using errcode = '22023';
  end if;
  insert into pac_dsd.media_files (file_name, mime_type, byte_size, content, alt_text)
  values (left(coalesce(p_file_name, 'file'), 300), left(coalesce(p_mime_type, 'application/octet-stream'), 200), length(p_content), p_content, left(coalesce(p_alt_text, ''), 2000))
  returning media_id into new_id;
  return new_id;
end;
$$;

create or replace function pac_dsd.read_media_file(p_media_id uuid)
returns table (file_name text, mime_type text, byte_size integer, content bytea, alt_text text)
language sql
stable
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
  select m.file_name, m.mime_type, m.byte_size, m.content, m.alt_text
  from pac_dsd.media_files m where m.media_id = p_media_id;
$$;

create or replace function pac_dsd.read_page_image_overrides(requested_scope_id text, requested_route text)
returns table (image_key text, media_id uuid, alt_text text)
language sql
stable
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
  select o.image_key, o.media_id, o.alt_text
  from pac_dsd.page_image_overrides o
  where o.scope_id = requested_scope_id and o.route = requested_route
  order by o.image_key;
$$;

-- Replaces the full set of image replacements for one page and view.
create or replace function pac_dsd.save_page_image_overrides(requested_scope_id text, requested_route text, entries jsonb)
returns integer
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  saved integer;
begin
  if requested_scope_id not in ('one-dhs', 'dsd') then
    raise exception 'Unknown program scope' using errcode = '22023';
  end if;
  if jsonb_typeof(entries) <> 'array' or jsonb_array_length(entries) > 500 then
    raise exception 'Invalid page image entries' using errcode = '22023';
  end if;
  delete from pac_dsd.page_image_overrides o where o.scope_id = requested_scope_id and o.route = requested_route;
  insert into pac_dsd.page_image_overrides (scope_id, route, image_key, media_id, alt_text)
  select requested_scope_id, requested_route, entry->>'key', (entry->>'mediaId')::uuid, coalesce(entry->>'alt', '')
  from jsonb_array_elements(entries) as entry
  where entry ? 'key' and entry ? 'mediaId';
  get diagnostics saved = row_count;
  return saved;
end;
$$;

create or replace function pac_dsd.list_resource_media(p_content_item_id text)
returns table (resource_media_id uuid, kind text, media_id uuid, external_url text, title text, alt_text text, mime_type text, file_name text)
language sql
stable
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
  select r.resource_media_id, r.kind, r.media_id, r.external_url, r.title, r.alt_text, m.mime_type, m.file_name
  from pac_dsd.resource_media r
  left join pac_dsd.media_files m on m.media_id = r.media_id
  where r.content_item_id = p_content_item_id
  order by r.sort_order, r.created_at;
$$;

create or replace function pac_dsd.add_resource_media(p_content_item_id text, p_kind text, p_media_id uuid, p_external_url text, p_title text, p_alt_text text)
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  new_id uuid;
  next_order integer;
begin
  if not exists (select 1 from pac_dsd.content_items i where i.content_item_id = p_content_item_id) then
    raise exception 'This resource is not available' using errcode = 'P0002';
  end if;
  select coalesce(max(sort_order), 0) + 1 into next_order from pac_dsd.resource_media where content_item_id = p_content_item_id;
  insert into pac_dsd.resource_media (content_item_id, kind, media_id, external_url, title, alt_text, sort_order)
  values (p_content_item_id, p_kind, p_media_id, nullif(btrim(coalesce(p_external_url, '')), ''), left(coalesce(p_title, ''), 300), left(coalesce(p_alt_text, ''), 2000), next_order)
  returning resource_media_id into new_id;
  return new_id;
end;
$$;

create or replace function pac_dsd.delete_resource_media(p_resource_media_id uuid)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  removed_media uuid;
begin
  delete from pac_dsd.resource_media where resource_media_id = p_resource_media_id returning media_id into removed_media;
  if not found then return false; end if;
  if removed_media is not null
    and not exists (select 1 from pac_dsd.resource_media where media_id = removed_media)
    and not exists (select 1 from pac_dsd.page_image_overrides where media_id = removed_media) then
    delete from pac_dsd.media_files where media_id = removed_media;
  end if;
  return true;
end;
$$;

-- A resource written by the consultant. It is published outright with the
-- consultant's standing approval and appears immediately in the chosen view.
create or replace function pac_dsd.create_resource_outright(requested_scope_id text, payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
declare
  new_item_id text;
  new_source_id text;
  new_revision_id uuid;
  new_decision_id bigint;
begin
  if requested_scope_id not in ('one-dhs', 'dsd') then
    raise exception 'Unknown program scope' using errcode = '22023';
  end if;
  if pac_dsd.resource_scope_id(payload) <> requested_scope_id then
    raise exception 'The resource view does not match' using errcode = '22023';
  end if;
  new_item_id := payload ->> 'id';
  if new_item_id is null or new_item_id !~ '^[a-z0-9][a-z0-9-]{2,120}$' then
    raise exception 'The resource identifier is not valid' using errcode = '22023';
  end if;
  if exists (select 1 from pac_dsd.content_items i where i.content_item_id = new_item_id) then
    raise exception 'A resource with this identifier already exists' using errcode = '23505';
  end if;

  insert into pac_dsd.content_items (content_item_id, content_kind, default_scope_id, staff_label, restricted, created_by, sensitivity_class)
  values (new_item_id, 'resource', requested_scope_id, left(payload ->> 'title', 300), false, 'practice-workspace-owner', 'S0');

  new_source_id := 'consultant-authored:' || new_item_id;
  insert into pac_dsd.source_items (
    source_item_id, source_business_id, source_version, title, normalized_payload,
    normalized_item_sha256, hash_algorithm, hash_algorithm_version,
    owner_approval_status, accounting_status, access_scope,
    sensitivity_class, deidentification_status, ordinary_indexing_allowed, model_context_allowed
  ) values (
    new_source_id, new_source_id, '1', left(payload ->> 'title', 300), payload,
    encode(sha256(convert_to(payload::text, 'UTF8')), 'hex'), 'sha256', '1',
    'owner_approved_for_ingestion', 'accounted', 'consultant',
    'S0', 'not_needed', true, true
  );

  insert into pac_dsd.content_revisions (
    content_item_id, revision_number, canonical_payload, change_summary,
    required_review_dimensions, created_by, sensitivity_class, ordinary_indexing_allowed, model_context_allowed
  ) values (
    new_item_id, 1, payload, 'Resource added by the consultant.',
    '{}'::text[], 'practice-workspace-owner', 'S0', true, true
  ) returning revision_id into new_revision_id;

  insert into pac_dsd.revision_sources (revision_id, source_item_id, relationship, note)
  values (new_revision_id, new_source_id, 'primary', 'Written by the consultant.');

  insert into pac_dsd.publication_decisions (
    content_item_id, revision_id, scope_id, decision, gate_snapshot, decided_by, reason,
    sensitivity_class, unauthenticated_exposure_permitted, exposure_reason
  ) values (
    new_item_id, new_revision_id, requested_scope_id, 'publish',
    jsonb_build_object('approvalBasis', 'consultant_authored', 'staff_release_explicit', true),
    'practice-workspace-owner', 'Added by the consultant.',
    'S0', true, 'Consultant-authored resource for staff.'
  ) returning publication_decision_id into new_decision_id;

  insert into pac_dsd.change_events (actor_id, actor_role, scope_id, object_type, object_id, action, detail)
  values ('practice-workspace-owner', 'owner', requested_scope_id, 'content_item', new_item_id, 'resource_created',
    jsonb_build_object('revision_id', new_revision_id, 'publication_decision_id', new_decision_id));

  return jsonb_build_object('contentItemId', new_item_id, 'revisionId', new_revision_id);
end;
$$;

