-- 0054_pac_resource_media_script.sql
-- A timed script for read-aloud audio, so the words follow the recording.

alter table pac_dsd.resource_media add column if not exists script jsonb;

create or replace function pac_dsd.set_resource_media_script(p_resource_media_id uuid, p_script jsonb)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
begin
  if p_script is not null and (jsonb_typeof(p_script) <> 'array' or jsonb_array_length(p_script) > 5000) then
    raise exception 'Invalid script' using errcode = '22023';
  end if;
  update pac_dsd.resource_media set script = p_script where resource_media_id = p_resource_media_id;
  return found;
end;
$$;

