-- 0056_pac_equity_analysis_records.sql

-- Equity Analysis Toolkit records: analyses filed through the guided walkthrough,
-- follow-up completion events, and culture survey wave events. All three are
-- append-only decision families; later state is derived from later events, so
-- every change stays visible and reversible. Earlier contracts are preserved by
-- delegation. Roles and dates only: person-profile keys stay prohibited.

alter function pac_dsd.assert_runtime_work_object_contract(text,text,jsonb) rename to assert_runtime_work_object_contract_pre_equity_v1;
alter function pac_dsd.assert_runtime_idempotency_receipt_contract(text,text,text,jsonb) rename to assert_runtime_idempotency_receipt_contract_pre_equity_v1;
alter function pac_dsd.assert_runtime_rate_limit_request(text,text,integer,integer) rename to assert_runtime_rate_limit_request_pre_equity_v1;

create function pac_dsd.assert_equity_calendar_date(payload jsonb, field_name text, required boolean default true)
returns void language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
begin
  if not (payload ? field_name) then
    if required then raise exception 'Missing equity date field: %', field_name using errcode='22023'; end if;
    return;
  end if;
  if jsonb_typeof(payload->field_name) is distinct from 'string'
    or payload->>field_name !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    or ((payload->>field_name)::date)::text <> payload->>field_name then
    raise exception 'Invalid equity date field: %', field_name using errcode='22023';
  end if;
end $$;

create function pac_dsd.assert_equity_analysis_record(requested_object_id text, payload jsonb)
returns void language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
declare answers jsonb; answer_key text; answer_value jsonb; required_key text;
begin
  perform pac_dsd.assert_allowed_jsonb_keys(payload,array['schemaVersion','recordType','id','createdAt','programScope','kind','workTitle','workType','administration','approvalDate','disposition','answers','consent','sourceRoute']);
  if not (payload ?& array['schemaVersion','recordType','id','createdAt','programScope','kind','workTitle','workType','administration','disposition','answers','consent','sourceRoute']) then
    raise exception 'Incomplete equity analysis' using errcode='22023';
  end if;
  perform pac_dsd.assert_jsonb_scalar_types(payload,array['recordType','id','createdAt','programScope','kind','workTitle','workType','administration','approvalDate','disposition','sourceRoute'],array['consent'],array['schemaVersion']);
  if payload->'schemaVersion' is distinct from '1'::jsonb or payload->'consent' is distinct from 'true'::jsonb
    or payload->>'recordType' is distinct from 'equity_analysis'
    or payload->>'id' !~ '^equity-analysis-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or requested_object_id is distinct from 'equity_analysis:'||(payload->>'id')
    or payload->>'programScope' not in ('one-dhs','dsd')
    or payload->>'kind' not in ('full','scan')
    or payload->>'workType' not in ('policy','budget','hiring','it','contract','service','engagement','other')
    or payload->>'administration' not in ('Aging and Disability Services','Behavioral Health','Community Supports','Health Care','Operations','Central Office')
    or payload->>'disposition' not in ('approve','revise','pause','pilot','reject','escalate')
    or payload->>'sourceRoute' is distinct from '/equity-policy/analysis' then
    raise exception 'Invalid equity analysis' using errcode='22023';
  end if;
  perform pac_dsd.assert_program_string(payload,'workTitle',1,200);
  if btrim(payload->>'workTitle')='' then raise exception 'Blank equity analysis title' using errcode='22023'; end if;
  perform pac_dsd.assert_program_instant(payload,'createdAt');
  perform pac_dsd.assert_equity_calendar_date(payload,'approvalDate',false);

  answers := payload->'answers';
  perform pac_dsd.assert_allowed_jsonb_keys(answers,array['action','affected_groups','dhs_areas','data_shows','data_missing','heard_from','still_missing','tribal_consultation','benefits','burdens','design_change','impact_statement','impact_owner','impact_date','outcome_owner','outcome_date','communication','equity_director','policy_alignment','funded','staffed','data_capacity','sustainability_note','rationale']);
  for answer_key, answer_value in select key, value from jsonb_each(answers) loop
    if jsonb_typeof(answer_value) <> 'string' or length(answer_value #>> '{}') not between 1 and 4000 then
      raise exception 'Invalid equity analysis answer: %', answer_key using errcode='22023';
    end if;
  end loop;
  perform pac_dsd.assert_equity_calendar_date(answers,'impact_date',false);
  perform pac_dsd.assert_equity_calendar_date(answers,'outcome_date',false);
  if answers ? 'tribal_consultation' and answers->>'tribal_consultation' not in ('not_applicable','requested','completed','needed') then raise exception 'Invalid equity analysis answer: tribal_consultation' using errcode='22023'; end if;
  if answers ? 'equity_director' and answers->>'equity_director' not in ('consulted','scheduled','not_yet') then raise exception 'Invalid equity analysis answer: equity_director' using errcode='22023'; end if;
  foreach answer_key in array array['funded','staffed','data_capacity'] loop
    if answers ? answer_key and answers->>answer_key not in ('yes','partial','no') then raise exception 'Invalid equity analysis answer: %', answer_key using errcode='22023'; end if;
  end loop;
  -- Both forms require these; the full analysis also requires its own steps.
  foreach required_key in array array['action','affected_groups','data_shows','benefits','burdens','design_change','impact_owner','impact_date','outcome_owner','outcome_date','communication','rationale'] loop
    if not (answers ? required_key) then raise exception 'Incomplete equity analysis answer: %', required_key using errcode='22023'; end if;
  end loop;
  if payload->>'kind'='full' then
    foreach required_key in array array['heard_from','still_missing','tribal_consultation','impact_statement','equity_director','policy_alignment','funded','staffed','data_capacity'] loop
      if not (answers ? required_key) then raise exception 'Incomplete full equity analysis answer: %', required_key using errcode='22023'; end if;
    end loop;
  end if;
end $$;

create function pac_dsd.assert_equity_followup_event(requested_object_id text, payload jsonb)
returns void language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
begin
  perform pac_dsd.assert_allowed_jsonb_keys(payload,array['schemaVersion','recordType','id','createdAt','analysisId','followUp','done','reverts']);
  if not (payload ?& array['schemaVersion','recordType','id','createdAt','analysisId','followUp','done']) then raise exception 'Incomplete equity follow-up event' using errcode='22023'; end if;
  perform pac_dsd.assert_jsonb_scalar_types(payload,array['recordType','id','createdAt','analysisId','followUp','reverts'],array['done'],array['schemaVersion']);
  if payload->'schemaVersion' is distinct from '1'::jsonb
    or payload->>'recordType' is distinct from 'equity_analysis_followup'
    or payload->>'id' !~ '^equity-followup-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or requested_object_id is distinct from 'equity_followup:'||(payload->>'id')
    or payload->>'analysisId' !~ '^equity-analysis-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or payload->>'followUp' not in ('approval','impact','outcome')
    or (payload ? 'reverts' and payload->>'reverts' !~ '^equity-followup-[0-9a-f-]{36}$') then
    raise exception 'Invalid equity follow-up event' using errcode='22023';
  end if;
  perform pac_dsd.assert_program_instant(payload,'createdAt');
end $$;

create function pac_dsd.assert_equity_survey_event(requested_object_id text, payload jsonb)
returns void language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
declare v jsonb; pct_key text;
begin
  perform pac_dsd.assert_allowed_jsonb_keys(payload,array['schemaVersion','recordType','id','createdAt','wave','action','values','reverts']);
  if not (payload ?& array['schemaVersion','recordType','id','createdAt','wave','action']) then raise exception 'Incomplete equity survey event' using errcode='22023'; end if;
  perform pac_dsd.assert_jsonb_scalar_types(payload,array['recordType','id','createdAt','wave','action','reverts'],array[]::text[],array['schemaVersion']);
  if payload->'schemaVersion' is distinct from '1'::jsonb
    or payload->>'recordType' is distinct from 'equity_survey_wave'
    or payload->>'id' !~ '^equity-survey-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or requested_object_id is distinct from 'equity_survey:'||(payload->>'id')
    or payload->>'wave' !~ '^[0-9]{4}([- ][A-Za-z0-9]{1,12})?$'
    or payload->>'action' not in ('set','remove')
    or (payload->>'action'='set') <> (payload ? 'values')
    or (payload ? 'reverts' and payload->>'reverts' !~ '^equity-survey-[0-9a-f-]{36}$') then
    raise exception 'Invalid equity survey event' using errcode='22023';
  end if;
  perform pac_dsd.assert_program_instant(payload,'createdAt');
  if payload ? 'values' then
    v := payload->'values';
    perform pac_dsd.assert_allowed_jsonb_keys(v,array['fielded','respondents','responseRate','belonging','inclusion','engagement']);
    if not (v ?& array['fielded','respondents','responseRate','belonging','inclusion','engagement']) then raise exception 'Incomplete equity survey values' using errcode='22023'; end if;
    perform pac_dsd.assert_jsonb_scalar_types(v,array['fielded'],array[]::text[],array['respondents','responseRate','belonging','inclusion','engagement']);
    if v->>'fielded' !~ '^[0-9]{4}-[0-9]{2}$'
      or pac_dsd.jsonb_is_safe_integer(v->'respondents',0) is distinct from true or (v->>'respondents')::numeric > 1000000
      or (v->>'responseRate')::numeric not between 0 and 1 then
      raise exception 'Invalid equity survey values' using errcode='22023';
    end if;
    foreach pct_key in array array['belonging','inclusion','engagement'] loop
      if pac_dsd.jsonb_is_safe_integer(v->pct_key,0) is distinct from true or (v->>pct_key)::numeric > 100 then raise exception 'Invalid equity survey percent: %', pct_key using errcode='22023'; end if;
    end loop;
  end if;
end $$;

create function pac_dsd.assert_runtime_work_object_contract(requested_kind text, requested_object_id text, payload jsonb)
returns void language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
begin
  perform pac_dsd.assert_no_prohibited_profile_fields(payload);
  if requested_kind is distinct from 'decision' or requested_object_id !~ '^equity_(analysis|followup|survey):' then
    perform pac_dsd.assert_runtime_work_object_contract_pre_equity_v1(requested_kind,requested_object_id,payload); return;
  end if;
  if payload is null or jsonb_typeof(payload) <> 'object' or requested_object_id is null or length(requested_object_id)>180 then raise exception 'Invalid equity work object' using errcode='22023'; end if;
  if requested_object_id like 'equity_analysis:%' then perform pac_dsd.assert_equity_analysis_record(requested_object_id,payload); return; end if;
  if requested_object_id like 'equity_followup:%' then perform pac_dsd.assert_equity_followup_event(requested_object_id,payload); return; end if;
  perform pac_dsd.assert_equity_survey_event(requested_object_id,payload);
end $$;

create function pac_dsd.assert_runtime_idempotency_receipt_contract(requested_idempotency_key text, requested_kind text, requested_object_id text, payload jsonb)
returns void language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
declare family text; suffix text;
begin
  if requested_kind is distinct from 'decision' or requested_object_id !~ '^equity_(analysis|followup|survey):' then
    perform pac_dsd.assert_runtime_idempotency_receipt_contract_pre_equity_v1(requested_idempotency_key,requested_kind,requested_object_id,payload); return;
  end if;
  perform pac_dsd.assert_no_prohibited_profile_fields(payload);
  perform pac_dsd.assert_allowed_jsonb_keys(payload,array['work_kind','object_id']);
  family := split_part(requested_object_id,':',1);           -- equity_analysis | equity_followup | equity_survey
  suffix := substring(requested_object_id from '[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$');
  if not (payload ?& array['work_kind','object_id'])
    or payload->>'work_kind' is distinct from requested_kind or payload->>'object_id' is distinct from requested_object_id
    or jsonb_typeof(payload->'work_kind') is distinct from 'string' or jsonb_typeof(payload->'object_id') is distinct from 'string'
    or suffix is null
    or requested_idempotency_key is distinct from replace(family,'_','-')||':'||suffix then
    raise exception 'Invalid equity idempotency contract' using errcode='22023';
  end if;
end $$;

create function pac_dsd.assert_runtime_rate_limit_request(requested_scope text, requested_subject_hash text, requested_limit integer, requested_window_seconds integer)
returns void language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
begin
  if requested_scope not in ('staff-equity-analysis','staff-equity-register') then
    perform pac_dsd.assert_runtime_rate_limit_request_pre_equity_v1(requested_scope,requested_subject_hash,requested_limit,requested_window_seconds); return;
  end if;
  if requested_subject_hash is null or requested_subject_hash !~ '^[a-f0-9]{64}$'
    or requested_window_seconds is distinct from 600
    or requested_limit is distinct from (case requested_scope when 'staff-equity-analysis' then 10 else 60 end) then
    raise exception 'Invalid equity analysis rate limit' using errcode='22023';
  end if;
end $$;
-- The original column check from 0009 lists only the first four purposes and was
-- never widened when later purposes were registered; the registered_identity
-- constraint below is the single, complete allowlist.
alter table pac_dsd.runtime_rate_limits drop constraint if exists runtime_rate_limits_scope_check;
alter table pac_dsd.runtime_rate_limits drop constraint runtime_rate_limits_registered_identity;
alter table pac_dsd.runtime_rate_limits add constraint runtime_rate_limits_registered_identity check(
  scope in ('staff-ask','owner-login','consultation-intake','consultation-tracking','staff-program-outcome','program-login-network','program-login-account','program-invitation-network','program-invitation-code','staff-equity-analysis','staff-equity-register')
  and subject_hash ~ '^[a-f0-9]{64}$'
);

create function pac_dsd.prevent_equity_record_rewrite()
returns trigger language plpgsql set search_path=pg_catalog,pac_dsd as $$
begin
  if (old.work_kind='decision' and old.object_id ~ '^equity_(analysis|followup|survey):')
    or (new.work_kind='decision' and new.object_id ~ '^equity_(analysis|followup|survey):') then
    if old.work_kind is distinct from new.work_kind or old.object_id is distinct from new.object_id
      or old.value is distinct from new.value or old.created_at is distinct from new.created_at then
      raise exception 'Equity analysis records are append-only; add a new event' using errcode='22023';
    end if;
  end if;
  return new;
end $$;
create trigger immutable_equity_record before update on pac_dsd.runtime_work_objects
for each row execute function pac_dsd.prevent_equity_record_rewrite();

revoke all on function pac_dsd.assert_equity_calendar_date(jsonb,text,boolean) from public,pac_dsd_app_runtime,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
revoke all on function pac_dsd.assert_equity_analysis_record(text,jsonb) from public,pac_dsd_app_runtime,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
revoke all on function pac_dsd.assert_equity_followup_event(text,jsonb) from public,pac_dsd_app_runtime,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
revoke all on function pac_dsd.assert_equity_survey_event(text,jsonb) from public,pac_dsd_app_runtime,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
revoke all on function pac_dsd.assert_runtime_work_object_contract(text,text,jsonb) from public,pac_dsd_app_runtime,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
revoke all on function pac_dsd.assert_runtime_idempotency_receipt_contract(text,text,text,jsonb) from public,pac_dsd_app_runtime,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
revoke all on function pac_dsd.assert_runtime_rate_limit_request(text,text,integer,integer) from public,pac_dsd_app_runtime,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;
revoke all on function pac_dsd.prevent_equity_record_rewrite() from public,pac_dsd_app_runtime,pac_dsd_contributor_runtime,pac_dsd_authentication_broker;

comment on function pac_dsd.assert_equity_analysis_record(text,jsonb) is 'Purpose limitation: an equity analysis names work, groups, roles, and dates. It never carries a person''s name, case, or profile.';
comment on function pac_dsd.prevent_equity_record_rewrite() is 'Equity analysis records and their follow-up and survey events are append-only so every change stays visible and reversible.';


-- 0057_pac_read_surface_publications.sql

-- Batch read of current publications for many page areas in one round trip.
-- A page area that the application registers before its database definition
-- exists is skipped instead of aborting the whole batch: aborting a set-returning
-- query after rows were already streamed left the pooled connection with stray
-- rows that surfaced in the next query as "more than one effective publication".
create or replace function pac_dsd.read_surface_publications(
  requested_scope_id text,
  requested_surface_ids text[]
)
returns table(
  surface_id text,
  revision_id uuid,
  scope_id text,
  document jsonb,
  publication_decision_id bigint,
  decided_at timestamp with time zone
)
language plpgsql
stable
security definer
set search_path to 'pg_catalog', 'pac_dsd'
set row_security to 'off'
as $$
declare
  requested text;
begin
  foreach requested in array coalesce(requested_surface_ids, '{}'::text[]) loop
    begin
      return query select * from pac_dsd.read_surface_publication(requested_scope_id, requested);
    exception
      when no_data_found then
        null;
    end;
  end loop;
end;
$$;

revoke all privileges on function pac_dsd.read_surface_publications(text, text[]) from public;
grant execute on function pac_dsd.read_surface_publications(text, text[]) to pac_dsd_app_runtime;


-- 0058_pac_optional_home_headline_line.sql

-- The Home heading may omit its optional third line, matching the application
-- contract (headlineLine3 accepts an empty value) and the current program name,
-- which fits on two lines. As with the optional supporting note, a nonblank
-- third line still receives the same length and plain-text validation, and
-- every other page-copy field remains required.
create or replace function pac_dsd.assert_valid_page_block_copy(
  requested_content_item_id text,
  requested_copy jsonb
)
returns void
language plpgsql
immutable
set search_path = pg_catalog, pac_dsd
as $$
declare
  expected_keys text[];
  link_keys text[];
  candidate_key text;
  maximum_length integer;
  candidate_value text;
begin
  if jsonb_typeof(requested_copy) <> 'object' then
    raise exception 'Page wording must be a complete set of labeled fields' using errcode = '22023';
  end if;

  if requested_content_item_id = 'page-home' then
    expected_keys := array[
      'heroKicker', 'headlineLine1', 'headlineLine2', 'headlineLine3',
      'heroLede', 'heroNote', 'heroImageAlt', 'primaryActionLabel',
      'primaryActionHref', 'secondaryActionLabel', 'secondaryActionHref',
      'aboutLabel', 'aboutText', 'guidedKicker', 'guidedTitle', 'guidedIntro',
      'guidedFallbackLabel', 'guidedFallbackNote', 'helpKicker', 'helpTitle',
      'askLabel', 'askHref', 'askDescription', 'communitiesLabel',
      'communitiesHref', 'communitiesDescription', 'resourcesLabel',
      'resourcesHref', 'resourcesDescription', 'supportLabel', 'supportHref',
      'supportAvailableDescription', 'supportPreviewDescription', 'goalsKicker',
      'goalsTitle', 'foundationLabel', 'foundationHref', 'learnLabel', 'learnHref',
      'applyLabel', 'applyHref', 'leadLabel', 'leadHref', 'commitmentsKicker',
      'commitmentsTitle', 'commitmentsLinkLabel', 'commitmentsLinkHref',
      'privacyLabel', 'privacyText'
    ]::text[];
    link_keys := array[
      'primaryActionHref', 'secondaryActionHref', 'askHref', 'communitiesHref',
      'resourcesHref', 'supportHref', 'foundationHref', 'learnHref', 'applyHref',
      'leadHref', 'commitmentsLinkHref'
    ]::text[];
  elsif requested_content_item_id = 'site-footer' then
    expected_keys := array[
      'identityKicker', 'identityText', 'helpHeading', 'askLabel', 'askHref',
      'resourcesLabel', 'resourcesHref', 'communitiesLabel', 'communitiesHref',
      'requestAvailableLabel', 'requestPreviewLabel', 'requestHref', 'trackLabel',
      'trackHref', 'escalationLabel', 'escalationHref', 'privacyHeading', 'privacyText'
    ]::text[];
    link_keys := array[
      'askHref', 'resourcesHref', 'communitiesHref', 'requestHref', 'trackHref',
      'escalationHref'
    ]::text[];
  else
    raise exception 'This page area is not available' using errcode = 'P0002';
  end if;

  if exists (
    select 1 from unnest(expected_keys) expected(name)
    where not requested_copy ? expected.name
  ) or exists (
    select 1 from jsonb_object_keys(requested_copy) actual(name)
    where actual.name <> all(expected_keys)
  ) then
    raise exception 'Page wording fields do not match this page area' using errcode = '22023';
  end if;

  foreach candidate_key in array expected_keys loop
    if jsonb_typeof(requested_copy -> candidate_key) <> 'string' then
      raise exception 'Every page wording field must be text' using errcode = '22023';
    end if;
    candidate_value := requested_copy ->> candidate_key;
    maximum_length := case
      when candidate_key = any(link_keys) then 2000
      when candidate_key in ('identityText', 'privacyText') and requested_content_item_id = 'site-footer' then 4000
      when candidate_key in ('aboutText', 'guidedIntro', 'privacyText') then 3000
      when candidate_key in (
        'heroNote', 'askDescription', 'communitiesDescription', 'resourcesDescription',
        'supportAvailableDescription', 'supportPreviewDescription'
      ) then 2000
      when candidate_key in ('heroLede', 'guidedFallbackNote') then 1000
      when candidate_key in (
        'helpTitle', 'goalsTitle', 'foundationLabel', 'learnLabel', 'applyLabel',
        'leadLabel', 'commitmentsTitle', 'escalationLabel', 'heroImageAlt'
      ) then 500
      when candidate_key in ('guidedTitle', 'guidedFallbackLabel', 'commitmentsLinkLabel',
        'requestAvailableLabel', 'requestPreviewLabel', 'trackLabel') then 300
      else 200
    end;

    if requested_content_item_id = 'page-home'
      and candidate_key in ('heroNote', 'headlineLine3')
      and candidate_value = '' then
      continue;
    end if;

    if length(btrim(candidate_value)) not between 1 and maximum_length then
      raise exception 'A page wording field is blank or too long' using errcode = '22023';
    end if;
    if candidate_key = any(link_keys) then
      perform pac_dsd.assert_safe_page_link(candidate_value);
    else
      perform pac_dsd.assert_plain_page_text(candidate_value);
    end if;
  end loop;
end;
$$;


-- 0060_pac_static_resource_overlay.sql

-- An absent publication must not resurrect a withdrawn or retired bundled resource.
create or replace function pac_dsd.read_static_resource_overlay(requested_scope_id text)
returns table(content_item_id text, revision_id uuid, scope_id text, canonical_payload jsonb, payload_sha256 text, decided_at timestamptz)
language plpgsql stable security definer
set search_path = pg_catalog, pac_dsd
set row_security = off
as $$
begin
  if requested_scope_id not in ('one-dhs', 'dsd') then
    raise exception 'Unknown program scope' using errcode = '22023';
  end if;
  return query
  select item.content_item_id, published.revision_id, published.scope_id,
         published.canonical_payload, published.payload_sha256, published.decided_at
  from pac_dsd.content_items item
  left join pac_dsd.read_staff_publications(requested_scope_id, null) published
    on published.content_item_id = item.content_item_id
  where item.content_kind = 'resource'
    and (item.default_scope_id = 'one-dhs' or (requested_scope_id = 'dsd' and item.default_scope_id = 'dsd'));
end;
$$;
revoke all on function pac_dsd.read_static_resource_overlay(text) from public;
grant execute on function pac_dsd.read_static_resource_overlay(text) to pac_dsd_app_runtime;


-- 0062_pac_consultation_program_reference_authority.sql
-- Match the existing application citation contract for the reviewed program
-- documents. This changes only the enumerated authority label; every field,
-- length, privacy, timestamp, version, and role restriction remains intact.

do $$
declare definition text; revised text;
begin
  definition := pg_get_functiondef('pac_dsd.assert_consultation_persistence_contract(text,jsonb)'::regprocedure);
  revised := replace(definition, '''partner_informed'', ''local''', '''partner_informed'', ''program_reference'', ''local''');
  if revised = definition then
    raise exception 'Expected consultation authority contract is missing; verify the migration ledger';
  end if;
  execute revised;
end;
$$;


-- 0063_pac_owner_immediate_resource_saves.sql
-- Explicit consultant direction: authenticated resource saves publish immediately.
-- Preserve originals and immutable history; record approval without inventing reviews.

create or replace function pac_dsd.save_owner_approved_resource(
  requested_scope_id text, requested_content_item_id text,
  expected_base_revision_id uuid, expected_published_revision_id uuid,
  requested_editable_fields jsonb, requested_change_note text default null
)
returns table(content_item_id text,published_revision_id uuid,base_revision_id uuid,
  editable_fields jsonb,has_unpublished_changes boolean)
language plpgsql security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
declare
  previous pac_dsd.content_revisions%rowtype;
  published_trust pac_dsd.content_revisions%rowtype;
  published record;
  editing_state record;
  next_payload jsonb;
  next_id uuid;
  next_number integer;
  decision_id bigint;
  note text;
begin
  if requested_scope_id not in ('one-dhs','dsd') or expected_published_revision_id is null then
    raise exception 'Exact publication scope and revision are required' using errcode='22023';
  end if;
  perform pac_dsd.assert_valid_resource_edit_fields(requested_editable_fields);
  note:=coalesce(nullif(btrim(requested_change_note),''),'Resource wording saved by the program owner.');
  if length(note)>500 then raise exception 'Change note is too long' using errcode='22023'; end if;
  perform pac_dsd.assert_plain_resource_text(note);
  perform 1 from pac_dsd.content_items i where i.content_item_id=requested_content_item_id
    and i.content_kind='resource' and not i.restricted and i.retired_at is null for update;
  if not found then raise exception 'Resource is not available' using errcode='P0002'; end if;
  select * into published from pac_dsd.read_staff_publications(requested_scope_id,requested_content_item_id);
  if not found then raise exception 'Resource is not published in this view' using errcode='P0002'; end if;
  select r.* into published_trust from pac_dsd.content_revisions r where r.revision_id=published.revision_id;
  select * into editing_state from pac_dsd.read_resource_editing_state(requested_scope_id,requested_content_item_id);
  select r.* into previous from pac_dsd.content_revisions r where r.revision_id=editing_state.base_revision_id;
  if previous.revision_id is distinct from expected_base_revision_id
    or published.revision_id is distinct from expected_published_revision_id then
    raise exception 'Resource wording or publication changed' using errcode='40001';
  end if;
  select coalesce(max(r.revision_number),0)+1 into next_number from pac_dsd.content_revisions r
    where r.content_item_id=requested_content_item_id;
  next_payload:=jsonb_strip_nulls(previous.canonical_payload||requested_editable_fields
    ||jsonb_build_object('id',requested_content_item_id,'status','approved','accessibility','reviewed',
      'scope',case when requested_scope_id='dsd' then 'dsd' else 'agencywide' end,
      'version','owner-'||next_number));
  perform pac_dsd.assert_exact_resource_scope(requested_scope_id,next_payload);
  insert into pac_dsd.content_revisions(content_item_id,revision_number,canonical_payload,change_summary,
    required_review_dimensions,created_by,based_on_revision_id,sensitivity_class,
    ordinary_indexing_allowed,model_context_allowed,limitations)
    values(requested_content_item_id,next_number,next_payload,note,'{}'::text[],
      'pac-consultant-workspace-owner',previous.revision_id,published_trust.sensitivity_class,
      published_trust.ordinary_indexing_allowed,published_trust.model_context_allowed,previous.limitations)
    returning content_revisions.revision_id into next_id;
  insert into pac_dsd.revision_sources(revision_id,source_item_id,relationship,note)
    select next_id,s.source_item_id,s.relationship,s.note from pac_dsd.revision_sources s where s.revision_id=previous.revision_id;
  insert into pac_dsd.revision_assets(revision_id,asset_id,purpose,staff_label,sort_order)
    select next_id,a.asset_id,a.purpose,a.staff_label,a.sort_order from pac_dsd.revision_assets a where a.revision_id=previous.revision_id;
  perform pac_dsd.assert_resource_staff_release(next_id);
  insert into pac_dsd.publication_decisions(content_item_id,revision_id,scope_id,decision,gate_snapshot,
    decided_by,reason,sensitivity_class,unauthenticated_exposure_permitted,exposure_reason)
    values(requested_content_item_id,next_id,requested_scope_id,'publish',
      jsonb_build_object('approvalBasis','standing_owner_approval_on_input','explicitOwnerDecision',true,
        'ownerApprovedCopy',true,'automaticValidationCompleted',true,'independentFactualReviewPerformed',false,
        'independentAccessibilityAuditPerformed',false,'staff_release_explicit',true,
        'basedOnRevisionId',previous.revision_id,'replacedPublishedRevisionId',published.revision_id),
      'pac-consultant-workspace-owner','Resource saved with the consultant''s standing publication approval.',
      published_trust.sensitivity_class,true,'Owner-approved change to an existing staff resource.')
    returning publication_decision_id into decision_id;
  insert into pac_dsd.change_events(actor_id,actor_role,scope_id,object_type,object_id,action,detail)
    values('pac-consultant-workspace-owner','owner',requested_scope_id,'content_item',requested_content_item_id,
      'published',jsonb_build_object('revision_id',next_id,'publication_decision_id',decision_id,
        'approvalBasis','standing_owner_approval_on_input','automaticValidationCompleted',true,
        'independentFactualReviewPerformed',false,'independentAccessibilityAuditPerformed',false));
  return query select * from pac_dsd.read_resource_editing_state(requested_scope_id,requested_content_item_id);
end;
$$;
revoke all on function pac_dsd.save_owner_approved_resource(text,text,uuid,uuid,jsonb,text) from public;
revoke all on function pac_dsd.save_owner_approved_resource(text,text,uuid,uuid,jsonb,text) from pac_dsd_app_runtime;
grant execute on function pac_dsd.save_owner_approved_resource(text,text,uuid,uuid,jsonb,text) to pac_dsd_owner_writer;
comment on function pac_dsd.save_owner_approved_resource(text,text,uuid,uuid,jsonb,text) is
  'Authenticated consultant API only: exact scoped CAS save/publication under standing owner approval, with truthful immutable provenance.';


-- 0063_pac_owner_page_text_history.sql

do $$ begin
  if not exists (select 1 from pg_catalog.pg_roles where rolname='pac_dsd_owner_writer') then
    create role pac_dsd_owner_writer login noinherit nosuperuser nocreatedb nocreaterole nobypassrls;
  end if;
end; $$;
grant usage on schema pac_dsd to pac_dsd_owner_writer;
alter table pac_dsd.page_text_overrides enable row level security;
create table if not exists pac_dsd.page_text_snapshots (
  snapshot_id bigint generated always as identity primary key,
  scope_id text not null check(scope_id in ('one-dhs','dsd')),
  route text not null,
  entries jsonb not null check(jsonb_typeof(entries)='array'),
  archived_at timestamptz not null default now()
);
alter table pac_dsd.page_text_snapshots enable row level security;
revoke all on pac_dsd.page_text_snapshots, pac_dsd.page_text_overrides from public, pac_dsd_app_runtime, pac_dsd_owner_writer;

create or replace function pac_dsd.save_page_text_overrides(requested_scope_id text, requested_route text, entries jsonb)
returns integer language plpgsql security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
declare saved integer;
begin
  if requested_scope_id not in ('one-dhs','dsd') or requested_route !~ '^/[A-Za-z0-9_./-]*$' or length(requested_route)>300 then
    raise exception 'Invalid page' using errcode='22023';
  end if;
  if jsonb_typeof(entries) <> 'array' or jsonb_array_length(entries)>2000 then raise exception 'Invalid entries' using errcode='22023'; end if;
  if exists(select 1 from jsonb_array_elements(entries) e where
    not(e ? 'key' and e ? 'original' and e ? 'text') or jsonb_typeof(e->'key') <> 'string'
    or jsonb_typeof(e->'original') <> 'string' or jsonb_typeof(e->'text') <> 'string'
    or length(e->>'key') not between 1 and 200 or length(e->>'original')>20000
    or length(e->>'text')>20000 or length(btrim(e->>'text'))=0) then
    raise exception 'Invalid entry' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(requested_scope_id||':'||requested_route,0));
  insert into pac_dsd.page_text_snapshots(scope_id,route,entries)
  select requested_scope_id,requested_route,coalesce(jsonb_agg(jsonb_build_object('key',o.element_key,'original',o.original_text,'text',o.replacement_text,'updatedAt',o.updated_at,'updatedBy',o.updated_by)),'[]'::jsonb)
  from pac_dsd.page_text_overrides o where o.scope_id=requested_scope_id and o.route=requested_route;
  delete from pac_dsd.page_text_overrides o where o.scope_id=requested_scope_id and o.route=requested_route;
  insert into pac_dsd.page_text_overrides(scope_id,route,element_key,original_text,replacement_text)
  select requested_scope_id,requested_route,e->>'key',e->>'original',e->>'text' from jsonb_array_elements(entries) e where e->>'text' is distinct from e->>'original';
  get diagnostics saved=row_count;
  return saved;
end; $$;

create or replace function pac_dsd.read_page_text_history(requested_scope_id text,requested_route text)
returns table(element_key text,original_text text,replacement_text text,updated_at timestamptz,updated_by text,superseded_at timestamptz,superseded_by text)
language sql stable security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
  select e->>'key',e->>'original',e->>'text',(e->>'updatedAt')::timestamptz,e->>'updatedBy',s.archived_at,'consultant'::text
  from pac_dsd.page_text_snapshots s cross join lateral jsonb_array_elements(s.entries) e
  where s.scope_id=requested_scope_id and s.route=requested_route order by s.snapshot_id desc limit 200;
$$;

create or replace function pac_dsd.restore_page_text_route(requested_scope_id text,requested_route text)
returns integer language plpgsql security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
declare previous jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended(requested_scope_id||':'||requested_route,0));
  select s.entries into previous from pac_dsd.page_text_snapshots s where s.scope_id=requested_scope_id and s.route=requested_route order by s.snapshot_id desc limit 1;
  if previous is null then return 0; end if;
  return pac_dsd.save_page_text_overrides(requested_scope_id,requested_route,previous);
end; $$;
revoke all on function pac_dsd.save_page_text_overrides(text,text,jsonb),pac_dsd.read_page_text_history(text,text),pac_dsd.restore_page_text_route(text,text) from public,pac_dsd_app_runtime;
