-- 0064_pac_course_lesson_objectives_contract.sql
-- Match the existing application course contract without changing course copy.
-- Lesson learning may include 3–5 explicit objectives as well as its existing
-- single objective. Strict object keys and all other limits remain unchanged.

do $migration$
declare
  existing_schema jsonb := pac_dsd.course_pack_schema();
  objectives_schema constant jsonb := '{"type":"array","minItems":3,"maxItems":5,"items":{"type":"string","minLength":1,"maxLength":100000,"pattern":"(?s)."}}'::jsonb;
  field_path constant text[] := array['properties','course','properties','lessons','items','properties','learning','properties','objectives'];
  revised_schema jsonb;
begin
  if existing_schema #>> '{properties,course,properties,lessons,items,properties,learning,type}' is distinct from 'object'
    or existing_schema #> '{properties,course,properties,lessons,items,properties,learning,additionalProperties}' is distinct from 'false'::jsonb
    or not (existing_schema #> '{properties,course,properties,lessons,items,properties,learning,properties}')
      ?& array['objective','takeaways','evidence','appliedNextStep'] then
    raise exception 'Expected lesson learning contract is unavailable' using errcode='55000';
  end if;
  if existing_schema #> field_path is not null then
    if existing_schema #> field_path is distinct from objectives_schema then
      raise exception 'Existing lesson objectives contract requires reconciliation' using errcode='55000';
    end if;
    return;
  end if;
  -- The existing SQL validator enforces patterns; (?s). also enforces the
  -- nonempty-string minimum across line breaks without widening any other field.
  revised_schema := jsonb_set(existing_schema,field_path,objectives_schema,true);
  execute format(
    'create or replace function pac_dsd.course_pack_schema() returns jsonb language sql immutable set search_path=pg_catalog as $schema_function$ select %L::jsonb $schema_function$',
    revised_schema::text
  );
end;
$migration$;


-- 0065_pac_withdrawn_resource_history_flag.sql
-- A withdrawn resource has no effective publication. History entries still
-- need a boolean current flag so owner withdrawal responses remain readable.
-- Read contract only: no resource, decision, or history records are changed.

do $migration$
declare
  definition text := pg_get_functiondef('pac_dsd.read_resource_release_state(text,text)'::regprocedure);
  previous constant text := E'''isCurrent'', history.revision_id = publication.revision_id\n          and history.scope_id = publication.scope_id';
  replacement constant text := '''isCurrent'', coalesce(history.revision_id = publication.revision_id and history.scope_id = publication.scope_id, false)';
begin
  if position(replacement in definition)>0 then return; end if;
  if position(previous in definition)=0 then
    raise exception 'Expected resource history flag contract is unavailable' using errcode='55000';
  end if;
  execute replace(definition,previous,replacement);
end;
$migration$;


-- 0066_pac_unified_operational_work.sql

-- Forward-only: align hosted durable work with the unified application.
alter function pac_dsd.assert_runtime_work_object_contract(text,text,jsonb) rename to assert_runtime_work_object_contract_pre_unified_v1;
create function pac_dsd.assert_runtime_work_object_contract(requested_kind text, requested_object_id text, payload jsonb)
returns void language plpgsql immutable set search_path=pg_catalog,pac_dsd as $$
declare field_name text; item jsonb;
begin
  perform pac_dsd.assert_no_prohibited_profile_fields(payload);
  if requested_kind='decision' and requested_object_id ~ '^program_(task|event):' then perform pac_dsd.assert_no_collaboration_surveillance_text(payload); end if;
  if requested_kind is distinct from 'decision' or requested_object_id !~ '^program_(task|event|outcome):' then
    perform pac_dsd.assert_runtime_work_object_contract_pre_unified_v1(requested_kind,requested_object_id,payload); return;
  end if;
  if payload is null or jsonb_typeof(payload) <> 'object' or requested_object_id is null or length(requested_object_id)>180 then raise exception 'Invalid program work object' using errcode='22023'; end if;
  if requested_object_id like 'program_task:%' then
    perform pac_dsd.assert_allowed_jsonb_keys(payload,array['recordType','id','createdAt','functionId','outcomeIds','kind','title','objective','agentId','sourceId','dueAt','eligible','exclusionReason','source','evidenceMode','executionMode','goalActionIds']);
    if not (payload ?& array['recordType','id','createdAt','functionId','outcomeIds','kind','title','objective','agentId','dueAt','eligible','source','evidenceMode']) then raise exception 'Incomplete program task' using errcode='22023'; end if;
    perform pac_dsd.assert_jsonb_scalar_types(payload,array['recordType','id','functionId','kind','agentId','source','evidenceMode'],array['eligible'],array[]::text[]);
    if payload->>'recordType' is distinct from 'program_task' or payload->>'id' !~ '^task-[a-f0-9]{32}$' or requested_object_id is distinct from 'program_task:'||(payload->>'id')
      or payload->>'kind' not in ('work_preparation','cadence_review','outcome_followup','source_review','resource_review')
      or payload->>'agentId' not in ('program_orchestrator','ask_concierge','ci_guide','librarian','a11y_reviewer','consult_intake','graduation_coach','embed_advisor','content_sentinel','eval_steward')
      or payload->>'source' not in ('owner','cadence','staff_result','program_maintenance')
      or payload->>'evidenceMode' not in ('operational','verification')
      or (payload->>'eligible'='false' and coalesce(payload->>'exclusionReason','')='') then raise exception 'Invalid program task' using errcode='22023'; end if;
    perform pac_dsd.assert_program_string(payload,'functionId',1,60);
    perform pac_dsd.assert_program_string(payload,'title',5,180);
    perform pac_dsd.assert_program_string(payload,'objective',10,3000);
    perform pac_dsd.assert_program_string(payload,'sourceId',0,180,false);
    perform pac_dsd.assert_program_string(payload,'exclusionReason',0,300,false);
    perform pac_dsd.assert_program_instant(payload,'createdAt');
    perform pac_dsd.assert_program_instant(payload,'dueAt');
    perform pac_dsd.assert_jsonb_string_array(payload->'outcomeIds');
    if jsonb_array_length(payload->'outcomeIds')>7 then raise exception 'Too many program outcomes' using errcode='22023'; end if;
    for item in select value from jsonb_array_elements(payload->'outcomeIds') loop
      if length(item#>>'{}')>60 then raise exception 'Invalid program outcome identifier' using errcode='22023'; end if;
    end loop;
    if payload ? 'executionMode' and payload->>'executionMode' not in ('manual','assisted') then raise exception 'Invalid preparation mode'; end if;
    if payload ? 'goalActionIds' then
      perform pac_dsd.assert_jsonb_string_array(payload->'goalActionIds');
      if jsonb_array_length(payload->'goalActionIds')>28 or (select count(distinct value) from jsonb_array_elements(payload->'goalActionIds'))<>jsonb_array_length(payload->'goalActionIds') then raise exception 'Invalid action selections'; end if;
      for item in select value from jsonb_array_elements(payload->'goalActionIds') loop
        if item#>>'{}' !~ '^ADSA-(1\.[1-5]|2\.[1-5]|3\.[1-8]|4\.[1-3]|5\.[1-3]|6\.[1-4])$' then raise exception 'Unknown supplied action'; end if;
      end loop;
    end if;
    return;
  end if;  if requested_object_id like 'program_event:%' then
    perform pac_dsd.assert_allowed_jsonb_keys(payload,array['recordType','id','taskId','at','phase','attempt','actor','note','receipt','disposition','followUpAt','humanMinutes','preparationPlan','decisionOwner','decisionReference','nextAction','implementationOwner','resultObservation','resultEvidence','resultLimitations','resultConfidence']);
    if not (payload ?& array['recordType','id','taskId','at','phase','attempt','actor','note']) then raise exception 'Incomplete program event' using errcode='22023'; end if;
    perform pac_dsd.assert_jsonb_scalar_types(payload,array['recordType','id','taskId','phase','actor','disposition'],array[]::text[],array['attempt','humanMinutes']);
    if payload->>'recordType' is distinct from 'program_event'
      or payload->>'id' !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
      or requested_object_id is distinct from 'program_event:'||(payload->>'id')
      or payload->>'taskId' !~ '^task-[a-f0-9]{32}$'
      or payload->>'phase' not in ('started','completed','prepared','decision_recorded','results_recorded','failed','applied','reviewed','cancelled','retry_requested')
      or payload->>'actor' not in ('agent','owner')
      or pac_dsd.jsonb_is_safe_integer(payload->'attempt',0) is distinct from true
      or (payload->>'attempt')::numeric>10000
      or (payload->>'phase'='completed' and not (payload ? 'receipt'))
      or (payload->>'phase' in ('prepared','decision_recorded','results_recorded','applied','reviewed','cancelled','retry_requested') and payload->>'actor'<>'owner')
      or (payload ? 'disposition' and payload->>'disposition' not in ('retain','revise','stop','not_yet_known'))
      or (payload ? 'humanMinutes' and (payload->>'humanMinutes')::numeric not between 0 and 100000) then raise exception 'Invalid program event' using errcode='22023'; end if;
    perform pac_dsd.assert_program_string(payload,'note',0,3000);
    perform pac_dsd.assert_program_instant(payload,'at');
    perform pac_dsd.assert_program_instant(payload,'followUpAt',false);
    if payload ? 'receipt' then perform pac_dsd.assert_program_receipt(payload->'receipt'); end if;
    if payload->>'phase'='prepared' and (jsonb_typeof(payload->'preparationPlan') is distinct from 'object' or payload->'receipt'->>'method' is distinct from 'owner_report' or payload->'receipt'->>'evidenceLevel' is distinct from 'delivery') then raise exception 'Manual draft receipt required'; end if;
    foreach field_name in array array['decisionOwner','decisionReference','nextAction','implementationOwner'] loop
      if payload ? field_name or payload->>'phase'='decision_recorded' then perform pac_dsd.assert_program_string(payload,field_name,case when field_name in ('decisionOwner','implementationOwner') then 2 else 5 end,case when field_name in ('decisionOwner','implementationOwner') then 240 else 1500 end); end if;
    end loop;
    foreach field_name in array array['resultObservation','resultEvidence','resultLimitations'] loop
      if payload ? field_name or payload->>'phase'='results_recorded' then perform pac_dsd.assert_program_string(payload,field_name,10,1500); end if;
    end loop;
    if payload->>'phase'='results_recorded' or payload ? 'resultConfidence' then
      if payload->>'resultConfidence' is null or payload->>'resultConfidence' not in ('early_observation','supported_observation','not_yet_known') then raise exception 'Result confidence required'; end if;
    end if;
    if payload ? 'preparationPlan' then
      perform pac_dsd.assert_allowed_jsonb_keys(payload->'preparationPlan',array['reviewNeeds','measure','reportBack','measureDefinition']);
      perform pac_dsd.assert_program_string(payload->'preparationPlan','reviewNeeds',10,1500);
      perform pac_dsd.assert_program_string(payload->'preparationPlan','measure',10,1500);
      perform pac_dsd.assert_program_string(payload->'preparationPlan','reportBack',5,1000);
      if payload->'preparationPlan' ? 'measureDefinition' then
        item:=payload->'preparationPlan'->'measureDefinition';
        perform pac_dsd.assert_allowed_jsonb_keys(item,array['id','version','status','title','calculation','population','evidenceSource','period','comparison','differencesPrivacy','targetReference','reviewReference','nextTrigger']);
        if item->>'status' is distinct from 'proposed' or item->>'id' is distinct from 'measure-'||substring(payload->>'taskId' from 6) or pac_dsd.jsonb_is_safe_integer(item->'version',1) is distinct from true or (item->>'version')::numeric>100000 then raise exception 'Invalid proposed measure identity'; end if;
        foreach field_name in array array['title','calculation','population','evidenceSource','period','comparison','differencesPrivacy','targetReference','reviewReference','nextTrigger'] loop perform pac_dsd.assert_program_string(item,field_name,case when field_name in ('calculation','population','evidenceSource','comparison','differencesPrivacy') then 10 else 5 end,case when field_name='title' then 240 when field_name='period' then 500 when field_name in ('population','nextTrigger') then 1000 else 1500 end); end loop;
      end if;
    end if;

    return;
  end if;
  perform pac_dsd.assert_runtime_work_object_contract_pre_unified_v1(requested_kind,requested_object_id,payload);
end $$;
create or replace function pac_dsd.program_event_transition_valid(payload jsonb)
returns boolean language plpgsql volatile security definer set search_path=pg_catalog,pac_dsd as $$
declare task jsonb; latest jsonb; execution jsonb; current_status text; current_attempt integer; phase text; actor text; attempted integer;
begin
  perform pac_dsd.assert_runtime_work_object_contract('decision','program_event:'||(payload->>'id'),payload);
  select value into task from pac_dsd.runtime_work_objects
    where work_kind='decision' and object_id='program_task:'||(payload->>'taskId') for update;
  if task is null then return false; end if;
  select value into latest from pac_dsd.runtime_work_objects
    where work_kind='decision' and object_id like 'program_event:%' and value->>'taskId'=payload->>'taskId'
    order by value->>'at' desc, (value->>'attempt')::integer desc, value->>'id' desc limit 1;
  select value into execution from pac_dsd.runtime_work_objects
    where work_kind='decision' and object_id like 'program_event:%' and value->>'taskId'=payload->>'taskId'
      and value->>'phase' in ('started','completed','prepared','failed','cancelled','retry_requested')
    order by value->>'at' desc, (value->>'attempt')::integer desc, value->>'id' desc limit 1;
  select coalesce(max((value->>'attempt')::integer),0) into current_attempt from pac_dsd.runtime_work_objects
    where work_kind='decision' and object_id like 'program_event:%' and value->>'taskId'=payload->>'taskId';
  if latest is not null and payload->>'at'<=latest->>'at' then return false; end if;
  current_status:=coalesce(execution->>'phase','queued');
  phase:=payload->>'phase';actor:=payload->>'actor';attempted:=(payload->>'attempt')::integer;
  if payload ? 'receipt' and payload->'receipt'->>'contentHash' is distinct from encode(sha256(convert_to(payload->'receipt'->>'body','UTF8')),'hex') then return false; end if;
  if payload->'preparationPlan' ? 'measureDefinition' then
    if phase<>'prepared' or (payload->'preparationPlan'->'measureDefinition'->>'version')::integer<>(select coalesce(max((value->'preparationPlan'->'measureDefinition'->>'version')::integer),0)+1 from pac_dsd.runtime_work_objects where work_kind='decision' and value->>'taskId'=payload->>'taskId') then return false; end if;
  end if;
  if phase='prepared' then return actor='owner' and task->>'executionMode'='manual' and attempted=current_attempt and current_status in ('queued','retry_requested','failed') and payload->'receipt'->>'method'='owner_report' and payload->'receipt'->>'evidenceLevel'='delivery'; end if;
  if phase='started' then
    if task->>'executionMode'='manual' then return false; end if;
    return actor='agent' and attempted=current_attempt+1 and (
      current_status in ('queued','retry_requested') or (current_status='failed' and current_attempt<3) or
      (current_status='started' and (payload->>'at')::timestamptz-(execution->>'at')::timestamptz>=interval '10 minutes'));
  end if;
  if phase in ('completed','failed') then
    return actor='agent' and current_status='started' and attempted=current_attempt and
      (phase<>'completed' or payload->'receipt'->>'evidenceLevel'='delivery');
  end if;
  if actor<>'owner' or attempted<>current_attempt or payload ? 'receipt' then return false; end if;
  if phase='cancelled' then return current_status<>'cancelled'; end if;
  if phase='retry_requested' then return current_status in ('failed','cancelled','completed','prepared'); end if;
  if phase in ('applied','results_recorded') and not exists(select 1 from pac_dsd.runtime_work_objects where work_kind='decision' and value->>'taskId'=payload->>'taskId' and value->>'phase'=case when phase='applied' then 'decision_recorded' else 'applied' end and value->>'at'>execution->>'at') then return false; end if;
  return phase in ('decision_recorded','results_recorded','applied','reviewed') and current_status in ('completed','prepared') and execution ? 'receipt';
end $$;

revoke all on function pac_dsd.assert_runtime_work_object_contract(text,text,jsonb) from public,pac_dsd_app_runtime;

-- 20261005220104_pac_review_resource_receipts.sql
-- Admit only the four published planning/reporting resource IDs that can
-- occur in cycle, stale-content and audit receipts. No policy level, role,
-- row access or arbitrary guide-* namespace is changed.

do $$
declare target regprocedure; definition text; audit_updated integer := 0; work_updated integer := 0;
  previous text := 'somali|hmong|karen|oromo';
  replacement text := 'guide-one-dsd-quarterly-report|guide-one-dsd-measures|guide-one-dsd-work-plan|guide-one-dsd-implementation-plan|somali|hmong|karen|oromo';
begin
  -- Later contracts delegate to preserved validators. Update the validator
  -- that actually owns the resource list, without replacing its wrappers.
  foreach target in array array_remove(array[
    to_regprocedure('pac_dsd.assert_runtime_audit_event_contract(jsonb)'),
    to_regprocedure('pac_dsd.assert_runtime_audit_event_contract_pre_program_v1(jsonb)'),
    to_regprocedure('pac_dsd.assert_runtime_work_object_contract(text,text,jsonb)'),
    to_regprocedure('pac_dsd.assert_runtime_work_object_contract_pre_program_v1(text,text,jsonb)')
  ], null) loop
    definition := pg_get_functiondef(target);
    if position(previous in definition) = 0 then continue; end if;
    if position('guide-one-dsd-quarterly-report' in definition) = 0 then
      definition := replace(definition, previous, replacement);
    end if;
    -- Also preserve the four program references intended by migration 0061
    -- when an installation uses the later delegating contract wrappers.
    if position('ref-one-dsd-three-year-plan' in definition) = 0 then
      definition := replace(definition, previous,
        'ref-one-dsd-three-year-plan|ref-dhs-equity-landscape|ref-minnesota-equity-research|ref-one-dsd-policy-analysis-presentation|' || previous);
    end if;
    execute definition;
    if target::text like '%audit_event%' then audit_updated := audit_updated + 1;
    else work_updated := work_updated + 1; end if;
  end loop;
  if audit_updated <> 1 or work_updated <> 1 then
    raise exception 'Expected one resource validator for audit and one for work objects; found %, %', audit_updated, work_updated;
  end if;
end;
$$;


-- Match the current application resource contract in this private namespace only.
do $patch$ declare definition text; begin definition:=pg_get_functiondef('pac_dsd.assert_valid_resource_edit_fields(jsonb)'::regprocedure); definition:=replace(definition,'''under_review'', ''external_verify''','''under_review'', ''external_verify'', ''program_reference'''); definition:=replace(definition,'''^\\d{4}-\\d{2}-\\d{2}$''','''^[0-9]{4}-[0-9]{2}-[0-9]{2}$'''); execute definition; end $patch$;

-- 0067_pac_ask_voice_limits_and_internal_helpers.sql

-- Forward-only: retain existing request scopes and their exact limits while adding ASK voice.
create or replace function pac_dsd.assert_runtime_rate_limit_request(requested_scope text, requested_subject_hash text, requested_limit integer, requested_window_seconds integer)
returns void language plpgsql immutable security invoker set search_path=pg_catalog,pac_dsd as $function$
begin
  if requested_scope in ('ask-voice','ask-transcribe') then
    if requested_subject_hash is null or requested_subject_hash !~ '^[a-f0-9]{64}$'
      or requested_window_seconds is distinct from 600
      or requested_limit is distinct from (case requested_scope when 'ask-voice' then 30 else 20 end) then
      raise exception 'Invalid voice rate limit' using errcode='22023';
    end if;
    return;
  end if;
  if requested_scope not in ('staff-equity-analysis','staff-equity-register') then
    perform pac_dsd.assert_runtime_rate_limit_request_pre_equity_v1(requested_scope,requested_subject_hash,requested_limit,requested_window_seconds); return;
  end if;
  if requested_subject_hash is null or requested_subject_hash !~ '^[a-f0-9]{64}$'
    or requested_window_seconds is distinct from 600
    or requested_limit is distinct from (case requested_scope when 'staff-equity-analysis' then 10 else 60 end) then
    raise exception 'Invalid equity analysis rate limit' using errcode='22023';
  end if;
end $function$;
alter table pac_dsd.runtime_rate_limits drop constraint runtime_rate_limits_registered_identity;
alter table pac_dsd.runtime_rate_limits add constraint runtime_rate_limits_registered_identity check(
 scope in ('staff-ask','owner-login','consultation-intake','consultation-tracking','staff-program-outcome','program-login-network','program-login-account','program-invitation-network','program-invitation-code','staff-equity-analysis','staff-equity-register','ask-voice','ask-transcribe')
 and subject_hash ~ '^[a-f0-9]{64}$'
);

-- These helpers run inside owner-owned protected functions or triggers.
-- Preserve owner and explicit ACLs; do not inherit direct access through PUBLIC.
revoke execute on function pac_dsd.surface_document_hash(text) from public;
revoke execute on function pac_dsd.protected_action_fingerprint(text,jsonb) from public;
revoke execute on function pac_dsd.assert_protected_action_authorization_shape() from public;



-- 0068_pac_engagement_pdf_receipts.sql
-- Admit only the four approved public resources and pages present in their PDFs.
-- Preserve all other receipt fields, privacy exclusions, roles, and ACLs.
do $$
declare target regprocedure; definition text; audit_updated integer := 0; work_updated integer := 0;
  previous text := 'somali|hmong|karen|oromo';
  addition text := 'ref-clas-implementation-checklist(-pdf-page-[1-8])?|ref-adsa-engagement-guide(-pdf-page-([1-9]|[1-5][0-9]|60))?|ref-adsa-engagement-checklist(-pdf-page-[1-3])?|ref-adsa-engagement-presentation(-pdf-page-([1-9]|[12][0-9]|3[0-3]))?|';
begin
  foreach target in array array_remove(array[
    to_regprocedure('pac_dsd.assert_runtime_audit_event_contract(jsonb)'),
    to_regprocedure('pac_dsd.assert_runtime_audit_event_contract_pre_program_v1(jsonb)'),
    to_regprocedure('pac_dsd.assert_runtime_work_object_contract(text,text,jsonb)'),
    to_regprocedure('pac_dsd.assert_runtime_work_object_contract_pre_program_v1(text,text,jsonb)')
  ], null) loop
    definition := pg_get_functiondef(target);
    if position(previous in definition) = 0 then continue; end if;
    if position(addition in definition) = 0 then
      if position('ref-adsa-engagement-guide' in definition) > 0 then
        raise exception 'Unexpected engagement receipt definition in %', target;
      end if;
      execute replace(definition, previous, addition || previous);
    end if;
    if target::text like '%audit_event%' then audit_updated := audit_updated + 1;
    else work_updated := work_updated + 1; end if;
  end loop;
  if audit_updated <> 1 or work_updated <> 1 then
    raise exception 'Expected one resource validator for audit and work; found %, %', audit_updated, work_updated;
  end if;
end;
$$;


-- 0069_pac_jev_audit_receipts.sql
-- Register the existing bounded Jev decision tool in the finite audit contract.
-- Do not change agent permissions, autonomy, review outcomes, or stored payloads.
do $$
declare target regprocedure; definition text; updated integer := 0;
  previous text := '''citation.attach''';
  replacement text := '''decision.jev'', ''citation.attach''';
begin
  foreach target in array array_remove(array[
    to_regprocedure('pac_dsd.assert_runtime_audit_event_contract(jsonb)'),
    to_regprocedure('pac_dsd.assert_runtime_audit_event_contract_pre_program_v1(jsonb)')
  ], null) loop
    definition := pg_get_functiondef(target);
    if position(previous in definition) = 0 then continue; end if;
    if position('''decision.jev''' in definition) = 0 then
      execute replace(definition, previous, replacement);
    end if;
    updated := updated + 1;
  end loop;
  if updated <> 1 then raise exception 'Expected one finite audit tool validator, found %', updated; end if;
end;
$$;

-- 0072_pac_dsd_consensus_research_usage.sql
-- Extend only One DSD's existing research receipt and retention validators.
-- CREATE OR REPLACE via the catalog definition preserves owners and ACLs.

do $migration$
declare
  target regprocedure;
  definition text;
  previous text := $anchor$payload ->> 'provider' not in ('perplexity_agent', 'openai_web', 'fixture')$anchor$;
  replacement text := $anchor$payload ->> 'provider' not in ('perplexity_agent', 'openai_web', 'fixture', 'consensus')$anchor$;
  updated integer := 0;
begin
  -- Older installations can have the provider check in the current function.
  -- Newer installations retain it in the original, delegated validator.
  foreach target in array array_remove(array[
    to_regprocedure('pac_dsd.assert_runtime_work_object_contract(text,text,jsonb)'),
    to_regprocedure('pac_dsd.assert_runtime_work_object_contract_pre_program_v1(text,text,jsonb)')
  ], null) loop
    definition := pg_get_functiondef(target);
    if position(replacement in definition) > 0 then
      updated := updated + 1;
    elsif position(previous in definition) > 0 then
      execute replace(definition, previous, replacement);
      updated := updated + 1;
    end if;
  end loop;
  if updated <> 1 then
    raise exception 'Expected one One DSD research usage writer validator, found %', updated;
  end if;

  definition := pg_get_functiondef('pac_dsd.is_valid_research_usage_record(text,jsonb)'::regprocedure);
  replacement := $anchor$candidate ->> 'provider' in ('perplexity_agent', 'openai_web', 'fixture', 'consensus')$anchor$;
  if position(replacement in definition) = 0 then
    previous := $anchor$candidate ->> 'provider' in ('perplexity_agent', 'openai_web', 'fixture')$anchor$;
    if position(previous in definition) = 0 then
      previous := $anchor$candidate ->> 'provider' in ('perplexity_agent', 'fixture')$anchor$;
    end if;
    if position(previous in definition) = 0 then
      raise exception 'Expected the One DSD research usage retention validator';
    end if;
    execute replace(definition, previous, replacement);
  end if;
end;
$migration$;

do $verify$
declare
  receipt_id text := 'ru_20261113120000_abcdef_0123';
  receipt jsonb := jsonb_build_object(
    'id', receipt_id, 'at', '2026-11-13T12:00:00.000Z',
    'provider', 'consensus', 'model', 'msh_' || repeat('a', 64), 'depth', 'current_web',
    'query_hash', 'abcdef0123456789', 'domains', jsonb_build_array('doi.org'),
    'estimated_usd', 0, 'search_queries', 1, 'tool_calls', 1, 'ok', true,
    'latency_ms', 10, 'trace_id', '12345678-1234-4abc-8abc-123456789abc'
  );
begin
  perform pac_dsd.assert_runtime_work_object_contract('decision', 'research_usage:' || receipt_id, receipt);
  if not pac_dsd.is_valid_research_usage_record('research_usage:' || receipt_id, receipt) then
    raise exception 'Consensus receipt failed retention validation';
  end if;
  if pac_dsd.is_valid_research_usage_record('research_usage:' || receipt_id, receipt || '{"provider":"unknown"}'::jsonb) then
    raise exception 'Unregistered provider passed retention validation';
  end if;
  begin
    perform pac_dsd.assert_runtime_work_object_contract('decision', 'research_usage:' || receipt_id, receipt || '{"provider":"unknown"}'::jsonb);
    raise exception 'Unregistered provider passed write validation';
  exception when sqlstate '22023' then null;
  end;
end;
$verify$;

-- 0073_pac_dsd_volume_free_runtime_records.sql
-- Records that used to need the One DSD service's persistent volume: the owner's page edits and
-- the Ask pilot's operational counts (runs, voice use, the daily review claim). No prompts, names,
-- answers or audio are kept. The application uses these only when PAC_RUNTIME_RECORDS=postgres;
-- until then nothing reads or writes them.
--
-- Readers and the Ask ledger use pac_dsd_app_runtime. Page edit saves use pac_dsd_owner_writer, as
-- every other owner edit does. Tables are reachable only through these definer functions.

do $$ begin
  if not exists (select 1 from pg_catalog.pg_roles where rolname='pac_dsd_owner_writer') then
    create role pac_dsd_owner_writer login noinherit nosuperuser nocreatedb nocreaterole nobypassrls;
  end if;
end; $$;
grant usage on schema pac_dsd to pac_dsd_owner_writer;

-- One document, the same JSON shape as .data/page-edits/page-edits.json (version 1).
create table if not exists pac_dsd.page_edit_documents (
  document_id text primary key check (document_id = 'page-edits'),
  revision bigint not null check (revision > 0),
  body jsonb not null check (
    jsonb_typeof(body) = 'object'
    and body->'version' = '1'::jsonb
    and jsonb_typeof(body->'pages') = 'object'
    and jsonb_typeof(body->'log') = 'array'
    and octet_length(body::text) <= 16777216
  ),
  updated_at timestamptz not null default now()
);
-- The last 40 versions before each save, as the file store's backups folder keeps.
create table if not exists pac_dsd.page_edit_document_history (
  history_id bigint generated always as identity primary key,
  document_id text not null check (document_id = 'page-edits'),
  revision bigint not null,
  body jsonb not null,
  archived_at timestamptz not null default now()
);
create index if not exists page_edit_document_history_recent_idx on pac_dsd.page_edit_document_history(document_id, history_id desc);

create table if not exists pac_dsd.clone_agent_runs (
  run_id uuid primary key,
  started_at timestamptz not null,
  finished_at timestamptz,
  status text not null check (status in ('running','interrupted','completed','needs_review','refused','failed')),
  route text check (route is null or route in ('resources','learning','equity','accessibility','development','support','general')),
  jev_calls integer not null default 0 check (jev_calls >= 0)
);
create index if not exists clone_agent_runs_started_idx on pac_dsd.clone_agent_runs(started_at);
create index if not exists clone_agent_runs_running_idx on pac_dsd.clone_agent_runs(started_at) where status = 'running';

create table if not exists pac_dsd.clone_voice_usage (
  usage_id bigint generated always as identity primary key,
  used_at timestamptz not null,
  kind text not null check (kind in ('speech','transcribe')),
  units integer not null check (units between 1 and 1000000)
);

create table if not exists pac_dsd.clone_daily_reviews (
  review_day date primary key,
  status text not null check (status in ('running','completed','needs_review','failed'))
);

alter table pac_dsd.page_edit_documents enable row level security;
alter table pac_dsd.page_edit_document_history enable row level security;
alter table pac_dsd.clone_agent_runs enable row level security;
alter table pac_dsd.clone_voice_usage enable row level security;
alter table pac_dsd.clone_daily_reviews enable row level security;
revoke all on pac_dsd.page_edit_documents, pac_dsd.page_edit_document_history, pac_dsd.clone_agent_runs,
  pac_dsd.clone_voice_usage, pac_dsd.clone_daily_reviews from public, pac_dsd_app_runtime, pac_dsd_owner_writer;

-- Page edits. A read names the revision the server already holds, so an unchanged document is not resent.
create or replace function pac_dsd.read_page_edit_document(known_revision bigint)
returns table(revision bigint, body jsonb)
language sql stable security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
  select d.revision, case when d.revision = known_revision then null else d.body end
  from pac_dsd.page_edit_documents d where d.document_id = 'page-edits';
$$;

-- A save names the revision it started from (0 when there was no document) and fails with 40001
-- when another save came first, so no edit is ever overwritten unseen.
create or replace function pac_dsd.write_page_edit_document(expected_revision bigint, new_body jsonb)
returns bigint language plpgsql security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
declare current_revision bigint;
declare current_body jsonb;
begin
  if expected_revision is null or expected_revision < 0 or new_body is null then
    raise exception 'Invalid page edit document' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('pac_dsd.page_edit_documents', 0));
  select d.revision, d.body into current_revision, current_body from pac_dsd.page_edit_documents d where d.document_id = 'page-edits';
  if coalesce(current_revision, 0) <> expected_revision then
    raise exception 'Page edits changed since they were read' using errcode='40001';
  end if;
  if current_revision is null then
    insert into pac_dsd.page_edit_documents(document_id, revision, body) values ('page-edits', 1, new_body);
    return 1;
  end if;
  insert into pac_dsd.page_edit_document_history(document_id, revision, body) values ('page-edits', current_revision, current_body);
  delete from pac_dsd.page_edit_document_history h where h.document_id = 'page-edits' and h.history_id not in (
    select k.history_id from pac_dsd.page_edit_document_history k where k.document_id = 'page-edits' order by k.history_id desc limit 40
  );
  update pac_dsd.page_edit_documents set revision = current_revision + 1, body = new_body, updated_at = now() where document_id = 'page-edits';
  return current_revision + 1;
end; $$;

-- Ask pilot ledger. Runs still running after four minutes are marked interrupted when the next run starts.
create or replace function pac_dsd.admit_clone_agent_run(admitted_at timestamptz)
returns uuid language plpgsql security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
declare new_id uuid := gen_random_uuid();
begin
  if admitted_at is null then raise exception 'Invalid run time' using errcode='22023'; end if;
  update pac_dsd.clone_agent_runs set status = 'interrupted', finished_at = admitted_at
    where status = 'running' and started_at < admitted_at - interval '240 seconds';
  insert into pac_dsd.clone_agent_runs(run_id, started_at, status) values (new_id, admitted_at, 'running');
  return new_id;
end; $$;

create or replace function pac_dsd.finish_clone_agent_run(target_run uuid, final_status text)
returns void language plpgsql security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
begin
  if final_status is null or final_status not in ('completed','needs_review','refused','failed') then
    raise exception 'Invalid run status' using errcode='22023';
  end if;
  update pac_dsd.clone_agent_runs set status = final_status, finished_at = now() where run_id = target_run and status = 'running';
end; $$;

create or replace function pac_dsd.record_clone_agent_decision(target_run uuid, decided_route text)
returns void language sql security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
  update pac_dsd.clone_agent_runs set jev_calls = jev_calls + 1, route = coalesce(decided_route, route) where run_id = target_run;
$$;

create or replace function pac_dsd.record_clone_voice_use(voice_kind text, used_units integer, used_at timestamptz)
returns boolean language plpgsql security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
begin
  if used_units is null or used_units <= 0 then return false; end if;
  if voice_kind is null or voice_kind not in ('speech','transcribe') or used_at is null or used_units > 1000000 then
    raise exception 'Invalid voice use' using errcode='22023';
  end if;
  insert into pac_dsd.clone_voice_usage(used_at, kind, units) values (used_at, voice_kind, used_units);
  return true;
end; $$;

create or replace function pac_dsd.claim_clone_daily_review(claimed_day date)
returns boolean language plpgsql security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
declare claimed integer;
begin
  if claimed_day is null then raise exception 'Invalid review day' using errcode='22023'; end if;
  insert into pac_dsd.clone_daily_reviews(review_day, status) values (claimed_day, 'running') on conflict (review_day) do nothing;
  get diagnostics claimed = row_count;
  return claimed > 0;
end; $$;

create or replace function pac_dsd.settle_clone_daily_review(claimed_day date, final_status text)
returns void language plpgsql security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
begin
  if final_status is null or final_status not in ('completed','needs_review','failed') then
    raise exception 'Invalid review status' using errcode='22023';
  end if;
  update pac_dsd.clone_daily_reviews set status = final_status where review_day = claimed_day;
end; $$;

create or replace function pac_dsd.summarize_clone_agent_runs(since timestamptz)
returns table(status text, count bigint, jev_calls bigint)
language sql stable security definer set search_path=pg_catalog,pac_dsd set row_security=off as $$
  select r.status, count(*), coalesce(sum(r.jev_calls), 0)::bigint from pac_dsd.clone_agent_runs r
  where r.started_at >= since group by r.status order by r.status;
$$;

revoke all on function
  pac_dsd.read_page_edit_document(bigint), pac_dsd.write_page_edit_document(bigint,jsonb),
  pac_dsd.admit_clone_agent_run(timestamptz), pac_dsd.finish_clone_agent_run(uuid,text),
  pac_dsd.record_clone_agent_decision(uuid,text), pac_dsd.record_clone_voice_use(text,integer,timestamptz),
  pac_dsd.claim_clone_daily_review(date), pac_dsd.settle_clone_daily_review(date,text),
  pac_dsd.summarize_clone_agent_runs(timestamptz)
from public, pac_dsd_app_runtime, pac_dsd_owner_writer;
grant execute on function
  pac_dsd.read_page_edit_document(bigint),
  pac_dsd.admit_clone_agent_run(timestamptz), pac_dsd.finish_clone_agent_run(uuid,text),
  pac_dsd.record_clone_agent_decision(uuid,text), pac_dsd.record_clone_voice_use(text,integer,timestamptz),
  pac_dsd.claim_clone_daily_review(date), pac_dsd.settle_clone_daily_review(date,text),
  pac_dsd.summarize_clone_agent_runs(timestamptz)
to pac_dsd_app_runtime;
grant execute on function pac_dsd.read_page_edit_document(bigint), pac_dsd.write_page_edit_document(bigint,jsonb) to pac_dsd_owner_writer;

-- Checks, inside the same transaction: nothing here is kept.
do $verify$
declare
  first_run uuid;
  stale_run uuid;
  claimed boolean;
  saved bigint;
begin
  if has_function_privilege('pac_dsd_app_runtime', 'pac_dsd.write_page_edit_document(bigint,jsonb)', 'execute') then
    raise exception 'The runtime role must not save page edits';
  end if;
  if not has_function_privilege('pac_dsd_owner_writer', 'pac_dsd.write_page_edit_document(bigint,jsonb)', 'execute') then
    raise exception 'The owner writer must be able to save page edits';
  end if;
  if has_table_privilege('pac_dsd_app_runtime', 'pac_dsd.clone_agent_runs', 'select')
    or has_table_privilege('pac_dsd_app_runtime', 'pac_dsd.page_edit_documents', 'select') then
    raise exception 'Runtime records must be reachable only through their functions';
  end if;

  stale_run := pac_dsd.admit_clone_agent_run('2000-01-01T00:00:00Z');
  first_run := pac_dsd.admit_clone_agent_run('2000-01-01T00:05:00Z');
  if (select status from pac_dsd.clone_agent_runs where run_id = stale_run) <> 'interrupted' then
    raise exception 'A stale run was not marked interrupted';
  end if;
  perform pac_dsd.record_clone_agent_decision(first_run, 'learning');
  perform pac_dsd.finish_clone_agent_run(first_run, 'completed');
  if (select jev_calls from pac_dsd.summarize_clone_agent_runs('2000-01-01T00:00:00Z') where status = 'completed') <> 1 then
    raise exception 'The run summary is wrong';
  end if;
  begin
    perform pac_dsd.finish_clone_agent_run(first_run, 'running');
    raise exception 'An invalid run status was accepted';
  exception when sqlstate '22023' then null;
  end;
  if pac_dsd.record_clone_voice_use('speech', 0, now()) or not pac_dsd.record_clone_voice_use('speech', 12, now()) then
    raise exception 'Voice use was recorded wrongly';
  end if;
  claimed := pac_dsd.claim_clone_daily_review('2000-01-01');
  if not claimed or pac_dsd.claim_clone_daily_review('2000-01-01') then
    raise exception 'A daily review was claimed twice';
  end if;
  perform pac_dsd.settle_clone_daily_review('2000-01-01', 'completed');

  if not exists (select 1 from pac_dsd.page_edit_documents) then
    saved := pac_dsd.write_page_edit_document(0, '{"version":1,"updatedAt":null,"pages":{},"log":[]}');
    if saved <> 1 or (select body from pac_dsd.read_page_edit_document(1)) is not null then
      raise exception 'An unchanged page edit document was resent';
    end if;
    begin
      perform pac_dsd.write_page_edit_document(0, '{"version":1,"updatedAt":null,"pages":{},"log":[]}');
      raise exception 'A stale page edit save was accepted';
    exception when sqlstate '40001' then null;
    end;
    saved := pac_dsd.write_page_edit_document(1, '{"version":1,"updatedAt":"2000-01-01T00:00:00.000Z","pages":{},"log":[]}');
    if saved <> 2 or (select count(*) from pac_dsd.page_edit_document_history) <> 1 then
      raise exception 'A page edit save did not keep the earlier version';
    end if;
    delete from pac_dsd.page_edit_document_history;
    delete from pac_dsd.page_edit_documents;
  end if;

  delete from pac_dsd.clone_agent_runs where run_id in (stale_run, first_run);
  delete from pac_dsd.clone_voice_usage where used_at > now() - interval '1 minute' and units = 12;
  delete from pac_dsd.clone_daily_reviews where review_day = '2000-01-01';
end;
$verify$;

commit;
